  subroutine build_block_writeback_plan
    ! Build persistent reverse routes from final block owners to the ranks
    ! that own the corresponding legacy Domains. No field is overwritten.

    implicit none

    integer :: b
    integer :: current_block_count
    integer :: d
    integer :: destination
    integer :: first_field_level
    integer :: first
    integer :: ierr
    integer :: last
    integer :: local_index
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_patch
    integer :: n_scalar_variable
    integer :: r
    integer :: slot
    integer :: v_scalar
    integer :: v_vector

    integer, allocatable :: cursor(:)

    integer(int64) :: rank_nvalue
    integer(int64) :: total_patch
    integer(int64) :: total_vector_transform

    if (.not. allocated(block_catalog) .or. &
         .not. allocated(owner)) then
       call fail("writeback plan before catalogue ownership is ready")
    end if
    if (.not. local_block_store_ready()) then
       call fail("writeback plan before local block installation")
    end if

    current_block_count = n_local_blocks()

    if (block_writeback_plan%ready) then
       if (block_writeback_plan%catalog_size /= size(block_catalog) .or. &
            block_writeback_plan%installed_block_count /= &
            current_block_count) then
          call fail("ready writeback plan has stale block coverage")
       end if
       return
    end if

    call clear_block_writeback_plan

    allocate(block_writeback_plan%send_count(n_process))
    allocate(block_writeback_plan%recv_count(n_process))
    allocate(block_writeback_plan%send_displ(n_process))
    allocate(block_writeback_plan%recv_displ(n_process))

    block_writeback_plan%send_count = 0
    block_writeback_plan%recv_count = 0
    block_writeback_plan%send_displ = 0
    block_writeback_plan%recv_displ = 0
    block_writeback_plan%n_retained = 0

    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       if (block_catalog(b)%owner /= rank) then
          call fail("writeback source block has wrong final owner")
       end if
       destination = source_rank(b)
       if (destination == rank) then
          block_writeback_plan%n_retained = &
               block_writeback_plan%n_retained + 1
       else
          block_writeback_plan%send_count(destination+1) = &
               block_writeback_plan%send_count(destination+1) + 1
       end if
    end do

    call MPI_Alltoall( &
         block_writeback_plan%send_count,1,MPI_INTEGER, &
         block_writeback_plan%recv_count,1,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoall writeback block counts")

    do r = 2,n_process
       block_writeback_plan%send_displ(r) = &
            block_writeback_plan%send_displ(r-1) + &
            block_writeback_plan%send_count(r-1)
       block_writeback_plan%recv_displ(r) = &
            block_writeback_plan%recv_displ(r-1) + &
            block_writeback_plan%recv_count(r-1)
    end do

    block_writeback_plan%n_send = &
         sum(block_writeback_plan%send_count)
    block_writeback_plan%n_recv = &
         sum(block_writeback_plan%recv_count)

    allocate(block_writeback_plan%send_block( &
         max(1,block_writeback_plan%n_send)))
    allocate(block_writeback_plan%recv_block( &
         max(1,block_writeback_plan%n_recv)))
    block_writeback_plan%send_block = 0
    block_writeback_plan%recv_block = 0

    allocate(cursor(n_process))
    cursor = block_writeback_plan%send_displ
    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       destination = source_rank(b)
       if (destination == rank) cycle
       slot = cursor(destination+1) + 1
       if (slot < 1 .or. slot > block_writeback_plan%n_send) then
          call fail("writeback send-block position is invalid")
       end if
       block_writeback_plan%send_block(slot) = b
       cursor(destination+1) = cursor(destination+1) + 1
    end do
    do r = 1,n_process
       if (cursor(r) /= block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)) then
          call fail("writeback send-block count mismatch")
       end if
    end do
    deallocate(cursor)

    call MPI_Alltoallv( &
         block_writeback_plan%send_block, &
         block_writeback_plan%send_count, &
         block_writeback_plan%send_displ,MPI_INTEGER, &
         block_writeback_plan%recv_block, &
         block_writeback_plan%recv_count, &
         block_writeback_plan%recv_displ,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv writeback block manifest")

    allocate(block_writeback_plan%send_patch_count( &
         max(1,block_writeback_plan%n_send)))
    allocate(block_writeback_plan%recv_patch_count( &
         max(1,block_writeback_plan%n_recv)))
    allocate(block_writeback_plan%send_scalar_nvalue( &
         max(1,block_writeback_plan%n_send)))
    allocate(block_writeback_plan%recv_scalar_nvalue( &
         max(1,block_writeback_plan%n_recv)))
    allocate(block_writeback_plan%send_vector_nvalue( &
         max(1,block_writeback_plan%n_send)))
    allocate(block_writeback_plan%recv_vector_nvalue( &
         max(1,block_writeback_plan%n_recv)))

    block_writeback_plan%send_patch_count = 0
    block_writeback_plan%recv_patch_count = 0
    block_writeback_plan%send_scalar_nvalue = 0
    block_writeback_plan%recv_scalar_nvalue = 0
    block_writeback_plan%send_vector_nvalue = 0
    block_writeback_plan%recv_vector_nvalue = 0

    do slot = 1,block_writeback_plan%n_send
       b = block_writeback_plan%send_block(slot)
       n_patch = local_block_patch_count(b)
       block_writeback_plan%send_patch_count(slot) = n_patch
       block_writeback_plan%send_scalar_nvalue(slot) = n_patch * &
            local_block_scalar_family_patch_nvalue(b)
       block_writeback_plan%send_vector_nvalue(slot) = n_patch * &
            local_block_vector_family_patch_nvalue(b)
       if (n_patch <= 0 .or. &
            block_writeback_plan%send_scalar_nvalue(slot) <= 0 .or. &
            block_writeback_plan%send_vector_nvalue(slot) <= 0) then
          call fail("writeback send payload extent is invalid")
       end if
    end do

    call MPI_Alltoallv( &
         block_writeback_plan%send_patch_count, &
         block_writeback_plan%send_count, &
         block_writeback_plan%send_displ,MPI_INTEGER, &
         block_writeback_plan%recv_patch_count, &
         block_writeback_plan%recv_count, &
         block_writeback_plan%recv_displ,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv writeback patch counts")
    call MPI_Alltoallv( &
         block_writeback_plan%send_scalar_nvalue, &
         block_writeback_plan%send_count, &
         block_writeback_plan%send_displ,MPI_INTEGER, &
         block_writeback_plan%recv_scalar_nvalue, &
         block_writeback_plan%recv_count, &
         block_writeback_plan%recv_displ,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv writeback scalar extents")
    call MPI_Alltoallv( &
         block_writeback_plan%send_vector_nvalue, &
         block_writeback_plan%send_count, &
         block_writeback_plan%send_displ,MPI_INTEGER, &
         block_writeback_plan%recv_vector_nvalue, &
         block_writeback_plan%recv_count, &
         block_writeback_plan%recv_displ,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv writeback vector extents")

    allocate(block_writeback_plan%scalar_send_count(n_process))
    allocate(block_writeback_plan%scalar_recv_count(n_process))
    allocate(block_writeback_plan%scalar_send_displ(n_process))
    allocate(block_writeback_plan%scalar_recv_displ(n_process))
    allocate(block_writeback_plan%vector_send_count(n_process))
    allocate(block_writeback_plan%vector_recv_count(n_process))
    allocate(block_writeback_plan%vector_send_displ(n_process))
    allocate(block_writeback_plan%vector_recv_displ(n_process))

    block_writeback_plan%scalar_send_count = 0
    block_writeback_plan%scalar_recv_count = 0
    block_writeback_plan%scalar_send_displ = 0
    block_writeback_plan%scalar_recv_displ = 0
    block_writeback_plan%vector_send_count = 0
    block_writeback_plan%vector_recv_count = 0
    block_writeback_plan%vector_send_displ = 0
    block_writeback_plan%vector_recv_displ = 0

    do r = 1,n_process
       first = block_writeback_plan%send_displ(r) + 1
       last = block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)
       rank_nvalue = 0_int64
       if (last >= first) then
          rank_nvalue = sum(int( &
               block_writeback_plan%send_scalar_nvalue(first:last), &
               int64))
       end if
       if (rank_nvalue > int(huge(0),int64)) then
          call fail("writeback scalar send count exceeds MPI range")
       end if
       block_writeback_plan%scalar_send_count(r) = int(rank_nvalue)

       rank_nvalue = 0_int64
       if (last >= first) then
          rank_nvalue = sum(int( &
               block_writeback_plan%send_vector_nvalue(first:last), &
               int64))
       end if
       if (rank_nvalue > int(huge(0),int64)) then
          call fail("writeback vector send count exceeds MPI range")
       end if
       block_writeback_plan%vector_send_count(r) = int(rank_nvalue)

       first = block_writeback_plan%recv_displ(r) + 1
       last = block_writeback_plan%recv_displ(r) + &
            block_writeback_plan%recv_count(r)
       rank_nvalue = 0_int64
       if (last >= first) then
          rank_nvalue = sum(int( &
               block_writeback_plan%recv_scalar_nvalue(first:last), &
               int64))
       end if
       if (rank_nvalue > int(huge(0),int64)) then
          call fail("writeback scalar receive count exceeds MPI range")
       end if
       block_writeback_plan%scalar_recv_count(r) = int(rank_nvalue)

       rank_nvalue = 0_int64
       if (last >= first) then
          rank_nvalue = sum(int( &
               block_writeback_plan%recv_vector_nvalue(first:last), &
               int64))
       end if
       if (rank_nvalue > int(huge(0),int64)) then
          call fail("writeback vector receive count exceeds MPI range")
       end if
       block_writeback_plan%vector_recv_count(r) = int(rank_nvalue)
    end do

    do r = 2,n_process
       block_writeback_plan%scalar_send_displ(r) = &
            block_writeback_plan%scalar_send_displ(r-1) + &
            block_writeback_plan%scalar_send_count(r-1)
       block_writeback_plan%scalar_recv_displ(r) = &
            block_writeback_plan%scalar_recv_displ(r-1) + &
            block_writeback_plan%scalar_recv_count(r-1)
       block_writeback_plan%vector_send_displ(r) = &
            block_writeback_plan%vector_send_displ(r-1) + &
            block_writeback_plan%vector_send_count(r-1)
       block_writeback_plan%vector_recv_displ(r) = &
            block_writeback_plan%vector_recv_displ(r-1) + &
            block_writeback_plan%vector_recv_count(r-1)
    end do

    allocate(block_writeback_plan%scalar_send_buffer(max(1, &
         sum(block_writeback_plan%scalar_send_count))))
    allocate(block_writeback_plan%scalar_recv_buffer(max(1, &
         sum(block_writeback_plan%scalar_recv_count))))
    allocate(block_writeback_plan%vector_send_buffer(max(1, &
         sum(block_writeback_plan%vector_send_count))))
    allocate(block_writeback_plan%vector_recv_buffer(max(1, &
         sum(block_writeback_plan%vector_recv_count))))
    block_writeback_plan%buffer_allocations = &
         block_writeback_plan%buffer_allocations + 4_int64

    block_writeback_plan%scalar_send_buffer = 0.0_dp
    block_writeback_plan%scalar_recv_buffer = 0.0_dp
    block_writeback_plan%vector_send_buffer = 0.0_dp
    block_writeback_plan%vector_recv_buffer = 0.0_dp

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    if (v_scalar < 1 .or. v_vector < 1 .or. &
         n_scalar_variable < 1 .or. n_field_level < 1 .or. &
         mult_scalar < 1 .or. mult_vector < 1) then
       call fail("writeback Domain stage field layout is invalid")
    end if
    block_writeback_plan%scalar_patch_nvalue = &
         n_scalar_variable*n_field_level*mult_scalar*PATCH_SIZE**2
    block_writeback_plan%vector_patch_nvalue = &
         n_field_level*mult_vector*PATCH_SIZE**2

    allocate(block_writeback_plan%domain_patch_displ(size(grid)))
    block_writeback_plan%domain_patch_displ = 0
    do d = 2,size(grid)
       block_writeback_plan%domain_patch_displ(d) = &
            block_writeback_plan%domain_patch_displ(d-1) + &
            grid(d-1)%patch%length
    end do

    total_patch = 0_int64
    if (size(grid) > 0) then
       total_patch = int( &
            block_writeback_plan%domain_patch_displ(size(grid)),int64) + &
            int(grid(size(grid))%patch%length,int64)
    end if
    if (total_patch > int(huge(0),int64)) then
       call fail("writeback Domain stage patch count exceeds range")
    end if
    if (total_patch*int( &
         block_writeback_plan%scalar_patch_nvalue,int64) > &
         int(huge(0),int64) .or. &
         total_patch*int( &
         block_writeback_plan%vector_patch_nvalue,int64) > &
         int(huge(0),int64)) then
       call fail("writeback Domain stage value count exceeds range")
    end if

    allocate(block_writeback_plan%scalar_domain_stage(max(1, &
         int(total_patch)*block_writeback_plan%scalar_patch_nvalue)))
    allocate(block_writeback_plan%vector_domain_stage(max(1, &
         int(total_patch)*block_writeback_plan%vector_patch_nvalue)))
    allocate(block_writeback_plan%native_scalar_stage(max(1, &
         int(total_patch)*block_writeback_plan%scalar_patch_nvalue)))
    allocate(block_writeback_plan%native_vector_stage(max(1, &
         int(total_patch)*block_writeback_plan%vector_patch_nvalue)))
    allocate(block_writeback_plan%domain_patch_covered(max(1, &
         int(total_patch))))
    allocate(block_writeback_plan%domain_patch_reconstructed(max(1, &
         int(total_patch))))
    block_writeback_plan%stage_allocations = &
         block_writeback_plan%stage_allocations + 6_int64
    block_writeback_plan%scalar_domain_stage = 0.0_dp
    block_writeback_plan%vector_domain_stage = 0.0_dp
    block_writeback_plan%native_scalar_stage = 0.0_dp
    block_writeback_plan%native_vector_stage = 0.0_dp
    block_writeback_plan%domain_patch_covered = .false.
    block_writeback_plan%domain_patch_reconstructed = .false.

    ! The complete vector transform needs Domain indexing for geometric
    ! stencils, but its field values remain an independent block-derived
    ! stage.  Allocate that persistent shape once with the writeback plan.
    allocate(production_vector_transform_displ(size(grid)+1))
    production_vector_transform_displ = 0
    total_vector_transform = 0_int64
    do d = 1,size(grid)
       production_vector_transform_displ(d) = int(total_vector_transform)
       total_vector_transform = total_vector_transform + int( &
            n_field_level*size(sol(S_VELO,first_field_level)% &
            data(d)%elts),int64)
       if (total_vector_transform > int(huge(0),int64)) then
          call fail("native vector transform stage exceeds range")
       end if
    end do
    production_vector_transform_displ(size(grid)+1) = &
         int(total_vector_transform)
    allocate(production_vector_transform_stage( &
         max(1,int(total_vector_transform))))
    allocate(production_vector_wavelet_stage( &
         max(1,int(total_vector_transform))))
    allocate(production_vector_transform_covered( &
         max(1,int(total_vector_transform))))
    production_vector_transform_stage = 0.0_dp
    production_vector_wavelet_stage = 0.0_dp
    production_vector_transform_covered = .false.
    block_writeback_plan%stage_allocations = &
         block_writeback_plan%stage_allocations + 4_int64
    block_writeback_plan%catalog_size = size(block_catalog)
    block_writeback_plan%domain_count = size(grid)
    block_writeback_plan%installed_block_count = n_local_blocks()
    call build_block_domain_boundary_plan
    call build_staged_coarse_vector_boundary_plan
    block_writeback_plan%ready = .true.
    block_writeback_plan_generation = &
         block_writeback_plan_generation + 1_int64

  end subroutine build_block_writeback_plan


  subroutine build_block_domain_boundary_plan
    ! Extend the persistent block routes with the variable-size compact
    ! boundary manifest and Domain-owner-to-final-owner payload buffers.

    implicit none

    integer :: b
    integer :: boundary_index
    integer :: elts_start
    integer :: ierr
    integer :: n_boundary
    integer :: n_node
    integer :: pos
    integer :: r
    integer :: slot
    integer :: source_bdry
    integer :: source_level

    integer, allocatable :: metadata_recv_count(:)
    integer, allocatable :: metadata_recv_displ(:)
    integer, allocatable :: metadata_send_count(:)
    integer, allocatable :: metadata_send_displ(:)

    allocate(block_writeback_plan%send_boundary_count( &
         max(1,block_writeback_plan%n_send)))
    allocate(block_writeback_plan%recv_boundary_count( &
         max(1,block_writeback_plan%n_recv)))
    allocate(block_writeback_plan%send_boundary_displ( &
         max(1,block_writeback_plan%n_send)))
    allocate(block_writeback_plan%recv_boundary_displ( &
         max(1,block_writeback_plan%n_recv)))
    allocate(block_writeback_plan%send_boundary_scalar_nvalue( &
         max(1,block_writeback_plan%n_send)))
    allocate(block_writeback_plan%recv_boundary_scalar_nvalue( &
         max(1,block_writeback_plan%n_recv)))
    allocate(block_writeback_plan%send_boundary_vector_nvalue( &
         max(1,block_writeback_plan%n_send)))
    allocate(block_writeback_plan%recv_boundary_vector_nvalue( &
         max(1,block_writeback_plan%n_recv)))

    block_writeback_plan%send_boundary_count = 0
    block_writeback_plan%recv_boundary_count = 0
    block_writeback_plan%send_boundary_displ = 0
    block_writeback_plan%recv_boundary_displ = 0
    block_writeback_plan%send_boundary_scalar_nvalue = 0
    block_writeback_plan%recv_boundary_scalar_nvalue = 0
    block_writeback_plan%send_boundary_vector_nvalue = 0
    block_writeback_plan%recv_boundary_vector_nvalue = 0

    do slot = 1,block_writeback_plan%n_send
       b = block_writeback_plan%send_block(slot)
       n_boundary = local_block_boundary_count(b)
       block_writeback_plan%send_boundary_count(slot) = n_boundary
       do boundary_index = 1,n_boundary
          block_writeback_plan%send_boundary_scalar_nvalue(slot) = &
               block_writeback_plan%send_boundary_scalar_nvalue(slot) + &
               local_block_scalar_family_boundary_nvalue( &
               b,boundary_index)
          block_writeback_plan%send_boundary_vector_nvalue(slot) = &
               block_writeback_plan%send_boundary_vector_nvalue(slot) + &
               local_block_vector_family_boundary_nvalue( &
               b,boundary_index)
       end do
    end do

    call MPI_Alltoallv( &
         block_writeback_plan%send_boundary_count, &
         block_writeback_plan%send_count, &
         block_writeback_plan%send_displ,MPI_INTEGER, &
         block_writeback_plan%recv_boundary_count, &
         block_writeback_plan%recv_count, &
         block_writeback_plan%recv_displ,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv boundary record counts")
    call MPI_Alltoallv( &
         block_writeback_plan%send_boundary_scalar_nvalue, &
         block_writeback_plan%send_count, &
         block_writeback_plan%send_displ,MPI_INTEGER, &
         block_writeback_plan%recv_boundary_scalar_nvalue, &
         block_writeback_plan%recv_count, &
         block_writeback_plan%recv_displ,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv scalar boundary extents")
    call MPI_Alltoallv( &
         block_writeback_plan%send_boundary_vector_nvalue, &
         block_writeback_plan%send_count, &
         block_writeback_plan%send_displ,MPI_INTEGER, &
         block_writeback_plan%recv_boundary_vector_nvalue, &
         block_writeback_plan%recv_count, &
         block_writeback_plan%recv_displ,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv vector boundary extents")

    do slot = 2,block_writeback_plan%n_send
       block_writeback_plan%send_boundary_displ(slot) = &
            block_writeback_plan%send_boundary_displ(slot-1) + &
            block_writeback_plan%send_boundary_count(slot-1)
    end do
    do slot = 2,block_writeback_plan%n_recv
       block_writeback_plan%recv_boundary_displ(slot) = &
            block_writeback_plan%recv_boundary_displ(slot-1) + &
            block_writeback_plan%recv_boundary_count(slot-1)
    end do
    block_writeback_plan%n_send_boundary = 0
    if (block_writeback_plan%n_send > 0) then
       block_writeback_plan%n_send_boundary = &
            block_writeback_plan%send_boundary_displ( &
            block_writeback_plan%n_send) + &
            block_writeback_plan%send_boundary_count( &
            block_writeback_plan%n_send)
    end if
    block_writeback_plan%n_recv_boundary = 0
    if (block_writeback_plan%n_recv > 0) then
       block_writeback_plan%n_recv_boundary = &
            block_writeback_plan%recv_boundary_displ( &
            block_writeback_plan%n_recv) + &
            block_writeback_plan%recv_boundary_count( &
            block_writeback_plan%n_recv)
    end if

    allocate(block_writeback_plan%send_boundary_source( &
         max(1,block_writeback_plan%n_send_boundary)))
    allocate(block_writeback_plan%recv_boundary_source( &
         max(1,block_writeback_plan%n_recv_boundary)))
    allocate(block_writeback_plan%send_boundary_level( &
         max(1,block_writeback_plan%n_send_boundary)))
    allocate(block_writeback_plan%recv_boundary_level( &
         max(1,block_writeback_plan%n_recv_boundary)))
    allocate(block_writeback_plan%send_boundary_nnode( &
         max(1,block_writeback_plan%n_send_boundary)))
    allocate(block_writeback_plan%recv_boundary_nnode( &
         max(1,block_writeback_plan%n_recv_boundary)))
    block_writeback_plan%send_boundary_source = 0
    block_writeback_plan%recv_boundary_source = 0
    block_writeback_plan%send_boundary_level = -1
    block_writeback_plan%recv_boundary_level = -1
    block_writeback_plan%send_boundary_nnode = 0
    block_writeback_plan%recv_boundary_nnode = 0

    do slot = 1,block_writeback_plan%n_send
       b = block_writeback_plan%send_block(slot)
       do boundary_index = 1, &
            block_writeback_plan%send_boundary_count(slot)
          pos = block_writeback_plan%send_boundary_displ(slot) + &
               boundary_index
          call get_local_block_boundary_source( &
               b,boundary_index,source_bdry,elts_start,n_node, &
               source_level)
          block_writeback_plan%send_boundary_source(pos) = source_bdry
          block_writeback_plan%send_boundary_level(pos) = source_level
          block_writeback_plan%send_boundary_nnode(pos) = n_node
       end do
    end do

    allocate(metadata_send_count(n_process))
    allocate(metadata_recv_count(n_process))
    allocate(metadata_send_displ(n_process))
    allocate(metadata_recv_displ(n_process))
    metadata_send_count = 0
    metadata_recv_count = 0
    metadata_send_displ = 0
    metadata_recv_displ = 0
    do r = 1,n_process
       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)
          metadata_send_count(r) = metadata_send_count(r) + &
               block_writeback_plan%send_boundary_count(slot)
       end do
       do slot = block_writeback_plan%recv_displ(r)+1, &
            block_writeback_plan%recv_displ(r) + &
            block_writeback_plan%recv_count(r)
          metadata_recv_count(r) = metadata_recv_count(r) + &
               block_writeback_plan%recv_boundary_count(slot)
       end do
    end do
    do r = 2,n_process
       metadata_send_displ(r) = metadata_send_displ(r-1) + &
            metadata_send_count(r-1)
       metadata_recv_displ(r) = metadata_recv_displ(r-1) + &
            metadata_recv_count(r-1)
    end do
    if (sum(metadata_send_count) /= &
         block_writeback_plan%n_send_boundary .or. &
         sum(metadata_recv_count) /= &
         block_writeback_plan%n_recv_boundary) then
       call fail("boundary metadata extent mismatch")
    end if

    call MPI_Alltoallv( &
         block_writeback_plan%send_boundary_source, &
         metadata_send_count,metadata_send_displ,MPI_INTEGER, &
         block_writeback_plan%recv_boundary_source, &
         metadata_recv_count,metadata_recv_displ,MPI_INTEGER, &
         comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv boundary source manifest")
    call MPI_Alltoallv( &
         block_writeback_plan%send_boundary_level, &
         metadata_send_count,metadata_send_displ,MPI_INTEGER, &
         block_writeback_plan%recv_boundary_level, &
         metadata_recv_count,metadata_recv_displ,MPI_INTEGER, &
         comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv boundary level manifest")
    call MPI_Alltoallv( &
         block_writeback_plan%send_boundary_nnode, &
         metadata_send_count,metadata_send_displ,MPI_INTEGER, &
         block_writeback_plan%recv_boundary_nnode, &
         metadata_recv_count,metadata_recv_displ,MPI_INTEGER, &
         comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv boundary node manifest")

    allocate( &
         block_writeback_plan%boundary_scalar_domain_send_count( &
         n_process))
    allocate( &
         block_writeback_plan%boundary_scalar_domain_send_displ( &
         n_process))
    allocate( &
         block_writeback_plan%boundary_scalar_block_recv_count( &
         n_process))
    allocate( &
         block_writeback_plan%boundary_scalar_block_recv_displ( &
         n_process))
    allocate( &
         block_writeback_plan%boundary_vector_domain_send_count( &
         n_process))
    allocate( &
         block_writeback_plan%boundary_vector_domain_send_displ( &
         n_process))
    allocate( &
         block_writeback_plan%boundary_vector_block_recv_count( &
         n_process))
    allocate( &
         block_writeback_plan%boundary_vector_block_recv_displ( &
         n_process))
    block_writeback_plan%boundary_scalar_domain_send_count = 0
    block_writeback_plan%boundary_scalar_domain_send_displ = 0
    block_writeback_plan%boundary_scalar_block_recv_count = 0
    block_writeback_plan%boundary_scalar_block_recv_displ = 0
    block_writeback_plan%boundary_vector_domain_send_count = 0
    block_writeback_plan%boundary_vector_domain_send_displ = 0
    block_writeback_plan%boundary_vector_block_recv_count = 0
    block_writeback_plan%boundary_vector_block_recv_displ = 0

    do r = 1,n_process
       do slot = block_writeback_plan%recv_displ(r)+1, &
            block_writeback_plan%recv_displ(r) + &
            block_writeback_plan%recv_count(r)
          block_writeback_plan%boundary_scalar_domain_send_count(r) = &
               block_writeback_plan% &
               boundary_scalar_domain_send_count(r) + &
               block_writeback_plan%recv_boundary_scalar_nvalue(slot)
          block_writeback_plan%boundary_vector_domain_send_count(r) = &
               block_writeback_plan% &
               boundary_vector_domain_send_count(r) + &
               block_writeback_plan%recv_boundary_vector_nvalue(slot)
       end do
       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)
          block_writeback_plan%boundary_scalar_block_recv_count(r) = &
               block_writeback_plan%boundary_scalar_block_recv_count(r) + &
               block_writeback_plan%send_boundary_scalar_nvalue(slot)
          block_writeback_plan%boundary_vector_block_recv_count(r) = &
               block_writeback_plan%boundary_vector_block_recv_count(r) + &
               block_writeback_plan%send_boundary_vector_nvalue(slot)
       end do
    end do
    do r = 2,n_process
       block_writeback_plan%boundary_scalar_domain_send_displ(r) = &
            block_writeback_plan% &
            boundary_scalar_domain_send_displ(r-1) + &
            block_writeback_plan% &
            boundary_scalar_domain_send_count(r-1)
       block_writeback_plan%boundary_scalar_block_recv_displ(r) = &
            block_writeback_plan% &
            boundary_scalar_block_recv_displ(r-1) + &
            block_writeback_plan% &
            boundary_scalar_block_recv_count(r-1)
       block_writeback_plan%boundary_vector_domain_send_displ(r) = &
            block_writeback_plan% &
            boundary_vector_domain_send_displ(r-1) + &
            block_writeback_plan% &
            boundary_vector_domain_send_count(r-1)
       block_writeback_plan%boundary_vector_block_recv_displ(r) = &
            block_writeback_plan% &
            boundary_vector_block_recv_displ(r-1) + &
            block_writeback_plan% &
            boundary_vector_block_recv_count(r-1)
    end do

    allocate( &
         block_writeback_plan%boundary_scalar_domain_send_buffer( &
         max(1,sum(block_writeback_plan% &
         boundary_scalar_domain_send_count))))
    allocate( &
         block_writeback_plan%boundary_scalar_block_recv_buffer( &
         max(1,sum(block_writeback_plan% &
         boundary_scalar_block_recv_count))))
    allocate( &
         block_writeback_plan%boundary_vector_domain_send_buffer( &
         max(1,sum(block_writeback_plan% &
         boundary_vector_domain_send_count))))
    allocate( &
         block_writeback_plan%boundary_vector_block_recv_buffer( &
         max(1,sum(block_writeback_plan% &
         boundary_vector_block_recv_count))))
    block_writeback_plan%buffer_allocations = &
         block_writeback_plan%buffer_allocations + 4_int64
    block_writeback_plan%boundary_scalar_domain_send_buffer = 0.0_dp
    block_writeback_plan%boundary_scalar_block_recv_buffer = 0.0_dp
    block_writeback_plan%boundary_vector_domain_send_buffer = 0.0_dp
    block_writeback_plan%boundary_vector_block_recv_buffer = 0.0_dp

    deallocate(metadata_recv_displ)
    deallocate(metadata_recv_count)
    deallocate(metadata_send_displ)
    deallocate(metadata_send_count)

  end subroutine build_block_domain_boundary_plan


  subroutine build_staged_coarse_vector_boundary_plan
    ! Build the persistent vector routes used by update_bdry at
    ! level_start-1. Production expands that coarse request across
    ! level_start-1:level_end, so retain the same complete route range. The
    ! payload source is the independent block-derived stage, never the
    ! authoritative Domain field.

    implicit none

    integer :: d_destination
    integer :: d_source
    integer :: destination
    integer :: destination_global
    integer :: destination_id
    integer :: first_field_level
    integer :: i
    integer :: ierr
    integer :: level
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_variable
    integer :: p
    integer :: pos
    integer :: r
    integer :: source_global
    integer :: source_id
    integer :: total_edge
    integer :: v_scalar
    integer :: v_vector

    integer, allocatable :: announced_recv(:)

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    if (v_vector /= S_VELO .or. mult_vector /= EDGE .or. &
         n_field_level < 1) then
       call fail("staged coarse boundary field layout is invalid")
    end if

    allocate(staged_coarse_vector_boundary_plan%send_count(n_process))
    allocate(staged_coarse_vector_boundary_plan%recv_count(n_process))
    allocate(staged_coarse_vector_boundary_plan%send_displ(n_process))
    allocate(staged_coarse_vector_boundary_plan%recv_displ(n_process))
    staged_coarse_vector_boundary_plan%send_count = 0
    staged_coarse_vector_boundary_plan%recv_count = 0
    staged_coarse_vector_boundary_plan%send_displ = 0
    staged_coarse_vector_boundary_plan%recv_displ = 0

    do r = 1,n_process
       if (r == rank+1) cycle
       do d_source = 1,size(grid)
          do d_destination = 1,n_domain(r)
             destination = glo_id(r,d_destination)+1
             do i = 1,grid(d_source)%pack(AT_EDGE,destination)%length
                source_id = grid(d_source)% &
                     pack(AT_EDGE,destination)%elts(i)
                level = grid(d_source)%level%elts(source_id/EDGE+1)
                if (level >= level_start-1 .and. &
                     level <= level_end) then
                   staged_coarse_vector_boundary_plan%send_count(r) = &
                        staged_coarse_vector_boundary_plan%send_count(r)+1
                end if
             end do
          end do
       end do
    end do

    do r = 1,n_process
       if (r == rank+1) cycle
       do d_source = 1,n_domain(r)
          source_global = glo_id(r,d_source)+1
          do d_destination = 1,size(grid)
             do i = 1,grid(d_destination)% &
                  unpk(AT_EDGE,source_global)%length
                destination_id = abs(grid(d_destination)% &
                     unpk(AT_EDGE,source_global)%elts(i))
                level = grid(d_destination)%level%elts( &
                     destination_id/EDGE+1)
                if (level >= level_start-1 .and. &
                     level <= level_end) then
                   staged_coarse_vector_boundary_plan%recv_count(r) = &
                        staged_coarse_vector_boundary_plan%recv_count(r)+1
                end if
             end do
          end do
       end do
    end do

    allocate(announced_recv(n_process))
    call MPI_Alltoall( &
         staged_coarse_vector_boundary_plan%send_count,1,MPI_INTEGER, &
         announced_recv,1,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoall staged coarse boundary counts")
    if (any(announced_recv /= &
         staged_coarse_vector_boundary_plan%recv_count)) then
       call fail("staged coarse boundary route counts differ")
    end if
    deallocate(announced_recv)

    do r = 2,n_process
       staged_coarse_vector_boundary_plan%send_displ(r) = &
            staged_coarse_vector_boundary_plan%send_displ(r-1) + &
            staged_coarse_vector_boundary_plan%send_count(r-1)
       staged_coarse_vector_boundary_plan%recv_displ(r) = &
            staged_coarse_vector_boundary_plan%recv_displ(r-1) + &
            staged_coarse_vector_boundary_plan%recv_count(r-1)
    end do
    staged_coarse_vector_boundary_plan%n_send = sum( &
         staged_coarse_vector_boundary_plan%send_count)
    staged_coarse_vector_boundary_plan%n_recv = sum( &
         staged_coarse_vector_boundary_plan%recv_count)

    staged_coarse_vector_boundary_plan%n_local = 0
    do d_source = 1,size(grid)
       source_global = glo_id(rank+1,d_source)+1
       do d_destination = 1,size(grid)
          destination_global = glo_id(rank+1,d_destination)+1
          if (grid(d_source)%pack(AT_EDGE,destination_global)%length /= &
               grid(d_destination)%unpk(AT_EDGE,source_global)%length) then
             call fail("staged local coarse boundary routes differ")
          end if
          do i = 1,grid(d_source)% &
               pack(AT_EDGE,destination_global)%length
             source_id = grid(d_source)% &
                  pack(AT_EDGE,destination_global)%elts(i)
             destination_id = abs(grid(d_destination)% &
                  unpk(AT_EDGE,source_global)%elts(i))
             level = grid(d_source)%level%elts(source_id/EDGE+1)
             if (level /= grid(d_destination)%level%elts( &
                  destination_id/EDGE+1)) then
                call fail("staged local coarse boundary levels differ")
             end if
             if (level >= level_start-1 .and. level <= level_end) then
                staged_coarse_vector_boundary_plan%n_local = &
                     staged_coarse_vector_boundary_plan%n_local+1
             end if
          end do
       end do
    end do

    allocate(staged_coarse_vector_boundary_plan%send_domain( &
         max(1,staged_coarse_vector_boundary_plan%n_send)))
    allocate(staged_coarse_vector_boundary_plan%send_id( &
         max(1,staged_coarse_vector_boundary_plan%n_send)))
    allocate(staged_coarse_vector_boundary_plan%recv_domain( &
         max(1,staged_coarse_vector_boundary_plan%n_recv)))
    allocate(staged_coarse_vector_boundary_plan%recv_id( &
         max(1,staged_coarse_vector_boundary_plan%n_recv)))
    allocate( &
         staged_coarse_vector_boundary_plan%local_source_domain( &
         max(1,staged_coarse_vector_boundary_plan%n_local)))
    allocate(staged_coarse_vector_boundary_plan%local_source_id( &
         max(1,staged_coarse_vector_boundary_plan%n_local)))
    allocate( &
         staged_coarse_vector_boundary_plan%local_destination_domain( &
         max(1,staged_coarse_vector_boundary_plan%n_local)))
    allocate( &
         staged_coarse_vector_boundary_plan%local_destination_id( &
         max(1,staged_coarse_vector_boundary_plan%n_local)))
    staged_coarse_vector_boundary_plan%send_domain = 0
    staged_coarse_vector_boundary_plan%send_id = 0
    staged_coarse_vector_boundary_plan%recv_domain = 0
    staged_coarse_vector_boundary_plan%recv_id = 0
    staged_coarse_vector_boundary_plan%local_source_domain = 0
    staged_coarse_vector_boundary_plan%local_source_id = 0
    staged_coarse_vector_boundary_plan%local_destination_domain = 0
    staged_coarse_vector_boundary_plan%local_destination_id = 0

    pos = 0
    do r = 1,n_process
       if (r == rank+1) cycle
       do d_source = 1,size(grid)
          do d_destination = 1,n_domain(r)
             destination = glo_id(r,d_destination)+1
             do i = 1,grid(d_source)%pack(AT_EDGE,destination)%length
                source_id = grid(d_source)% &
                     pack(AT_EDGE,destination)%elts(i)
                level = grid(d_source)%level%elts(source_id/EDGE+1)
                if (level < level_start-1 .or. level > level_end) cycle
                pos = pos+1
                staged_coarse_vector_boundary_plan%send_domain(pos) = &
                     d_source
                staged_coarse_vector_boundary_plan%send_id(pos) = source_id
             end do
          end do
       end do
    end do
    if (pos /= staged_coarse_vector_boundary_plan%n_send) then
       call fail("staged coarse boundary send manifest differs")
    end if

    pos = 0
    do r = 1,n_process
       if (r == rank+1) cycle
       do d_source = 1,n_domain(r)
          source_global = glo_id(r,d_source)+1
          do d_destination = 1,size(grid)
             do i = 1,grid(d_destination)% &
                  unpk(AT_EDGE,source_global)%length
                destination_id = grid(d_destination)% &
                     unpk(AT_EDGE,source_global)%elts(i)
                level = grid(d_destination)%level%elts( &
                     abs(destination_id)/EDGE+1)
                if (level < level_start-1 .or. level > level_end) cycle
                pos = pos+1
                staged_coarse_vector_boundary_plan%recv_domain(pos) = &
                     d_destination
                staged_coarse_vector_boundary_plan%recv_id(pos) = &
                     destination_id
             end do
          end do
       end do
    end do
    if (pos /= staged_coarse_vector_boundary_plan%n_recv) then
       call fail("staged coarse boundary receive manifest differs")
    end if

    pos = 0
    do d_source = 1,size(grid)
       source_global = glo_id(rank+1,d_source)+1
       do d_destination = 1,size(grid)
          destination_global = glo_id(rank+1,d_destination)+1
          do i = 1,grid(d_source)% &
               pack(AT_EDGE,destination_global)%length
             source_id = grid(d_source)% &
                  pack(AT_EDGE,destination_global)%elts(i)
             level = grid(d_source)%level%elts(source_id/EDGE+1)
             if (level < level_start-1 .or. level > level_end) cycle
             pos = pos+1
             staged_coarse_vector_boundary_plan% &
                  local_source_domain(pos) = d_source
             staged_coarse_vector_boundary_plan% &
                  local_source_id(pos) = source_id
             staged_coarse_vector_boundary_plan% &
                  local_destination_domain(pos) = d_destination
             staged_coarse_vector_boundary_plan% &
                  local_destination_id(pos) = grid(d_destination)% &
                  unpk(AT_EDGE,source_global)%elts(i)
          end do
       end do
    end do
    if (pos /= staged_coarse_vector_boundary_plan%n_local) then
       call fail("staged local coarse boundary manifest differs")
    end if

    allocate(staged_coarse_vector_boundary_plan%domain_edge_displ( &
         size(grid)+1))
    staged_coarse_vector_boundary_plan%domain_edge_displ(1) = 0
    do d_destination = 1,size(grid)
       total_edge = EDGE*grid(d_destination)%node%length
       staged_coarse_vector_boundary_plan% &
            domain_edge_displ(d_destination+1) = &
            staged_coarse_vector_boundary_plan% &
            domain_edge_displ(d_destination)+total_edge
    end do
    total_edge = staged_coarse_vector_boundary_plan% &
         domain_edge_displ(size(grid)+1)
    allocate(staged_coarse_vector_boundary_plan%boundary_lookup( &
         max(1,total_edge)))
    staged_coarse_vector_boundary_plan%boundary_lookup = 0
    allocate(staged_coarse_vector_boundary_plan%source_produced( &
         max(1,total_edge*n_field_level)))
    staged_coarse_vector_boundary_plan%source_produced = .false.
    do p = 1,staged_coarse_vector_boundary_plan%n_recv
       d_destination = staged_coarse_vector_boundary_plan%recv_domain(p)
       destination_id = abs( &
            staged_coarse_vector_boundary_plan%recv_id(p))
       i = staged_coarse_vector_boundary_plan% &
            domain_edge_displ(d_destination)+destination_id+1
       if (i < 1 .or. i > total_edge) then
          call fail("staged coarse boundary receive lookup is invalid")
       end if
       staged_coarse_vector_boundary_plan%boundary_lookup(i) = p
    end do
    do p = 1,staged_coarse_vector_boundary_plan%n_local
       d_destination = staged_coarse_vector_boundary_plan% &
            local_destination_domain(p)
       destination_id = abs(staged_coarse_vector_boundary_plan% &
            local_destination_id(p))
       i = staged_coarse_vector_boundary_plan% &
            domain_edge_displ(d_destination)+destination_id+1
       if (i < 1 .or. i > total_edge) then
          call fail("staged local coarse boundary lookup is invalid")
       end if
       staged_coarse_vector_boundary_plan%boundary_lookup(i) = &
            staged_coarse_vector_boundary_plan%n_recv+p
    end do

    allocate(staged_coarse_vector_boundary_plan%send_buffer(max(1, &
         n_field_level*staged_coarse_vector_boundary_plan%n_send)))
    allocate(staged_coarse_vector_boundary_plan%recv_buffer(max(1, &
         n_field_level*staged_coarse_vector_boundary_plan%n_recv)))
    allocate(staged_coarse_vector_boundary_plan%boundary_value(max(1, &
         n_field_level*(staged_coarse_vector_boundary_plan%n_recv + &
         staged_coarse_vector_boundary_plan%n_local))))
    allocate(staged_coarse_vector_boundary_plan%send_produced_buffer( &
         max(1,n_field_level* &
         staged_coarse_vector_boundary_plan%n_send)))
    allocate(staged_coarse_vector_boundary_plan%recv_produced_buffer( &
         max(1,n_field_level* &
         staged_coarse_vector_boundary_plan%n_recv)))
    allocate(staged_coarse_vector_boundary_plan%boundary_produced( &
         max(1,n_field_level*( &
         staged_coarse_vector_boundary_plan%n_recv + &
         staged_coarse_vector_boundary_plan%n_local))))
    allocate( &
         staged_coarse_vector_boundary_plan%retained_boundary_produced( &
         max(1,n_field_level*total_edge)))
    allocate(staged_coarse_vector_boundary_plan%retained_boundary_value( &
         max(1,n_field_level*total_edge)))
    staged_coarse_vector_boundary_plan%send_buffer = 0.0_dp
    staged_coarse_vector_boundary_plan%recv_buffer = 0.0_dp
    staged_coarse_vector_boundary_plan%boundary_value = 0.0_dp
    staged_coarse_vector_boundary_plan%send_produced_buffer = 0
    staged_coarse_vector_boundary_plan%recv_produced_buffer = 0
    staged_coarse_vector_boundary_plan%boundary_produced = 0
    staged_coarse_vector_boundary_plan%retained_boundary_produced = .false.
    staged_coarse_vector_boundary_plan%retained_boundary_value = 0.0_dp
    staged_coarse_vector_boundary_plan%coarse_level = level_start-1
    staged_coarse_vector_boundary_plan%n_field_level = n_field_level
    staged_coarse_vector_boundary_plan%allocations = 23_int64
    staged_coarse_vector_boundary_plan%exchange_count = 0_int64
    staged_coarse_vector_boundary_plan%ready = .true.
    staged_coarse_vector_boundary_plan%values_ready = .false.

  end subroutine build_staged_coarse_vector_boundary_plan


  subroutine exchange_staged_coarse_vector_boundaries ( &
       coarse_level,n_field_level)
    ! Exchange the independently restricted coarse vector stage through the
    ! exact update_bdry pack/unpack routes, including edge sign reversals.

    implicit none

    integer, intent(in) :: coarse_level
    integer, intent(in) :: n_field_level

    integer :: d
    integer :: destination_id
    integer :: field_level
    integer :: first_field_level
    integer :: ierr
    integer :: level_slot
    integer :: layout_n_field_level
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_scalar_variable
    integer :: p
    integer :: source_id
    integer :: v_scalar
    integer :: v_vector

    integer :: recv_value_count(n_process)
    integer :: recv_value_displ(n_process)
    integer :: send_value_count(n_process)
    integer :: send_value_displ(n_process)

    integer(int64) :: count_global(2)
    integer(int64) :: count_local(2)

    real(dp) :: allowed
    real(dp) :: reference_value
    real(dp) :: staged_value

    if (.not. staged_coarse_vector_boundary_plan%ready .or. &
         staged_coarse_vector_boundary_plan%coarse_level /= &
         coarse_level .or. &
         staged_coarse_vector_boundary_plan%n_field_level /= &
         n_field_level) then
       call fail("staged coarse boundary exchange plan is invalid")
    end if
    if (coarse_level /= level_start-1 .or. &
         production_velocity_restriction_level /= coarse_level) then
       call fail("staged coarse boundary exchange source is not ready")
    end if

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         layout_n_field_level,mult_scalar,mult_vector)
    if (v_vector /= S_VELO .or. mult_vector /= EDGE .or. &
         layout_n_field_level /= n_field_level) then
       call fail("staged coarse boundary exchange layout differs")
    end if

    staged_coarse_vector_boundary_plan%values_ready = .false.
    staged_coarse_vector_boundary_plan%send_buffer = 0.0_dp
    staged_coarse_vector_boundary_plan%recv_buffer = 0.0_dp
    staged_coarse_vector_boundary_plan%boundary_value = 0.0_dp
    staged_coarse_vector_boundary_plan%send_produced_buffer = 0
    staged_coarse_vector_boundary_plan%recv_produced_buffer = 0
    staged_coarse_vector_boundary_plan%boundary_produced = 0
    staged_coarse_vector_boundary_plan%retained_boundary_produced = .false.
    staged_coarse_vector_boundary_plan%retained_boundary_value = 0.0_dp

    call capture_retained_staged_vector_boundaries
    do p = 1,staged_coarse_vector_boundary_plan%n_send
       d = staged_coarse_vector_boundary_plan%send_domain(p)
       source_id = staged_coarse_vector_boundary_plan%send_id(p)
       do level_slot = 1,n_field_level
          staged_coarse_vector_boundary_plan%send_buffer( &
               (p-1)*n_field_level+level_slot) = &
               staged_coarse_source_vector_value( &
               d,source_id,level_slot)
          if (staged_boundary_source_is_independent( &
               d,source_id,level_slot)) then
             staged_coarse_vector_boundary_plan%send_produced_buffer( &
                  (p-1)*n_field_level+level_slot) = 1
          end if
       end do
    end do

    send_value_count = n_field_level* &
         staged_coarse_vector_boundary_plan%send_count
    recv_value_count = n_field_level* &
         staged_coarse_vector_boundary_plan%recv_count
    send_value_displ = n_field_level* &
         staged_coarse_vector_boundary_plan%send_displ
    recv_value_displ = n_field_level* &
         staged_coarse_vector_boundary_plan%recv_displ
    call MPI_Alltoallv( &
         staged_coarse_vector_boundary_plan%send_buffer, &
         send_value_count,send_value_displ,MPI_DOUBLE_PRECISION, &
         staged_coarse_vector_boundary_plan%recv_buffer, &
         recv_value_count,recv_value_displ,MPI_DOUBLE_PRECISION, &
         comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv staged coarse vector boundary")
    call MPI_Alltoallv( &
         staged_coarse_vector_boundary_plan%send_produced_buffer, &
         send_value_count,send_value_displ,MPI_INTEGER, &
         staged_coarse_vector_boundary_plan%recv_produced_buffer, &
         recv_value_count,recv_value_displ,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv staged coarse source flags")

    do p = 1,staged_coarse_vector_boundary_plan%n_recv
       do level_slot = 1,n_field_level
          staged_value = staged_coarse_vector_boundary_plan%recv_buffer( &
               (p-1)*n_field_level+level_slot)
          if (staged_coarse_vector_boundary_plan%recv_id(p) < 0) then
             staged_value = -staged_value
          end if
          staged_coarse_vector_boundary_plan%boundary_value( &
               (p-1)*n_field_level+level_slot) = staged_value
          staged_coarse_vector_boundary_plan%boundary_produced( &
               (p-1)*n_field_level+level_slot) = &
               staged_coarse_vector_boundary_plan% &
               recv_produced_buffer((p-1)*n_field_level+level_slot)
       end do
    end do

    do p = 1,staged_coarse_vector_boundary_plan%n_local
       d = staged_coarse_vector_boundary_plan%local_source_domain(p)
       source_id = staged_coarse_vector_boundary_plan%local_source_id(p)
       do level_slot = 1,n_field_level
          staged_value = staged_coarse_source_vector_value( &
               d,source_id,level_slot)
          if (staged_coarse_vector_boundary_plan% &
               local_destination_id(p) < 0) then
             staged_value = -staged_value
          end if
          staged_coarse_vector_boundary_plan%boundary_value( &
               (staged_coarse_vector_boundary_plan%n_recv+p-1)* &
               n_field_level+level_slot) = staged_value
          if (staged_boundary_source_is_independent( &
               d,source_id,level_slot)) then
             staged_coarse_vector_boundary_plan%boundary_produced( &
                  (staged_coarse_vector_boundary_plan%n_recv+p-1)* &
                  n_field_level+level_slot) = 1
          end if
       end do
    end do

    count_local = [ &
         int(staged_coarse_vector_boundary_plan%n_recv,int64), &
         int(staged_coarse_vector_boundary_plan%n_local,int64) ]
    do p = 1,staged_coarse_vector_boundary_plan%n_recv + &
         staged_coarse_vector_boundary_plan%n_local
       if (p <= staged_coarse_vector_boundary_plan%n_recv) then
          d = staged_coarse_vector_boundary_plan%recv_domain(p)
          destination_id = abs( &
               staged_coarse_vector_boundary_plan%recv_id(p))
       else
          d = staged_coarse_vector_boundary_plan% &
               local_destination_domain( &
               p-staged_coarse_vector_boundary_plan%n_recv)
          destination_id = abs(staged_coarse_vector_boundary_plan% &
               local_destination_id( &
               p-staged_coarse_vector_boundary_plan%n_recv))
       end if
       do level_slot = 1,n_field_level
          field_level = first_field_level+level_slot-1
          staged_value = staged_coarse_vector_boundary_plan% &
               boundary_value((p-1)*n_field_level+level_slot)
          reference_value = sol(S_VELO,field_level)%data(d)% &
               elts(destination_id+1)
          if (.not. ieee_is_finite(staged_value) .or. &
               .not. ieee_is_finite(reference_value)) then
             call fail("staged coarse boundary value is non-finite")
          end if
          allowed = 16.0_dp*epsilon(1.0_dp)*max( &
               1.0_dp,abs(staged_value),abs(reference_value))
          if (abs(staged_value-reference_value) > allowed) then
             write(error_unit,'(/,a,i0,a,i0,a,i0,a,i0)') &
                  "Rank ",rank, &
                  ": staged coarse boundary mismatch: Domain = ",d, &
                  ", edge id = ",destination_id, &
                  ", field level = ",field_level
             write(error_unit,'(a,3(es24.16,1x))') &
                  "  staged, Domain, allowed = ", &
                  staged_value,reference_value,allowed
             flush(error_unit)
             call fail("staged coarse boundary comparison failed")
          end if
       end do
    end do

    call MPI_Allreduce(count_local,count_global,size(count_local), &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce staged coarse boundary coverage")
    if (sum(count_global) <= 0_int64) then
       call fail("staged coarse boundary exchange coverage is empty")
    end if

    staged_coarse_vector_boundary_plan%exchange_count = &
         staged_coarse_vector_boundary_plan%exchange_count+1_int64
    staged_coarse_vector_boundary_plan%values_ready = .true.
    if (rank == 0) then
       write(6,'(a,i0,a,i0)') &
            "  staged coarse vector boundary transport passed: remote = ", &
            count_global(1),", local = ",count_global(2)
    end if

  contains

    subroutine capture_retained_staged_vector_boundaries
      ! Reverse the persistent block-boundary route so Domain owners retain
      ! the candidate halo values that legacy update_bdry deliberately leaves
      ! unchanged (notably TOLRNZ corner edges on the fixed coarse scaffold).

      implicit none

      integer :: b
      integer :: boundary_index
      integer :: d_boundary
      integer :: elts_start
      integer :: metadata_pos
      integer :: n_boundary
      integer :: n_node
      integer :: n_vector
      integer :: pos
      integer :: r
      integer :: slot
      integer :: source
      integer :: source_bdry

      block_writeback_plan%boundary_vector_block_recv_buffer = 0.0_dp
      block_writeback_plan%boundary_vector_domain_send_buffer = 0.0_dp

      do r = 1,n_process
         pos = block_writeback_plan% &
              boundary_vector_block_recv_displ(r)+1
         do slot = block_writeback_plan%send_displ(r)+1, &
              block_writeback_plan%send_displ(r) + &
              block_writeback_plan%send_count(r)
            b = block_writeback_plan%send_block(slot)
            source = source_rank(b)
            if (source /= r-1) then
               call fail("retained staged boundary send route differs")
            end if
            n_boundary = local_block_boundary_count(b)
            if (n_boundary /= &
                 block_writeback_plan%send_boundary_count(slot)) then
               call fail("retained staged boundary send layout differs")
            end if
            do boundary_index = 1,n_boundary
               n_vector = local_block_vector_family_boundary_nvalue( &
                    b,boundary_index)
               if (pos < 1 .or. pos+n_vector-1 > size( &
                    block_writeback_plan% &
                    boundary_vector_block_recv_buffer)) then
                  call fail("retained staged boundary send extent is invalid")
               end if
               call get_local_block_vector_boundary_family_values( &
                    b,boundary_index,BLOCK_PAYLOAD_SOL, &
                    block_writeback_plan% &
                    boundary_vector_block_recv_buffer( &
                    pos:pos+n_vector-1))
               pos = pos+n_vector
            end do
         end do
         if (pos /= block_writeback_plan% &
              boundary_vector_block_recv_displ(r) + &
              block_writeback_plan% &
              boundary_vector_block_recv_count(r)+1) then
            call fail("retained staged boundary send extent differs")
         end if
      end do

      call MPI_Alltoallv( &
           block_writeback_plan%boundary_vector_block_recv_buffer, &
           block_writeback_plan%boundary_vector_block_recv_count, &
           block_writeback_plan%boundary_vector_block_recv_displ, &
           MPI_DOUBLE_PRECISION, &
           block_writeback_plan%boundary_vector_domain_send_buffer, &
           block_writeback_plan%boundary_vector_domain_send_count, &
           block_writeback_plan%boundary_vector_domain_send_displ, &
           MPI_DOUBLE_PRECISION,comm,ierr)
      call check_mpi(ierr,"MPI_Alltoallv retained staged boundaries")

      do r = 1,n_process
         pos = block_writeback_plan% &
              boundary_vector_domain_send_displ(r)+1
         do slot = block_writeback_plan%recv_displ(r)+1, &
              block_writeback_plan%recv_displ(r) + &
              block_writeback_plan%recv_count(r)
            b = block_writeback_plan%recv_block(slot)
            source = source_rank(b)
            if (source /= rank .or. block_catalog(b)%owner /= r-1) then
               call fail("retained staged boundary receive route differs")
            end if
            d_boundary = loc_id(block_catalog(b)%root_domain+1)+1
            if (d_boundary < 1 .or. d_boundary > size(grid)) then
               call fail("retained staged boundary Domain is invalid")
            end if
            do boundary_index = 1, &
                 block_writeback_plan%recv_boundary_count(slot)
               metadata_pos = &
                    block_writeback_plan%recv_boundary_displ(slot) + &
                    boundary_index
               source_bdry = &
                    block_writeback_plan%recv_boundary_source(metadata_pos)
               n_node = &
                    block_writeback_plan%recv_boundary_nnode(metadata_pos)
               n_vector = EDGE*n_field_level*n_node
               if (pos < 1 .or. pos+n_vector-1 > size( &
                    block_writeback_plan% &
                    boundary_vector_domain_send_buffer)) then
                  call fail( &
                       "retained staged boundary receive extent is invalid")
               end if
               call install_retained_boundary( &
                    d_boundary,source_bdry,n_node, &
                    block_writeback_plan% &
                    boundary_vector_domain_send_buffer( &
                    pos:pos+n_vector-1))
               pos = pos+n_vector
            end do
         end do
         if (pos /= block_writeback_plan% &
              boundary_vector_domain_send_displ(r) + &
              block_writeback_plan% &
              boundary_vector_domain_send_count(r)+1) then
            call fail("retained staged boundary receive extent differs")
         end if
      end do

      do slot = 1,n_local_blocks()
         b = local_block_catalog(slot)
         source = source_rank(b)
         if (source /= rank) cycle
         d_boundary = loc_id(block_catalog(b)%root_domain+1)+1
         if (d_boundary < 1 .or. d_boundary > size(grid)) then
            call fail("retained local staged boundary Domain is invalid")
         end if
         do boundary_index = 1,local_block_boundary_count(b)
            call get_local_block_boundary_source( &
                 b,boundary_index,source_bdry,elts_start,n_node)
            n_vector = local_block_vector_family_boundary_nvalue( &
                 b,boundary_index)
            if (n_vector > &
                 size(ghost_exchange_plan%vector_patch_buffer)) then
               call fail("retained local staged boundary scratch is invalid")
            end if
            call get_local_block_vector_boundary_family_values( &
                 b,boundary_index,BLOCK_PAYLOAD_SOL, &
                 ghost_exchange_plan%vector_patch_buffer(1:n_vector))
            call install_retained_boundary( &
                 d_boundary,source_bdry,n_node, &
                 ghost_exchange_plan%vector_patch_buffer(1:n_vector))
         end do
      end do

    end subroutine capture_retained_staged_vector_boundaries


    subroutine install_retained_boundary ( &
         d_boundary,source_bdry,n_node,value)

      implicit none

      integer, intent(in) :: d_boundary
      integer, intent(in) :: source_bdry
      integer, intent(in) :: n_node
      real(dp), intent(in) :: value(:)

      integer :: component
      integer :: edge_id
      integer :: field_slot
      integer :: node
      integer :: source_start
      integer :: stage_index
      integer :: value_index

      if (source_bdry < 0 .or. &
           source_bdry >= grid(d_boundary)%bdry_patch%length .or. &
           size(value) /= EDGE*n_field_level*n_node) then
         call fail("retained staged boundary record is invalid")
      end if
      source_start = &
           grid(d_boundary)%bdry_patch%elts(source_bdry+1)%elts_start
      do field_slot = 1,n_field_level
         do node = 0,n_node-1
            do component = RT,UP
               edge_id = EDGE*(source_start+node)+component
               stage_index = (staged_coarse_vector_boundary_plan% &
                    domain_edge_displ(d_boundary)+edge_id)* &
                    n_field_level+field_slot
               value_index = (field_slot-1)*EDGE*n_node + &
                    EDGE*node+component+1
               if (stage_index < 1 .or. stage_index > size( &
                    staged_coarse_vector_boundary_plan% &
                    retained_boundary_value) .or. &
                    .not. ieee_is_finite(value(value_index))) then
                  call fail("retained staged boundary value is invalid")
               end if
               if (staged_coarse_vector_boundary_plan% &
                    retained_boundary_produced(stage_index)) then
                  if (abs(staged_coarse_vector_boundary_plan% &
                       retained_boundary_value(stage_index) - &
                       value(value_index)) > 0.0_dp) then
                     call fail("retained staged boundary values differ")
                  end if
               else
                  staged_coarse_vector_boundary_plan% &
                       retained_boundary_value(stage_index) = &
                       value(value_index)
                  staged_coarse_vector_boundary_plan% &
                       retained_boundary_produced(stage_index) = .true.
               end if
            end do
         end do
      end do

    end subroutine install_retained_boundary

    real(dp) function staged_coarse_source_vector_value ( &
         d_source,edge_id,field_slot) result(value)

      implicit none

      integer, intent(in) :: d_source
      integer, intent(in) :: edge_id
      integer, intent(in) :: field_slot

      integer :: cell
      integer :: edge_component
      integer :: node
      integer :: source_patch
      integer :: patch_slot
      integer :: patch_start
      integer :: value_index

      value = 0.0_dp
      node = edge_id/EDGE
      edge_component = mod(edge_id,EDGE)
      if (edge_component < RT .or. edge_component > UP) then
         call fail("staged coarse boundary source edge is invalid")
      end if
      do source_patch = 0,grid(d_source)%patch%length-1
         if (grid(d_source)%patch%elts(source_patch+1)%deleted) cycle
         patch_start = &
              grid(d_source)%patch%elts(source_patch+1)%elts_start
         if (node < patch_start .or. &
              node >= patch_start+PATCH_SIZE**2) cycle
         cell = node-patch_start
         patch_slot = block_writeback_plan% &
              domain_patch_displ(d_source)+source_patch+1
         value_index = (patch_slot-1)* &
              block_writeback_plan%vector_patch_nvalue + &
              (field_slot-1)*EDGE*PATCH_SIZE**2 + &
              EDGE*cell+edge_component+1
         if (patch_slot < 1 .or. patch_slot > &
              size(block_writeback_plan%domain_patch_covered) .or. &
              .not. block_writeback_plan%domain_patch_covered(patch_slot) &
              .or. value_index < 1 .or. value_index > &
              size(block_writeback_plan%vector_domain_stage)) then
            call fail("staged coarse boundary source is unavailable")
         end if
         value = block_writeback_plan%vector_domain_stage(value_index)
         if (.not. ieee_is_finite(value)) then
            call fail("staged coarse boundary source is non-finite")
         end if
         return
      end do
      call fail("staged boundary source escaped active patches")

    end function staged_coarse_source_vector_value


    logical function staged_boundary_source_is_independent ( &
         d_source,edge_id,field_slot) result(independent)

      implicit none

      integer, intent(in) :: d_source
      integer, intent(in) :: edge_id
      integer, intent(in) :: field_slot

      integer :: node
      integer :: patch_slot
      integer :: patch_start
      integer :: produced_index
      integer :: source_patch

      independent = .false.
      node = edge_id/EDGE
      do source_patch = 0,grid(d_source)%patch%length-1
         if (grid(d_source)%patch%elts(source_patch+1)%deleted) cycle
         patch_start = &
              grid(d_source)%patch%elts(source_patch+1)%elts_start
         if (node < patch_start .or. &
              node >= patch_start+PATCH_SIZE**2) cycle
         patch_slot = block_writeback_plan% &
              domain_patch_displ(d_source)+source_patch+1
         if (patch_slot < 1 .or. patch_slot > size( &
              block_writeback_plan%domain_patch_reconstructed)) then
            call fail("staged boundary source origin is invalid")
         end if
         if (grid(d_source)%patch%elts(source_patch+1)%level == &
              coarse_level) then
            produced_index = (staged_coarse_vector_boundary_plan% &
                 domain_edge_displ(d_source)+edge_id)*n_field_level + &
                 field_slot
            if (produced_index < 1 .or. produced_index > size( &
                 staged_coarse_vector_boundary_plan%source_produced)) then
               call fail("staged coarse source origin is invalid")
            end if
            independent = staged_coarse_vector_boundary_plan% &
                 source_produced(produced_index)
         else
            independent = block_writeback_plan% &
                 domain_patch_reconstructed(patch_slot)
         end if
         return
      end do
      call fail("staged boundary source origin escaped active patches")

    end function staged_boundary_source_is_independent

  end subroutine exchange_staged_coarse_vector_boundaries


  logical function block_writeback_plan_is_ready () result(ready)
    ! Report whether the reverse Domain-owner routes match this block store.

    implicit none

    ready = .false.
    if (.not. block_writeback_plan%ready) return
    if (.not. allocated(block_catalog)) return
    if (.not. local_block_store_ready()) return
    if (block_writeback_plan%catalog_size /= size(block_catalog)) return
    if (block_writeback_plan%domain_count /= size(grid)) return
    if (block_writeback_plan%installed_block_count /= &
         n_local_blocks()) return
    if (.not. allocated( &
         block_writeback_plan%native_scalar_stage)) return
    if (.not. allocated( &
         block_writeback_plan%native_vector_stage)) return
    if (.not. allocated( &
         block_writeback_plan%send_boundary_count)) return
    if (.not. allocated( &
         block_writeback_plan%recv_boundary_count)) return
    if (.not. allocated( &
         block_writeback_plan%send_boundary_source)) return
    if (.not. allocated( &
         block_writeback_plan%recv_boundary_source)) return
    if (.not. allocated( &
         block_writeback_plan%send_boundary_level)) return
    if (.not. allocated( &
         block_writeback_plan%recv_boundary_level)) return
    if (.not. allocated( &
         block_writeback_plan%boundary_scalar_domain_send_buffer)) return
    if (.not. allocated( &
         block_writeback_plan%boundary_scalar_block_recv_buffer)) return
    if (.not. allocated( &
         block_writeback_plan%boundary_vector_domain_send_buffer)) return
    if (.not. allocated( &
         block_writeback_plan%boundary_vector_block_recv_buffer)) return
    if (.not. staged_coarse_vector_boundary_plan%ready) return
    if (staged_coarse_vector_boundary_plan%coarse_level /= &
         level_start-1) return
    if (.not. allocated( &
         staged_coarse_vector_boundary_plan%boundary_lookup)) return
    if (.not. allocated( &
         staged_coarse_vector_boundary_plan%source_produced)) return
    if (.not. allocated( &
         staged_coarse_vector_boundary_plan%send_produced_buffer)) return
    if (.not. allocated( &
         staged_coarse_vector_boundary_plan%recv_produced_buffer)) return
    if (.not. allocated( &
         staged_coarse_vector_boundary_plan%boundary_produced)) return
    if (.not. allocated( &
         staged_coarse_vector_boundary_plan%boundary_value)) return
    if (.not. allocated(staged_coarse_vector_boundary_plan% &
         retained_boundary_produced)) return
    if (.not. allocated(staged_coarse_vector_boundary_plan% &
         retained_boundary_value)) return
    ready = .true.

  end function block_writeback_plan_is_ready


  integer(int64) function block_writeback_plan_allocation_count () &
       result(n_allocation)
    ! Count persistent scalar/vector communication-buffer allocations.

    implicit none

    n_allocation = block_writeback_plan%buffer_allocations + &
         staged_coarse_vector_boundary_plan%allocations

  end function block_writeback_plan_allocation_count


  integer(int64) function block_domain_production_writeback_count () &
       result(n_writeback)
    ! Count successful production-facing field-family synchronizations.

    implicit none

    n_writeback = block_writeback_plan%production_writeback_count

  end function block_domain_production_writeback_count


  subroutine check_block_writeback_plan (verbose)
    ! Prove that every final-owner block has exactly one reverse route to
    ! its Domain owner and that all future payload extents balance globally.

    implicit none

    logical, optional, intent(in) :: verbose

    integer :: b
    integer :: destination
    integer :: expected_remote
    integer :: expected_retained
    integer :: ierr
    integer :: pos
    integer :: r
    integer :: stage_patch_count

    integer(int64) :: allocation_before
    integer(int64) :: expected_checksum
    integer(int64) :: global_recv
    integer(int64) :: global_recv_checksum
    integer(int64) :: global_recv_patch
    integer(int64) :: global_recv_scalar
    integer(int64) :: global_recv_vector
    integer(int64) :: global_retained
    integer(int64) :: global_send
    integer(int64) :: global_send_checksum
    integer(int64) :: global_send_patch
    integer(int64) :: global_send_scalar
    integer(int64) :: global_send_vector
    integer(int64) :: local_recv
    integer(int64) :: local_recv_checksum
    integer(int64) :: local_recv_patch
    integer(int64) :: local_recv_scalar
    integer(int64) :: local_recv_vector
    integer(int64) :: local_retained
    integer(int64) :: local_send
    integer(int64) :: local_send_checksum
    integer(int64) :: local_send_patch
    integer(int64) :: local_send_scalar
    integer(int64) :: local_send_vector

    logical :: print_summary
    logical, allocatable :: seen(:)

    print_summary = .true.
    if (present(verbose)) print_summary = verbose

    if (.not. block_writeback_plan_is_ready()) then
       call fail("writeback plan check before plan is ready")
    end if
    if (.not. allocated(block_writeback_plan%send_block) .or. &
         .not. allocated(block_writeback_plan%recv_block) .or. &
         .not. allocated(block_writeback_plan%send_patch_count) .or. &
         .not. allocated(block_writeback_plan%recv_patch_count) .or. &
         .not. allocated(block_writeback_plan%send_scalar_nvalue) .or. &
         .not. allocated(block_writeback_plan%recv_scalar_nvalue) .or. &
         .not. allocated(block_writeback_plan%send_vector_nvalue) .or. &
         .not. allocated(block_writeback_plan%recv_vector_nvalue)) then
       call fail("writeback plan record storage is incomplete")
    end if
    if (.not. allocated(block_writeback_plan%scalar_send_buffer) .or. &
         .not. allocated(block_writeback_plan%scalar_recv_buffer) .or. &
         .not. allocated(block_writeback_plan%vector_send_buffer) .or. &
         .not. allocated(block_writeback_plan%vector_recv_buffer)) then
       call fail("writeback plan payload storage is incomplete")
    end if
    if (.not. allocated(block_writeback_plan%domain_patch_displ) .or. &
         .not. allocated(block_writeback_plan%scalar_domain_stage) .or. &
         .not. allocated(block_writeback_plan%vector_domain_stage) .or. &
         .not. allocated(block_writeback_plan%native_scalar_stage) .or. &
         .not. allocated(block_writeback_plan%native_vector_stage) .or. &
         .not. allocated(block_writeback_plan%domain_patch_covered) .or. &
         .not. allocated( &
         block_writeback_plan%domain_patch_reconstructed) .or. &
         .not. allocated(production_vector_transform_displ) .or. &
         .not. allocated(production_vector_transform_stage) .or. &
         .not. allocated(production_vector_wavelet_stage) .or. &
         .not. allocated(production_vector_transform_covered)) then
       call fail("writeback Domain stage storage is incomplete")
    end if

    if (block_writeback_plan%n_send /= &
         sum(block_writeback_plan%send_count) .or. &
         block_writeback_plan%n_recv /= &
         sum(block_writeback_plan%recv_count)) then
       call fail("writeback plan block totals are inconsistent")
    end if
    if (block_writeback_plan%n_send + &
         block_writeback_plan%n_retained /= n_local_blocks()) then
       call fail("writeback plan does not cover every local block")
    end if
    if (size(block_writeback_plan%scalar_send_buffer) /= max(1, &
         sum(block_writeback_plan%scalar_send_count)) .or. &
         size(block_writeback_plan%scalar_recv_buffer) /= max(1, &
         sum(block_writeback_plan%scalar_recv_count)) .or. &
         size(block_writeback_plan%vector_send_buffer) /= max(1, &
         sum(block_writeback_plan%vector_send_count)) .or. &
         size(block_writeback_plan%vector_recv_buffer) /= max(1, &
         sum(block_writeback_plan%vector_recv_count))) then
       call fail("writeback plan payload buffer extent mismatch")
    end if

    stage_patch_count = 0
    if (size(grid) > 0) then
       stage_patch_count = &
            block_writeback_plan%domain_patch_displ(size(grid)) + &
            grid(size(grid))%patch%length
    end if
    if (size(block_writeback_plan%domain_patch_covered) /= &
         max(1,stage_patch_count) .or. &
         size(block_writeback_plan%domain_patch_reconstructed) /= &
         max(1,stage_patch_count) .or. &
         size(block_writeback_plan%scalar_domain_stage) /= max(1, &
         stage_patch_count* &
         block_writeback_plan%scalar_patch_nvalue) .or. &
         size(block_writeback_plan%vector_domain_stage) /= max(1, &
         stage_patch_count* &
         block_writeback_plan%vector_patch_nvalue) .or. &
         size(block_writeback_plan%native_scalar_stage) /= max(1, &
         stage_patch_count* &
         block_writeback_plan%scalar_patch_nvalue) .or. &
         size(block_writeback_plan%native_vector_stage) /= max(1, &
         stage_patch_count* &
         block_writeback_plan%vector_patch_nvalue)) then
       call fail("writeback Domain stage extent mismatch")
    end if
    if (production_vector_transform_displ(1) /= 0 .or. &
         production_vector_transform_displ(size(grid)+1) /= &
         size(production_vector_transform_stage) .or. &
         size(production_vector_wavelet_stage) /= &
         size(production_vector_transform_stage) .or. &
         size(production_vector_transform_covered) /= &
         size(production_vector_transform_stage)) then
       call fail("complete vector transform stage extent mismatch")
    end if

    allocate(seen(size(block_catalog)))
    seen = .false.

    do r = 0,n_process-1
       do pos = block_writeback_plan%send_displ(r+1)+1, &
            block_writeback_plan%send_displ(r+1) + &
            block_writeback_plan%send_count(r+1)
          b = block_writeback_plan%send_block(pos)
          if (b < 1 .or. b > size(block_catalog)) then
             call fail("writeback send catalogue index is invalid")
          end if
          if (seen(b)) then
             call fail("duplicate block in writeback send manifest")
          end if
          seen(b) = .true.
          destination = source_rank(b)
          if (block_catalog(b)%owner /= rank .or. &
               destination /= r .or. r == rank) then
             call fail("writeback send route is invalid")
          end if
          if (catalog_local_block(b) < 1) then
             call fail("writeback send block is not installed locally")
          end if
          if (block_writeback_plan%send_patch_count(pos) <= 0 .or. &
               block_writeback_plan%send_scalar_nvalue(pos) <= 0 .or. &
               block_writeback_plan%send_vector_nvalue(pos) <= 0) then
             call fail("writeback send record has invalid extent")
          end if
       end do
    end do

    seen = .false.
    do r = 0,n_process-1
       do pos = block_writeback_plan%recv_displ(r+1)+1, &
            block_writeback_plan%recv_displ(r+1) + &
            block_writeback_plan%recv_count(r+1)
          b = block_writeback_plan%recv_block(pos)
          if (b < 1 .or. b > size(block_catalog)) then
             call fail("writeback receive catalogue index is invalid")
          end if
          if (seen(b)) then
             call fail("duplicate block in writeback receive manifest")
          end if
          seen(b) = .true.
          destination = source_rank(b)
          if (block_catalog(b)%owner /= r .or. &
               destination /= rank .or. r == rank) then
             call fail("writeback receive route is invalid")
          end if
          if (block_writeback_plan%recv_patch_count(pos) <= 0 .or. &
               block_writeback_plan%recv_scalar_nvalue(pos) <= 0 .or. &
               block_writeback_plan%recv_vector_nvalue(pos) <= 0) then
             call fail("writeback receive record has invalid extent")
          end if
       end do
    end do

    expected_retained = 0
    do b = 1,size(block_catalog)
       if (source_rank(b) /= rank) cycle
       if (block_catalog(b)%owner == rank) then
          expected_retained = expected_retained + 1
          if (catalog_local_block(b) < 1) then
             call fail("retained writeback block is not installed")
          end if
       else
          if (.not. seen(b)) then
             call fail("Domain-owner writeback block is missing")
          end if
       end if
    end do
    if (block_writeback_plan%n_retained /= expected_retained) then
       call fail("writeback retained-block count mismatch")
    end if
    deallocate(seen)

    allocation_before = block_writeback_plan_allocation_count()
    call build_block_writeback_plan
    if (block_writeback_plan_allocation_count() /= allocation_before) then
       call fail("ready writeback plan reallocated payload buffers")
    end if

    local_send_checksum = 0_int64
    local_recv_checksum = 0_int64
    if (block_writeback_plan%n_send > 0) then
       local_send_checksum = sum(int( &
            block_writeback_plan%send_block( &
            1:block_writeback_plan%n_send),int64))
    end if
    if (block_writeback_plan%n_recv > 0) then
       local_recv_checksum = sum(int( &
            block_writeback_plan%recv_block( &
            1:block_writeback_plan%n_recv),int64))
    end if

    local_send = int(block_writeback_plan%n_send,int64)
    local_recv = int(block_writeback_plan%n_recv,int64)
    local_retained = int(block_writeback_plan%n_retained,int64)
    local_send_patch = 0_int64
    local_recv_patch = 0_int64
    if (block_writeback_plan%n_send > 0) then
       local_send_patch = sum(int( &
            block_writeback_plan%send_patch_count( &
            1:block_writeback_plan%n_send),int64))
    end if
    if (block_writeback_plan%n_recv > 0) then
       local_recv_patch = sum(int( &
            block_writeback_plan%recv_patch_count( &
            1:block_writeback_plan%n_recv),int64))
    end if
    local_send_scalar = sum(int( &
         block_writeback_plan%scalar_send_count,int64))
    local_recv_scalar = sum(int( &
         block_writeback_plan%scalar_recv_count,int64))
    local_send_vector = sum(int( &
         block_writeback_plan%vector_send_count,int64))
    local_recv_vector = sum(int( &
         block_writeback_plan%vector_recv_count,int64))

    call MPI_Allreduce(local_send,global_send,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce writeback send blocks")
    call MPI_Allreduce(local_recv,global_recv,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce writeback receive blocks")
    call MPI_Allreduce(local_retained,global_retained,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce writeback retained blocks")
    call MPI_Allreduce(local_send_checksum,global_send_checksum,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce writeback send checksum")
    call MPI_Allreduce(local_recv_checksum,global_recv_checksum,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce writeback receive checksum")
    call MPI_Allreduce(local_send_patch,global_send_patch,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce writeback send patches")
    call MPI_Allreduce(local_recv_patch,global_recv_patch,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce writeback receive patches")
    call MPI_Allreduce(local_send_scalar,global_send_scalar,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce writeback send scalar values")
    call MPI_Allreduce(local_recv_scalar,global_recv_scalar,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce writeback receive scalar values")
    call MPI_Allreduce(local_send_vector,global_send_vector,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce writeback send vector values")
    call MPI_Allreduce(local_recv_vector,global_recv_vector,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce writeback receive vector values")

    expected_remote = 0
    expected_checksum = 0_int64
    do b = 1,size(block_catalog)
       if (block_catalog(b)%owner == source_rank(b)) cycle
       expected_remote = expected_remote + 1
       expected_checksum = expected_checksum + int(b,int64)
    end do

    if (global_send /= int(expected_remote,int64) .or. &
         global_recv /= int(expected_remote,int64) .or. &
         global_retained+global_send /= &
         int(size(block_catalog),int64)) then
       call fail("global writeback block coverage mismatch")
    end if
    if (global_send_checksum /= expected_checksum .or. &
         global_recv_checksum /= expected_checksum) then
       call fail("global writeback catalogue checksum mismatch")
    end if
    if (global_send_patch /= global_recv_patch .or. &
         global_send_scalar /= global_recv_scalar .or. &
         global_send_vector /= global_recv_vector) then
       call fail("global writeback payload extent mismatch")
    end if

    if (print_summary) then
       write(6,'(/,a,i0,a)') &
            "Persistent block writeback plan for rank ",rank,":"
       write(6,'(a,i0)') "  remote blocks sent     = ", &
            block_writeback_plan%n_send
       write(6,'(a,i0)') "  remote blocks received = ", &
            block_writeback_plan%n_recv
       write(6,'(a,i0)') "  locally retained blocks = ", &
            block_writeback_plan%n_retained
       write(6,'(a,i0)') "  scalar send values      = ", &
            sum(block_writeback_plan%scalar_send_count)
       write(6,'(a,i0)') "  vector send values      = ", &
            sum(block_writeback_plan%vector_send_count)
       write(6,'(a)') "  final-owner to Domain-owner routes passed"
       write(6,'(a)') "  patch and payload extent exchange passed"
       write(6,'(a,/)') "  persistent buffer reuse passed"
    end if

    if (print_summary .and. rank == 0) then
       write(6,'(/,a,i0)') &
            "Global remote block writeback routes = ",global_send
       write(6,'(a,i0)') &
            "Global retained block writeback routes = ",global_retained
       write(6,'(a,i0)') &
            "Global writeback patches = ",global_send_patch
       write(6,'(a,i0)') &
            "Global writeback scalar values = ",global_send_scalar
       write(6,'(a,i0)') &
            "Global writeback vector values = ",global_send_vector
       write(6,'(a,/)') &
            "Persistent block-to-Domain writeback plan passed"
    end if

  end subroutine check_block_writeback_plan


  subroutine exchange_block_writeback_payloads (payload_family)
    ! Pack one scalar/vector prognostic-field family owned by final block
    ! ranks and transport it back to the legacy Domain owners.
    ! The persistent plan buffers are reused and Domain fields are unchanged.

    implicit none

    integer, optional, intent(in) :: payload_family

    integer :: b
    integer :: family
    integer :: ierr
    integer :: local_patch
    integer :: n_patch
    integer :: n_scalar_patch
    integer :: n_vector_patch
    integer :: pos_scalar
    integer :: pos_vector
    integer :: r
    integer :: slot

    if (.not. block_writeback_plan_is_ready()) then
       call fail("writeback payload exchange before plan is ready")
    end if

    family = BLOCK_PAYLOAD_SOL
    if (present(payload_family)) family = payload_family
    if (family /= BLOCK_PAYLOAD_SOL .and. &
         family /= BLOCK_PAYLOAD_WAV_COEFF) then
       call fail("invalid writeback payload family")
    end if

    block_writeback_plan%scalar_send_buffer = 0.0_dp
    block_writeback_plan%scalar_recv_buffer = 0.0_dp
    block_writeback_plan%vector_send_buffer = 0.0_dp
    block_writeback_plan%vector_recv_buffer = 0.0_dp

    do r = 1,n_process
       pos_scalar = block_writeback_plan%scalar_send_displ(r) + 1
       pos_vector = block_writeback_plan%vector_send_displ(r) + 1

       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)
          b = block_writeback_plan%send_block(slot)
          n_patch = local_block_patch_count(b)
          n_scalar_patch = local_block_scalar_family_patch_nvalue(b)
          n_vector_patch = local_block_vector_family_patch_nvalue(b)

          if (n_patch /= block_writeback_plan%send_patch_count(slot) .or. &
               n_patch*n_scalar_patch /= &
               block_writeback_plan%send_scalar_nvalue(slot) .or. &
               n_patch*n_vector_patch /= &
               block_writeback_plan%send_vector_nvalue(slot)) then
             call fail("writeback payload source extent changed")
          end if

          do local_patch = 0,n_patch-1
             call get_local_block_scalar_patch_family_values( &
                  b,local_patch,family, &
                  block_writeback_plan%scalar_send_buffer( &
                  pos_scalar:pos_scalar+n_scalar_patch-1))
             call get_local_block_vector_patch_family_values( &
                  b,local_patch,family, &
                  block_writeback_plan%vector_send_buffer( &
                  pos_vector:pos_vector+n_vector_patch-1))
             pos_scalar = pos_scalar + n_scalar_patch
             pos_vector = pos_vector + n_vector_patch
          end do
       end do

       if (pos_scalar /= block_writeback_plan%scalar_send_displ(r) + &
            block_writeback_plan%scalar_send_count(r) + 1 .or. &
            pos_vector /= block_writeback_plan%vector_send_displ(r) + &
            block_writeback_plan%vector_send_count(r) + 1) then
          call fail("writeback packed send extent mismatch")
       end if
    end do

    call MPI_Alltoallv( &
         block_writeback_plan%scalar_send_buffer, &
         block_writeback_plan%scalar_send_count, &
         block_writeback_plan%scalar_send_displ, &
         MPI_DOUBLE_PRECISION, &
         block_writeback_plan%scalar_recv_buffer, &
         block_writeback_plan%scalar_recv_count, &
         block_writeback_plan%scalar_recv_displ, &
         MPI_DOUBLE_PRECISION,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv writeback scalar-family payload")

    call MPI_Alltoallv( &
         block_writeback_plan%vector_send_buffer, &
         block_writeback_plan%vector_send_count, &
         block_writeback_plan%vector_send_displ, &
         MPI_DOUBLE_PRECISION, &
         block_writeback_plan%vector_recv_buffer, &
         block_writeback_plan%vector_recv_count, &
         block_writeback_plan%vector_recv_displ, &
         MPI_DOUBLE_PRECISION,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv writeback vector-family payload")

  end subroutine exchange_block_writeback_payloads


  subroutine check_block_writeback_payload_exchange (verbose)
    ! Compare every remotely transported sol and wav_coeff value with the
    ! exact values still held by its destination Domain owner. Repeat each
    ! exchange to prove that the persistent communication storage is reused
    ! without changing the authoritative Domain representation.

    implicit none

    logical, optional, intent(in) :: verbose

    integer :: b
    integer :: d
    integer :: ierr
    integer :: n_patch
    integer :: pos_scalar
    integer :: pos_vector
    integer :: r
    integer :: scalar_start
    integer :: slot
    integer :: vector_start

    integer(int64) :: allocation_before
    integer(int64) :: global_scalar
    integer(int64) :: global_vector
    integer(int64) :: local_scalar
    integer(int64) :: local_vector

    logical :: print_summary

    real(dp), allocatable :: expected_scalar(:)
    real(dp), allocatable :: expected_vector(:)

    print_summary = .true.
    if (present(verbose)) print_summary = verbose

    if (.not. block_writeback_plan_is_ready()) then
       call fail("writeback payload check before plan is ready")
    end if

    allocate(expected_scalar(size( &
         block_writeback_plan%scalar_recv_buffer)))
    allocate(expected_vector(size( &
         block_writeback_plan%vector_recv_buffer)))

    allocation_before = block_writeback_plan_allocation_count()

    call check_writeback_family(BLOCK_PAYLOAD_SOL)
    call check_writeback_family(BLOCK_PAYLOAD_WAV_COEFF)

    if (block_writeback_plan_allocation_count() /= allocation_before) then
       call fail("writeback payload exchange reallocated plan buffers")
    end if

    local_scalar = int(sum( &
         block_writeback_plan%scalar_recv_count),int64)
    local_vector = int(sum( &
         block_writeback_plan%vector_recv_count),int64)

    call MPI_Allreduce(local_scalar,global_scalar,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce transported scalar values")
    call MPI_Allreduce(local_vector,global_vector,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce transported vector values")

    if (print_summary) then
       write(6,'(/,a,i0,a)') &
            "Block writeback payload exchange for rank ",rank,":"
       write(6,'(a,i0)') "  scalar values received = ",local_scalar
       write(6,'(a,i0)') "  vector values received = ",local_vector
       write(6,'(a)') "  exact sol Domain payload comparison passed"
       write(6,'(a)') "  exact wav_coeff Domain payload comparison passed"
       write(6,'(a)') "  repeated sol exchange passed"
       write(6,'(a,/)') "  repeated wav_coeff exchange passed"
    end if

    if (print_summary .and. rank == 0) then
       write(6,'(/,a,i0)') &
            "Global transported writeback scalar values = ", &
            global_scalar
       write(6,'(a,i0)') &
            "Global transported writeback vector values = ", &
            global_vector
       write(6,'(a,/)') &
            "Exact sol/wav_coeff block-to-Domain transport passed"
    end if

    deallocate(expected_vector)
    deallocate(expected_scalar)

  contains

    subroutine check_writeback_family (payload_family)

      implicit none

      integer, intent(in) :: payload_family

      call exchange_block_writeback_payloads(payload_family)
      call build_expected_writeback_payloads( &
           payload_family,expected_scalar,expected_vector)
      call compare_writeback_payloads( &
           payload_family,expected_scalar,expected_vector)

      call exchange_block_writeback_payloads(payload_family)
      call build_expected_writeback_payloads( &
           payload_family,expected_scalar,expected_vector)
      call compare_writeback_payloads( &
           payload_family,expected_scalar,expected_vector)

    end subroutine check_writeback_family

    subroutine build_expected_writeback_payloads ( &
         payload_family,scalar_payload,vector_payload)

      implicit none

      integer, intent(in) :: payload_family
      real(dp), intent(out) :: scalar_payload(:)
      real(dp), intent(out) :: vector_payload(:)

      scalar_payload = 0.0_dp
      vector_payload = 0.0_dp

      do r = 1,n_process
         pos_scalar = block_writeback_plan%scalar_recv_displ(r) + 1
         pos_vector = block_writeback_plan%vector_recv_displ(r) + 1

         do slot = block_writeback_plan%recv_displ(r)+1, &
              block_writeback_plan%recv_displ(r) + &
              block_writeback_plan%recv_count(r)
            b = block_writeback_plan%recv_block(slot)
            if (source_rank(b) /= rank) then
               call fail("writeback payload arrived at wrong Domain owner")
            end if
            if (block_catalog(b)%owner /= r-1) then
               call fail("writeback payload came from wrong block owner")
            end if

            d = loc_id(block_catalog(b)%root_domain+1) + 1
            if (d < 1 .or. d > size(grid)) then
               call fail("writeback payload has invalid local Domain")
            end if

            scalar_start = pos_scalar
            vector_start = pos_vector
            n_patch = 0
            call pack_domain_subtree_prognostic( &
                 d,block_catalog(b)%root_patch,payload_family, &
                 scalar_payload,pos_scalar, &
                 vector_payload,pos_vector,n_patch)

            if (n_patch /= &
                 block_writeback_plan%recv_patch_count(slot) .or. &
                 pos_scalar-scalar_start /= &
                 block_writeback_plan%recv_scalar_nvalue(slot) .or. &
                 pos_vector-vector_start /= &
                 block_writeback_plan%recv_vector_nvalue(slot)) then
               call fail("writeback expected payload extent mismatch")
            end if
         end do

         if (pos_scalar /= block_writeback_plan%scalar_recv_displ(r) + &
              block_writeback_plan%scalar_recv_count(r) + 1 .or. &
              pos_vector /= block_writeback_plan%vector_recv_displ(r) + &
              block_writeback_plan%vector_recv_count(r) + 1) then
            call fail("writeback expected receive extent mismatch")
         end if
      end do

    end subroutine build_expected_writeback_payloads


    subroutine compare_writeback_payloads ( &
         payload_family,scalar_payload,vector_payload)

      implicit none

      integer, intent(in) :: payload_family
      real(dp), intent(in) :: scalar_payload(:)
      real(dp), intent(in) :: vector_payload(:)

      integer :: n_scalar
      integer :: n_vector

      n_scalar = sum(block_writeback_plan%scalar_recv_count)
      n_vector = sum(block_writeback_plan%vector_recv_count)

      if (n_scalar > 0) then
         if (any(abs(block_writeback_plan%scalar_recv_buffer( &
              1:n_scalar)-scalar_payload(1:n_scalar)) > 0.0_dp)) then
            if (payload_family == BLOCK_PAYLOAD_SOL) then
               call fail("transported scalar sol writeback mismatch")
            else
               call fail("transported scalar wav_coeff writeback mismatch")
            end if
         end if
      end if
      if (n_vector > 0) then
         if (any(abs(block_writeback_plan%vector_recv_buffer( &
              1:n_vector)-vector_payload(1:n_vector)) > 0.0_dp)) then
            if (payload_family == BLOCK_PAYLOAD_SOL) then
               call fail("transported vector sol writeback mismatch")
            else
               call fail("transported vector wav_coeff writeback mismatch")
            end if
         end if
      end if

    end subroutine compare_writeback_payloads

  end subroutine check_block_writeback_payload_exchange


  subroutine exchange_domain_to_block_payloads ( &
       payload_family,tag_payload,domain_sol)
    ! Reverse the persistent writeback routes without reallocating them.
    ! Domain owners pack one field family and final block owners receive the
    ! payload in catalogue order. Neither representation is modified.

    implicit none

    integer, intent(in) :: payload_family
    logical, optional, intent(in) :: tag_payload
    type(Float_Field), optional, intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)

    integer :: b
    integer :: d
    integer :: destination
    integer :: ierr
    integer :: i
    integer :: n_patch
    integer :: pos_scalar
    integer :: pos_vector
    integer :: r
    integer :: scalar_start
    integer :: slot
    integer :: vector_start

    logical :: plan_ready
    logical :: use_tags

    use_tags = .false.
    if (present(tag_payload)) use_tags = tag_payload
    plan_ready = block_writeback_plan_is_ready()
    if (.not. plan_ready) then
       call fail("Domain-to-block exchange before plan is ready")
    end if
    if (payload_family /= BLOCK_PAYLOAD_SOL .and. &
         payload_family /= BLOCK_PAYLOAD_WAV_COEFF .and. &
         payload_family /= BLOCK_PAYLOAD_TREND .and. &
         payload_family /= BLOCK_PAYLOAD_THETA_EDGE .and. &
         payload_family /= BLOCK_PAYLOAD_EXNER_DIFFERENCE .and. &
         payload_family /= BLOCK_PAYLOAD_THERMODYNAMIC_GRADIENT .and. &
         payload_family /= BLOCK_PAYLOAD_COMPLETE_EXNER_GRADIENT .and. &
         payload_family /= BLOCK_PAYLOAD_EDGE_LENGTH .and. &
         payload_family /= BLOCK_PAYLOAD_VELOCITY_REMAINDER .and. &
         payload_family /= BLOCK_PAYLOAD_COMPLETE_VELOCITY .and. &
         payload_family /= BLOCK_PAYLOAD_PHYSICAL_COMPONENTS .and. &
         payload_family /= &
         BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY) then
       call fail("invalid Domain-to-block payload family")
    end if

    block_writeback_plan%scalar_recv_buffer = 0.0_dp
    block_writeback_plan%vector_recv_buffer = 0.0_dp
    block_writeback_plan%scalar_send_buffer = 0.0_dp
    block_writeback_plan%vector_send_buffer = 0.0_dp

    do r = 1,n_process
       pos_scalar = block_writeback_plan%scalar_recv_displ(r) + 1
       pos_vector = block_writeback_plan%vector_recv_displ(r) + 1

       do slot = block_writeback_plan%recv_displ(r)+1, &
            block_writeback_plan%recv_displ(r) + &
            block_writeback_plan%recv_count(r)
          b = block_writeback_plan%recv_block(slot)
          destination = source_rank(b)
          if (destination /= rank) then
             call fail("Domain-to-block source is not the Domain owner")
          end if
          if (block_catalog(b)%owner /= r-1) then
             call fail("Domain-to-block destination owner mismatch")
          end if

          d = loc_id(block_catalog(b)%root_domain+1) + 1
          if (d < 1 .or. d > size(grid)) then
             call fail("Domain-to-block source Domain is invalid")
          end if

          scalar_start = pos_scalar
          vector_start = pos_vector
          n_patch = 0
          call pack_domain_subtree_prognostic( &
               d,block_catalog(b)%root_patch,payload_family, &
               block_writeback_plan%scalar_recv_buffer,pos_scalar, &
               block_writeback_plan%vector_recv_buffer,pos_vector, &
               n_patch,domain_sol)

          if (use_tags) then
             do i = scalar_start,pos_scalar-1
                block_writeback_plan%scalar_recv_buffer(i) = &
                     block_writeback_plan%scalar_recv_buffer(i) + &
                     real(int(b,int64) + &
                     int(i-scalar_start+1,int64),dp)
             end do
             do i = vector_start,pos_vector-1
                block_writeback_plan%vector_recv_buffer(i) = &
                     block_writeback_plan%vector_recv_buffer(i) - &
                     real(int(b,int64) + &
                     int(i-vector_start+1,int64),dp)
             end do
          end if

          if (n_patch /= &
               block_writeback_plan%recv_patch_count(slot) .or. &
               pos_scalar-scalar_start /= &
               block_writeback_plan%recv_scalar_nvalue(slot) .or. &
               pos_vector-vector_start /= &
               block_writeback_plan%recv_vector_nvalue(slot)) then
             call fail("Domain-to-block packed payload extent mismatch")
          end if
       end do

       if (pos_scalar /= block_writeback_plan%scalar_recv_displ(r) + &
            block_writeback_plan%scalar_recv_count(r) + 1 .or. &
            pos_vector /= block_writeback_plan%vector_recv_displ(r) + &
            block_writeback_plan%vector_recv_count(r) + 1) then
          call fail("Domain-to-block send extent mismatch")
       end if
    end do

    call MPI_Alltoallv( &
         block_writeback_plan%scalar_recv_buffer, &
         block_writeback_plan%scalar_recv_count, &
         block_writeback_plan%scalar_recv_displ, &
         MPI_DOUBLE_PRECISION, &
         block_writeback_plan%scalar_send_buffer, &
         block_writeback_plan%scalar_send_count, &
         block_writeback_plan%scalar_send_displ, &
         MPI_DOUBLE_PRECISION,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv Domain-to-block scalar payload")

    call MPI_Alltoallv( &
         block_writeback_plan%vector_recv_buffer, &
         block_writeback_plan%vector_recv_count, &
         block_writeback_plan%vector_recv_displ, &
         MPI_DOUBLE_PRECISION, &
         block_writeback_plan%vector_send_buffer, &
         block_writeback_plan%vector_send_count, &
         block_writeback_plan%vector_send_displ, &
         MPI_DOUBLE_PRECISION,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv Domain-to-block vector payload")

  end subroutine exchange_domain_to_block_payloads


  subroutine check_domain_to_block_payload_exchange (verbose)
    ! Compare reverse-transported Domain sol and wav_coeff values with the
    ! installed final-owner blocks. Repeat both exchanges to prove reuse.

    implicit none

    logical, optional, intent(in) :: verbose

    integer :: ierr

    integer(int64) :: allocation_after
    integer(int64) :: allocation_before
    integer(int64) :: global_scalar
    integer(int64) :: global_vector
    integer(int64) :: local_scalar
    integer(int64) :: local_vector
    integer(int64) :: stage_allocation_after
    integer(int64) :: stage_allocation_before

    logical :: plan_ready
    logical :: print_summary

    real(dp), allocatable :: expected_scalar(:)
    real(dp), allocatable :: expected_vector(:)

    print_summary = .true.
    if (present(verbose)) print_summary = verbose

    plan_ready = block_writeback_plan_is_ready()
    if (.not. plan_ready) then
       call fail("Domain-to-block check before plan is ready")
    end if
    if (block_writeback_plan%scalar_patch_nvalue <= 0 .or. &
         block_writeback_plan%vector_patch_nvalue <= 0) then
       call fail("Domain-to-block patch payload layout is invalid")
    end if

    allocate(expected_scalar( &
         block_writeback_plan%scalar_patch_nvalue))
    allocate(expected_vector( &
         block_writeback_plan%vector_patch_nvalue))

    allocation_before = block_writeback_plan_allocation_count()
    stage_allocation_before = block_writeback_plan%stage_allocations

    call check_family(BLOCK_PAYLOAD_SOL)
    call check_family(BLOCK_PAYLOAD_WAV_COEFF)

    allocation_after = block_writeback_plan_allocation_count()
    stage_allocation_after = block_writeback_plan%stage_allocations
    if (allocation_after /= allocation_before) then
       call fail("Domain-to-block exchange reallocated payload buffers")
    end if
    if (stage_allocation_after /= stage_allocation_before) then
       call fail("Domain-to-block exchange reallocated Domain staging")
    end if

    local_scalar = sum(int( &
         block_writeback_plan%scalar_send_count,int64))
    local_vector = sum(int( &
         block_writeback_plan%vector_send_count,int64))
    call MPI_Allreduce(local_scalar,global_scalar,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce Domain-to-block scalar values")
    call MPI_Allreduce(local_vector,global_vector,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce Domain-to-block vector values")

    if (print_summary) then
       write(6,'(/,a,i0,a)') &
            "Domain-to-block payload exchange for rank ",rank,":"
       write(6,'(a,i0)') "  scalar values received = ",local_scalar
       write(6,'(a,i0)') "  vector values received = ",local_vector
       write(6,'(a)') "  exact sol block payload comparison passed"
       write(6,'(a)') "  exact wav_coeff block payload comparison passed"
       write(6,'(a)') "  repeated sol reverse exchange passed"
       write(6,'(a,/)') "  repeated wav_coeff reverse exchange passed"
    end if

    if (print_summary .and. rank == 0) then
       write(6,'(/,a,i0)') &
            "Global Domain-to-block scalar values = ",global_scalar
       write(6,'(a,i0)') &
            "Global Domain-to-block vector values = ",global_vector
       write(6,'(a,/)') &
            "Exact Domain-to-final-block reverse transport passed"
    end if

    deallocate(expected_vector)
    deallocate(expected_scalar)

  contains

    subroutine check_family (payload_family)

      implicit none

      integer, intent(in) :: payload_family

      call exchange_domain_to_block_payloads(payload_family)
      call compare_received_payloads(payload_family)
      call exchange_domain_to_block_payloads(payload_family)
      call compare_received_payloads(payload_family)

    end subroutine check_family


    subroutine compare_received_payloads (payload_family)

      implicit none

      integer, intent(in) :: payload_family

      integer :: b
      integer :: destination
      integer :: local_patch
      integer :: n_patch
      integer :: pos_scalar
      integer :: pos_vector
      integer :: r
      integer :: scalar_start
      integer :: slot
      integer :: vector_start

      do r = 1,n_process
         pos_scalar = block_writeback_plan%scalar_send_displ(r) + 1
         pos_vector = block_writeback_plan%vector_send_displ(r) + 1

         do slot = block_writeback_plan%send_displ(r)+1, &
              block_writeback_plan%send_displ(r) + &
              block_writeback_plan%send_count(r)
            b = block_writeback_plan%send_block(slot)
            destination = source_rank(b)
            if (block_catalog(b)%owner /= rank) then
               call fail("reverse payload arrived at wrong block owner")
            end if
            if (destination /= r-1) then
               call fail("reverse payload came from wrong Domain owner")
            end if

            scalar_start = pos_scalar
            vector_start = pos_vector
            n_patch = local_block_patch_count(b)

            do local_patch = 0,n_patch-1
               call get_local_block_scalar_patch_family_values( &
                    b,local_patch,payload_family,expected_scalar)
               call get_local_block_vector_patch_family_values( &
                    b,local_patch,payload_family,expected_vector)

               if (pos_scalar < 1 .or. pos_scalar + &
                    size(expected_scalar)-1 > &
                    size(block_writeback_plan%scalar_send_buffer) .or. &
                    pos_vector < 1 .or. pos_vector + &
                    size(expected_vector)-1 > &
                    size(block_writeback_plan%vector_send_buffer)) then
                  call fail("reverse received payload buffer is too small")
               end if

               if (any(abs( &
                    block_writeback_plan%scalar_send_buffer( &
                    pos_scalar:pos_scalar+size(expected_scalar)-1) - &
                    expected_scalar) > 0.0_dp)) then
                  if (payload_family == BLOCK_PAYLOAD_SOL) then
                     call fail("reverse transported scalar sol mismatch")
                  else
                     call fail( &
                          "reverse transported scalar wav_coeff mismatch")
                  end if
               end if
               if (any(abs( &
                    block_writeback_plan%vector_send_buffer( &
                    pos_vector:pos_vector+size(expected_vector)-1) - &
                    expected_vector) > 0.0_dp)) then
                  if (payload_family == BLOCK_PAYLOAD_SOL) then
                     call fail("reverse transported vector sol mismatch")
                  else
                     call fail( &
                          "reverse transported vector wav_coeff mismatch")
                  end if
               end if

               pos_scalar = pos_scalar + size(expected_scalar)
               pos_vector = pos_vector + size(expected_vector)
            end do

            if (pos_scalar-scalar_start /= &
                 block_writeback_plan%send_scalar_nvalue(slot) .or. &
                 pos_vector-vector_start /= &
                 block_writeback_plan%send_vector_nvalue(slot) .or. &
                 n_patch /= &
                 block_writeback_plan%send_patch_count(slot)) then
               call fail("reverse received payload extent mismatch")
            end if
         end do

         if (pos_scalar /= block_writeback_plan%scalar_send_displ(r) + &
              block_writeback_plan%scalar_send_count(r) + 1 .or. &
              pos_vector /= block_writeback_plan%vector_send_displ(r) + &
              block_writeback_plan%vector_send_count(r) + 1) then
            call fail("Domain-to-block receive extent mismatch")
         end if
      end do

    end subroutine compare_received_payloads

  end subroutine check_domain_to_block_payload_exchange


  subroutine import_domain_field_family_to_blocks ( &
       payload_family,domain_sol,preserve_checkpoint)
    ! Preflight and install one complete Domain prognostic family into every
    ! final-owner block patch using the persistent reverse-route buffers.

    implicit none

    integer, intent(in) :: payload_family
    type(Float_Field), optional, intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    logical, optional, intent(in) :: preserve_checkpoint

    integer :: b
    integer :: d
    integer :: expected_patch_count
    integer :: imported_patch_count
    integer :: local_index
    integer :: local_patch
    integer :: n_patch
    integer :: n_scalar_patch
    integer :: n_vector_patch
    integer :: pos_scalar
    integer :: pos_vector
    integer :: r
    integer :: source
    integer :: slot

    logical :: checkpoint_ready
    logical :: import_active
    logical :: keep_checkpoint
    logical :: plan_ready
    logical :: store_ready
    logical :: trial_active

    keep_checkpoint = .false.
    if (present(preserve_checkpoint)) then
       keep_checkpoint = preserve_checkpoint
    end if

    store_ready = local_block_store_ready()
    plan_ready = block_writeback_plan_is_ready()
    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    import_active = local_block_tendency_import_is_active()
    if (.not. store_ready .or. .not. plan_ready) then
       call fail("Domain prognostic import before block state is ready")
    end if
    if (trial_active .or. import_active .or. &
         (checkpoint_ready .and. .not. keep_checkpoint)) then
       call fail("Domain prognostic import found a pending transaction")
    end if
    if (keep_checkpoint .and. .not. checkpoint_ready) then
       call fail("Domain prognostic import has no checkpoint to preserve")
    end if
    if (present(domain_sol)) then
       if (.not. keep_checkpoint) then
          call fail("stage Domain prognostic import has no checkpoint guard")
       end if
    else
       if (keep_checkpoint .and. &
            payload_family /= BLOCK_PAYLOAD_WAV_COEFF) then
          call fail("checkpoint-preserving import has no stage payload")
       end if
    end if
    if (payload_family /= BLOCK_PAYLOAD_SOL .and. &
         payload_family /= BLOCK_PAYLOAD_WAV_COEFF) then
       call fail("invalid Domain prognostic import family")
    end if
    if (present(domain_sol)) then
       if (payload_family /= BLOCK_PAYLOAD_SOL) then
          call fail("stage Domain prognostic import is not sol")
       end if
    end if
    if (.not. allocated(ghost_exchange_plan%scalar_patch_buffer)) then
       call fail("Domain prognostic scalar patch buffer is not allocated")
    end if
    if (.not. allocated(ghost_exchange_plan%vector_patch_buffer)) then
       call fail("Domain prognostic vector patch buffer is not allocated")
    end if
    if (size(ghost_exchange_plan%scalar_patch_buffer) /= &
         block_writeback_plan%scalar_patch_nvalue .or. &
         size(ghost_exchange_plan%vector_patch_buffer) /= &
         block_writeback_plan%vector_patch_nvalue) then
       call fail("Domain prognostic import patch layout mismatch")
    end if

    expected_patch_count = 0
    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       n_patch = local_block_patch_count(b)
       n_scalar_patch = local_block_scalar_family_patch_nvalue(b)
       n_vector_patch = local_block_vector_family_patch_nvalue(b)
       if (n_patch < 1 .or. &
            n_scalar_patch /= &
            block_writeback_plan%scalar_patch_nvalue .or. &
            n_vector_patch /= &
            block_writeback_plan%vector_patch_nvalue) then
          call fail("Domain prognostic local block layout mismatch")
       end if
       expected_patch_count = expected_patch_count + n_patch

       r = source_rank(b)
       if (r == rank) then
          d = loc_id(block_catalog(b)%root_domain+1) + 1
          if (d < 1 .or. d > size(grid)) then
             call fail("Domain prognostic retained Domain is invalid")
          end if
          local_patch = 0
          call count_retained_subtree( &
               d,block_catalog(b)%root_patch,local_patch)
          if (local_patch /= n_patch) then
             call fail("Domain prognostic retained coverage mismatch")
          end if
       end if
    end do

    do r = 1,n_process
       pos_scalar = block_writeback_plan%scalar_send_displ(r) + 1
       pos_vector = block_writeback_plan%vector_send_displ(r) + 1
       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)
          b = block_writeback_plan%send_block(slot)
          source = source_rank(b)
          if (source /= r-1 .or. &
               block_catalog(b)%owner /= rank) then
             call fail("Domain prognostic reverse route mismatch")
          end if
          n_patch = local_block_patch_count(b)
          pos_scalar = pos_scalar + n_patch* &
               block_writeback_plan%scalar_patch_nvalue
          pos_vector = pos_vector + n_patch* &
               block_writeback_plan%vector_patch_nvalue
       end do
       if (pos_scalar /= block_writeback_plan%scalar_send_displ(r) + &
            block_writeback_plan%scalar_send_count(r) + 1 .or. &
            pos_vector /= block_writeback_plan%vector_send_displ(r) + &
            block_writeback_plan%vector_send_count(r) + 1) then
          call fail("Domain prognostic reverse buffer extent mismatch")
       end if
    end do

    call exchange_domain_to_block_payloads( &
         payload_family,domain_sol=domain_sol)

    imported_patch_count = 0
    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       r = source_rank(b)
       if (r /= rank) cycle
       d = loc_id(block_catalog(b)%root_domain+1) + 1
       local_patch = 0
       call import_retained_subtree( &
            d,block_catalog(b)%root_patch,b,local_patch)
       if (local_patch /= local_block_patch_count(b)) then
          call fail("retained Domain prognostic import is incomplete")
       end if
       imported_patch_count = imported_patch_count + local_patch
    end do

    do r = 1,n_process
       pos_scalar = block_writeback_plan%scalar_send_displ(r) + 1
       pos_vector = block_writeback_plan%vector_send_displ(r) + 1
       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)
          b = block_writeback_plan%send_block(slot)
          n_patch = local_block_patch_count(b)
          do local_patch = 0,n_patch-1
             if (pos_scalar < 1 .or. pos_scalar + &
                  block_writeback_plan%scalar_patch_nvalue - 1 > &
                  size(block_writeback_plan%scalar_send_buffer) .or. &
                  pos_vector < 1 .or. pos_vector + &
                  block_writeback_plan%vector_patch_nvalue - 1 > &
                  size(block_writeback_plan%vector_send_buffer)) then
                call fail("Domain prognostic import payload is truncated")
             end if
             call set_local_block_scalar_patch_family_values( &
                  b,local_patch,payload_family, &
                  block_writeback_plan%scalar_send_buffer( &
                  pos_scalar:pos_scalar+ &
                  block_writeback_plan%scalar_patch_nvalue-1))
             call set_local_block_vector_patch_family_values( &
                  b,local_patch,payload_family, &
                  block_writeback_plan%vector_send_buffer( &
                  pos_vector:pos_vector+ &
                  block_writeback_plan%vector_patch_nvalue-1))
             pos_scalar = pos_scalar + &
                  block_writeback_plan%scalar_patch_nvalue
             pos_vector = pos_vector + &
                  block_writeback_plan%vector_patch_nvalue
          end do
          imported_patch_count = imported_patch_count + n_patch
       end do
       if (pos_scalar /= block_writeback_plan%scalar_send_displ(r) + &
            block_writeback_plan%scalar_send_count(r) + 1 .or. &
            pos_vector /= block_writeback_plan%vector_send_displ(r) + &
            block_writeback_plan%vector_send_count(r) + 1) then
          call fail("Domain prognostic import consumed wrong buffer extent")
       end if
    end do

    if (imported_patch_count /= expected_patch_count) then
       call fail("Domain prognostic import local coverage mismatch")
    end if
    if (payload_family == BLOCK_PAYLOAD_SOL) then
       if (.not. keep_checkpoint) then
          call invalidate_local_block_tendency_products
       end if
    end if

  contains

    recursive subroutine count_retained_subtree (d,p,n_patch)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(inout) :: n_patch

      integer :: c
      integer :: p_child

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("Domain prognostic retained patch is invalid")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return
      if (.not. domain_patch_prognostic_extent_is_valid( &
           d,p,payload_family)) then
         call fail("Domain prognostic retained extent is invalid")
      end if
      n_patch = n_patch + 1
      do c = 1,N_CHDRN
         p_child = grid(d)%patch%elts(p+1)%children(c)
         if (p_child <= 0) cycle
         call count_retained_subtree(d,p_child,n_patch)
      end do

    end subroutine count_retained_subtree


    recursive subroutine import_retained_subtree ( &
         d,p,b,local_patch)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(in) :: b
      integer, intent(inout) :: local_patch

      integer :: c
      integer :: p_child
      integer :: scalar_pos
      integer :: vector_pos

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("retained Domain prognostic import patch is invalid")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return

      scalar_pos = 1
      vector_pos = 1
      call pack_domain_patch_prognostic( &
           d,p,payload_family, &
           ghost_exchange_plan%scalar_patch_buffer,scalar_pos, &
           ghost_exchange_plan%vector_patch_buffer,vector_pos, &
           domain_sol)
      if (scalar_pos /= &
           size(ghost_exchange_plan%scalar_patch_buffer)+1 .or. &
           vector_pos /= &
           size(ghost_exchange_plan%vector_patch_buffer)+1) then
         call fail("retained Domain prognostic patch extent mismatch")
      end if
      call set_local_block_scalar_patch_family_values( &
           b,local_patch,payload_family, &
           ghost_exchange_plan%scalar_patch_buffer)
      call set_local_block_vector_patch_family_values( &
           b,local_patch,payload_family, &
           ghost_exchange_plan%vector_patch_buffer)
      local_patch = local_patch + 1

      do c = 1,N_CHDRN
         p_child = grid(d)%patch%elts(p+1)%children(c)
         if (p_child <= 0) cycle
         call import_retained_subtree(d,p_child,b,local_patch)
      end do

    end subroutine import_retained_subtree

  end subroutine import_domain_field_family_to_blocks


  subroutine import_domain_boundary_field_family_to_blocks ( &
       payload_family,verify_current,domain_sol)
    ! Install one complete Domain boundary prognostic family in final-owner
    ! compact boundary storage. Remote payloads reuse the persistent
    ! boundary manifest and buffers; retained blocks use a direct path.

    implicit none

    integer, intent(in) :: payload_family
    logical, optional, intent(in) :: verify_current
    type(Float_Field), optional, intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)

    integer :: b
    integer :: boundary_index
    integer :: d
    integer :: elts_start
    integer :: ierr
    integer :: local_index
    integer :: metadata_pos
    integer :: n_boundary
    integer :: n_node
    integer :: n_scalar
    integer :: n_vector
    integer :: pos_scalar
    integer :: pos_vector
    integer :: r
    integer :: slot
    integer :: source
    integer :: source_bdry

    logical :: check_current
    logical :: plan_ready

    check_current = .false.
    if (present(verify_current)) check_current = verify_current
    plan_ready = block_writeback_plan_is_ready()
    if (.not. plan_ready) then
       call fail("Domain boundary import before plan is ready")
    end if
    if (payload_family /= BLOCK_PAYLOAD_SOL .and. &
         payload_family /= BLOCK_PAYLOAD_WAV_COEFF) then
       call fail("invalid Domain boundary import family")
    end if

    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       d = 0
       source = source_rank(b)
       n_boundary = local_block_boundary_count(b)
       if (source == rank) then
          d = loc_id(block_catalog(b)%root_domain+1) + 1
          if (d < 1 .or. d > size(grid)) then
             call fail("Domain boundary preflight has invalid Domain")
          end if
       end if
       do boundary_index = 1,n_boundary
          call get_local_block_boundary_source( &
               b,boundary_index,source_bdry,elts_start,n_node)
          n_scalar = local_block_scalar_family_boundary_nvalue( &
               b,boundary_index)
          n_vector = local_block_vector_family_boundary_nvalue( &
               b,boundary_index)
          if (n_scalar > &
               size(ghost_exchange_plan%scalar_patch_buffer) .or. &
               n_vector > &
               size(ghost_exchange_plan%vector_patch_buffer)) then
             call fail("Domain boundary preflight scratch extent")
          end if
          if (source == rank) then
             if (source_bdry < 0 .or. &
                  source_bdry >= grid(d)%bdry_patch%length) then
                call fail("Domain boundary preflight source is invalid")
             end if
             if (grid(d)%bdry_patch%elts(source_bdry+1)%elts_start /= &
                  elts_start) then
                call fail("Domain boundary preflight offset changed")
             end if
          end if
       end do
    end do

    block_writeback_plan%boundary_scalar_domain_send_buffer = 0.0_dp
    block_writeback_plan%boundary_scalar_block_recv_buffer = 0.0_dp
    block_writeback_plan%boundary_vector_domain_send_buffer = 0.0_dp
    block_writeback_plan%boundary_vector_block_recv_buffer = 0.0_dp

    do r = 1,n_process
       pos_scalar = block_writeback_plan% &
            boundary_scalar_domain_send_displ(r) + 1
       pos_vector = block_writeback_plan% &
            boundary_vector_domain_send_displ(r) + 1
       do slot = block_writeback_plan%recv_displ(r)+1, &
            block_writeback_plan%recv_displ(r) + &
            block_writeback_plan%recv_count(r)
          b = block_writeback_plan%recv_block(slot)
          source = source_rank(b)
          if (source /= rank .or. block_catalog(b)%owner /= r-1) then
             call fail("Domain boundary import route mismatch")
          end if
          d = loc_id(block_catalog(b)%root_domain+1) + 1
          if (d < 1 .or. d > size(grid)) then
             call fail("Domain boundary import has invalid local Domain")
          end if
          do boundary_index = 1, &
               block_writeback_plan%recv_boundary_count(slot)
             metadata_pos = &
                  block_writeback_plan%recv_boundary_displ(slot) + &
                  boundary_index
             source_bdry = &
                  block_writeback_plan%recv_boundary_source(metadata_pos)
             n_node = &
                  block_writeback_plan%recv_boundary_nnode(metadata_pos)
             n_scalar = n_node * &
                  block_writeback_plan%scalar_patch_nvalue / &
                  PATCH_SIZE**2
             n_vector = n_node * &
                  block_writeback_plan%vector_patch_nvalue / &
                  PATCH_SIZE**2
             call pack_domain_boundary_prognostic( &
                  d,source_bdry,n_node,payload_family, &
                  block_writeback_plan% &
                  boundary_scalar_domain_send_buffer( &
                  pos_scalar:pos_scalar+n_scalar-1), &
                  block_writeback_plan% &
                  boundary_vector_domain_send_buffer( &
                  pos_vector:pos_vector+n_vector-1),domain_sol)
             pos_scalar = pos_scalar + n_scalar
             pos_vector = pos_vector + n_vector
          end do
       end do
       if (pos_scalar /= block_writeback_plan% &
            boundary_scalar_domain_send_displ(r) + &
            block_writeback_plan% &
            boundary_scalar_domain_send_count(r) + 1 .or. &
            pos_vector /= block_writeback_plan% &
            boundary_vector_domain_send_displ(r) + &
            block_writeback_plan% &
            boundary_vector_domain_send_count(r) + 1) then
          call fail("Domain boundary packed extent mismatch")
       end if
    end do

    call MPI_Alltoallv( &
         block_writeback_plan%boundary_scalar_domain_send_buffer, &
         block_writeback_plan%boundary_scalar_domain_send_count, &
         block_writeback_plan%boundary_scalar_domain_send_displ, &
         MPI_DOUBLE_PRECISION, &
         block_writeback_plan%boundary_scalar_block_recv_buffer, &
         block_writeback_plan%boundary_scalar_block_recv_count, &
         block_writeback_plan%boundary_scalar_block_recv_displ, &
         MPI_DOUBLE_PRECISION,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv Domain scalar boundary payload")
    call MPI_Alltoallv( &
         block_writeback_plan%boundary_vector_domain_send_buffer, &
         block_writeback_plan%boundary_vector_domain_send_count, &
         block_writeback_plan%boundary_vector_domain_send_displ, &
         MPI_DOUBLE_PRECISION, &
         block_writeback_plan%boundary_vector_block_recv_buffer, &
         block_writeback_plan%boundary_vector_block_recv_count, &
         block_writeback_plan%boundary_vector_block_recv_displ, &
         MPI_DOUBLE_PRECISION,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv Domain vector boundary payload")

    do r = 1,n_process
       pos_scalar = block_writeback_plan% &
            boundary_scalar_block_recv_displ(r) + 1
       pos_vector = block_writeback_plan% &
            boundary_vector_block_recv_displ(r) + 1
       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)
          b = block_writeback_plan%send_block(slot)
          n_boundary = local_block_boundary_count(b)
          if (n_boundary /= &
               block_writeback_plan%send_boundary_count(slot)) then
             call fail("Domain boundary destination layout changed")
          end if
          do boundary_index = 1,n_boundary
             n_scalar = &
                  local_block_scalar_family_boundary_nvalue( &
                  b,boundary_index)
             n_vector = &
                  local_block_vector_family_boundary_nvalue( &
                  b,boundary_index)
             if (n_scalar > &
                  size(ghost_exchange_plan%scalar_patch_buffer) .or. &
                  n_vector > &
                  size(ghost_exchange_plan%vector_patch_buffer)) then
                call fail("remote boundary scratch extent is invalid")
             end if
             if (check_current) then
                call get_local_block_scalar_boundary_family_values( &
                     b,boundary_index,payload_family, &
                     ghost_exchange_plan% &
                     scalar_patch_buffer(1:n_scalar))
                if (any(abs(ghost_exchange_plan% &
                     scalar_patch_buffer(1:n_scalar) - &
                     block_writeback_plan% &
                     boundary_scalar_block_recv_buffer( &
                     pos_scalar:pos_scalar+n_scalar-1)) > 0.0_dp)) then
                   call fail("remote scalar Domain boundary mismatch")
                end if
                call get_local_block_vector_boundary_family_values( &
                     b,boundary_index,payload_family, &
                     ghost_exchange_plan% &
                     vector_patch_buffer(1:n_vector))
                if (any(abs(ghost_exchange_plan% &
                     vector_patch_buffer(1:n_vector) - &
                     block_writeback_plan% &
                     boundary_vector_block_recv_buffer( &
                     pos_vector:pos_vector+n_vector-1)) > 0.0_dp)) then
                   call fail("remote vector Domain boundary mismatch")
                end if
             end if
             call set_local_block_scalar_boundary_family_values( &
                  b,boundary_index,payload_family, &
                  block_writeback_plan% &
                  boundary_scalar_block_recv_buffer( &
                  pos_scalar:pos_scalar+n_scalar-1))
             call set_local_block_vector_boundary_family_values( &
                  b,boundary_index,payload_family, &
                  block_writeback_plan% &
                  boundary_vector_block_recv_buffer( &
                  pos_vector:pos_vector+n_vector-1))
             pos_scalar = pos_scalar + n_scalar
             pos_vector = pos_vector + n_vector
          end do
       end do
       if (pos_scalar /= block_writeback_plan% &
            boundary_scalar_block_recv_displ(r) + &
            block_writeback_plan% &
            boundary_scalar_block_recv_count(r) + 1 .or. &
            pos_vector /= block_writeback_plan% &
            boundary_vector_block_recv_displ(r) + &
            block_writeback_plan% &
            boundary_vector_block_recv_count(r) + 1) then
          call fail("Domain boundary consumed extent mismatch")
       end if
    end do

    do slot = 1,n_local_blocks()
       b = local_block_catalog(slot)
       source = source_rank(b)
       if (source /= rank) cycle
       d = loc_id(block_catalog(b)%root_domain+1) + 1
       if (d < 1 .or. d > size(grid)) then
          call fail("retained boundary import has invalid Domain")
       end if
       n_boundary = local_block_boundary_count(b)
       do boundary_index = 1,n_boundary
          call get_local_block_boundary_source( &
               b,boundary_index,source_bdry,elts_start,n_node)
          if (source_bdry < 0 .or. &
               source_bdry >= grid(d)%bdry_patch%length) then
             call fail("retained boundary import source is invalid")
          end if
          if (grid(d)%bdry_patch%elts(source_bdry+1)%elts_start /= &
               elts_start) then
             call fail("retained boundary source offset changed")
          end if
          n_scalar = local_block_scalar_family_boundary_nvalue( &
               b,boundary_index)
          n_vector = local_block_vector_family_boundary_nvalue( &
               b,boundary_index)
          if (n_scalar > &
               size(ghost_exchange_plan%scalar_patch_buffer) .or. &
               n_vector > &
               size(ghost_exchange_plan%vector_patch_buffer)) then
             call fail("retained boundary scratch extent is invalid")
          end if
          call pack_domain_boundary_prognostic( &
               d,source_bdry,n_node,payload_family, &
               ghost_exchange_plan%scalar_patch_buffer(1:n_scalar), &
               ghost_exchange_plan%vector_patch_buffer(1:n_vector), &
               domain_sol)
          if (check_current) then
             call compare_retained_boundary( &
                  b,boundary_index,payload_family,n_scalar,n_vector)
          end if
          call set_local_block_scalar_boundary_family_values( &
               b,boundary_index,payload_family, &
               ghost_exchange_plan%scalar_patch_buffer(1:n_scalar))
          call set_local_block_vector_boundary_family_values( &
               b,boundary_index,payload_family, &
               ghost_exchange_plan%vector_patch_buffer(1:n_vector))
       end do
    end do

  contains

    subroutine compare_retained_boundary ( &
         b,boundary_index,payload_family,n_scalar,n_vector)

      implicit none

      integer, intent(in) :: b
      integer, intent(in) :: boundary_index
      integer, intent(in) :: payload_family
      integer, intent(in) :: n_scalar
      integer, intent(in) :: n_vector

      real(dp) :: scalar_current(n_scalar)
      real(dp) :: vector_current(n_vector)

      call get_local_block_scalar_boundary_family_values( &
           b,boundary_index,payload_family,scalar_current)
      if (any(abs(scalar_current - &
           ghost_exchange_plan%scalar_patch_buffer(1:n_scalar)) > &
           0.0_dp)) then
         call fail("retained scalar Domain boundary mismatch")
      end if
      call get_local_block_vector_boundary_family_values( &
           b,boundary_index,payload_family,vector_current)
      if (any(abs(vector_current - &
           ghost_exchange_plan%vector_patch_buffer(1:n_vector)) > &
           0.0_dp)) then
         call fail("retained vector Domain boundary mismatch")
      end if

    end subroutine compare_retained_boundary

  end subroutine import_domain_boundary_field_family_to_blocks


  subroutine pack_domain_boundary_prognostic ( &
       d,source_bdry,n_node,payload_family,scalar_payload,vector_payload, &
       domain_sol)
    ! Pack one authoritative Domain compact boundary in the same
    ! variable/level/component order used by Block_Data boundary storage.

    implicit none

    integer, intent(in) :: d
    integer, intent(in) :: source_bdry
    integer, intent(in) :: n_node
    integer, intent(in) :: payload_family
    real(dp), intent(out) :: scalar_payload(:)
    real(dp), intent(out) :: vector_payload(:)
    type(Float_Field), optional, intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)

    integer :: field_level
    integer :: first_field_level
    integer :: level_slot
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_variable
    integer :: old_start
    integer :: output_base
    integer :: scalar_id
    integer :: scalar_slot
    integer :: v_scalar
    integer :: v_vector

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    if (d < 1 .or. d > size(grid) .or. &
         source_bdry < 0 .or. &
         source_bdry >= grid(d)%bdry_patch%length .or. &
         n_node < 1) then
       call fail("Domain boundary pack address is invalid")
    end if
    if (size(scalar_payload) /= &
         n_scalar_variable*n_field_level*mult_scalar*n_node .or. &
         size(vector_payload) /= &
         n_field_level*mult_vector*n_node) then
       call fail("Domain boundary pack payload extent is invalid")
    end if
    if (payload_family /= BLOCK_PAYLOAD_SOL .and. &
         payload_family /= BLOCK_PAYLOAD_WAV_COEFF) then
       call fail("Domain boundary pack family is invalid")
    end if
    scalar_payload = 0.0_dp
    vector_payload = 0.0_dp
    old_start = grid(d)%bdry_patch%elts(source_bdry+1)%elts_start
    if (old_start < 0 .or. &
         old_start+n_node > grid(d)%node%length) then
       call fail("Domain boundary pack source extent is invalid")
    end if

    do scalar_slot = 1,n_scalar_variable
       scalar_id = v_scalar + scalar_slot - 1
       do level_slot = 1,n_field_level
          field_level = first_field_level + level_slot - 1
          output_base = ((scalar_slot-1)*n_field_level + &
               level_slot-1)*mult_scalar*n_node
          select case (payload_family)
          case (BLOCK_PAYLOAD_SOL)
             if (present(domain_sol) .and. field_level >= 1 .and. &
                  field_level <= zlevels) then
                scalar_payload(output_base+1: &
                     output_base+mult_scalar*n_node) = &
                     domain_sol(scalar_id,field_level)%data(d)%elts( &
                     mult_scalar*old_start+1: &
                     mult_scalar*(old_start+n_node))
             else
                scalar_payload(output_base+1: &
                     output_base+mult_scalar*n_node) = &
                     sol(scalar_id,field_level)%data(d)%elts( &
                     mult_scalar*old_start+1: &
                     mult_scalar*(old_start+n_node))
             end if
          case (BLOCK_PAYLOAD_WAV_COEFF)
             scalar_payload(output_base+1: &
                  output_base+mult_scalar*n_node) = &
                  wav_coeff(scalar_id,field_level)%data(d)%elts( &
                  mult_scalar*old_start+1: &
                  mult_scalar*(old_start+n_node))
          end select
       end do
    end do

    do level_slot = 1,n_field_level
       field_level = first_field_level + level_slot - 1
       output_base = (level_slot-1)*mult_vector*n_node
       select case (payload_family)
       case (BLOCK_PAYLOAD_SOL)
          if (present(domain_sol) .and. field_level >= 1 .and. &
               field_level <= zlevels) then
             vector_payload(output_base+1: &
                  output_base+mult_vector*n_node) = &
                  domain_sol(v_vector,field_level)%data(d)%elts( &
                  mult_vector*old_start+1: &
                  mult_vector*(old_start+n_node))
          else
             vector_payload(output_base+1: &
                  output_base+mult_vector*n_node) = &
                  sol(v_vector,field_level)%data(d)%elts( &
                  mult_vector*old_start+1: &
                  mult_vector*(old_start+n_node))
          end if
       case (BLOCK_PAYLOAD_WAV_COEFF)
          vector_payload(output_base+1: &
               output_base+mult_vector*n_node) = &
               wav_coeff(v_vector,field_level)%data(d)%elts( &
               mult_vector*old_start+1: &
               mult_vector*(old_start+n_node))
       end select
    end do

  end subroutine pack_domain_boundary_prognostic


  subroutine check_domain_field_family_block_import (verbose)
    ! Poison and exactly restore both prognostic families through the
    ! production Domain-to-final-block installation entry point.

    implicit none

    logical, optional, intent(in) :: verbose

    integer :: b
    integer :: ierr
    integer :: local_index
    integer :: n_patch

    integer(int64) :: global_patch_count
    integer(int64) :: local_patch_count
    integer(int64) :: production_writeback_before
    integer(int64) :: stage_allocation_before
    integer(int64) :: writeback_allocation_before

    logical :: accumulator_ready
    logical :: hydrostatic_ready
    logical :: print_summary
    logical :: tendency_ready

    print_summary = .true.
    if (present(verbose)) print_summary = verbose

    if (.not. block_writeback_plan_is_ready()) then
       call fail("Domain prognostic block import check before plan is ready")
    end if

    writeback_allocation_before = &
         block_writeback_plan_allocation_count()
    stage_allocation_before = block_writeback_plan%stage_allocations
    production_writeback_before = &
         block_domain_production_writeback_count()

    call check_family(BLOCK_PAYLOAD_SOL)
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (tendency_ready .or. accumulator_ready) then
       call fail("sol block import retained stale tendency products")
    end if
    call check_family(BLOCK_PAYLOAD_WAV_COEFF)

    if (compressible) then
       call ensure_local_block_hydrostatic_state
       hydrostatic_ready = local_block_hydrostatic_state_ready()
       if (.not. hydrostatic_ready) then
          call fail("Domain prognostic import hydrostatic refresh failed")
       end if
    end if

    if (block_writeback_plan_allocation_count() /= &
         writeback_allocation_before) then
       call fail("Domain prognostic import reallocated transport buffers")
    end if
    if (block_writeback_plan%stage_allocations /= &
         stage_allocation_before) then
       call fail("Domain prognostic import reallocated Domain staging")
    end if
    if (block_domain_production_writeback_count() /= &
         production_writeback_before) then
       call fail("Domain prognostic import modified Domain fields")
    end if

    local_patch_count = 0_int64
    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       n_patch = local_block_patch_count(b)
       local_patch_count = local_patch_count + int( &
            n_patch,int64)
    end do
    call MPI_Allreduce(local_patch_count,global_patch_count,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce prognostic import patches")

    if (print_summary) then
       write(6,'(/,a,i0,a)') &
            "Domain prognostic block import for rank ",rank,":"
       write(6,'(a,i0)') "  imported local patches = ", &
            local_patch_count
       write(6,'(a)') "  exact scalar sol block import passed"
       write(6,'(a)') "  exact vector sol block import passed"
       write(6,'(a)') &
            "  exact scalar wav_coeff block import passed"
       write(6,'(a)') &
            "  exact vector wav_coeff block import passed"
       write(6,'(a)') &
            "  complete final-owner patch coverage passed"
       write(6,'(a)') &
            "  stale tendency products invalidated after sol import"
       if (compressible) then
          write(6,'(a)') &
               "  derived hydrostatic state refreshed after sol import"
       end if
       write(6,'(a,/)') &
            "  repeated prognostic import buffer reuse passed"
    end if

    if (print_summary .and. rank == 0) then
       write(6,'(/,a,i0)') &
            "Global Domain prognostic block import patches = ", &
            global_patch_count
       write(6,'(a,/)') &
            "Transactional Domain prognostic block import passed"
    end if

  contains

    subroutine check_family (payload_family)

      implicit none

      integer, intent(in) :: payload_family

      call fill_local_block_scalar_patch_family_values( &
           payload_family,BLOCK_PATCH_POISON)
      call fill_local_block_vector_patch_family_values( &
           payload_family,-BLOCK_PATCH_POISON)
      call import_domain_field_family_to_blocks(payload_family)
      call assert_block_domain_field_family_match(payload_family)

      call import_domain_field_family_to_blocks(payload_family)
      call assert_block_domain_field_family_match(payload_family)

    end subroutine check_family

  end subroutine check_domain_field_family_block_import


  subroutine check_domain_boundary_field_family_block_import (verbose)
    ! Poison and exactly restore both compact boundary prognostic families
    ! through the persistent Domain-owner-to-final-owner boundary routes.

    implicit none

    logical, optional, intent(in) :: verbose

    integer :: b
    integer :: boundary_index
    integer :: ierr
    integer :: local_index
    integer :: n_boundary

    integer(int64) :: allocation_before
    integer(int64) :: global_boundary_count
    integer(int64) :: global_scalar_count
    integer(int64) :: global_vector_count
    integer(int64) :: local_boundary_count
    integer(int64) :: local_scalar_count
    integer(int64) :: local_vector_count
    integer(int64) :: writeback_before

    logical :: print_summary

    print_summary = .true.
    if (present(verbose)) print_summary = verbose

    allocation_before = block_writeback_plan_allocation_count()
    writeback_before = block_domain_production_writeback_count()

    call check_family(BLOCK_PAYLOAD_SOL)
    call check_family(BLOCK_PAYLOAD_WAV_COEFF)

    if (block_writeback_plan_allocation_count() /= &
         allocation_before) then
       call fail("Domain boundary import reallocated persistent buffers")
    end if
    if (block_domain_production_writeback_count() /= &
         writeback_before) then
       call fail("Domain boundary import modified Domain fields")
    end if

    local_boundary_count = 0_int64
    local_scalar_count = 0_int64
    local_vector_count = 0_int64
    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       n_boundary = local_block_boundary_count(b)
       local_boundary_count = local_boundary_count + &
            int(n_boundary,int64)
       do boundary_index = 1,n_boundary
          local_scalar_count = local_scalar_count + int( &
               local_block_scalar_family_boundary_nvalue( &
               b,boundary_index),int64)
          local_vector_count = local_vector_count + int( &
               local_block_vector_family_boundary_nvalue( &
               b,boundary_index),int64)
       end do
    end do
    call MPI_Allreduce(local_boundary_count,global_boundary_count,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce Domain boundary records")
    call MPI_Allreduce(local_scalar_count,global_scalar_count,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce Domain scalar boundary values")
    call MPI_Allreduce(local_vector_count,global_vector_count,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce Domain vector boundary values")

    if (print_summary) then
       write(6,'(/,a,i0,a)') &
            "Domain boundary block import for rank ",rank,":"
       write(6,'(a,i0)') "  imported local boundary records = ", &
            local_boundary_count
       write(6,'(a)') &
            "  exact scalar/vector sol boundary import passed"
       write(6,'(a)') &
            "  exact scalar/vector wav_coeff boundary import passed"
       write(6,'(a,/)') &
            "  repeated persistent boundary-buffer reuse passed"
    end if

    if (print_summary .and. rank == 0) then
       write(6,'(/,a,i0)') &
            "Global Domain boundary records imported = ", &
            global_boundary_count
       write(6,'(a,i0)') &
            "Global scalar Domain boundary values imported = ", &
            global_scalar_count
       write(6,'(a,i0)') &
            "Global vector Domain boundary values imported = ", &
            global_vector_count
       write(6,'(a,/)') &
            "Transactional Domain boundary prognostic import passed"
    end if

  contains

    subroutine check_family (payload_family)

      implicit none

      integer, intent(in) :: payload_family

      call fill_local_block_scalar_boundary_family_values( &
           payload_family,BLOCK_BOUNDARY_POISON)
      call fill_local_block_vector_boundary_family_values( &
           payload_family,-BLOCK_BOUNDARY_POISON)
      call import_domain_boundary_field_family_to_blocks( &
           payload_family,.false.)
      call import_domain_boundary_field_family_to_blocks( &
           payload_family,.true.)

    end subroutine check_family

  end subroutine check_domain_boundary_field_family_block_import


  subroutine refresh_parallel_block_trend_boundary_state
    ! Mirror the first production trend_ml update_bdry in the retained block
    ! representation. Domain values remain authoritative: compact boundary
    ! payloads are imported after update_bdry, while inter-block sol ghosts
    ! are refreshed from exact block interiors through persistent routes.

    implicit none

    integer :: b
    integer :: ierr
    integer :: local_index
    integer :: scalar_ghost_recv_size_before
    integer :: scalar_ghost_send_size_before
    integer :: vector_ghost_recv_size_before
    integer :: vector_ghost_send_size_before

    integer(int64) :: count_global(3)
    integer(int64) :: count_local(3)
    integer(int64) :: production_writeback_before
    integer(int64) :: scalar_address_first(3)
    integer(int64) :: scalar_address_second(3)
    integer(int64) :: scalar_value_first
    integer(int64) :: scalar_value_second
    integer(int64) :: vector_address_first(3)
    integer(int64) :: vector_address_second(3)
    integer(int64) :: vector_value_first
    integer(int64) :: vector_value_second
    integer(int64) :: writeback_allocation_before

    logical :: accumulator_ready
    logical :: checkpoint_ready
    logical :: state_ready
    logical :: tendency_ready
    logical :: trial_active

    real(dp) :: scalar_moment_first(3,3)
    real(dp) :: scalar_moment_second(3,3)
    real(dp) :: vector_moment_first(3,3)
    real(dp) :: vector_moment_second(3,3)

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail("trend boundary refresh before block state is ready")
    end if
    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (trial_active .or. checkpoint_ready .or. tendency_ready .or. &
         accumulator_ready) then
       call fail("trend boundary refresh found pending tendency state")
    end if

    writeback_allocation_before = &
         block_writeback_plan_allocation_count()
    production_writeback_before = &
         block_domain_production_writeback_count()
    scalar_ghost_send_size_before = &
         size(ghost_exchange_plan%scalar_send_buffer)
    scalar_ghost_recv_size_before = &
         size(ghost_exchange_plan%scalar_recv_buffer)
    vector_ghost_send_size_before = &
         size(ghost_exchange_plan%vector_send_buffer)
    vector_ghost_recv_size_before = &
         size(ghost_exchange_plan%vector_recv_buffer)

    call assert_block_domain_field_family_match(BLOCK_PAYLOAD_SOL)
    call import_domain_boundary_field_family_to_blocks( &
         BLOCK_PAYLOAD_SOL,.false.)
    call import_domain_boundary_field_family_to_blocks( &
         BLOCK_PAYLOAD_SOL,.true.)
    call refresh_block_sol_ghosts
    call local_block_scalar_stencil_statistics( &
         scalar_address_first,scalar_value_first,scalar_moment_first)
    call local_block_vector_stencil_statistics( &
         vector_address_first,vector_value_first,vector_moment_first)

    ! A second identical refresh must preserve the complete compact stencil
    ! image exactly and reuse every persistent communication buffer.
    call import_domain_boundary_field_family_to_blocks( &
         BLOCK_PAYLOAD_SOL,.true.)
    call refresh_block_sol_ghosts
    call local_block_scalar_stencil_statistics( &
         scalar_address_second,scalar_value_second,scalar_moment_second)
    call local_block_vector_stencil_statistics( &
         vector_address_second,vector_value_second,vector_moment_second)
    call assert_block_domain_field_family_match(BLOCK_PAYLOAD_SOL)

    if (any(scalar_address_first /= scalar_address_second) .or. &
         scalar_value_first /= scalar_value_second .or. &
         any(abs(scalar_moment_first-scalar_moment_second) > 0.0_dp)) then
       call fail("repeated scalar trend boundary refresh changed stencil")
    end if
    if (any(vector_address_first /= vector_address_second) .or. &
         vector_value_first /= vector_value_second .or. &
         any(abs(vector_moment_first-vector_moment_second) > 0.0_dp)) then
       call fail("repeated vector trend boundary refresh changed stencil")
    end if
    if (block_writeback_plan_allocation_count() /= &
         writeback_allocation_before) then
       call fail("trend boundary refresh reallocated transport buffers")
    end if
    if (block_domain_production_writeback_count() /= &
         production_writeback_before) then
       call fail("trend boundary refresh modified Domain fields")
    end if
    if (size(ghost_exchange_plan%scalar_send_buffer) /= &
         scalar_ghost_send_size_before .or. &
         size(ghost_exchange_plan%scalar_recv_buffer) /= &
         scalar_ghost_recv_size_before .or. &
         size(ghost_exchange_plan%vector_send_buffer) /= &
         vector_ghost_send_size_before .or. &
         size(ghost_exchange_plan%vector_recv_buffer) /= &
         vector_ghost_recv_size_before) then
       call fail("trend boundary refresh resized ghost buffers")
    end if

    count_local = 0_int64
    count_local(1) = int(n_local_blocks(),int64)
    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       count_local(2) = count_local(2) + &
            int(local_block_boundary_count(b),int64)
       count_local(3) = count_local(3) + &
            int(local_block_ghost_count(b),int64)
    end do
    call MPI_Allreduce(count_local,count_global,3, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce trend boundary refresh coverage")
    if (any(count_global <= 0_int64)) then
       call fail("trend boundary refresh coverage is incomplete")
    end if

    block_writeback_plan%production_trend_boundary_refresh_count = &
         block_writeback_plan%production_trend_boundary_refresh_count + &
         1_int64

    if (rank == 0) then
       write(6,'(/,a,i0)') &
            "Production trend-entry block boundary refresh number = ", &
            block_writeback_plan% &
            production_trend_boundary_refresh_count
       write(6,'(a,3(i0,1x))') &
            "  global block/boundary/ghost records = ",count_global
       write(6,'(a,/)') &
            "Production trend-entry block boundary compatibility passed"
    end if

  end subroutine refresh_parallel_block_trend_boundary_state


  subroutine refresh_parallel_block_candidate_boundary_state ( &
       domain_sol,stage,stage_count)
    ! Replace the retained pre-wavelet block candidate with the authoritative
    ! post-wavelet Domain stage state while retaining the timestep-start
    ! checkpoint required by the low-storage formula. Import compact
    ! boundaries and refresh inter-block ghosts for the next RK tendency.

    implicit none

    type(Float_Field), intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    integer, intent(in) :: stage
    integer, intent(in) :: stage_count

    integer :: scalar_ghost_recv_size_before
    integer :: scalar_ghost_send_size_before
    integer :: vector_ghost_recv_size_before
    integer :: vector_ghost_send_size_before

    integer(int64) :: production_writeback_before
    integer(int64) :: hydrostatic_refresh_after
    integer(int64) :: hydrostatic_refresh_before
    integer(int64) :: writeback_allocation_before

    logical :: accumulator_ready
    logical :: checkpoint_ready
    logical :: hydrostatic_ready
    logical :: state_ready
    logical :: tendency_ready
    logical :: trial_active

    character(len=3) :: scheme_name

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail("multistage boundary refresh before state is ready")
    end if
    if (.not. compressible) then
       call fail("multistage boundary refresh requires compressible state")
    end if
    if (stage_count /= 3 .and. stage_count /= 4) then
       call fail("multistage boundary refresh stage count is invalid")
    end if
    if (stage < 1 .or. stage >= stage_count) then
       call fail("multistage boundary refresh stage is invalid")
    end if
    if (production_multistage_candidate_stage_count /= stage_count .or. &
         production_multistage_candidate_stage /= stage) then
       call fail("multistage boundary refresh sequence is invalid")
    end if
    if (block_writeback_plan% &
         production_multistage_boundary_refresh_count /= &
         int(stage-1,int64)) then
       call fail("multistage boundary refresh count is invalid")
    end if
    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (trial_active .or. .not. checkpoint_ready .or. tendency_ready .or. &
         accumulator_ready) then
       call fail("multistage boundary refresh transaction is invalid")
    end if
    call consume_native_multistage_candidate_snapshot(stage,stage_count)

    writeback_allocation_before = &
         block_writeback_plan_allocation_count()
    production_writeback_before = &
         block_domain_production_writeback_count()
    scalar_ghost_send_size_before = &
         size(ghost_exchange_plan%scalar_send_buffer)
    scalar_ghost_recv_size_before = &
         size(ghost_exchange_plan%scalar_recv_buffer)
    vector_ghost_send_size_before = &
         size(ghost_exchange_plan%vector_send_buffer)
    vector_ghost_recv_size_before = &
         size(ghost_exchange_plan%vector_recv_buffer)

    call import_domain_field_family_to_blocks( &
         BLOCK_PAYLOAD_SOL,domain_sol,.true.)
    call import_domain_boundary_field_family_to_blocks( &
         BLOCK_PAYLOAD_SOL,.false.,domain_sol)
    call import_domain_boundary_field_family_to_blocks( &
         BLOCK_PAYLOAD_SOL,.true.,domain_sol)
    call refresh_block_sol_ghosts
    call assert_block_domain_field_family_match( &
         BLOCK_PAYLOAD_SOL,domain_sol)

    hydrostatic_refresh_before = &
         local_block_hydrostatic_refresh_count()
    call ensure_local_block_hydrostatic_state
    hydrostatic_refresh_after = &
         local_block_hydrostatic_refresh_count()
    hydrostatic_ready = local_block_hydrostatic_state_ready()
    if (.not. hydrostatic_ready) then
       call fail("multistage provisional hydrostatic state is not ready")
    end if
    if (hydrostatic_refresh_after-hydrostatic_refresh_before /= &
         int(n_local_blocks(),int64)) then
       call fail("multistage provisional hydrostatic refresh is incomplete")
    end if
    call assert_candidate_block_hydrostatic_match(domain_sol)
    call ensure_local_block_hydrostatic_state
    if (local_block_hydrostatic_refresh_count() /= &
         hydrostatic_refresh_after) then
       call fail("multistage provisional hydrostatic cache refreshed twice")
    end if
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    trial_active = local_block_tendency_trial_is_active()
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (.not. checkpoint_ready .or. trial_active .or. tendency_ready .or. &
         accumulator_ready) then
       call fail("multistage boundary refresh lost rollback checkpoint")
    end if
    if (block_writeback_plan_allocation_count() /= &
         writeback_allocation_before) then
       call fail("multistage boundary refresh reallocated transport")
    end if
    if (block_domain_production_writeback_count() /= &
         production_writeback_before) then
       call fail("multistage boundary refresh modified Domain fields")
    end if
    if (size(ghost_exchange_plan%scalar_send_buffer) /= &
         scalar_ghost_send_size_before .or. &
         size(ghost_exchange_plan%scalar_recv_buffer) /= &
         scalar_ghost_recv_size_before .or. &
         size(ghost_exchange_plan%vector_send_buffer) /= &
         vector_ghost_send_size_before .or. &
         size(ghost_exchange_plan%vector_recv_buffer) /= &
         vector_ghost_recv_size_before) then
       call fail("multistage boundary refresh resized ghost buffers")
    end if

    block_writeback_plan%production_multistage_boundary_refresh_count = &
         block_writeback_plan% &
         production_multistage_boundary_refresh_count + 1_int64

    if (stage_count == 3) then
       scheme_name = "RK3"
    else
       scheme_name = "RK4"
    end if
    if (rank == 0) then
       write(6,'(/,a,a,a,i0,a,i0)') &
            "Production ",scheme_name, &
            " block stage boundary compatibility passed: stage = ", &
            stage," of ",stage_count-1
    end if

  end subroutine refresh_parallel_block_candidate_boundary_state


  subroutine validate_candidate_block_velocity_restriction ( &
       domain_scaling,coarse_level)
    ! Reproduce Restrict_velo from a complete block-derived fine-level stage
    ! on the Domain owner before the accepted transform consumes its result.

    implicit none

    type(Float_Field), intent(in) :: &
         domain_scaling(1:N_VARIABLE,1:zlevels)
    integer, intent(in) :: coarse_level

    integer :: candidate_stage
    integer :: candidate_stage_count
    integer :: c
    integer :: d
    integer :: e
    integer :: field_level
    integer :: first_field_level
    integer :: i
    integer :: i_chd
    integer :: i_par
    integer :: ierr
    integer :: j
    integer :: j_chd
    integer :: j_par
    integer :: level_slot
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_variable
    integer :: p
    integer :: p_child
    integer :: p_index
    integer :: v_scalar
    integer :: v_vector

    integer(int64) :: count_global(4)
    integer(int64) :: count_local(4)
    integer(int64) :: restriction_allocation_before
    integer(int64) :: scalar_allocation_before
    integer(int64) :: writeback_allocation_before
    integer(int64) :: writeback_before

    logical :: checkpoint_ready
    logical :: state_ready

    real(dp) :: allowed
    real(dp) :: mask_value
    real(dp) :: native_value
    real(dp) :: reference_value

    character(len=3) :: scheme_name

    type(Block_Velocity_Restriction_Context) :: statistics

    candidate_stage = production_multistage_candidate_stage
    candidate_stage_count = production_multistage_candidate_stage_count
    if (candidate_stage_count == 0) return
    if (candidate_stage /= candidate_stage_count .or. &
         coarse_level /= level_start-1) then
       call fail("velocity restriction is outside the accepted transform")
    end if
    if (.not. production_multistage_final_snapshot_consumed .or. &
         block_writeback_plan%native_stage_ready) then
       call fail("velocity restriction snapshot boundary is invalid")
    end if
    if (production_velocity_restriction_level /= -1) then
       call fail("velocity restriction was already produced")
    end if
    staged_coarse_vector_boundary_plan%values_ready = .false.
    staged_coarse_vector_boundary_plan%source_produced = .false.

    state_ready = parallel_block_state_is_ready()
    checkpoint_ready = local_block_tendency_commit_checkpoint_is_ready()
    if (.not. state_ready .or. .not. checkpoint_ready) then
       call fail("velocity restriction transaction is not ready")
    end if
    if (.not. block_scalar_divergence_plan%ready .or. &
         .not. allocated(block_scalar_tendency)) then
       call fail("velocity restriction geometry is not ready")
    end if

    writeback_allocation_before = block_writeback_plan_allocation_count()
    scalar_allocation_before = block_scalar_tendency_allocations
    restriction_allocation_before = &
         block_scalar_restriction_exchange%allocations
    writeback_before = block_domain_production_writeback_count()

    ! Retain the in-block producer for later restriction levels. The accepted
    ! transform currently requests only the fixed scaffold below block roots.
    if (coarse_level >= level_start) then
       statistics%coarse_level = coarse_level
       call apply_local_block_field_producer( &
            produce_block_velocity_restriction,statistics)
    end if

    ! No compact block owns the fixed coarse scaffold at level_start-1.
    ! Reconstruct a non-authoritative Domain-layout stage from all retained
    ! block roots, including migrated roots, and evaluate Restrict_velo on
    ! each source Domain owner from those block-derived fine values.
    call reconstruct_block_writeback_domain_stage(BLOCK_PAYLOAD_SOL)
    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    if (v_vector /= S_VELO .or. mult_vector /= EDGE .or. &
         n_field_level < 1) then
       call fail("velocity restriction field layout is invalid")
    end if

    do d = 1,size(grid)
       do p_index = 1,grid(d)%lev(coarse_level)%length
          p = grid(d)%lev(coarse_level)%elts(p_index)
          statistics%parent_patch_count = &
               statistics%parent_patch_count + 1_int64
          do c = 1,N_CHDRN
             p_child = grid(d)%patch%elts(p+1)%children(c)
             if (p_child == 0) cycle
             if (grid(d)%patch%elts(p_child+1)%level /= &
                  coarse_level+1) then
                call fail("velocity restriction staged child level is invalid")
             end if
             do level_slot = 1,n_field_level
                field_level = first_field_level+level_slot-1
                if (field_level < 1 .or. field_level > zlevels) cycle
                do j = 1,PATCH_SIZE/2
                   j_chd = 2*(j-1)
                   j_par = j-1+chd_offs(2,c)
                   do i = 1,PATCH_SIZE/2
                      i_chd = 2*(i-1)
                      i_par = i-1+chd_offs(1,c)
                      do e = RT,UP
                         statistics%candidate_count = &
                              statistics%candidate_count + 1_int64
                         mask_value = real(grid(d)%mask_e%elts( &
                              EDGE*(grid(d)%patch%elts(p_child+1)% &
                              elts_start+PATCH_SIZE*j_chd+i_chd)+e+1),dp)
                         if (mask_value <= 0.0_dp) cycle
                         statistics%active_count = &
                              statistics%active_count + 1_int64
                         native_value = staged_restricted_velocity( &
                              d,p_child,level_slot,i_chd,j_chd,e)
                         reference_value = domain_restricted_velocity( &
                              d,p,field_level,i_par,j_par,e)
                         allowed = 8.0_dp*epsilon(1.0_dp)*max( &
                              1.0_dp,abs(native_value), &
                              abs(reference_value))
                         if (abs(native_value-reference_value) > allowed) then
                            call report_velocity_restriction_mismatch
                         end if
                         call set_staged_parent_velocity( &
                              d,p,level_slot,i_par,j_par,e,native_value)
                         statistics%produced_count = &
                              statistics%produced_count + 1_int64
                      end do
                   end do
                end do
             end do
          end do
       end do
    end do

    count_local = [statistics%parent_patch_count, &
         statistics%candidate_count,statistics%active_count, &
         statistics%produced_count]
    call MPI_Allreduce(count_local,count_global,size(count_local), &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce velocity restriction coverage")
    if (any(count_global <= 0_int64)) then
       call fail("block-derived velocity restriction coverage is empty")
    end if
    if (count_global(3) /= count_global(4)) then
       call fail("block-derived velocity restriction coverage differs")
    end if

    production_velocity_restriction_level = coarse_level

    if (.not. local_block_tendency_commit_checkpoint_is_ready() .or. &
         block_writeback_plan%native_stage_ready .or. &
         .not. production_multistage_final_snapshot_consumed) then
       call fail("velocity restriction changed transaction state")
    end if
    if (block_writeback_plan_allocation_count() /= &
         writeback_allocation_before .or. &
         block_scalar_tendency_allocations /= scalar_allocation_before .or. &
         block_scalar_restriction_exchange%allocations /= &
         restriction_allocation_before) then
       call fail("velocity restriction reallocated persistent storage")
    end if
    if (block_domain_production_writeback_count() /= writeback_before) then
       call fail("velocity restriction modified Domain fields")
    end if

    if (candidate_stage_count == 3) then
       scheme_name = "RK3"
    else
       scheme_name = "RK4"
    end if
    if (rank == 0) then
       write(6,'(a,a,a,i0)') &
            "  block-derived ",scheme_name, &
            " staged velocity restriction production passed: coarse level = ", &
            coarse_level
    end if

  contains

    real(dp) function staged_vector_value ( &
         d_stage,p_stage,level_stage,i_stage,j_stage,e_stage) &
         result(value)

      implicit none

      integer, intent(in) :: d_stage
      integer, intent(in) :: p_stage
      integer, intent(in) :: level_stage
      integer, intent(in) :: i_stage
      integer, intent(in) :: j_stage
      integer, intent(in) :: e_stage

      integer :: patch_slot
      integer :: value_index

      value = 0.0_dp
      patch_slot = block_writeback_plan%domain_patch_displ(d_stage) + &
           p_stage + 1
      value_index = (patch_slot-1)* &
           block_writeback_plan%vector_patch_nvalue + &
           (level_stage-1)*EDGE*PATCH_SIZE**2 + &
           EDGE*(PATCH_SIZE*j_stage+i_stage)+e_stage+1
      if (patch_slot < 1 .or. patch_slot > &
           size(block_writeback_plan%domain_patch_covered) .or. &
           .not. block_writeback_plan% &
           domain_patch_reconstructed(patch_slot) .or. &
           value_index < 1 .or. value_index > &
           size(block_writeback_plan%vector_domain_stage)) then
         call fail("velocity restriction staged source is invalid")
      end if
      value = block_writeback_plan%vector_domain_stage(value_index)
      if (.not. ieee_is_finite(value)) then
         call fail("velocity restriction staged source is non-finite")
      end if

    end function staged_vector_value


    real(dp) function staged_restricted_velocity ( &
         d_stage,p_stage,level_stage,i_stage,j_stage,e_stage) &
         result(value)

      implicit none

      integer, intent(in) :: d_stage
      integer, intent(in) :: p_stage
      integer, intent(in) :: level_stage
      integer, intent(in) :: i_stage
      integer, intent(in) :: j_stage
      integer, intent(in) :: e_stage

      select case (e_stage)
      case (RT)
         value = 0.5_dp*( &
              staged_vector_value(d_stage,p_stage,level_stage, &
                   i_stage,j_stage,RT) + &
              staged_vector_value(d_stage,p_stage,level_stage, &
                   i_stage+1,j_stage,RT))
      case (DG)
         value = 0.5_dp*( &
              staged_vector_value(d_stage,p_stage,level_stage, &
                   i_stage+1,j_stage+1,DG) + &
              staged_vector_value(d_stage,p_stage,level_stage, &
                   i_stage,j_stage,DG))
      case (UP)
         value = 0.5_dp*( &
              staged_vector_value(d_stage,p_stage,level_stage, &
                   i_stage,j_stage,UP) + &
              staged_vector_value(d_stage,p_stage,level_stage, &
                   i_stage,j_stage+1,UP))
      case default
         call fail("velocity restriction staged edge is invalid")
      end select

    end function staged_restricted_velocity


    real(dp) function domain_restricted_velocity ( &
         d_domain,p_domain,field_domain,i_domain,j_domain,e_domain) &
         result(value)

      implicit none

      integer, intent(in) :: d_domain
      integer, intent(in) :: p_domain
      integer, intent(in) :: field_domain
      integer, intent(in) :: i_domain
      integer, intent(in) :: j_domain
      integer, intent(in) :: e_domain

      integer :: node_index
      integer :: value_index

      value = 0.0_dp
      node_index = grid(d_domain)%patch%elts(p_domain+1)%elts_start + &
           PATCH_SIZE*j_domain+i_domain
      value_index = EDGE*node_index+e_domain+1
      if (value_index < 1 .or. value_index > size( &
           domain_scaling(S_VELO,field_domain)%data(d_domain)%elts)) then
         call fail("velocity restriction Domain target is invalid")
      end if
      value = domain_scaling(S_VELO,field_domain)% &
           data(d_domain)%elts(value_index)
      if (.not. ieee_is_finite(value)) then
         call fail("velocity restriction Domain target is non-finite")
      end if

    end function domain_restricted_velocity


    subroutine set_staged_parent_velocity ( &
         d_stage,p_stage,level_stage,i_stage,j_stage,e_stage,value)

      implicit none

      integer, intent(in) :: d_stage
      integer, intent(in) :: p_stage
      integer, intent(in) :: level_stage
      integer, intent(in) :: i_stage
      integer, intent(in) :: j_stage
      integer, intent(in) :: e_stage
      real(dp), intent(in) :: value

      integer :: edge_id
      integer :: patch_slot
      integer :: produced_index
      integer :: value_index

      patch_slot = block_writeback_plan%domain_patch_displ(d_stage) + &
           p_stage + 1
      value_index = (patch_slot-1)* &
           block_writeback_plan%vector_patch_nvalue + &
           (level_stage-1)*EDGE*PATCH_SIZE**2 + &
           EDGE*(PATCH_SIZE*j_stage+i_stage)+e_stage+1
      if (patch_slot < 1 .or. patch_slot > &
           size(block_writeback_plan%domain_patch_covered) .or. &
           .not. block_writeback_plan%domain_patch_covered(patch_slot) .or. &
           value_index < 1 .or. value_index > &
           size(block_writeback_plan%vector_domain_stage) .or. &
           .not. ieee_is_finite(value)) then
         call fail("velocity restriction staged target is invalid")
      end if
      block_writeback_plan%vector_domain_stage(value_index) = value
      edge_id = EDGE*(grid(d_stage)%patch%elts(p_stage+1)%elts_start + &
           PATCH_SIZE*j_stage+i_stage)+e_stage
      produced_index = (staged_coarse_vector_boundary_plan% &
           domain_edge_displ(d_stage)+edge_id)* &
           staged_coarse_vector_boundary_plan%n_field_level + level_stage
      if (produced_index < 1 .or. produced_index > &
           size(staged_coarse_vector_boundary_plan%source_produced)) then
         call fail("velocity restriction produced-source address is invalid")
      end if
      staged_coarse_vector_boundary_plan% &
           source_produced(produced_index) = .true.

    end subroutine set_staged_parent_velocity


    subroutine report_velocity_restriction_mismatch

      implicit none

      write(error_unit,'(/,a,i0,a)') &
           "Rank ",rank,": block-derived velocity restriction differs"
      write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
           "  Domain = ",d,", parent patch = ",p, &
           ", child = ",c,", child patch = ",p_child
      write(error_unit,'(a,i0,a,i0,a,i0)') &
           "  coarse level = ",coarse_level, &
           ", field level = ",field_level,", edge = ",e
      write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
           "  parent coordinates = ",i_par,", ",j_par, &
           "; child coordinates = ",i_chd,", ",j_chd
      write(error_unit,'(a,4(es24.16,1x))') &
           "  native, reference, difference, allowed = ", &
           native_value,reference_value, &
           abs(native_value-reference_value),allowed
      flush(error_unit)
      call fail("velocity restriction shadow comparison failed")

    end subroutine report_velocity_restriction_mismatch

  end subroutine validate_candidate_block_velocity_restriction


  subroutine produce_block_velocity_restriction ( &
       catalog_index,block,context)
    ! Exact compact-patch form of the three Restrict_velo edge averages.

    implicit none

    integer, intent(in) :: catalog_index
    type(Block_Data), intent(inout) :: block
    class(*), intent(inout) :: context

    integer :: c
    integer :: child
    integer :: i
    integer :: i_chd
    integer :: i_par
    integer :: j
    integer :: j_chd
    integer :: j_par
    integer :: level_slot
    integer :: local_index
    integer :: p

    local_index = catalog_local_block(catalog_index)
    if (local_index < 1 .or. &
         local_index > size(block_scalar_tendency)) then
       call fail("velocity restriction block is invalid")
    end if
    if (.not. block_scalar_tendency(local_index)%ready .or. &
         block_scalar_tendency(local_index)%catalog_index /= &
         catalog_index) then
       call fail("velocity restriction geometry block is stale")
    end if

    select type (statistics => context)
    type is (Block_Velocity_Restriction_Context)
       do p = 1,size(block%patch)
          if (block%patch(p)%level /= statistics%coarse_level) cycle
          statistics%parent_patch_count = &
               statistics%parent_patch_count + 1_int64
          do c = 1,N_CHDRN
             child = block%patch(p)%children(c)
             if (child == 0) cycle
             if (child < 0 .or. child >= size(block%patch)) then
                call fail("velocity restriction child patch is invalid")
             end if
             if (block%patch(child+1)%level /= &
                  block%patch(p)%level+1) then
                call fail("velocity restriction child level is invalid")
             end if
             do level_slot = 1,block%n_field_level
                if (block%field_level+level_slot-1 < 1 .or. &
                     block%field_level+level_slot-1 > zlevels) cycle
                do j = 1,PATCH_SIZE/2
                   j_chd = 2*(j-1)
                   j_par = j-1+chd_offs(2,c)
                   do i = 1,PATCH_SIZE/2
                      i_chd = 2*(i-1)
                      i_par = i-1+chd_offs(1,c)
                      call produce_edge(RT,i_chd,j_chd, &
                           i_chd+1,j_chd,statistics)
                      call produce_edge(DG,i_chd+1,j_chd+1, &
                           i_chd,j_chd,statistics)
                      call produce_edge(UP,i_chd,j_chd, &
                           i_chd,j_chd+1,statistics)
                   end do
                end do
             end do
          end do
       end do
    class default
       call fail("velocity restriction context is invalid")
    end select

  contains

    subroutine produce_edge (e,first_i,first_j,second_i,second_j,stats)

      implicit none

      integer, intent(in) :: e
      integer, intent(in) :: first_i
      integer, intent(in) :: first_j
      integer, intent(in) :: second_i
      integer, intent(in) :: second_j
      type(Block_Velocity_Restriction_Context), intent(inout) :: stats

      real(dp) :: mask_value
      real(dp) :: value

      stats%candidate_count = stats%candidate_count + 1_int64
      mask_value = block_scalar_record_value( &
           block,local_index,child+1,0,level_slot,i_chd,j_chd, &
           BLOCK_SCALAR_EDGE_MASK_START+e)
      if (mask_value <= 0.0_dp) return

      stats%active_count = stats%active_count + 1_int64
      value = 0.5_dp*( &
           block_vector_family_value( &
                block,local_index,child+1,level_slot, &
                first_i,first_j,e,BLOCK_PAYLOAD_SOL) + &
           block_vector_family_value( &
                block,local_index,child+1,level_slot, &
                second_i,second_j,e,BLOCK_PAYLOAD_SOL))
      call set_block_vector_sol_value( &
           block,p,level_slot,i_par,j_par,e,value)
      stats%produced_count = stats%produced_count + 1_int64

    end subroutine produce_edge

  end subroutine produce_block_velocity_restriction


  subroutine set_block_vector_sol_value ( &
       block,p,level_slot,i,j,e,value)
    ! Install one verified coarse velocity in native compact patch storage.

    implicit none

    type(Block_Data), intent(inout) :: block
    integer, intent(in) :: p
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: e
    real(dp), intent(in) :: value

    integer :: field_index
    integer :: n_storage_node
    integer :: node_index

    if (p < 1 .or. p > size(block%patch) .or. &
         level_slot < 1 .or. level_slot > block%n_field_level .or. &
         i < 0 .or. i >= PATCH_SIZE .or. &
         j < 0 .or. j >= PATCH_SIZE .or. &
         e < RT .or. e > UP) then
       call fail("velocity restriction address is invalid")
    end if
    if (.not. ieee_is_finite(value)) then
       call fail("velocity restriction value is non-finite")
    end if

    n_storage_node = size(block%node)
    node_index = block%patch(p)%elts_start+PATCH_SIZE*j+i
    field_index = (level_slot-1)*EDGE*n_storage_node + &
         EDGE*node_index+e+1
    if (node_index < 0 .or. node_index >= n_storage_node .or. &
         field_index < 1 .or. field_index > size(block%vector)) then
       call fail("velocity restriction storage is invalid")
    end if
    block%vector(field_index) = value

  end subroutine set_block_vector_sol_value


  subroutine validate_candidate_block_outer_vector_wavelets ( &
       domain_scaling,wavelet_level)
    ! Compare the regular outer-edge velocity wavelets after every field
    ! level has been evaluated but before pentagon corrections are applied.

    implicit none

    type(Float_Field), intent(in) :: &
         domain_scaling(1:N_VARIABLE,1:zlevels)
    integer, intent(in) :: wavelet_level

    integer :: candidate_stage
    integer :: candidate_stage_count
    integer :: ierr

    integer(int64) :: count_global(4)
    integer(int64) :: count_local(4)
    integer(int64) :: restriction_allocation_before
    integer(int64) :: scalar_allocation_before
    integer(int64) :: writeback_allocation_before
    integer(int64) :: writeback_before

    logical :: checkpoint_ready
    logical :: has_candidates
    logical :: state_ready

    character(len=3) :: scheme_name

    type(Block_Outer_Vector_Wavelet_Context) :: statistics

    candidate_stage = production_multistage_candidate_stage
    candidate_stage_count = &
         production_multistage_candidate_stage_count
    if (candidate_stage_count == 0) return

    if (wavelet_level == level_start-1) then
       if (candidate_stage /= candidate_stage_count .or. &
            production_velocity_restriction_level /= wavelet_level) then
          call fail("cross-root outer wavelet preceded velocity restriction")
       end if
       call validate_staged_coarse_outer_vector_wavelets( &
            wavelet_level,candidate_stage,candidate_stage_count)
       return
    end if
    if (wavelet_level < level_start-1) then
       call fail("outer vector-wavelet level is below staged coverage")
    end if
    if (wavelet_level > level_end-1) then
       call fail("outer vector-wavelet level is invalid")
    end if

    state_ready = parallel_block_state_is_ready()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    if (.not. state_ready .or. .not. checkpoint_ready) then
       call fail("outer vector-wavelet transaction is not ready")
    end if
    if (candidate_stage < candidate_stage_count) then
       if (.not. block_writeback_plan%native_stage_ready) then
          call fail("outer vector-wavelet native snapshot is not ready")
       end if
    else
       if (.not. production_multistage_final_snapshot_consumed .or. &
            block_writeback_plan%native_stage_ready) then
          call fail("accepted outer vector-wavelet snapshot is invalid")
       end if
    end if
    if (.not. block_scalar_divergence_plan%ready .or. &
         .not. allocated(block_scalar_tendency)) then
       call fail("outer vector-wavelet geometry is not ready")
    end if

    writeback_allocation_before = &
         block_writeback_plan_allocation_count()
    scalar_allocation_before = block_scalar_tendency_allocations
    restriction_allocation_before = &
         block_scalar_restriction_exchange%allocations
    writeback_before = block_domain_production_writeback_count()

    call import_domain_boundary_field_family_to_blocks( &
         BLOCK_PAYLOAD_SOL,.false.,domain_scaling)
    call refresh_block_sol_ghosts
    call import_domain_field_family_to_blocks( &
         BLOCK_PAYLOAD_WAV_COEFF,preserve_checkpoint=.true.)

    statistics%wavelet_level = wavelet_level
    call apply_local_block_field_consumer( &
         compare_block_outer_vector_wavelets,statistics)

    count_local = [statistics%parent_patch_count, &
         statistics%candidate_count,statistics%active_count, &
         statistics%compared_count]
    call MPI_Allreduce(count_local,count_global,size(count_local), &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce outer vector-wavelet coverage")
    has_candidates = count_global(2) > 0_int64
    if (has_candidates) then
       if (count_global(1) <= 0_int64) then
          call fail("outer vector-wavelet parent coverage is empty")
       end if
    else if (count_global(3) /= 0_int64 .or. &
         count_global(4) /= 0_int64) then
       call fail("empty outer vector-wavelet level has active coverage")
    end if
    if (count_global(3) /= count_global(4)) then
       call fail("outer vector-wavelet comparison coverage differs")
    end if

    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    if (.not. checkpoint_ready) then
       call fail("outer vector-wavelet lost RK transaction state")
    end if
    if (block_writeback_plan_allocation_count() /= &
         writeback_allocation_before .or. &
         block_scalar_tendency_allocations /= scalar_allocation_before .or. &
         block_scalar_restriction_exchange%allocations /= &
         restriction_allocation_before) then
       call fail("outer vector-wavelet reallocated persistent storage")
    end if
    if (block_domain_production_writeback_count() /= writeback_before) then
       call fail("outer vector-wavelet modified Domain fields")
    end if

    if (candidate_stage_count == 3) then
       scheme_name = "RK3"
    else
       scheme_name = "RK4"
    end if
    if (rank == 0) then
       if (has_candidates) then
          write(6,'(a,a,a,i0,a,i0,a,i0)') &
               "  block-native ",scheme_name, &
               " outer vector wavelet shadow passed: stage = ", &
               candidate_stage," of ",candidate_stage_count, &
               ", level = ",wavelet_level
       else
          write(6,'(a,a,a,i0,a,i0,a,i0)') &
               "  block-native ",scheme_name, &
               " outer vector wavelet shadow has no co-resident pairs: ", &
               candidate_stage," of ",candidate_stage_count, &
               ", level = ",wavelet_level
       end if
    end if

  end subroutine validate_candidate_block_outer_vector_wavelets


  subroutine validate_staged_coarse_outer_vector_wavelets ( &
       wavelet_level,candidate_stage,candidate_stage_count)
    ! Validate every regular outer wavelet spanning distinct block roots.
    ! Coarse stencil values crossing a Domain edge come only from the
    ! independently exchanged staged boundary payload.

    implicit none

    integer, intent(in) :: wavelet_level
    integer, intent(in) :: candidate_stage
    integer, intent(in) :: candidate_stage_count

    integer :: c
    integer :: d
    integer :: e
    integer :: field_level
    integer :: first_field_level
    integer :: i
    integer :: i_chd
    integer :: i_par
    integer :: ierr
    integer :: j
    integer :: j_chd
    integer :: j_par
    integer :: level_slot
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_variable
    integer :: p
    integer :: p_child
    integer :: p_index
    integer :: v_scalar
    integer :: v_vector

    integer :: dims_par(2,N_BDRY+1)
    integer :: offs_par(N_BDRY+1)

    integer(int64) :: count_global(5)
    integer(int64) :: count_local(5)
    integer(int64) :: boundary_exchange_before
    integer(int64) :: restriction_allocation_before
    integer(int64) :: scalar_allocation_before
    integer(int64) :: writeback_allocation_before
    integer(int64) :: writeback_before

    logical :: checkpoint_ready

    real(dp) :: allowed
    real(dp) :: companion_reference
    real(dp) :: mask_value
    real(dp) :: native_value
    real(dp) :: operation_scale
    real(dp) :: reference_value

    character(len=3) :: scheme_name

    writeback_allocation_before = block_writeback_plan_allocation_count()
    scalar_allocation_before = block_scalar_tendency_allocations
    restriction_allocation_before = &
         block_scalar_restriction_exchange%allocations
    writeback_before = block_domain_production_writeback_count()
    if (production_coarse_outer_wavelet_validated) then
       call fail("staged coarse outer wavelet was already validated")
    end if

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    if (v_vector /= S_VELO .or. mult_vector /= EDGE .or. &
         n_field_level < 1) then
       call fail("staged coarse outer-wavelet field layout is invalid")
    end if
    boundary_exchange_before = &
         staged_coarse_vector_boundary_plan%exchange_count
    call exchange_staged_coarse_vector_boundaries( &
         wavelet_level,n_field_level)

    count_local = 0_int64
    do d = 1,size(grid)
       do p_index = 1,grid(d)%lev(wavelet_level)%length
          p = grid(d)%lev(wavelet_level)%elts(p_index)
          call get_offs_Domain(grid(d),p,offs_par,dims_par)
          count_local(1) = count_local(1) + 1_int64
          do c = 1,N_CHDRN
             p_child = grid(d)%patch%elts(p+1)%children(c)
             if (p_child == 0) cycle
             if (grid(d)%patch%elts(p_child+1)%level /= &
                  wavelet_level+1) then
                call fail("staged coarse outer-wavelet child is invalid")
             end if
             do level_slot = 1,n_field_level
                field_level = first_field_level+level_slot-1
                if (field_level < 1 .or. field_level > zlevels) cycle
                do j = 1,PATCH_SIZE/2
                   j_chd = 2*(j-1)
                   j_par = j-1+chd_offs(2,c)
                   do i = 1,PATCH_SIZE/2
                      i_chd = 2*(i-1)
                      i_par = i-1+chd_offs(1,c)
                      do e = RT,UP
                         if (coarse_outer_stencil_uses_transport()) then
                            count_local(5) = count_local(5) + 2_int64
                         end if
                         count_local(2) = count_local(2) + 2_int64
                         native_value = 0.0_dp
                         operation_scale = 0.0_dp
                         allowed = 0.0_dp
                         call staged_wavelet_references( &
                              mask_value,reference_value, &
                              companion_reference)
                         if (mask_value < real(ADJZONE,dp)) then
                            if (abs(reference_value) > 0.0_dp .or. &
                                 abs(companion_reference) > 0.0_dp) then
                               call report_staged_outer_mismatch( &
                                    "inactive staged outer wavelet is not zero")
                            end if
                            cycle
                         end if
                         count_local(3) = count_local(3) + 2_int64
                         native_value = staged_outer_wavelet(operation_scale)
                         allowed = 64.0_dp*epsilon(1.0_dp)*max( &
                              1.0_dp,abs(native_value), &
                              abs(reference_value), &
                              abs(companion_reference),operation_scale)
                         if (abs(native_value-reference_value) > allowed .or. &
                              abs(native_value+companion_reference) > &
                              allowed) then
                            call report_staged_outer_mismatch( &
                                 "block-derived staged outer wavelet differs")
                         end if
                         count_local(4) = count_local(4) + 2_int64
                      end do
                   end do
                end do
             end do
          end do
       end do
    end do

    call MPI_Allreduce(count_local,count_global,size(count_local), &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce staged outer-wavelet coverage")
    if (count_global(1) <= 0_int64 .or. &
         count_global(2) <= 0_int64 .or. &
         count_global(3) <= 0_int64 .or. &
         count_global(5) <= 0_int64) then
       call fail("staged coarse outer-wavelet coverage is incomplete")
    end if
    if (count_global(3) /= count_global(4)) then
       call fail("staged coarse outer-wavelet comparison coverage differs")
    end if

    checkpoint_ready = local_block_tendency_commit_checkpoint_is_ready()
    if (.not. checkpoint_ready .or. &
         block_writeback_plan%native_stage_ready .or. &
         .not. production_multistage_final_snapshot_consumed) then
       call fail("staged coarse outer wavelet changed transaction state")
    end if
    if (block_writeback_plan_allocation_count() /= &
         writeback_allocation_before .or. &
         block_scalar_tendency_allocations /= scalar_allocation_before .or. &
         block_scalar_restriction_exchange%allocations /= &
         restriction_allocation_before) then
       call fail("staged coarse outer wavelet reallocated persistent storage")
    end if
    if (block_domain_production_writeback_count() /= writeback_before) then
       call fail("staged coarse outer wavelet modified Domain fields")
    end if
    if (.not. staged_coarse_vector_boundary_plan%values_ready .or. &
         staged_coarse_vector_boundary_plan%exchange_count /= &
         boundary_exchange_before+1_int64) then
       call fail("staged coarse boundary exchange lifecycle differs")
    end if
    production_coarse_outer_wavelet_validated = .true.

    if (candidate_stage_count == 3) then
       scheme_name = "RK3"
    else
       scheme_name = "RK4"
    end if
    if (rank == 0) then
       write(6,'(a,a,a,i0,a,i0,a,i0,a,i0)') &
            "  block-derived ",scheme_name, &
            " cross-root outer wavelet complete passed: stage = ", &
            candidate_stage," of ",candidate_stage_count, &
            ", level = ",wavelet_level, &
            ", transported boundary pairs = ",count_global(5)
    end if

  contains

    logical function coarse_outer_stencil_uses_transport() &
         result(uses_transport)

      implicit none

      uses_transport = .false.
      if (staged_side_uses_transport( &
           i_par+end_pt(1,2,e+1),j_par+end_pt(2,2,e+1), &
           hex_s_offs(e+1)+3)) uses_transport = .true.
      if (staged_side_uses_transport( &
           i_par+end_pt(1,1,e+1),j_par+end_pt(2,1,e+1), &
           hex_s_offs(e+1)+4)) uses_transport = .true.
      if (staged_side_uses_transport( &
           i_par+end_pt(1,1,e+1),j_par+end_pt(2,1,e+1), &
           hex_s_offs(e+1)+6)) uses_transport = .true.
      if (staged_side_uses_transport( &
           i_par+end_pt(1,2,e+1),j_par+end_pt(2,2,e+1), &
           hex_s_offs(e+1)+1)) uses_transport = .true.
      if (staged_side_uses_transport( &
           i_par+opp_no(1,1,e+1),j_par+opp_no(2,1,e+1), &
           hex_s_offs(e+1)+2)) uses_transport = .true.
      if (staged_side_uses_transport( &
           i_par+end_pt(1,1,e+1),j_par+end_pt(2,1,e+1), &
           hex_s_offs(e+1)+3)) uses_transport = .true.
      if (staged_side_uses_transport( &
           i_par+end_pt(1,2,e+1),j_par+end_pt(2,2,e+1), &
           hex_s_offs(e+1)+4)) uses_transport = .true.
      if (staged_side_uses_transport( &
           i_par+opp_no(1,1,e+1),j_par+opp_no(2,1,e+1), &
           hex_s_offs(e+1)+5)) uses_transport = .true.
      if (staged_side_uses_transport( &
           i_par+opp_no(1,2,e+1),j_par+opp_no(2,2,e+1), &
           hex_s_offs(e+1)+5)) uses_transport = .true.
      if (staged_side_uses_transport( &
           i_par+end_pt(1,2,e+1),j_par+end_pt(2,2,e+1), &
           hex_s_offs(e+1)+6)) uses_transport = .true.
      if (staged_side_uses_transport( &
           i_par+end_pt(1,1,e+1),j_par+end_pt(2,1,e+1), &
           hex_s_offs(e+1)+1)) uses_transport = .true.
      if (staged_side_uses_transport( &
           i_par+opp_no(1,2,e+1),j_par+opp_no(2,2,e+1), &
           hex_s_offs(e+1)+2)) uses_transport = .true.

    end function coarse_outer_stencil_uses_transport


    logical function staged_side_is_local (base_i,base_j,side_index) &
         result(local)

      implicit none

      integer, intent(in) :: base_i
      integer, intent(in) :: base_j
      integer, intent(in) :: side_index

      integer :: edge_i
      integer :: edge_j

      local = .false.
      if (side_index < 1 .or. side_index > size(hex_sides,2)) return
      edge_i = base_i+hex_sides(1,side_index)
      edge_j = base_j+hex_sides(2,side_index)
      local = edge_i >= 0 .and. edge_i < PATCH_SIZE .and. &
           edge_j >= 0 .and. edge_j < PATCH_SIZE

    end function staged_side_is_local


    logical function staged_side_uses_transport ( &
         base_i,base_j,side_index) result(uses_transport)

      implicit none

      integer, intent(in) :: base_i
      integer, intent(in) :: base_j
      integer, intent(in) :: side_index

      integer :: edge_component
      integer :: edge_i
      integer :: edge_id
      integer :: edge_j
      integer :: p_stage

      logical :: found

      uses_transport = .false.
      if (staged_side_is_local(base_i,base_j,side_index)) return
      if (side_index < 1 .or. side_index > size(hex_sides,2)) then
         call fail("staged outer-wavelet transport side is invalid")
      end if
      edge_id = ed_idx( &
           base_i,base_j,hex_sides(:,side_index),offs_par,dims_par)
      call locate_staged_coarse_edge( &
           edge_id,p_stage,edge_i,edge_j,edge_component,found)
      uses_transport = .not. found

    end function staged_side_uses_transport


    subroutine locate_staged_coarse_edge ( &
         edge_id,p_stage,i_stage,j_stage,e_stage,found)

      implicit none

      integer, intent(in) :: edge_id
      integer, intent(out) :: p_stage
      integer, intent(out) :: i_stage
      integer, intent(out) :: j_stage
      integer, intent(out) :: e_stage
      logical, intent(out) :: found

      integer :: cell
      integer :: node
      integer :: p_stage_index
      integer :: patch_start

      found = .false.
      p_stage = -1
      i_stage = -1
      j_stage = -1
      e_stage = mod(edge_id,EDGE)
      if (edge_id < 0 .or. e_stage < RT .or. e_stage > UP) return
      node = edge_id/EDGE
      do p_stage_index = 1,grid(d)%lev(wavelet_level)%length
         p_stage = grid(d)%lev(wavelet_level)%elts(p_stage_index)
         patch_start = grid(d)%patch%elts(p_stage+1)%elts_start
         if (node < patch_start .or. &
              node >= patch_start+PATCH_SIZE**2) cycle
         cell = node-patch_start
         i_stage = mod(cell,PATCH_SIZE)
         j_stage = cell/PATCH_SIZE
         found = .true.
         return
      end do
      p_stage = -1

    end subroutine locate_staged_coarse_edge


    real(dp) function staged_vector_value ( &
         p_stage,level_stage,i_stage,j_stage,e_stage, &
         require_reconstructed) result(value)

      implicit none

      integer, intent(in) :: p_stage
      integer, intent(in) :: level_stage
      integer, intent(in) :: i_stage
      integer, intent(in) :: j_stage
      integer, intent(in) :: e_stage
      logical, intent(in) :: require_reconstructed

      integer :: edge_id
      integer :: patch_slot
      integer :: produced_index
      integer :: value_index

      value = 0.0_dp
      patch_slot = block_writeback_plan%domain_patch_displ(d) + p_stage + 1
      value_index = (patch_slot-1)* &
           block_writeback_plan%vector_patch_nvalue + &
           (level_stage-1)*EDGE*PATCH_SIZE**2 + &
           EDGE*(PATCH_SIZE*j_stage+i_stage)+e_stage+1
      if (i_stage < 0 .or. i_stage >= PATCH_SIZE .or. &
           j_stage < 0 .or. j_stage >= PATCH_SIZE .or. &
           e_stage < RT .or. e_stage > UP .or. &
           patch_slot < 1 .or. patch_slot > &
           size(block_writeback_plan%domain_patch_covered) .or. &
           .not. block_writeback_plan%domain_patch_covered(patch_slot) .or. &
           value_index < 1 .or. value_index > &
           size(block_writeback_plan%vector_domain_stage)) then
         call fail("staged outer-wavelet source is invalid")
      end if
      if (require_reconstructed .and. .not. block_writeback_plan% &
           domain_patch_reconstructed(patch_slot)) then
         call fail("staged outer-wavelet fine source is not block-derived")
      end if
      if (grid(d)%patch%elts(p_stage+1)%level == wavelet_level) then
         edge_id = EDGE*(grid(d)%patch%elts(p_stage+1)%elts_start + &
              PATCH_SIZE*j_stage+i_stage)+e_stage
         produced_index = (staged_coarse_vector_boundary_plan% &
              domain_edge_displ(d)+edge_id)*n_field_level + level_stage
         if (produced_index < 1 .or. produced_index > &
              size(staged_coarse_vector_boundary_plan%source_produced) &
              .or. .not. staged_coarse_vector_boundary_plan% &
              source_produced(produced_index)) then
            call fail("staged outer-wavelet coarse source was not produced")
         end if
      end if
      value = block_writeback_plan%vector_domain_stage(value_index)
      if (.not. ieee_is_finite(value)) then
         call fail("staged outer-wavelet source is non-finite")
      end if

    end function staged_vector_value


    real(dp) function staged_side_value (base_i,base_j,side_index) &
         result(value)

      implicit none

      integer, intent(in) :: base_i
      integer, intent(in) :: base_j
      integer, intent(in) :: side_index

      integer :: edge_component
      integer :: edge_id
      integer :: edge_i
      integer :: edge_j
      integer :: lookup_index
      integer :: p_stage
      integer :: record

      logical :: found

      real(dp) :: degenerate_tolerance
      real(dp) :: midpoint_norm

      if (side_index < 1 .or. side_index > size(hex_sides,2)) then
         call fail("staged outer-wavelet side index is invalid")
      end if
      edge_i = base_i+hex_sides(1,side_index)
      edge_j = base_j+hex_sides(2,side_index)
      edge_component = hex_sides(3,side_index)
      if (staged_side_is_local(base_i,base_j,side_index)) then
         value = staged_vector_value( &
              p,level_slot,edge_i,edge_j,edge_component,.false.)
         return
      end if

      if (.not. staged_coarse_vector_boundary_plan%values_ready) then
         call fail("staged outer-wavelet boundary is not ready")
      end if
      edge_id = ed_idx( &
           base_i,base_j,hex_sides(:,side_index),offs_par,dims_par)
      call locate_staged_coarse_edge( &
           edge_id,p_stage,edge_i,edge_j,edge_component,found)
      if (found) then
         value = staged_vector_value( &
              p_stage,level_slot,edge_i,edge_j,edge_component,.false.)
         return
      end if
      lookup_index = staged_coarse_vector_boundary_plan% &
           domain_edge_displ(d)+edge_id+1
      if (lookup_index < 1 .or. lookup_index > &
           size(staged_coarse_vector_boundary_plan%boundary_lookup)) then
         call fail("staged outer-wavelet boundary lookup is invalid")
      end if
      record = staged_coarse_vector_boundary_plan% &
           boundary_lookup(lookup_index)
      if (record < 1 .or. record > &
           staged_coarse_vector_boundary_plan%n_recv + &
           staged_coarse_vector_boundary_plan%n_local) then
         ! At a pentagon, one logical component of the collapsed edge has
         ! zero dual length, while companion components of the same special
         ! hexagon have no physical midpoint.  wavelet_mod retains these
         ! structural zeros in its regular interpolation stencil, while
         ! create_pack_st2 deliberately provides no boundary routes for
         ! them.  Recognize the geometry, not hard-coded corner addresses,
         ! and do not import the authoritative Domain field as a source.
         degenerate_tolerance = 64.0_dp*epsilon(1.0_dp)*max( &
              1.0_dp,abs(grid(d)%len%elts(edge_id+1)))
         midpoint_norm = abs(grid(d)%midpt%elts(edge_id+1)%x) + &
              abs(grid(d)%midpt%elts(edge_id+1)%y) + &
              abs(grid(d)%midpt%elts(edge_id+1)%z)
         if (abs(grid(d)%pedlen%elts(edge_id+1)) <= &
              degenerate_tolerance .or. &
              midpoint_norm <= degenerate_tolerance) then
            value = 0.0_dp
            return
         end if
         write(error_unit,'(/,a,i0,a)') &
              "Rank ",rank, &
              ": staged outer-wavelet boundary route is missing"
         write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
              "  Domain = ",d,", parent patch = ",p, &
              ", parent i = ",i_par,", parent j = ",j_par
         write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
              "  wavelet edge = ",e,", side index = ",side_index, &
              ", base i = ",base_i,", base j = ",base_j
         write(error_unit,'(a,i0,a,i0)') &
              "  resolved edge id = ",edge_id, &
              ", lookup index = ",lookup_index
         flush(error_unit)
         call fail("staged outer-wavelet boundary source is unavailable")
      end if
      if (staged_coarse_vector_boundary_plan%boundary_produced( &
           (record-1)*n_field_level+level_slot) /= 1) then
         call fail("staged outer-wavelet boundary source was not produced")
      end if
      value = staged_coarse_vector_boundary_plan%boundary_value( &
           (record-1)*n_field_level+level_slot)
      if (.not. ieee_is_finite(value)) then
         call fail("staged outer-wavelet boundary source is non-finite")
      end if

    end function staged_side_value


    real(dp) function staged_outer_wavelet (scale) result(value)

      implicit none

      real(dp), intent(out) :: scale

      integer, parameter :: N_SIDE_TERM = 12

      integer :: base_i(N_SIDE_TERM)
      integer :: base_j(N_SIDE_TERM)
      integer :: edge_id(N_SIDE_TERM)
      integer :: first_term
      integer :: k
      integer :: m
      integer :: side_index(N_SIDE_TERM)
      integer :: target_i
      integer :: target_j
      integer :: target_node

      logical :: consumed(N_SIDE_TERM)

      real(dp) :: coefficient(N_SIDE_TERM)
      real(dp) :: coefficient_tolerance
      real(dp) :: net_coefficient
      real(dp) :: side_value
      real(dp) :: source_value
      real(dp) :: target_value
      real(dp) :: weight(9)

      target_i = i_chd+end_pt(1,2,e+1)
      target_j = j_chd+end_pt(2,2,e+1)
      target_node = grid(d)%patch%elts(p_child+1)%elts_start + &
           PATCH_SIZE*target_j+target_i
      weight = BLOCK_IU_BASE_WEIGHT + &
           [ (grid(d)%I_u_wgt%elts(target_node+1)%enc(k),k=1,9) ]
      coefficient_tolerance = 64.0_dp*epsilon(1.0_dp)*max( &
           1.0_dp,maxval(abs(weight)))

      ! Keep the twelve primitive side terms in exactly the order and
      ! topology used by wavelet_mod:Interp_outer_velo.  Some small-grid
      ! corner addresses are intentionally absent from create_pack_st2;
      ! they may be discarded only after all logical addresses have been
      ! resolved to Domain edge IDs and their coefficients cancel there.
      base_i = [ &
           i_par+end_pt(1,2,e+1), &
           i_par+end_pt(1,1,e+1), &
           i_par+end_pt(1,1,e+1), &
           i_par+end_pt(1,2,e+1), &
           i_par+opp_no(1,1,e+1), &
           i_par+end_pt(1,1,e+1), &
           i_par+end_pt(1,2,e+1), &
           i_par+opp_no(1,1,e+1), &
           i_par+opp_no(1,2,e+1), &
           i_par+end_pt(1,2,e+1), &
           i_par+end_pt(1,1,e+1), &
           i_par+opp_no(1,2,e+1) ]
      base_j = [ &
           j_par+end_pt(2,2,e+1), &
           j_par+end_pt(2,1,e+1), &
           j_par+end_pt(2,1,e+1), &
           j_par+end_pt(2,2,e+1), &
           j_par+opp_no(2,1,e+1), &
           j_par+end_pt(2,1,e+1), &
           j_par+end_pt(2,2,e+1), &
           j_par+opp_no(2,1,e+1), &
           j_par+opp_no(2,2,e+1), &
           j_par+end_pt(2,2,e+1), &
           j_par+end_pt(2,1,e+1), &
           j_par+opp_no(2,2,e+1) ]
      side_index = hex_s_offs(e+1) + &
           [ 3,4,6,1,2,3,4,5,5,6,1,2 ]
      coefficient = [ &
           weight(2),weight(3),weight(4),weight(5), &
           weight(6),-weight(6),weight(7),-weight(7), &
           weight(8),-weight(8),weight(9),-weight(9) ]

      do k = 1,N_SIDE_TERM
         edge_id(k) = ed_idx( &
              base_i(k),base_j(k),hex_sides(:,side_index(k)), &
              offs_par,dims_par)
      end do

      source_value = weight(1)*staged_vector_value( &
           p,level_slot,i_par,j_par,e,.false.)
      scale = abs(source_value)
      consumed = .false.
      do first_term = 1,N_SIDE_TERM
         if (consumed(first_term)) cycle
         net_coefficient = 0.0_dp
         do m = first_term,N_SIDE_TERM
            if (edge_id(m) /= edge_id(first_term)) cycle
            net_coefficient = net_coefficient+coefficient(m)
            consumed(m) = .true.
         end do
         if (abs(net_coefficient) <= coefficient_tolerance) cycle
         side_value = staged_side_value( &
              base_i(first_term),base_j(first_term), &
              side_index(first_term))
         source_value = source_value+net_coefficient*side_value
         scale = scale+abs(net_coefficient*side_value)
      end do
      target_value = staged_vector_value( &
           p_child,level_slot,target_i,target_j,e,.true.)
      value = target_value-source_value
      scale = abs(target_value)+scale

    end function staged_outer_wavelet


    subroutine staged_wavelet_references ( &
         mask,reference,companion)

      implicit none

      real(dp), intent(out) :: mask
      real(dp), intent(out) :: reference
      real(dp), intent(out) :: companion

      integer :: companion_i
      integer :: companion_j
      integer :: companion_node
      integer :: target_i
      integer :: target_j
      integer :: target_node

      target_i = i_chd+end_pt(1,2,e+1)
      target_j = j_chd+end_pt(2,2,e+1)
      companion_i = i_chd+end_pt(1,1,e+1)
      companion_j = j_chd+end_pt(2,1,e+1)
      target_node = grid(d)%patch%elts(p_child+1)%elts_start + &
           PATCH_SIZE*target_j+target_i
      companion_node = grid(d)%patch%elts(p_child+1)%elts_start + &
           PATCH_SIZE*companion_j+companion_i
      if (target_i < 0 .or. target_i >= PATCH_SIZE .or. &
           target_j < 0 .or. target_j >= PATCH_SIZE .or. &
           companion_i < 0 .or. companion_i >= PATCH_SIZE .or. &
           companion_j < 0 .or. companion_j >= PATCH_SIZE) then
         call fail("staged outer-wavelet fine target is invalid")
      end if
      mask = real(grid(d)%mask_e%elts(EDGE*target_node+e+1),dp)
      reference = wav_coeff(S_VELO,field_level)% &
           data(d)%elts(EDGE*target_node+e+1)
      companion = wav_coeff(S_VELO,field_level)% &
           data(d)%elts(EDGE*companion_node+e+1)
      if (.not. ieee_is_finite(reference) .or. &
           .not. ieee_is_finite(companion)) then
         call fail("staged outer-wavelet reference is non-finite")
      end if

    end subroutine staged_wavelet_references


    subroutine report_staged_outer_mismatch (message)

      implicit none

      character(len=*), intent(in) :: message

      write(error_unit,'(/,a,i0,a,a)') &
           "Rank ",rank,": ",trim(message)
      write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
           "  Domain = ",d,", parent patch = ",p, &
           ", child = ",c,", child patch = ",p_child
      write(error_unit,'(a,i0,a,i0,a,i0)') &
           "  wavelet level = ",wavelet_level, &
           ", field level = ",field_level,", edge = ",e
      write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
           "  parent coordinates = ",i_par,", ",j_par, &
           "; child coordinates = ",i_chd,", ",j_chd
      write(error_unit,'(a,4(es24.16,1x))') &
           "  native, reference, companion, allowed = ", &
           native_value,reference_value,companion_reference,allowed
      flush(error_unit)
      call fail("staged coarse outer-wavelet comparison failed")

    end subroutine report_staged_outer_mismatch

  end subroutine validate_staged_coarse_outer_vector_wavelets


  subroutine compare_block_outer_vector_wavelets ( &
       catalog_index,block,context)
    ! Reproduce the nine-edge Interp_outer_velo stencil and its paired
    ! antisymmetric coefficient for every regular parent-child cell.

    implicit none

    integer, intent(in) :: catalog_index
    type(Block_Data), intent(in) :: block
    class(*), intent(inout) :: context

    integer :: c
    integer :: child
    integer :: e
    integer :: i
    integer :: i_chd
    integer :: i_par
    integer :: j
    integer :: j_chd
    integer :: j_par
    integer :: level_slot
    integer :: local_index
    integer :: p

    local_index = catalog_local_block(catalog_index)
    if (local_index < 1 .or. &
         local_index > size(block_scalar_tendency)) then
       call fail("outer vector-wavelet comparison block is invalid")
    end if
    if (.not. block_scalar_tendency(local_index)%ready .or. &
         block_scalar_tendency(local_index)%catalog_index /= &
         catalog_index) then
       call fail("outer vector-wavelet geometry block is stale")
    end if

    select type (statistics => context)
    type is (Block_Outer_Vector_Wavelet_Context)
       do p = 1,size(block%patch)
          if (block%patch(p)%level /= statistics%wavelet_level) cycle
          statistics%parent_patch_count = &
               statistics%parent_patch_count + 1_int64
          do c = 1,N_CHDRN
             child = block%patch(p)%children(c)
             if (child == 0) cycle
             if (child < 0 .or. child >= size(block%patch)) then
                call fail("outer vector-wavelet child patch is invalid")
             end if
             if (block%patch(child+1)%level /= &
                  block%patch(p)%level+1) then
                call fail("outer vector-wavelet child level is invalid")
             end if
             do level_slot = 1,block%n_field_level
                if (block%field_level+level_slot-1 < 1 .or. &
                     block%field_level+level_slot-1 > zlevels) cycle
                do j = 1,PATCH_SIZE/2
                   j_chd = 2*(j-1)
                   j_par = j-1+chd_offs(2,c)
                   do i = 1,PATCH_SIZE/2
                      i_chd = 2*(i-1)
                      i_par = i-1+chd_offs(1,c)
                      do e = RT,UP
                         call compare_outer_pair(statistics)
                      end do
                   end do
                end do
             end do
          end do
       end do
    class default
       call fail("outer vector-wavelet comparison context is invalid")
    end select

  contains

    subroutine compare_outer_pair (stats)

      implicit none

      type(Block_Outer_Vector_Wavelet_Context), intent(inout) :: stats

      integer :: companion_i
      integer :: companion_j
      integer :: target_i
      integer :: target_j

      real(dp) :: allowed
      real(dp) :: companion_reference
      real(dp) :: mask_value
      real(dp) :: native_value
      real(dp) :: operation_scale
      real(dp) :: reference_value

      companion_i = i_chd+end_pt(1,1,e+1)
      companion_j = j_chd+end_pt(2,1,e+1)
      target_i = i_chd+end_pt(1,2,e+1)
      target_j = j_chd+end_pt(2,2,e+1)
      stats%candidate_count = stats%candidate_count + 2_int64
      mask_value = block_scalar_record_value( &
           block,local_index,child+1,0,level_slot,target_i,target_j, &
           BLOCK_SCALAR_EDGE_MASK_START+e)
      reference_value = block_vector_family_value( &
           block,local_index,child+1,level_slot,target_i,target_j,e, &
           BLOCK_PAYLOAD_WAV_COEFF)
      companion_reference = block_vector_family_value( &
           block,local_index,child+1,level_slot, &
           companion_i,companion_j,e,BLOCK_PAYLOAD_WAV_COEFF)
      if (mask_value < real(ADJZONE,dp)) then
         if (abs(reference_value) > 0.0_dp .or. &
              abs(companion_reference) > 0.0_dp) then
            call report_outer_vector_wavelet_mismatch( &
                 "inactive outer vector wavelet is not zero", &
                 target_i,target_j,companion_i,companion_j, &
                 0.0_dp,reference_value,companion_reference,0.0_dp)
         end if
         return
      end if

      stats%active_count = stats%active_count + 2_int64
      native_value = compute_block_outer_vector_wavelet( &
           block,local_index,p,child+1,level_slot,i_par,j_par, &
           i_chd,j_chd,e,operation_scale)
      allowed = 64.0_dp*epsilon(1.0_dp)*max( &
           1.0_dp,abs(native_value),abs(reference_value), &
           abs(companion_reference),operation_scale)
      if (abs(native_value-reference_value) > allowed .or. &
           abs(native_value+companion_reference) > allowed) then
         call report_outer_vector_wavelet_mismatch( &
              "block-native outer vector wavelet differs", &
              target_i,target_j,companion_i,companion_j,native_value, &
              reference_value,companion_reference,allowed)
      end if
      stats%compared_count = stats%compared_count + 2_int64

    end subroutine compare_outer_pair


    subroutine report_outer_vector_wavelet_mismatch ( &
         message,target_i,target_j,companion_i,companion_j,native_value, &
         reference_value,companion_reference,allowed)

      implicit none

      character(len=*), intent(in) :: message
      integer, intent(in) :: target_i
      integer, intent(in) :: target_j
      integer, intent(in) :: companion_i
      integer, intent(in) :: companion_j
      real(dp), intent(in) :: native_value
      real(dp), intent(in) :: reference_value
      real(dp), intent(in) :: companion_reference
      real(dp), intent(in) :: allowed

      write(error_unit,'(/,a,i0,a,a)') &
           "Rank ",rank,": ",trim(message)
      write(error_unit,'(a,i0,a,i0,a,i0)') &
           "  catalog block = ",catalog_index, &
           ", block id = ",block%id,", parent patch = ",p
      write(error_unit,'(a,i0,a,i0,a,i0)') &
           "  level = ",block%patch(p)%level, &
           ", child = ",c,", child patch = ",child+1
      write(error_unit,'(a,i0,a,i0,a,i0)') &
           "  field-level slot = ",level_slot, &
           ", physical level = ",block%field_level+level_slot-1, &
           ", edge = ",e
      write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
           "  target coordinates = ",target_i,", ",target_j, &
           "; companion coordinates = ",companion_i,", ",companion_j
      write(error_unit,'(a,4(es24.16,1x))') &
           "  native, reference, companion, allowed = ", &
           native_value,reference_value,companion_reference,allowed
      flush(error_unit)
      call fail("outer vector-wavelet shadow comparison failed")

    end subroutine report_outer_vector_wavelet_mismatch

  end subroutine compare_block_outer_vector_wavelets


  real(dp) function compute_block_outer_vector_wavelet ( &
       block,local_index,parent,child,level_slot,i_par,j_par, &
       i_chd,j_chd,e,operation_scale) result(value)
    ! Exact block form of Interp_outer_velo for one fine outer edge.

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: parent
    integer, intent(in) :: child
    integer, intent(in) :: level_slot
    integer, intent(in) :: i_par
    integer, intent(in) :: j_par
    integer, intent(in) :: i_chd
    integer, intent(in) :: j_chd
    integer, intent(in) :: e
    real(dp), intent(out) :: operation_scale

    integer :: i
    integer :: target_i
    integer :: target_j

    real(dp) :: source_value(9)
    real(dp) :: target_value
    real(dp) :: weight(9)

    target_i = i_chd+end_pt(1,2,e+1)
    target_j = j_chd+end_pt(2,2,e+1)
    source_value(1) = block_vector_family_value( &
         block,local_index,parent,level_slot,i_par,j_par,e, &
         BLOCK_PAYLOAD_SOL)
    source_value(2) = side_edge_value( &
         i_par+end_pt(1,2,e+1),j_par+end_pt(2,2,e+1), &
         hex_s_offs(e+1)+3)
    source_value(3) = side_edge_value( &
         i_par+end_pt(1,1,e+1),j_par+end_pt(2,1,e+1), &
         hex_s_offs(e+1)+4)
    source_value(4) = side_edge_value( &
         i_par+end_pt(1,1,e+1),j_par+end_pt(2,1,e+1), &
         hex_s_offs(e+1)+6)
    source_value(5) = side_edge_value( &
         i_par+end_pt(1,2,e+1),j_par+end_pt(2,2,e+1), &
         hex_s_offs(e+1)+1)
    source_value(6) = side_edge_value( &
         i_par+opp_no(1,1,e+1),j_par+opp_no(2,1,e+1), &
         hex_s_offs(e+1)+2)-side_edge_value( &
         i_par+end_pt(1,1,e+1),j_par+end_pt(2,1,e+1), &
         hex_s_offs(e+1)+3)
    source_value(7) = side_edge_value( &
         i_par+end_pt(1,2,e+1),j_par+end_pt(2,2,e+1), &
         hex_s_offs(e+1)+4)-side_edge_value( &
         i_par+opp_no(1,1,e+1),j_par+opp_no(2,1,e+1), &
         hex_s_offs(e+1)+5)
    source_value(8) = side_edge_value( &
         i_par+opp_no(1,2,e+1),j_par+opp_no(2,2,e+1), &
         hex_s_offs(e+1)+5)-side_edge_value( &
         i_par+end_pt(1,2,e+1),j_par+end_pt(2,2,e+1), &
         hex_s_offs(e+1)+6)
    source_value(9) = side_edge_value( &
         i_par+end_pt(1,1,e+1),j_par+end_pt(2,1,e+1), &
         hex_s_offs(e+1)+1)-side_edge_value( &
         i_par+opp_no(1,2,e+1),j_par+opp_no(2,2,e+1), &
         hex_s_offs(e+1)+2)
    weight = BLOCK_IU_BASE_WEIGHT
    weight = weight + [ (block_scalar_record_value( &
         block,local_index,child,0,level_slot,target_i,target_j, &
         BLOCK_VECTOR_WAVELET_WEIGHT_START+i),i=0,8) ]
    target_value = block_vector_family_value( &
         block,local_index,child,level_slot,target_i,target_j,e, &
         BLOCK_PAYLOAD_SOL)
    value = target_value-sum(weight*source_value)
    operation_scale = abs(target_value)+sum(abs(weight*source_value))

  contains

    real(dp) function side_edge_value (base_i,base_j,side_index) &
         result(edge_value)

      implicit none

      integer, intent(in) :: base_i
      integer, intent(in) :: base_j
      integer, intent(in) :: side_index

      integer :: edge_component
      integer :: edge_i
      integer :: edge_j

      if (side_index < 1 .or. side_index > size(hex_sides,2)) then
         call fail("outer vector-wavelet side index is invalid")
      end if
      edge_i = base_i+hex_sides(1,side_index)
      edge_j = base_j+hex_sides(2,side_index)
      edge_component = hex_sides(3,side_index)
      edge_value = block_vector_family_value( &
           block,local_index,parent,level_slot,edge_i,edge_j, &
           edge_component,BLOCK_PAYLOAD_SOL)

    end function side_edge_value

  end function compute_block_outer_vector_wavelet


  subroutine validate_complete_block_vector_wavelets (first_level)
    ! Produce the complete regular-outer, regular-inner and pentagon-corrected
    ! vector family from the block-derived Domain stage.  Geometry is read
    ! from grid, while every velocity source comes from reconstructed blocks
    ! or the independently exchanged Stage-123 boundary payload.

    implicit none

    integer, intent(in) :: first_level

    integer :: c
    integer :: d
    integer :: e
    integer :: edge_id
    integer :: field_level
    integer :: first_field_level
    integer :: i
    integer :: i_chd
    integer :: i_par
    integer :: ierr
    integer :: j
    integer :: j_chd
    integer :: j_par
    integer :: l
    integer :: level_slot
    integer :: lookup_index
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_edge_value
    integer :: n_field_level
    integer :: n_scalar_variable
    integer :: node
    integer :: p
    integer :: p_child
    integer :: p_index
    integer :: patch_slot
    integer :: record
    integer :: produced_index
    integer :: stage_index
    integer :: stage_start
    integer :: transform_start
    integer :: v_scalar
    integer :: v_vector

    integer :: dims_chd(2,N_BDRY+1)
    integer :: dims_par(2,N_BDRY+1)
    integer :: offs_chd(N_BDRY+1)
    integer :: offs_par(N_BDRY+1)

    integer(int64) :: count_global(4)
    integer(int64) :: count_local(4)

    logical :: route_valid

    real(dp), pointer :: native_velo(:)
    real(dp), pointer :: native_wc(:)
    real(dp) :: allowed
    real(dp) :: degenerate_tolerance
    real(dp) :: midpoint_norm
    real(dp) :: native_value
    real(dp) :: reference_value

    if (production_complete_vector_wavelet_validated) then
       call fail("complete vector wavelet was already validated")
    end if
    if (first_level /= level_start-1 .or. &
         .not. production_coarse_outer_wavelet_validated .or. &
         .not. staged_coarse_vector_boundary_plan%values_ready) then
       call fail("complete vector wavelet prerequisites are incomplete")
    end if
    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    if (v_vector /= S_VELO .or. mult_vector /= EDGE .or. &
         n_field_level < 1) then
       call fail("complete vector wavelet field layout is invalid")
    end if
    if (.not. allocated(production_vector_transform_displ) .or. &
         .not. allocated(production_vector_transform_stage) .or. &
         .not. allocated(production_vector_wavelet_stage) .or. &
         size(production_vector_transform_displ) /= size(grid)+1) then
       call fail("complete vector wavelet stage is not allocated")
    end if

    production_vector_transform_stage = 0.0_dp
    production_vector_wavelet_stage = 0.0_dp
    production_vector_transform_covered = .false.

    ! Expand the compact block stage into immutable Domain indexing.  Patch
    ! interiors and boundary routes have disjoint provenance and are checked
    ! independently before this point.
    do d = 1,size(grid)
       n_edge_value = size(sol(S_VELO,first_field_level)%data(d)%elts)
       do p = 0,grid(d)%patch%length-1
          if (grid(d)%patch%elts(p+1)%deleted) cycle
          patch_slot = block_writeback_plan%domain_patch_displ(d)+p+1
          if (patch_slot < 1 .or. patch_slot > &
               size(block_writeback_plan%domain_patch_covered) .or. &
               .not. block_writeback_plan%domain_patch_covered(patch_slot)) &
               call fail("complete vector wavelet patch is unavailable")
          stage_start = (patch_slot-1)* &
               block_writeback_plan%vector_patch_nvalue
          do level_slot = 1,n_field_level
             transform_start = production_vector_transform_displ(d) + &
                  (level_slot-1)*n_edge_value
             do node = 0,PATCH_SIZE**2-1
                do e = RT,UP
                   edge_id = EDGE*( &
                        grid(d)%patch%elts(p+1)%elts_start+node)+e
                   stage_index = stage_start + &
                        (level_slot-1)*EDGE*PATCH_SIZE**2 + &
                        EDGE*node+e+1
                   production_vector_transform_stage( &
                        transform_start+edge_id+1) = &
                        block_writeback_plan%vector_domain_stage(stage_index)
                   if (grid(d)%patch%elts(p+1)%level == first_level) then
                      produced_index = ( &
                           staged_coarse_vector_boundary_plan% &
                           domain_edge_displ(d)+edge_id)*n_field_level + &
                           level_slot
                      if (produced_index < 1 .or. produced_index > size( &
                           staged_coarse_vector_boundary_plan% &
                           source_produced)) then
                         call fail( &
                              "complete vector source address is invalid")
                      end if
                      production_vector_transform_covered( &
                           transform_start+edge_id+1) = &
                           staged_coarse_vector_boundary_plan% &
                           source_produced(produced_index)
                   else
                      production_vector_transform_covered( &
                           transform_start+edge_id+1) = &
                           block_writeback_plan% &
                           domain_patch_reconstructed(patch_slot)
                   end if
                end do
             end do
          end do
       end do

       do edge_id = 0,n_edge_value-1
          lookup_index = staged_coarse_vector_boundary_plan% &
               domain_edge_displ(d)+edge_id+1
          if (lookup_index < 1 .or. lookup_index > size( &
               staged_coarse_vector_boundary_plan%boundary_lookup)) cycle
          record = staged_coarse_vector_boundary_plan% &
               boundary_lookup(lookup_index)
          route_valid = record >= 1 .and. record <= &
               staged_coarse_vector_boundary_plan%n_recv + &
               staged_coarse_vector_boundary_plan%n_local
          do level_slot = 1,n_field_level
             transform_start = production_vector_transform_displ(d) + &
                  (level_slot-1)*n_edge_value
             stage_index = (staged_coarse_vector_boundary_plan% &
                  domain_edge_displ(d)+edge_id)*n_field_level + &
                  level_slot
             if (stage_index < 1 .or. stage_index > size( &
                  staged_coarse_vector_boundary_plan% &
                  retained_boundary_produced)) then
                call fail("complete retained boundary address is invalid")
             end if
             if (route_valid) then
                if (staged_coarse_vector_boundary_plan%boundary_produced( &
                     (record-1)*n_field_level+level_slot) == 1) then
                   production_vector_transform_stage( &
                        transform_start+edge_id+1) = &
                        staged_coarse_vector_boundary_plan%boundary_value( &
                        (record-1)*n_field_level+level_slot)
                   production_vector_transform_covered( &
                        transform_start+edge_id+1) = .true.
                   cycle
                end if
             end if
             if (staged_coarse_vector_boundary_plan% &
                  retained_boundary_produced(stage_index)) then
                ! Some full-range update_bdry routes originate on the fixed
                ! coarse scaffold and therefore have no reconstructed source
                ! flag.  Their independently retained block-boundary value is
                ! the correct native destination-oriented source.
                production_vector_transform_stage( &
                     transform_start+edge_id+1) = &
                     staged_coarse_vector_boundary_plan% &
                     retained_boundary_value(stage_index)
                production_vector_transform_covered( &
                     transform_start+edge_id+1) = .true.
             else if (route_valid) then
                if (edge_id+1 <= min(size(grid(d)%len%elts), &
                     size(grid(d)%pedlen%elts), &
                     size(grid(d)%midpt%elts))) then
                   degenerate_tolerance = &
                        64.0_dp*epsilon(1.0_dp)*max( &
                        1.0_dp,abs(grid(d)%len%elts(edge_id+1)))
                   midpoint_norm = &
                        abs(grid(d)%midpt%elts(edge_id+1)%x) + &
                        abs(grid(d)%midpt%elts(edge_id+1)%y) + &
                        abs(grid(d)%midpt%elts(edge_id+1)%z)
                   if (abs(grid(d)%pedlen%elts(edge_id+1)) <= &
                        degenerate_tolerance .or. &
                        midpoint_norm <= degenerate_tolerance) then
                      ! A pentagon is a hexagon with one collapsed zero-length
                      ! edge.  Unrouted logical components of that edge are
                      ! exact structural zeros in the regular stencil.
                      production_vector_transform_stage( &
                           transform_start+edge_id+1) = 0.0_dp
                      production_vector_transform_covered( &
                           transform_start+edge_id+1) = .true.
                   end if
                end if
             end if
          end do
       end do
    end do

    call seed_complete_vector_route_sources( &
         first_field_level,n_field_level)
    call propagate_complete_vector_boundaries( &
         first_field_level,n_field_level)

    count_local = 0_int64
    do d = 1,size(grid)
       n_edge_value = size(sol(S_VELO,first_field_level)%data(d)%elts)
       do level_slot = 1,n_field_level
          field_level = first_field_level+level_slot-1
          if (field_level < 1 .or. field_level > zlevels) cycle
          transform_start = production_vector_transform_displ(d) + &
               (level_slot-1)*n_edge_value
          native_velo => production_vector_transform_stage( &
               transform_start+1:transform_start+n_edge_value)
          native_wc => production_vector_wavelet_stage( &
               transform_start+1:transform_start+n_edge_value)

          do l = level_end-1,first_level,-1
             do p_index = 1,grid(d)%lev(l)%length
                p = grid(d)%lev(l)%elts(p_index)
                call get_offs_Domain(grid(d),p,offs_par,dims_par)
                do c = 1,N_CHDRN
                   p_child = grid(d)%patch%elts(p+1)%children(c)
                   if (p_child == 0) cycle
                   call get_offs_Domain( &
                        grid(d),p_child,offs_chd,dims_chd)
                   do j = 1,PATCH_SIZE/2
                      j_chd = 2*(j-1)
                      j_par = j-1+chd_offs(2,c)
                      do i = 1,PATCH_SIZE/2
                         i_chd = 2*(i-1)
                         i_par = i-1+chd_offs(1,c)
                         call produce_regular_vector_cell
                         count_local(1) = count_local(1)+12_int64
                      end do
                   end do
                end do
             end do
             call apply_native_pentagon_level(l)
          end do

          do p = 0,grid(d)%patch%length-1
             if (grid(d)%patch%elts(p+1)%deleted .or. &
                  grid(d)%patch%elts(p+1)%level <= first_level .or. &
                  grid(d)%patch%elts(p+1)%level > level_end) cycle
             do node = 0,PATCH_SIZE**2-1
                do e = RT,UP
                   edge_id = EDGE*( &
                        grid(d)%patch%elts(p+1)%elts_start+node)+e
                   native_value = native_wc(edge_id+1)
                   reference_value = wav_coeff(S_VELO,field_level)% &
                        data(d)%elts(edge_id+1)
                   allowed = 128.0_dp*epsilon(1.0_dp)*max( &
                        1.0_dp,abs(native_value),abs(reference_value))
                   count_local(2) = count_local(2)+1_int64
                   if (grid(d)%mask_e%elts(edge_id+1) >= ADJZONE) &
                        count_local(3) = count_local(3)+1_int64
                   if (.not. ieee_is_finite(native_value) .or. &
                        abs(native_value-reference_value) > allowed) then
                      write(error_unit,'(/,a,i0,a)') "Rank ",rank, &
                           ": complete block-derived vector wavelet differs"
                      write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
                           "  Domain = ",d,", patch = ",p, &
                           ", level = ",grid(d)%patch%elts(p+1)%level, &
                           ", field level = ",field_level
                      write(error_unit,'(a,i0,a,i0,a,i0)') &
                           "  node = ",node,", edge = ",e, &
                           ", edge id = ",edge_id
                      write(error_unit,'(a,3(es24.16,1x))') &
                           "  native, reference, allowed = ", &
                           native_value,reference_value,allowed
                      flush(error_unit)
                      call fail( &
                           "complete vector-wavelet comparison failed")
                   end if
                   count_local(4) = count_local(4)+1_int64
                end do
             end do
          end do
          nullify(native_velo,native_wc)
       end do
    end do

    call MPI_Allreduce(count_local,count_global,size(count_local), &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce complete vector-wavelet coverage")
    if (any(count_global <= 0_int64) .or. &
         count_global(2) /= count_global(4)) then
       call fail("complete vector-wavelet coverage is incomplete")
    end if
    production_complete_vector_wavelet_validated = .true.
    if (rank == 0) then
       write(6,'(a,i0,a,i0,a,i0)') &
            "  complete block-derived vector wavelet production passed: "// &
            "regular coefficients = ",count_global(1), &
            ", stored coefficients = ",count_global(2), &
            ", active coefficients = ",count_global(3)
    end if

  contains

    subroutine seed_complete_vector_route_sources ( &
         first_level_field,n_level_field)
      ! A coarse physical edge can occur both in a patch interior and in one
      ! or more boundary-patch storage records.  update_bdry inherits the
      ! current values before applying its communication routes.  Retain
      ! untouched fixed-scaffold patch values from the block candidate, then
      ! seed any remaining storage aliases from an independently produced
      ! interior representation with identical edge geometry.

      implicit none

      integer, intent(in) :: first_level_field
      integer, intent(in) :: n_level_field

      integer :: d_source
      integer :: p_route
      integer :: source_id

      do p_route = 1,staged_coarse_vector_boundary_plan%n_send
         d_source = staged_coarse_vector_boundary_plan% &
              send_domain(p_route)
         source_id = staged_coarse_vector_boundary_plan%send_id(p_route)
         call seed_complete_vector_route_source( &
              d_source,source_id,first_level_field,n_level_field)
      end do
      do p_route = 1,staged_coarse_vector_boundary_plan%n_local
         d_source = staged_coarse_vector_boundary_plan% &
              local_source_domain(p_route)
         source_id = staged_coarse_vector_boundary_plan% &
              local_source_id(p_route)
         call seed_complete_vector_route_source( &
              d_source,source_id,first_level_field,n_level_field)
      end do

    end subroutine seed_complete_vector_route_sources


    subroutine seed_complete_vector_route_source ( &
         d_alias,edge_alias,first_level_field,n_level_field)

      implicit none

      integer, intent(in) :: d_alias
      integer, intent(in) :: edge_alias
      integer, intent(in) :: first_level_field
      integer, intent(in) :: n_level_field

      integer :: candidate_id
      integer :: candidate_index
      integer :: field_slot
      integer :: geometry_extent
      integer :: matching_count
      integer :: node_alias
      integer :: p_alias
      integer :: p_index
      integer :: patch_slot
      integer :: patch_start
      integer :: source_index

      real(dp) :: geometry_allowed
      real(dp) :: midpoint_norm

      if (d_alias < 1 .or. d_alias > size(grid)) then
         call fail("complete vector alias Domain is invalid")
      end if
      node_alias = edge_alias/EDGE
      do p_index = 1,grid(d_alias)%lev(first_level)%length
         p_alias = grid(d_alias)%lev(first_level)%elts(p_index)
         if (grid(d_alias)%patch%elts(p_alias+1)%deleted) cycle
         patch_start = grid(d_alias)%patch%elts(p_alias+1)%elts_start
         if (node_alias < patch_start .or. &
              node_alias >= patch_start+PATCH_SIZE**2) cycle
         patch_slot = block_writeback_plan%domain_patch_displ(d_alias) + &
              p_alias+1
         if (patch_slot < 1 .or. patch_slot > &
              size(block_writeback_plan%domain_patch_covered) .or. &
              .not. block_writeback_plan% &
              domain_patch_covered(patch_slot)) then
            call fail("complete vector coarse route patch is unavailable")
         end if
         do field_slot = 1,n_level_field
            source_index = complete_transform_index( &
                 d_alias,edge_alias,field_slot,first_level_field)
            if (production_vector_transform_covered(source_index)) cycle
            if (.not. ieee_is_finite( &
                 production_vector_transform_stage(source_index))) then
               call fail("complete vector coarse route value is non-finite")
            end if
            production_vector_transform_covered(source_index) = .true.
         end do
         return
      end do

      geometry_extent = min(size(grid(d_alias)%midpt%elts), &
           size(grid(d_alias)%len%elts), &
           size(grid(d_alias)%pedlen%elts), &
           EDGE*size(grid(d_alias)%level%elts), &
           size(sol(S_VELO,first_level_field)%data(d_alias)%elts))
      if (edge_alias < 0 .or. edge_alias >= geometry_extent) return
      if (grid(d_alias)%level%elts(edge_alias/EDGE+1) /= first_level) return

      geometry_allowed = 64.0_dp*epsilon(1.0_dp)*max( &
           1.0_dp,abs(grid(d_alias)%len%elts(edge_alias+1)), &
           abs(grid(d_alias)%pedlen%elts(edge_alias+1)))
      midpoint_norm = &
           abs(grid(d_alias)%midpt%elts(edge_alias+1)%x) + &
           abs(grid(d_alias)%midpt%elts(edge_alias+1)%y) + &
           abs(grid(d_alias)%midpt%elts(edge_alias+1)%z)

      do field_slot = 1,n_level_field
         source_index = complete_transform_index( &
              d_alias,edge_alias,field_slot,first_level_field)
         if (production_vector_transform_covered(source_index)) cycle
         if (abs(grid(d_alias)%pedlen%elts(edge_alias+1)) <= &
              geometry_allowed .or. midpoint_norm <= geometry_allowed) then
            production_vector_transform_stage(source_index) = 0.0_dp
            production_vector_transform_covered(source_index) = .true.
            cycle
         end if

         matching_count = 0
         do candidate_id = 0,geometry_extent-1
            if (candidate_id == edge_alias) cycle
            if (grid(d_alias)%level%elts(candidate_id/EDGE+1) /= &
                 first_level) cycle
            candidate_index = complete_transform_index( &
                 d_alias,candidate_id,field_slot,first_level_field)
            if (.not. production_vector_transform_covered( &
                 candidate_index)) cycle
            if (.not. complete_vector_edge_geometry_matches( &
                 d_alias,edge_alias,candidate_id,geometry_allowed)) cycle
            matching_count = matching_count+1
            if (matching_count == 1) then
               production_vector_transform_stage(source_index) = &
                    production_vector_transform_stage(candidate_index)
            else if (abs(production_vector_transform_stage(source_index)- &
                 production_vector_transform_stage(candidate_index)) > &
                 16.0_dp*epsilon(1.0_dp)*max(1.0_dp,abs( &
                 production_vector_transform_stage(source_index)),abs( &
                 production_vector_transform_stage(candidate_index)))) then
               call fail("complete vector geometry aliases differ")
            end if
         end do
         if (matching_count > 0) then
            production_vector_transform_covered(source_index) = .true.
         end if
      end do

    end subroutine seed_complete_vector_route_source


    logical function complete_vector_edge_geometry_matches ( &
         d_alias,edge_alias,candidate,allowed) result(matches)

      implicit none

      integer, intent(in) :: d_alias
      integer, intent(in) :: edge_alias
      integer, intent(in) :: candidate
      real(dp), intent(in) :: allowed

      matches = abs(grid(d_alias)%midpt%elts(candidate+1)%x - &
           grid(d_alias)%midpt%elts(edge_alias+1)%x) <= allowed .and. &
           abs(grid(d_alias)%midpt%elts(candidate+1)%y - &
           grid(d_alias)%midpt%elts(edge_alias+1)%y) <= allowed .and. &
           abs(grid(d_alias)%midpt%elts(candidate+1)%z - &
           grid(d_alias)%midpt%elts(edge_alias+1)%z) <= allowed .and. &
           abs(grid(d_alias)%len%elts(candidate+1) - &
           grid(d_alias)%len%elts(edge_alias+1)) <= allowed .and. &
           abs(grid(d_alias)%pedlen%elts(candidate+1) - &
           grid(d_alias)%pedlen%elts(edge_alias+1)) <= allowed

    end function complete_vector_edge_geometry_matches

    subroutine propagate_complete_vector_boundaries ( &
         first_level_field,n_level_field)
      ! Reproduce the ordered forwarding semantics of update_bdry on the
      ! flattened persistent route graph.  Direct block interiors, restricted
      ! coarse edges and retained block boundaries are seeds; repeated signed
      ! route exchanges propagate those native values through corner routes.

      implicit none

      integer, intent(in) :: first_level_field
      integer, intent(in) :: n_level_field

      integer :: d_destination
      integer :: d_source
      integer :: destination_id
      integer :: destination_index
      integer :: field_slot
      integer :: ierr_propagate
      integer :: iteration
      integer :: new_global
      integer :: new_local
      integer :: p_route
      integer :: source_id
      integer :: source_index

      integer :: recv_value_count(n_process)
      integer :: recv_value_displ(n_process)
      integer :: send_value_count(n_process)
      integer :: send_value_displ(n_process)

      real(dp) :: propagated_value

      send_value_count = n_level_field* &
           staged_coarse_vector_boundary_plan%send_count
      recv_value_count = n_level_field* &
           staged_coarse_vector_boundary_plan%recv_count
      send_value_displ = n_level_field* &
           staged_coarse_vector_boundary_plan%send_displ
      recv_value_displ = n_level_field* &
           staged_coarse_vector_boundary_plan%recv_displ

      iteration = 0
      do
         iteration = iteration+1
         if (iteration > N_GLO_DOMAIN+N_BDRY) then
            call fail("complete vector boundary propagation did not converge")
         end if
         staged_coarse_vector_boundary_plan%send_buffer = 0.0_dp
         staged_coarse_vector_boundary_plan%recv_buffer = 0.0_dp
         staged_coarse_vector_boundary_plan%send_produced_buffer = 0
         staged_coarse_vector_boundary_plan%recv_produced_buffer = 0

         do p_route = 1,staged_coarse_vector_boundary_plan%n_send
            d_source = staged_coarse_vector_boundary_plan% &
                 send_domain(p_route)
            source_id = staged_coarse_vector_boundary_plan% &
                 send_id(p_route)
            do field_slot = 1,n_level_field
               source_index = complete_transform_index( &
                    d_source,source_id,field_slot,first_level_field)
               if (.not. production_vector_transform_covered( &
                    source_index)) cycle
               staged_coarse_vector_boundary_plan%send_buffer( &
                    (p_route-1)*n_level_field+field_slot) = &
                    production_vector_transform_stage(source_index)
               staged_coarse_vector_boundary_plan%send_produced_buffer( &
                    (p_route-1)*n_level_field+field_slot) = 1
            end do
         end do

         call MPI_Alltoallv( &
              staged_coarse_vector_boundary_plan%send_buffer, &
              send_value_count,send_value_displ,MPI_DOUBLE_PRECISION, &
              staged_coarse_vector_boundary_plan%recv_buffer, &
              recv_value_count,recv_value_displ,MPI_DOUBLE_PRECISION, &
              comm,ierr_propagate)
         call check_mpi(ierr_propagate, &
              "MPI_Alltoallv complete vector boundary values")
         call MPI_Alltoallv( &
              staged_coarse_vector_boundary_plan%send_produced_buffer, &
              send_value_count,send_value_displ,MPI_INTEGER, &
              staged_coarse_vector_boundary_plan%recv_produced_buffer, &
              recv_value_count,recv_value_displ,MPI_INTEGER,comm, &
              ierr_propagate)
         call check_mpi(ierr_propagate, &
              "MPI_Alltoallv complete vector boundary coverage")

         new_local = 0
         do p_route = 1,staged_coarse_vector_boundary_plan%n_recv
            d_destination = staged_coarse_vector_boundary_plan% &
                 recv_domain(p_route)
            destination_id = staged_coarse_vector_boundary_plan% &
                 recv_id(p_route)
            do field_slot = 1,n_level_field
               if (staged_coarse_vector_boundary_plan% &
                    recv_produced_buffer( &
                    (p_route-1)*n_level_field+field_slot) /= 1) cycle
               propagated_value = staged_coarse_vector_boundary_plan% &
                    recv_buffer((p_route-1)*n_level_field+field_slot)
               if (destination_id < 0) &
                    propagated_value = -propagated_value
               destination_index = complete_transform_index( &
                    d_destination,abs(destination_id),field_slot, &
                    first_level_field)
               call install_propagated_value( &
                    destination_index,propagated_value,new_local)
            end do
         end do

         do p_route = 1,staged_coarse_vector_boundary_plan%n_local
            d_source = staged_coarse_vector_boundary_plan% &
                 local_source_domain(p_route)
            source_id = staged_coarse_vector_boundary_plan% &
                 local_source_id(p_route)
            d_destination = staged_coarse_vector_boundary_plan% &
                 local_destination_domain(p_route)
            destination_id = staged_coarse_vector_boundary_plan% &
                 local_destination_id(p_route)
            do field_slot = 1,n_level_field
               source_index = complete_transform_index( &
                    d_source,source_id,field_slot,first_level_field)
               if (.not. production_vector_transform_covered( &
                    source_index)) cycle
               propagated_value = &
                    production_vector_transform_stage(source_index)
               if (destination_id < 0) &
                    propagated_value = -propagated_value
               destination_index = complete_transform_index( &
                    d_destination,abs(destination_id),field_slot, &
                    first_level_field)
               call install_propagated_value( &
                    destination_index,propagated_value,new_local)
            end do
         end do

         call MPI_Allreduce(new_local,new_global,1,MPI_INTEGER,MPI_SUM, &
              comm,ierr_propagate)
         call check_mpi(ierr_propagate, &
              "MPI_Allreduce complete vector boundary propagation")
         if (new_global == 0) exit
      end do

      do p_route = 1,staged_coarse_vector_boundary_plan%n_recv
         d_destination = staged_coarse_vector_boundary_plan% &
              recv_domain(p_route)
         destination_id = abs(staged_coarse_vector_boundary_plan% &
              recv_id(p_route))
         do field_slot = 1,n_level_field
            destination_index = complete_transform_index( &
                 d_destination,destination_id,field_slot, &
                 first_level_field)
            if (.not. production_vector_transform_covered( &
                 destination_index)) then
               call report_unresolved_route( &
                    d_destination,destination_id,field_slot,p_route)
            end if
         end do
      end do
      do p_route = 1,staged_coarse_vector_boundary_plan%n_local
         d_destination = staged_coarse_vector_boundary_plan% &
              local_destination_domain(p_route)
         destination_id = abs(staged_coarse_vector_boundary_plan% &
              local_destination_id(p_route))
         do field_slot = 1,n_level_field
            destination_index = complete_transform_index( &
                 d_destination,destination_id,field_slot, &
                 first_level_field)
            if (.not. production_vector_transform_covered( &
                 destination_index)) then
               call report_unresolved_route( &
                    d_destination,destination_id,field_slot, &
                    staged_coarse_vector_boundary_plan%n_recv+p_route)
            end if
         end do
      end do

    end subroutine propagate_complete_vector_boundaries


    integer function complete_transform_index ( &
         d_index,edge_index,field_slot,first_level_field) result(value_index)

      implicit none

      integer, intent(in) :: d_index
      integer, intent(in) :: edge_index
      integer, intent(in) :: field_slot
      integer, intent(in) :: first_level_field
      integer :: edge_extent

      if (d_index < 1 .or. d_index > size(grid) .or. &
           field_slot < 1 .or. field_slot > n_field_level) then
         call fail("complete vector route address is invalid")
      end if
      edge_extent = size(sol(S_VELO,first_level_field)% &
           data(d_index)%elts)
      if (edge_index < 0 .or. edge_index >= edge_extent) then
         call fail("complete vector route edge is invalid")
      end if
      value_index = production_vector_transform_displ(d_index) + &
           (field_slot-1)*edge_extent+edge_index+1
      if (value_index < 1 .or. value_index > &
           size(production_vector_transform_stage)) then
         call fail("complete vector route stage is invalid")
      end if

    end function complete_transform_index


    subroutine install_propagated_value ( &
         destination_index,propagated_value,new_count)

      implicit none

      integer, intent(in) :: destination_index
      real(dp), intent(in) :: propagated_value
      integer, intent(inout) :: new_count
      real(dp) :: route_allowed

      if (.not. ieee_is_finite(propagated_value)) then
         call fail("complete propagated boundary value is non-finite")
      end if
      if (production_vector_transform_covered(destination_index)) then
         route_allowed = 16.0_dp*epsilon(1.0_dp)*max( &
              1.0_dp,abs(propagated_value),abs( &
              production_vector_transform_stage(destination_index)))
         if (abs(production_vector_transform_stage(destination_index)- &
              propagated_value) > route_allowed) then
            call fail("complete propagated boundary values differ")
         end if
      else
         production_vector_transform_stage(destination_index) = &
              propagated_value
         production_vector_transform_covered(destination_index) = .true.
         new_count = new_count+1
      end if

    end subroutine install_propagated_value


    subroutine report_unresolved_route ( &
         d_route,edge_route,field_route,record_route)

      implicit none

      integer, intent(in) :: d_route
      integer, intent(in) :: edge_route
      integer, intent(in) :: field_route
      integer, intent(in) :: record_route

      write(error_unit,'(/,a,i0,a)') "Rank ",rank, &
           ": complete vector boundary route remains unresolved"
      write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
           "  Domain = ",d_route,", edge id = ",edge_route, &
           ", field level slot = ",field_route, &
           ", route record = ",record_route
      flush(error_unit)
      call fail("complete vector boundary propagation is incomplete")

    end subroutine report_unresolved_route


    subroutine produce_regular_vector_cell

      implicit none

      integer :: id1
      integer :: id2
      integer :: id_e
      integer :: id_n
      integer :: id_ne
      real(dp) :: inner_value(6)
      real(dp) :: interpolated

      do e = RT,UP
         id1 = idx(i_chd+end_pt(1,1,e+1), &
              j_chd+end_pt(2,1,e+1),offs_chd,dims_chd)
         id2 = idx(i_chd+end_pt(1,2,e+1), &
              j_chd+end_pt(2,2,e+1),offs_chd,dims_chd)
         if (grid(d)%mask_e%elts(EDGE*id2+e+1) < ADJZONE) cycle
         interpolated = native_outer_interpolation(id2,e)
         native_wc(EDGE*id2+e+1) = &
              native_velo(EDGE*id2+e+1)-interpolated
         native_wc(EDGE*id1+e+1) = -native_wc(EDGE*id2+e+1)
      end do

      call native_inner_interpolation(inner_value)
      id_e = idx(i_chd+1,j_chd,offs_chd,dims_chd)
      id_ne = idx(i_chd+1,j_chd+1,offs_chd,dims_chd)
      id_n = idx(i_chd,j_chd+1,offs_chd,dims_chd)
      call set_inner(id_e,UP,inner_value(1))
      call set_inner(id_e,DG,inner_value(2))
      call set_inner(id_ne,RT,inner_value(3))
      call set_inner(id_n,RT,inner_value(4))
      call set_inner(id_n,DG,inner_value(5))
      call set_inner(id_ne,UP,inner_value(6))

    end subroutine produce_regular_vector_cell


    subroutine set_inner(id_target,edge_component,interpolated)

      implicit none

      integer, intent(in) :: id_target
      integer, intent(in) :: edge_component
      real(dp), intent(in) :: interpolated

      if (grid(d)%mask_e%elts(EDGE*id_target+edge_component+1) >= &
           ADJZONE) then
         native_wc(EDGE*id_target+edge_component+1) = &
              native_velo(EDGE*id_target+edge_component+1)-interpolated
      end if

    end subroutine set_inner


    real(dp) function native_outer_interpolation(ide,edge_component) &
         result(value)

      implicit none

      integer, intent(in) :: ide
      integer, intent(in) :: edge_component
      integer :: k
      real(dp) :: source(9)
      real(dp) :: weight(9)

      weight = BLOCK_IU_BASE_WEIGHT + &
           [ (grid(d)%I_u_wgt%elts(ide+1)%enc(k),k=1,9) ]
      source(1) = native_velo(EDGE* &
           idx(i_par,j_par,offs_par,dims_par)+edge_component+1)
      source(2) = side_value(i_par+end_pt(1,2,edge_component+1), &
           j_par+end_pt(2,2,edge_component+1), &
           hex_s_offs(edge_component+1)+3)
      source(3) = side_value(i_par+end_pt(1,1,edge_component+1), &
           j_par+end_pt(2,1,edge_component+1), &
           hex_s_offs(edge_component+1)+4)
      source(4) = side_value(i_par+end_pt(1,1,edge_component+1), &
           j_par+end_pt(2,1,edge_component+1), &
           hex_s_offs(edge_component+1)+6)
      source(5) = side_value(i_par+end_pt(1,2,edge_component+1), &
           j_par+end_pt(2,2,edge_component+1), &
           hex_s_offs(edge_component+1)+1)
      source(6) = side_value(i_par+opp_no(1,1,edge_component+1), &
           j_par+opp_no(2,1,edge_component+1), &
           hex_s_offs(edge_component+1)+2) - &
           side_value(i_par+end_pt(1,1,edge_component+1), &
           j_par+end_pt(2,1,edge_component+1), &
           hex_s_offs(edge_component+1)+3)
      source(7) = side_value(i_par+end_pt(1,2,edge_component+1), &
           j_par+end_pt(2,2,edge_component+1), &
           hex_s_offs(edge_component+1)+4) - &
           side_value(i_par+opp_no(1,1,edge_component+1), &
           j_par+opp_no(2,1,edge_component+1), &
           hex_s_offs(edge_component+1)+5)
      source(8) = side_value(i_par+opp_no(1,2,edge_component+1), &
           j_par+opp_no(2,2,edge_component+1), &
           hex_s_offs(edge_component+1)+5) - &
           side_value(i_par+end_pt(1,2,edge_component+1), &
           j_par+end_pt(2,2,edge_component+1), &
           hex_s_offs(edge_component+1)+6)
      source(9) = side_value(i_par+end_pt(1,1,edge_component+1), &
           j_par+end_pt(2,1,edge_component+1), &
           hex_s_offs(edge_component+1)+1) - &
           side_value(i_par+opp_no(1,2,edge_component+1), &
           j_par+opp_no(2,2,edge_component+1), &
           hex_s_offs(edge_component+1)+2)
      value = sum(weight*source)

    end function native_outer_interpolation


    real(dp) function side_value(base_i,base_j,side_index) result(value)

      implicit none

      integer, intent(in) :: base_i
      integer, intent(in) :: base_j
      integer, intent(in) :: side_index
      integer :: id_side

      id_side = ed_idx(base_i,base_j,hex_sides(:,side_index), &
           offs_par,dims_par)
      value = native_velo(id_side+1)

    end function side_value


    subroutine native_inner_interpolation(value)

      implicit none

      real(dp), intent(out) :: value(6)
      integer :: id
      integer :: id_e
      integer :: id_e2
      integer :: id_n
      integer :: id_n2
      integer :: id_n2e
      integer :: id_ne
      integer :: id_2ne
      integer :: id_par
      integer :: id1_par
      integer :: id2_par
      integer :: t
      real(dp) :: curl_u(LORT:UPLT)

      id_par = idx(i_par,j_par,offs_par,dims_par)
      do t = LORT,UPLT
         id1_par = idx(i_par-t+1,j_par,offs_par,dims_par)
         id2_par = idx(i_par,j_par+t,offs_par,dims_par)
         curl_u(t) = ( &
              native_velo(EDGE*id_par+DG+1)* &
              grid(d)%len%elts(EDGE*id_par+DG+1) + &
              native_velo(EDGE*id1_par+UP+1)* &
              grid(d)%len%elts(EDGE*id1_par+UP+1) + &
              native_velo(EDGE*id2_par+RT+1)* &
              grid(d)%len%elts(EDGE*id2_par+RT+1))/ &
              grid(d)%triarea%elts(TRIAG*id_par+t+1)
      end do

      id = idx(i_chd,j_chd,offs_chd,dims_chd)
      id_e = idx(i_chd+1,j_chd,offs_chd,dims_chd)
      id_ne = idx(i_chd+1,j_chd+1,offs_chd,dims_chd)
      id_n = idx(i_chd,j_chd+1,offs_chd,dims_chd)
      id_n2e = idx(i_chd+2,j_chd+1,offs_chd,dims_chd)
      id_2ne = idx(i_chd+1,j_chd+2,offs_chd,dims_chd)
      id_n2 = idx(i_chd,j_chd+2,offs_chd,dims_chd)
      id_e2 = idx(i_chd+2,j_chd,offs_chd,dims_chd)

      value(1) = (grid(d)%triarea%elts(TRIAG*id+LORT+1)* &
           curl_u(LORT)-native_velo(EDGE*id+RT+1)* &
           grid(d)%len%elts(EDGE*id+RT+1)- &
           native_velo(EDGE*id+DG+1)*grid(d)%len%elts(EDGE*id+DG+1))/ &
           grid(d)%len%elts(EDGE*id_e+UP+1)
      value(2) = (grid(d)%triarea%elts(TRIAG*id_e+LORT+1)* &
           curl_u(LORT)-native_velo(EDGE*id_e+RT+1)* &
           grid(d)%len%elts(EDGE*id_e+RT+1)- &
           native_velo(EDGE*id_e2+UP+1)* &
           grid(d)%len%elts(EDGE*id_e2+UP+1))/ &
           grid(d)%len%elts(EDGE*id_e+DG+1)
      value(3) = (grid(d)%triarea%elts(TRIAG*id_ne+LORT+1)* &
           curl_u(LORT)-native_velo(EDGE*id_ne+DG+1)* &
           grid(d)%len%elts(EDGE*id_ne+DG+1)- &
           native_velo(EDGE*id_n2e+UP+1)* &
           grid(d)%len%elts(EDGE*id_n2e+UP+1))/ &
           grid(d)%len%elts(EDGE*id_ne+RT+1)
      value(4) = (grid(d)%triarea%elts(TRIAG*id+UPLT+1)* &
           curl_u(UPLT)-native_velo(EDGE*id+UP+1)* &
           grid(d)%len%elts(EDGE*id+UP+1)- &
           native_velo(EDGE*id+DG+1)*grid(d)%len%elts(EDGE*id+DG+1))/ &
           grid(d)%len%elts(EDGE*id_n+RT+1)
      value(5) = (grid(d)%triarea%elts(TRIAG*id_n+UPLT+1)* &
           curl_u(UPLT)-native_velo(EDGE*id_n+UP+1)* &
           grid(d)%len%elts(EDGE*id_n+UP+1)- &
           native_velo(EDGE*id_n2+RT+1)* &
           grid(d)%len%elts(EDGE*id_n2+RT+1))/ &
           grid(d)%len%elts(EDGE*id_n+DG+1)
      value(6) = (grid(d)%triarea%elts(TRIAG*id_ne+UPLT+1)* &
           curl_u(UPLT)-native_velo(EDGE*id_ne+DG+1)* &
           grid(d)%len%elts(EDGE*id_ne+DG+1)- &
           native_velo(EDGE*id_2ne+RT+1)* &
           grid(d)%len%elts(EDGE*id_2ne+RT+1))/ &
           grid(d)%len%elts(EDGE*id_ne+UP+1)

    end subroutine native_inner_interpolation


    subroutine apply_native_pentagon_level(target_level)

      implicit none

      integer, intent(in) :: target_level
      integer :: corner
      integer :: current_level
      integer :: p_current
      integer :: p_parent

      do corner = NORTHEAST,NORTHWEST
         if (.not. grid(d)%penta(corner)) cycle
         p_current = 1
         do while (p_current > 0)
            p_parent = p_current
            p_current = grid(d)%patch%elts(p_parent+1)% &
                 children(corner-4)
            current_level = grid(d)%patch%elts(p_parent+1)%level
            if (current_level < target_level) cycle
            if (current_level > target_level) exit
            call get_offs_Domain( &
                 grid(d),p_parent,offs_par,dims_par)
            call produce_pentagon(p_parent,corner)
            count_local(1) = count_local(1)+4_int64
         end do
      end do

    end subroutine apply_native_pentagon_level


    subroutine produce_pentagon(p_parent,corner)

      implicit none

      integer, intent(in) :: p_parent
      integer, intent(in) :: corner
      integer :: id_child
      integer :: id_e_child
      integer :: id_n_child
      integer :: penta_child
      real(dp) :: correction(2)
      real(dp) :: v

      penta_child = grid(d)%patch%elts(p_parent+1)%children(corner-4)
      if (penta_child == 0) return
      call get_offs_Domain( &
           grid(d),penta_child,offs_chd,dims_chd)

      if (corner == IMINUSJPLUS) then
         id_child = idx(0,LAST-1,offs_chd,dims_chd)
         id_n_child = idx(0,LAST,offs_chd,dims_chd)
         v = -(BLOCK_IU_BASE_WEIGHT(8)+ &
              grid(d)%I_u_wgt%elts(id_n_child+1)%enc(8))*( &
              native_velo(EDGE*idx(0,PATCH_SIZE, &
              offs_par,dims_par)+UP+1)+ &
              native_velo(EDGE*idx(-1,PATCH_SIZE, &
              offs_par,dims_par)+RT+1))
         if (grid(d)%mask_e%elts(EDGE*id_child+UP+1) >= ADJZONE) then
            native_wc(EDGE*id_child+UP+1) = &
                 native_wc(EDGE*id_child+UP+1)-v
            native_wc(EDGE*id_n_child+UP+1) = &
                 native_wc(EDGE*id_n_child+UP+1)+v
         end if
      else if (corner == IPLUSJMINUS) then
         id_child = idx(LAST-1,0,offs_chd,dims_chd)
         id_e_child = idx(LAST,0,offs_chd,dims_chd)
         v = (BLOCK_IU_BASE_WEIGHT(7)+ &
              grid(d)%I_u_wgt%elts(id_e_child+1)%enc(7))*( &
              native_velo(EDGE*idx(PATCH_SIZE,0, &
              offs_par,dims_par)+RT+1)+ &
              native_velo(EDGE*idx(PATCH_SIZE,-1, &
              offs_par,dims_par)+UP+1))
         if (grid(d)%mask_e%elts(EDGE*id_child+RT+1) >= ADJZONE) then
            native_wc(EDGE*id_child+RT+1) = &
                 native_wc(EDGE*id_child+RT+1)-v
            native_wc(EDGE*id_e_child+RT+1) = &
                 native_wc(EDGE*id_e_child+RT+1)+v
         end if
      end if
      if (corner /= IJMINUS) return

      id_child = idx(0,0,offs_chd,dims_chd)
      id_n_child = idx(0,1,offs_chd,dims_chd)
      id_e_child = idx(1,0,offs_chd,dims_chd)
      call native_pentagon_correction(correction)
      if (grid(d)%mask_e%elts(EDGE*id_child+UP+1) >= ADJZONE) then
         native_wc(EDGE*id_child+UP+1) = &
              native_wc(EDGE*id_child+UP+1)+correction(1)
         native_wc(EDGE*id_n_child+UP+1) = &
              native_wc(EDGE*id_n_child+UP+1)-correction(1)
      end if
      if (grid(d)%mask_e%elts(EDGE*id_child+RT+1) >= ADJZONE) then
         native_wc(EDGE*id_child+RT+1) = &
              native_wc(EDGE*id_child+RT+1)+correction(2)
         native_wc(EDGE*id_e_child+RT+1) = &
              native_wc(EDGE*id_e_child+RT+1)-correction(2)
      end if

    end subroutine produce_pentagon


    subroutine native_pentagon_correction(value)

      implicit none

      real(dp), intent(out) :: value(2)
      integer :: id_weight

      id_weight = idx(end_pt(1,2,UP+1),end_pt(2,2,UP+1), &
           offs_chd,dims_chd)
      value(1) = (BLOCK_IU_BASE_WEIGHT(9)+ &
           grid(d)%I_u_wgt%elts(id_weight+1)%enc(9))*( &
           (-native_velo(EDGE*idx(0,-1,offs_par,dims_par)+UP+1) - &
           (-native_velo(EDGE*idx(-1,-1,offs_par,dims_par)+RT+1))) - &
           (native_velo(ed_idx(end_pt(1,1,UP+1), &
           end_pt(2,1,UP+1),hex_sides(:,hex_s_offs(UP+1)+1), &
           offs_par,dims_par)+1) - &
           native_velo(ed_idx(opp_no(1,2,UP+1), &
           opp_no(2,2,UP+1),hex_sides(:,hex_s_offs(UP+1)+2), &
           offs_par,dims_par)+1)))

      id_weight = idx(end_pt(1,2,RT+1),end_pt(2,2,RT+1), &
           offs_chd,dims_chd)
      value(2) = (BLOCK_IU_BASE_WEIGHT(6)+ &
           grid(d)%I_u_wgt%elts(id_weight+1)%enc(6))*( &
           native_velo(EDGE*idx(-1,-1,offs_par,dims_par)+RT+1) + &
           native_velo(EDGE*idx(-1,0,offs_par,dims_par)+RT+1) - &
           (native_velo(ed_idx(opp_no(1,1,RT+1), &
           opp_no(2,1,RT+1),hex_sides(:,hex_s_offs(RT+1)+2), &
           offs_par,dims_par)+1) - &
           native_velo(ed_idx(end_pt(1,1,RT+1), &
           end_pt(2,1,RT+1),hex_sides(:,hex_s_offs(RT+1)+3), &
           offs_par,dims_par)+1)))

    end subroutine native_pentagon_correction

  end subroutine validate_complete_block_vector_wavelets


  subroutine validate_candidate_block_scalar_wavelets ( &
       domain_scaling,first_level)
    ! Evaluate each RK-candidate scalar wavelet stencil directly from retained
    ! block sol, compare it with the independent Domain result, then install
    ! the native coefficient in block storage. Compression, inverse
    ! reconstruction and adaptation remain unchanged.

    implicit none

    type(Float_Field), intent(in) :: &
         domain_scaling(1:N_VARIABLE,1:zlevels)
    integer, intent(in) :: first_level

    integer :: ierr
    integer :: candidate_stage
    integer :: candidate_stage_count

    integer(int64) :: count_global(5)
    integer(int64) :: count_local(5)
    integer(int64) :: restriction_allocation_before
    integer(int64) :: scalar_allocation_before
    integer(int64) :: writeback_allocation_after
    integer(int64) :: writeback_allocation_before
    integer(int64) :: writeback_before

    logical :: checkpoint_ready
    logical :: state_ready

    character(len=3) :: scheme_name

    type(Block_Scalar_Wavelet_Context) :: statistics

    candidate_stage = production_multistage_candidate_stage
    candidate_stage_count = &
         production_multistage_candidate_stage_count

    ! Every RK candidate still carries the retained native snapshot and
    ! rollback checkpoint at this point in WT_after_step. For the final
    ! candidate, acceptance is deliberately deferred until this pre-
    ! compression guard has validated the complete scalar transform.
    if (candidate_stage_count == 0) return

    state_ready = parallel_block_state_is_ready()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    if (.not. state_ready .or. .not. checkpoint_ready) then
       call fail("scalar-wavelet production transaction is not ready")
    end if
    if (candidate_stage < candidate_stage_count) then
       if (first_level /= level_start) then
          call fail("provisional scalar-wavelet first level is invalid")
       end if
    else
       if (first_level /= level_start-1) then
          call fail("accepted scalar-wavelet first level is invalid")
       end if
    end if
    if (candidate_stage < candidate_stage_count) then
       if (.not. block_writeback_plan%native_stage_ready .or. &
            block_writeback_plan%native_stage /= candidate_stage .or. &
            block_writeback_plan%native_stage_count /= &
            candidate_stage_count) then
          call fail("scalar-wavelet native snapshot is not ready")
       end if
    else
       if (.not. production_multistage_final_snapshot_consumed .or. &
            block_writeback_plan%native_stage_ready) then
          call fail("accepted scalar-wavelet snapshot boundary is invalid")
       end if
    end if
    if (.not. block_scalar_divergence_plan%ready .or. &
         .not. allocated(block_scalar_tendency)) then
       call fail("scalar-wavelet geometry shadow is not ready")
    end if

    writeback_allocation_before = &
         block_writeback_plan_allocation_count()
    scalar_allocation_before = block_scalar_tendency_allocations
    restriction_allocation_before = &
         block_scalar_restriction_exchange%allocations
    writeback_before = block_domain_production_writeback_count()

    ! WT_after_step has already refreshed the Domain scaling boundary. Import
    ! only compact boundary values; block interiors remain the native RK
    ! candidate. Inter-block ghosts are then produced from those interiors.
    call import_domain_boundary_field_family_to_blocks( &
         BLOCK_PAYLOAD_SOL,.false.,domain_scaling)
    call refresh_block_sol_ghosts
    call assert_block_domain_field_family_match( &
         BLOCK_PAYLOAD_SOL,domain_scaling)

    ! The production call uses the module wav_coeff object supplied to
    ! WT_after_step. Install its uncompressed patch coefficients as a
    ! read-only reference while preserving the RK rollback checkpoint.
    call import_domain_field_family_to_blocks( &
         BLOCK_PAYLOAD_WAV_COEFF,preserve_checkpoint=.true.)

    statistics%first_level = first_level
    statistics%last_level = level_end-1
    call apply_local_block_field_producer( &
         compare_block_scalar_wavelets,statistics)

    count_local = [statistics%parent_patch_count, &
         statistics%candidate_count,statistics%active_count, &
         statistics%compared_count,statistics%produced_count]
    call MPI_Allreduce(count_local,count_global,size(count_local), &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce scalar-wavelet shadow coverage")
    if (any(count_global <= 0_int64)) then
       call fail("block-native scalar-wavelet coverage is empty")
    end if
    if (count_global(3) /= count_global(4)) then
       call fail("block-native scalar-wavelet comparison coverage differs")
    end if
    if (count_global(2) /= count_global(5)) then
       call fail("block-native scalar-wavelet production coverage differs")
    end if

    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    if (.not. checkpoint_ready) then
       call fail("scalar-wavelet production lost RK transaction state")
    end if
    if (candidate_stage < candidate_stage_count) then
       if (.not. block_writeback_plan%native_stage_ready) then
          call fail("scalar-wavelet production lost native snapshot")
       end if
    else
       if (.not. production_multistage_final_snapshot_consumed .or. &
            block_writeback_plan%native_stage_ready) then
          call fail("accepted scalar-wavelet snapshot state changed")
       end if
    end if
    writeback_allocation_after = &
         block_writeback_plan_allocation_count()
    if (writeback_allocation_after /= writeback_allocation_before .or. &
         block_scalar_tendency_allocations /= scalar_allocation_before .or. &
         block_scalar_restriction_exchange%allocations /= &
         restriction_allocation_before) then
       call fail("scalar-wavelet production reallocated persistent storage")
    end if
    if (block_domain_production_writeback_count() /= writeback_before) then
       call fail("scalar-wavelet production modified Domain fields")
    end if

    ! The final candidate now closes the former Stages 124--126 as one
    ! transaction: regular inner production, pentagon correction, complete
    ! persistent staged storage and whole-family comparison.
    if (candidate_stage == candidate_stage_count) then
       call validate_complete_block_vector_wavelets(first_level)
    end if

    ! Close the final RK transaction downstream of the complete
    ! uncompressed comparison but upstream of wavelet compression, inverse
    ! reconstruction and any subsequent grid adaptation.
    if (candidate_stage == candidate_stage_count) then
       call accept_block_native_multistage_candidate( &
            candidate_stage_count)
       checkpoint_ready = &
            local_block_tendency_commit_checkpoint_is_ready()
       state_ready = parallel_block_state_is_ready()
       if (.not. state_ready) then
          call fail("scalar-wavelet acceptance invalidated block state")
       end if
       if (checkpoint_ready .or. &
            block_writeback_plan%native_stage_ready) then
          call fail("scalar-wavelet acceptance retained transaction state")
       end if
       if (production_multistage_final_snapshot_consumed) then
          call fail("scalar-wavelet acceptance retained snapshot state")
       end if
       if (production_multistage_candidate_stage /= 0 .or. &
            production_multistage_candidate_stage_count /= 0) then
          call fail("scalar-wavelet acceptance retained stage state")
       end if
    end if

    if (candidate_stage_count == 3) then
       scheme_name = "RK3"
    else
       scheme_name = "RK4"
    end if
    if (rank == 0) then
       write(6,'(a,a,a,i0,a,i0)') &
            "  block-native ",scheme_name, &
            " scalar wavelet production passed: stage = ", &
            candidate_stage," of ",candidate_stage_count
    end if

  end subroutine validate_candidate_block_scalar_wavelets


  subroutine compare_block_scalar_wavelets (catalog_index,block,context)
    ! Reproduce Compute_scalar_wavelets for every retained parent-child pair.

    implicit none

    integer, intent(in) :: catalog_index
    type(Block_Data), intent(inout) :: block
    class(*), intent(inout) :: context

    integer :: c
    integer :: child
    integer :: i
    integer :: i_chd
    integer :: i_par
    integer :: j
    integer :: j_chd
    integer :: j_par
    integer :: level_slot
    integer :: local_index
    integer :: p
    integer :: scalar_slot

    local_index = catalog_local_block(catalog_index)
    if (local_index < 1 .or. &
         local_index > size(block_scalar_tendency)) then
       call fail("scalar-wavelet comparison block is invalid")
    end if
    if (.not. block_scalar_tendency(local_index)%ready .or. &
         block_scalar_tendency(local_index)%catalog_index /= &
         catalog_index) then
       call fail("scalar-wavelet geometry block is stale")
    end if

    select type (statistics => context)
    type is (Block_Scalar_Wavelet_Context)
       do p = 1,size(block%patch)
          if (block%patch(p)%level < statistics%first_level .or. &
               block%patch(p)%level > statistics%last_level) cycle
          statistics%parent_patch_count = &
               statistics%parent_patch_count + 1_int64
          do c = 1,N_CHDRN
             child = block%patch(p)%children(c)
             if (child == 0) cycle
             if (child < 0 .or. child >= size(block%patch)) then
                call fail("scalar-wavelet child patch is invalid")
             end if
             if (block%patch(child+1)%level /= &
                  block%patch(p)%level+1) then
                call fail("scalar-wavelet child level is invalid")
             end if
             do scalar_slot = 0,block%n_scalar_variable-1
                do level_slot = 1,block%n_field_level
                   if (block%field_level+level_slot-1 < 1 .or. &
                        block%field_level+level_slot-1 > zlevels) cycle
                   do j = 1,PATCH_SIZE/2
                      j_chd = 2*(j-1)
                      j_par = j-1+chd_offs(2,c)
                      do i = 1,PATCH_SIZE/2
                         i_chd = 2*(i-1)
                         i_par = i-1+chd_offs(1,c)
                         call compare_child_value( &
                              i_chd+1,j_chd, &
                              [i_chd,i_chd+2,i_chd+2,i_chd], &
                              [j_chd,j_chd,j_chd+2,j_chd-2],statistics)
                         call compare_child_value( &
                              i_chd+1,j_chd+1, &
                              [i_chd+2,i_chd,i_chd+2,i_chd], &
                              [j_chd+2,j_chd,j_chd,j_chd+2],statistics)
                         call compare_child_value( &
                              i_chd,j_chd+1, &
                              [i_chd,i_chd,i_chd-2,i_chd+2], &
                              [j_chd,j_chd+2,j_chd,j_chd+2],statistics)
                      end do
                   end do
                end do
             end do
          end do
       end do
    class default
       call fail("scalar-wavelet comparison context is invalid")
    end select

  contains

    subroutine compare_child_value ( &
         target_i,target_j,source_i,source_j,stats)

      implicit none

      integer, intent(in) :: target_i
      integer, intent(in) :: target_j
      integer, intent(in) :: source_i(4)
      integer, intent(in) :: source_j(4)
      type(Block_Scalar_Wavelet_Context), intent(inout) :: stats

      real(dp) :: comparison_tolerance
      real(dp) :: mask_value
      real(dp) :: native_value
      real(dp) :: operation_scale
      real(dp) :: reference_value

      stats%candidate_count = stats%candidate_count + 1_int64
      mask_value = block_scalar_record_value( &
           block,local_index,child+1,scalar_slot,level_slot, &
           target_i,target_j,BLOCK_SCALAR_WAVELET_MASK_INDEX)
      reference_value = block_scalar_family_value( &
           block,local_index,child+1,scalar_slot,level_slot, &
           target_i,target_j,BLOCK_PAYLOAD_WAV_COEFF)
      if (mask_value < real(ADJZONE,dp)) then
         if (abs(reference_value) > 0.0_dp) then
            call report_scalar_wavelet_mismatch( &
                 "inactive Domain scalar wavelet is not zero", &
                 target_i,target_j,0.0_dp,reference_value,0.0_dp)
        end if
         call set_block_scalar_wavelet_value( &
              block,child+1,scalar_slot,level_slot, &
              target_i,target_j,0.0_dp)
         stats%produced_count = stats%produced_count + 1_int64
         return
      end if

      stats%active_count = stats%active_count + 1_int64
      native_value = compute_block_scalar_wavelet( &
           block,local_index,child+1,scalar_slot,level_slot, &
           target_i,target_j,source_i,source_j,operation_scale)
      comparison_tolerance = 32.0_dp*epsilon(1.0_dp)*max( &
           1.0_dp,abs(native_value),abs(reference_value),operation_scale)
      if (abs(native_value-reference_value) > comparison_tolerance) then
         call report_scalar_wavelet_mismatch( &
              "block-native scalar wavelet differs",target_i,target_j, &
              native_value,reference_value,comparison_tolerance)
      end if
      stats%compared_count = stats%compared_count + 1_int64
      call set_block_scalar_wavelet_value( &
           block,child+1,scalar_slot,level_slot, &
           target_i,target_j,native_value)
      stats%produced_count = stats%produced_count + 1_int64

    end subroutine compare_child_value


    subroutine report_scalar_wavelet_mismatch ( &
         message,target_i,target_j,native_value,reference_value,allowed)

      implicit none

      character(len=*), intent(in) :: message
      integer, intent(in) :: target_i
      integer, intent(in) :: target_j
      real(dp), intent(in) :: native_value
      real(dp), intent(in) :: reference_value
      real(dp), intent(in) :: allowed

      write(error_unit,'(/,a,i0,a,a)') &
           "Rank ",rank,": ",trim(message)
      write(error_unit,'(a,i0,a,i0,a,i0)') &
           "  catalog block = ",catalog_index, &
           ", block id = ",block%id,", parent patch = ",p
      write(error_unit,'(a,i0,a,i0,a,i0)') &
           "  parent level = ",block%patch(p)%level, &
           ", child = ",c,", child patch = ",child+1
      write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
           "  parent coordinates = ",i_par,", ",j_par, &
           "; child coordinates = ",target_i,", ",target_j
      write(error_unit,'(a,i0,a,i0)') &
           "  scalar slot = ",scalar_slot, &
           ", field-level slot = ",level_slot
      write(error_unit,'(a,4(es24.16,1x))') &
           "  native, reference, difference, allowed = ", &
           native_value,reference_value, &
           abs(native_value-reference_value),allowed
      flush(error_unit)
      call fail("scalar-wavelet production comparison failed")

    end subroutine report_scalar_wavelet_mismatch

  end subroutine compare_block_scalar_wavelets


  subroutine set_block_scalar_wavelet_value ( &
       block,p,scalar_slot,level_slot,i,j,value)
    ! Install one verified coefficient in native compact patch storage.

    implicit none

    type(Block_Data), intent(inout) :: block
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    real(dp), intent(in) :: value

    integer :: field_index
    integer :: n_storage_node
    integer :: node_index

    if (p < 1 .or. p > size(block%patch) .or. &
         scalar_slot < 0 .or. &
         scalar_slot >= block%n_scalar_variable .or. &
         level_slot < 1 .or. level_slot > block%n_field_level .or. &
         i < 0 .or. i >= PATCH_SIZE .or. &
         j < 0 .or. j >= PATCH_SIZE) then
       call fail("scalar-wavelet production address is invalid")
    end if
    if (.not. ieee_is_finite(value)) then
       call fail("scalar-wavelet production value is non-finite")
    end if

    n_storage_node = size(block%node)
    node_index = block%patch(p)%elts_start+PATCH_SIZE*j+i
    field_index = &
         (scalar_slot*block%n_field_level+level_slot-1)* &
         n_storage_node+node_index+1
    if (node_index < 0 .or. node_index >= n_storage_node .or. &
         field_index < 1 .or. &
         field_index > size(block%wavelet_scalar)) then
       call fail("scalar-wavelet production storage is invalid")
    end if
    block%wavelet_scalar(field_index) = value

  end subroutine set_block_scalar_wavelet_value


  real(dp) function compute_block_scalar_wavelet ( &
       block,local_index,p,scalar_slot,level_slot,target_i,target_j, &
       source_i,source_j,operation_scale) result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: target_i
    integer, intent(in) :: target_j
    integer, intent(in) :: source_i(4)
    integer, intent(in) :: source_j(4)
    real(dp), intent(out) :: operation_scale

    integer :: k

    real(dp) :: inverse_area
    real(dp) :: source_value(4)
    real(dp) :: target_value
    real(dp) :: weight(4)

    target_value = block_scalar_family_value( &
         block,local_index,p,scalar_slot,level_slot,target_i,target_j, &
         BLOCK_PAYLOAD_SOL)
    do k = 1,4
       source_value(k) = block_scalar_family_value( &
            block,local_index,p,scalar_slot,level_slot, &
            source_i(k),source_j(k),BLOCK_PAYLOAD_SOL)
       weight(k) = block_scalar_record_value( &
            block,local_index,p,scalar_slot,level_slot, &
            target_i,target_j,BLOCK_SCALAR_OVERLAP_START+k-1)
    end do
    inverse_area = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot,target_i,target_j, &
         BLOCK_SCALAR_AREA_INDEX)
    value = target_value - ( &
         weight(1)*source_value(1) + weight(2)*source_value(2) + &
         weight(3)*source_value(3) + weight(4)*source_value(4))* &
         inverse_area
    operation_scale = abs(target_value) + abs(inverse_area)*( &
         abs(weight(1)*source_value(1)) + &
         abs(weight(2)*source_value(2)) + &
         abs(weight(3)*source_value(3)) + &
         abs(weight(4)*source_value(4)))

  end function compute_block_scalar_wavelet


  real(dp) function block_scalar_family_value ( &
       block,local_index,p,scalar_slot,level_slot,i,j,payload_family) &
       result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: payload_family

    integer :: field_index
    integer :: n_storage_node
    integer :: node
    integer :: node_index
    integer :: record
    integer :: storage_class

    value = 0.0_dp
    if (scalar_slot < 0 .or. &
         scalar_slot >= block%n_scalar_variable .or. &
         level_slot < 1 .or. level_slot > block%n_field_level) then
       call fail("scalar-wavelet field slot is invalid")
    end if
    if (payload_family /= BLOCK_PAYLOAD_SOL .and. &
         payload_family /= BLOCK_PAYLOAD_WAV_COEFF) then
       call fail("scalar-wavelet field family is invalid")
    end if
    call locate_block_scalar_record( &
         block,local_index,p,i,j,storage_class,record,node)
    select case (storage_class)
    case (STORE_PATCH)
       if (record < 0 .or. record >= size(block%patch)) then
          call fail("scalar-wavelet patch record is invalid")
       end if
       n_storage_node = size(block%node)
       node_index = block%patch(record+1)%elts_start+node
       field_index = &
            (scalar_slot*block%n_field_level+level_slot-1)* &
            n_storage_node + node_index + 1
       if (field_index < 1 .or. field_index > size(block%scalar)) then
          call fail("scalar-wavelet patch field is invalid")
       end if
       if (payload_family == BLOCK_PAYLOAD_SOL) then
          value = block%scalar(field_index)
       else
          value = block%wavelet_scalar(field_index)
       end if
    case (STORE_BDRY)
       n_storage_node = size(block%bdry_node)
       node_index = node
       field_index = &
            (scalar_slot*block%n_field_level+level_slot-1)* &
            n_storage_node + node_index + 1
       if (field_index < 1 .or. &
            field_index > size(block%bdry_scalar)) then
          call fail("scalar-wavelet boundary field is invalid")
       end if
       if (payload_family == BLOCK_PAYLOAD_SOL) then
          value = block%bdry_scalar(field_index)
       else
          value = block%bdry_wavelet_scalar(field_index)
       end if
    case (STORE_GHOST)
       n_storage_node = size(block%ghost_node)
       node_index = node
       field_index = &
            (scalar_slot*block%n_field_level+level_slot-1)* &
            n_storage_node + node_index + 1
       if (field_index < 1 .or. &
            field_index > size(block%ghost_scalar)) then
          call fail("scalar-wavelet ghost field is invalid")
       end if
       if (payload_family == BLOCK_PAYLOAD_SOL) then
          value = block%ghost_scalar(field_index)
       else
          value = block%ghost_wavelet_scalar(field_index)
       end if
    case default
       call fail("scalar-wavelet storage class is invalid")
    end select

    if (.not. ieee_is_finite(value)) then
       call fail("scalar-wavelet field value is non-finite")
    end if

  end function block_scalar_family_value


  real(dp) function block_vector_family_value ( &
       block,local_index,p,level_slot,i,j,e,payload_family) result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: e
    integer, intent(in) :: payload_family

    integer :: field_index
    integer :: n_storage_node
    integer :: node
    integer :: node_index
    integer :: record
    integer :: storage_class

    value = 0.0_dp
    if (block%vector_mult /= EDGE .or. &
         level_slot < 1 .or. level_slot > block%n_field_level .or. &
         e < RT .or. e > UP) then
       call fail("vector-wavelet field slot is invalid")
    end if
    if (payload_family /= BLOCK_PAYLOAD_SOL .and. &
         payload_family /= BLOCK_PAYLOAD_WAV_COEFF) then
       call fail("vector-wavelet field family is invalid")
    end if
    call locate_block_scalar_record( &
         block,local_index,p,i,j,storage_class,record,node)
    select case (storage_class)
    case (STORE_PATCH)
       if (record < 0 .or. record >= size(block%patch)) then
          call fail("vector-wavelet patch record is invalid")
       end if
       n_storage_node = size(block%node)
       node_index = block%patch(record+1)%elts_start+node
       field_index = (level_slot-1)*EDGE*n_storage_node + &
            EDGE*node_index+e+1
       if (field_index < 1 .or. field_index > size(block%vector)) then
          call fail("vector-wavelet patch field is invalid")
       end if
       if (payload_family == BLOCK_PAYLOAD_SOL) then
          value = block%vector(field_index)
       else
          value = block%wavelet_vector(field_index)
       end if
    case (STORE_BDRY)
       n_storage_node = size(block%bdry_node)
       node_index = node
       field_index = (level_slot-1)*EDGE*n_storage_node + &
            EDGE*node_index+e+1
       if (field_index < 1 .or. &
            field_index > size(block%bdry_vector)) then
          call fail("vector-wavelet boundary field is invalid")
       end if
       if (payload_family == BLOCK_PAYLOAD_SOL) then
          value = block%bdry_vector(field_index)
       else
          value = block%bdry_wavelet_vector(field_index)
       end if
    case (STORE_GHOST)
       n_storage_node = size(block%ghost_node)
       node_index = node
       field_index = (level_slot-1)*EDGE*n_storage_node + &
            EDGE*node_index+e+1
       if (field_index < 1 .or. &
            field_index > size(block%ghost_vector)) then
          call fail("vector-wavelet ghost field is invalid")
       end if
       if (payload_family == BLOCK_PAYLOAD_SOL) then
          value = block%ghost_vector(field_index)
       else
          value = block%ghost_wavelet_vector(field_index)
       end if
    case default
       call fail("vector-wavelet storage class is invalid")
    end select

    if (.not. ieee_is_finite(value)) then
       call fail("vector-wavelet field value is non-finite")
    end if

  end function block_vector_family_value


  subroutine assert_candidate_block_hydrostatic_match (domain_sol)
    ! Compare the persistent provisional-stage block thermodynamic cache
    ! with an independent reconstruction from the authoritative Domain
    ! stage fields. Only catalogue-rooted patches participate.

    implicit none

    type(Float_Field), intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)

    integer :: b
    integer :: d
    integer :: ierr

    integer(int64) :: count_global(4)
    integer(int64) :: count_local(4)
    integer(int64) :: domain_column_count
    integer(int64) :: domain_surface_count

    real(dp) :: domain_exner_moment(3)
    real(dp) :: domain_surface_moment(3)
    real(dp) :: domain_temperature_moment(3)
    real(dp) :: moment_global(18)
    real(dp) :: moment_local(18)

    type(Block_Hydrostatic_Traversal_Context) :: block_statistics

    if (.not. compressible) then
       call fail("candidate hydrostatic comparison is incompressible")
    end if
    if (.not. local_block_hydrostatic_state_ready()) then
       call fail("candidate block hydrostatic state is not ready")
    end if

    block_statistics = Block_Hydrostatic_Traversal_Context()
    call apply_local_block_hydrostatic_consumer( &
         accumulate_block_hydrostatic_consumer,block_statistics)
    if (block_statistics%block_count /= int(n_local_blocks(),int64)) then
       call fail("candidate hydrostatic block traversal is incomplete")
    end if

    domain_surface_count = 0_int64
    domain_column_count = 0_int64
    domain_surface_moment = 0.0_dp
    domain_exner_moment = 0.0_dp
    domain_temperature_moment = 0.0_dp
    do b = 1,size(block_catalog)
       if (owner(block_catalog(b)%root_domain+1) /= rank) cycle
       d = loc_id(block_catalog(b)%root_domain+1) + 1
       if (d < 1 .or. d > size(grid)) then
          call fail("candidate hydrostatic source Domain is invalid")
       end if
       call accumulate_domain_subtree_hydrostatic( &
            d,block_catalog(b)%root_patch, &
            domain_surface_count,domain_column_count, &
            domain_surface_moment,domain_exner_moment, &
            domain_temperature_moment,domain_sol)
    end do

    count_local = [block_statistics%surface_count, &
         block_statistics%column_count,domain_surface_count, &
         domain_column_count]
    moment_local(1:3) = block_statistics%surface_moment
    moment_local(4:6) = block_statistics%exner_moment
    moment_local(7:9) = block_statistics%temperature_moment
    moment_local(10:12) = domain_surface_moment
    moment_local(13:15) = domain_exner_moment
    moment_local(16:18) = domain_temperature_moment

    call MPI_Allreduce(count_local,count_global,4, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce candidate hydrostatic counts")
    call MPI_Allreduce(moment_local,moment_global,18, &
         MPI_DOUBLE_PRECISION,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce candidate hydrostatic moments")

    if (count_global(1) /= count_global(3) .or. &
         count_global(2) /= count_global(4)) then
       call fail("candidate block/Domain hydrostatic counts differ")
    end if
    if (.not. field_moments_match( &
         moment_global(1:3),moment_global(10:12),count_global(1))) then
       call fail("candidate block/Domain surface pressure differs")
    end if
    if (.not. field_moments_match( &
         moment_global(4:6),moment_global(13:15),count_global(2))) then
       call fail("candidate block/Domain dynamic Exner differs")
    end if
    if (.not. field_moments_match( &
         moment_global(7:9),moment_global(16:18),count_global(2))) then
       call fail("candidate block/Domain air temperature differs")
    end if

  end subroutine assert_candidate_block_hydrostatic_match










  subroutine refresh_candidate_block_edge_metrics
    ! Install exact production primal-edge lengths in persistent final-owner
    ! block storage. The reverse transport and patch layout are the same as
    ! the tendency imports, but the metric remains read-only and separate.

    implicit none

    integer :: b
    integer :: d
    integer :: local_index
    integer :: local_patch
    integer :: n_local
    integer :: n_patch
    integer :: pos_scalar
    integer :: pos_vector
    integer :: r
    integer :: source
    integer :: slot

    integer(int64) :: allocation_after
    integer(int64) :: allocation_before

    logical :: storage_current

    n_local = n_local_blocks()
    storage_current = edge_metric_storage_is_current(n_local)
    if (storage_current) return
    allocation_before = block_edge_metric_allocations
    call prepare_edge_metric_storage(n_local)
    if (.not. allocated(ghost_exchange_plan%scalar_patch_buffer) .or. &
         .not. allocated(ghost_exchange_plan%vector_patch_buffer)) then
       call fail("edge-metric retained patch buffers are not allocated")
    end if
    if (block_writeback_plan%scalar_patch_nvalue <= 0 .or. &
         block_writeback_plan%vector_patch_nvalue <= 0) then
       call fail("edge-metric patch layout is invalid")
    end if
    call exchange_domain_to_block_payloads(BLOCK_PAYLOAD_EDGE_LENGTH)

    do local_index = 1,n_local
       block_edge_metric(local_index)%ready = .false.
       block_edge_metric(local_index)%installed_patch_count = 0
       block_edge_metric(local_index)%patch = 0.0_dp
    end do

    do local_index = 1,n_local
       b = local_block_catalog(local_index)
       source = source_rank(b)
       if (source /= rank) cycle
       d = loc_id(block_catalog(b)%root_domain+1) + 1
       if (d < 1 .or. d > size(grid)) then
          call fail("retained edge-metric Domain is invalid")
       end if
       local_patch = 0
       call install_retained_subtree( &
            d,block_catalog(b)%root_patch,b,local_patch)
       n_patch = local_block_patch_count(b)
       if (local_patch /= n_patch) then
          call fail("retained edge-metric coverage is incomplete")
       end if
    end do

    do r = 1,n_process
       pos_scalar = block_writeback_plan%scalar_send_displ(r) + 1
       pos_vector = block_writeback_plan%vector_send_displ(r) + 1
       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)
          b = block_writeback_plan%send_block(slot)
          n_patch = local_block_patch_count(b)
          do local_patch = 0,n_patch-1
             if (pos_scalar < 1 .or. pos_scalar + &
                  block_writeback_plan%scalar_patch_nvalue - 1 > &
                  size(block_writeback_plan%scalar_send_buffer) .or. &
                  pos_vector < 1 .or. pos_vector + &
                  block_writeback_plan%vector_patch_nvalue - 1 > &
                  size(block_writeback_plan%vector_send_buffer)) then
                call fail("remote edge-metric payload is truncated")
             end if
             call install_metric_patch( &
                  b,local_patch,block_writeback_plan%vector_send_buffer( &
                  pos_vector:pos_vector+ &
                  block_writeback_plan%vector_patch_nvalue-1))
             pos_scalar = pos_scalar + &
                  block_writeback_plan%scalar_patch_nvalue
             pos_vector = pos_vector + &
                  block_writeback_plan%vector_patch_nvalue
          end do
       end do
       if (pos_scalar /= block_writeback_plan%scalar_send_displ(r) + &
            block_writeback_plan%scalar_send_count(r) + 1 .or. &
            pos_vector /= block_writeback_plan%vector_send_displ(r) + &
            block_writeback_plan%vector_send_count(r) + 1) then
          call fail("remote edge-metric receive extent mismatch")
       end if
    end do

    do local_index = 1,n_local
       b = local_block_catalog(local_index)
       n_patch = local_block_patch_count(b)
       if (block_edge_metric(local_index)%catalog_index /= b .or. &
            block_edge_metric(local_index)%installed_patch_count /= &
            n_patch) then
          call fail("edge-metric installation coverage differs")
       end if
       block_edge_metric(local_index)%ready = .true.
    end do
    block_edge_metric_generation = block_writeback_plan_generation

    allocation_after = block_edge_metric_allocations
    if (allocation_after < allocation_before) then
       call fail("edge-metric allocation counter regressed")
    end if
    call prepare_edge_metric_storage(n_local)
    if (block_edge_metric_allocations /= allocation_after) then
       call fail("edge-metric storage was not reusable")
    end if

  contains

    logical function edge_metric_storage_is_current (n_block) &
         result(current)

      implicit none

      integer, intent(in) :: n_block

      integer :: catalog_index
      integer :: count
      integer :: index

      current = .false.
      if (block_edge_metric_generation /= &
           block_writeback_plan_generation) return
      if (.not. allocated(block_edge_metric)) return
      if (size(block_edge_metric) /= n_block) return
      do index = 1,n_block
         catalog_index = local_block_catalog(index)
         count = local_block_patch_count(catalog_index)* &
              block_writeback_plan%vector_patch_nvalue
         if (.not. block_edge_metric(index)%ready) return
         if (block_edge_metric(index)%catalog_index /= catalog_index) return
         if (.not. allocated(block_edge_metric(index)%patch)) return
         if (size(block_edge_metric(index)%patch) /= count) return
      end do
      current = .true.

    end function edge_metric_storage_is_current

    subroutine prepare_edge_metric_storage (n_block)

      implicit none

      integer, intent(in) :: n_block

      integer :: catalog_index
      integer :: count
      integer :: index
      integer :: patch_count

      if (allocated(block_edge_metric)) then
         if (size(block_edge_metric) /= n_block) then
            deallocate(block_edge_metric)
         end if
      end if
      if (.not. allocated(block_edge_metric)) then
         allocate(block_edge_metric(n_block))
         block_edge_metric_allocations = &
              block_edge_metric_allocations + 1_int64
      end if

      do index = 1,n_block
         catalog_index = local_block_catalog(index)
         patch_count = local_block_patch_count(catalog_index)
         count = patch_count*block_writeback_plan%vector_patch_nvalue
         if (allocated(block_edge_metric(index)%patch)) then
            if (block_edge_metric(index)%catalog_index /= catalog_index .or. &
                 size(block_edge_metric(index)%patch) /= count) then
               deallocate(block_edge_metric(index)%patch)
            end if
         end if
         if (.not. allocated(block_edge_metric(index)%patch)) then
            allocate(block_edge_metric(index)%patch(count))
            block_edge_metric_allocations = &
                 block_edge_metric_allocations + 1_int64
         end if
         block_edge_metric(index)%catalog_index = catalog_index
      end do

    end subroutine prepare_edge_metric_storage


    subroutine install_metric_patch (catalog_index,patch_index,value)

      implicit none

      integer, intent(in) :: catalog_index
      integer, intent(in) :: patch_index
      real(dp), intent(in) :: value(:)

      integer :: first
      integer :: index
      integer :: patch_count

      index = catalog_local_block(catalog_index)
      if (index < 1 .or. index > size(block_edge_metric)) then
         call fail("edge-metric local block is invalid")
      end if
      patch_count = local_block_patch_count(catalog_index)
      if (patch_index < 0 .or. patch_index >= patch_count) then
         call fail("edge-metric local patch is invalid")
      end if
      if (size(value) /= block_writeback_plan%vector_patch_nvalue) then
         call fail("edge-metric patch extent is invalid")
      end if
      first = patch_index*block_writeback_plan%vector_patch_nvalue + 1
      if (first < 1 .or. &
           first+size(value)-1 > size(block_edge_metric(index)%patch)) then
         call fail("edge-metric storage extent is invalid")
      end if
      block_edge_metric(index)%patch(first:first+size(value)-1) = value
      block_edge_metric(index)%installed_patch_count = &
           block_edge_metric(index)%installed_patch_count + 1

    end subroutine install_metric_patch


    recursive subroutine install_retained_subtree ( &
         d,p,catalog_index,patch_index)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(in) :: catalog_index
      integer, intent(inout) :: patch_index

      integer :: c
      integer :: child
      integer :: scalar_pos
      integer :: vector_pos

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("retained edge-metric patch is invalid")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return

      scalar_pos = 1
      vector_pos = 1
      call pack_domain_patch_prognostic( &
           d,p,BLOCK_PAYLOAD_EDGE_LENGTH, &
           ghost_exchange_plan%scalar_patch_buffer,scalar_pos, &
           ghost_exchange_plan%vector_patch_buffer,vector_pos)
      if (scalar_pos /= &
           size(ghost_exchange_plan%scalar_patch_buffer)+1 .or. &
           vector_pos /= &
           size(ghost_exchange_plan%vector_patch_buffer)+1) then
         call fail("retained edge-metric payload extent differs")
      end if
      call install_metric_patch( &
           catalog_index,patch_index, &
           ghost_exchange_plan%vector_patch_buffer)
      patch_index = patch_index + 1

      do c = 1,N_CHDRN
         child = grid(d)%patch%elts(p+1)%children(c)
         if (child <= 0) cycle
         call install_retained_subtree( &
              d,child,catalog_index,patch_index)
      end do

    end subroutine install_retained_subtree

  end subroutine refresh_candidate_block_edge_metrics




  subroutine evaluate_candidate_block_velocity_recomposition ( &
       domain_sol,checkpoint_required)
    ! Recompose the complete tendency, then replace its scalar component with
    ! the independently validated block-native restricted-flux divergence.
    ! The velocity component remains the reconstructed block-native result.

    implicit none

    type(Float_Field), intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    logical, intent(in) :: checkpoint_required

    call refresh_candidate_block_velocity_remainder(domain_sol)
    if (.not. block_scalar_divergence_plan%ready) then
       call fail("block-native scalar divergence input is not ready")
    end if
    call evaluate_candidate_block_exner_shadow( &
         domain_sol,BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY, &
         .true.,.true.,.true.,checkpoint_required,.true.,.true.)
    call evaluate_candidate_block_scalar_restriction

    if (rank == 0) then
       write(6,'(a)') &
            "  block-native complete physical tendency passed"
       write(6,'(a)') &
            "  recursive scalar restriction/divergence retained and activated"
       write(6,'(a)') &
            "  Domain compatibility and persistent workspace reuse passed"
    end if

  end subroutine evaluate_candidate_block_velocity_recomposition


  subroutine refresh_candidate_block_velocity_remainder (domain_sol)
    ! Install the Domain-authoritative non-Exner velocity residual in
    ! persistent final-owner block storage. It is consumed read-only by the
    ! rejected complete-velocity kernel.

    implicit none

    type(Float_Field), intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)

    integer :: b
    integer :: d
    integer :: local_index
    integer :: local_patch
    integer :: n_local
    integer :: n_patch
    integer :: pos_scalar
    integer :: pos_vector
    integer :: r
    integer :: source
    integer :: slot

    integer(int64) :: allocation_after
    integer(int64) :: allocation_before

    n_local = n_local_blocks()
    allocation_before = block_velocity_remainder_allocations
    call prepare_velocity_remainder_storage(n_local)
    if (.not. allocated(ghost_exchange_plan%scalar_patch_buffer) .or. &
         .not. allocated(ghost_exchange_plan%vector_patch_buffer)) then
       call fail("velocity-residual retained patch buffers are absent")
    end if
    call exchange_domain_to_block_payloads( &
         BLOCK_PAYLOAD_PHYSICAL_COMPONENTS,domain_sol=domain_sol)

    do local_index = 1,n_local
       block_velocity_remainder(local_index)%ready = .false.
       block_velocity_remainder(local_index)%installed_patch_count = 0
       block_velocity_remainder(local_index)%patch = 0.0_dp
    end do

    do local_index = 1,n_local
       b = local_block_catalog(local_index)
       source = source_rank(b)
       if (source /= rank) cycle
       d = loc_id(block_catalog(b)%root_domain+1) + 1
       if (d < 1 .or. d > size(grid)) then
          call fail("retained velocity-residual Domain is invalid")
       end if
       local_patch = 0
       call install_retained_subtree( &
            d,block_catalog(b)%root_patch,b,local_patch)
       n_patch = local_block_patch_count(b)
       if (local_patch /= n_patch) then
          call fail("retained velocity-residual coverage is incomplete")
       end if
    end do

    do r = 1,n_process
       pos_scalar = block_writeback_plan%scalar_send_displ(r) + 1
       pos_vector = block_writeback_plan%vector_send_displ(r) + 1
       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)
          b = block_writeback_plan%send_block(slot)
          n_patch = local_block_patch_count(b)
          do local_patch = 0,n_patch-1
             if (pos_scalar < 1 .or. pos_scalar + &
                  block_writeback_plan%scalar_patch_nvalue - 1 > &
                  size(block_writeback_plan%scalar_send_buffer) .or. &
                  pos_vector < 1 .or. pos_vector + &
                  block_writeback_plan%vector_patch_nvalue - 1 > &
                  size(block_writeback_plan%vector_send_buffer)) then
                call fail("remote velocity-residual payload is truncated")
             end if
             call install_remainder_patch( &
                  b,local_patch,block_writeback_plan%vector_send_buffer( &
                  pos_vector:pos_vector+ &
                  block_writeback_plan%vector_patch_nvalue-1))
             pos_scalar = pos_scalar + &
                  block_writeback_plan%scalar_patch_nvalue
             pos_vector = pos_vector + &
                  block_writeback_plan%vector_patch_nvalue
          end do
       end do
       if (pos_scalar /= block_writeback_plan%scalar_send_displ(r) + &
            block_writeback_plan%scalar_send_count(r) + 1 .or. &
            pos_vector /= block_writeback_plan%vector_send_displ(r) + &
            block_writeback_plan%vector_send_count(r) + 1) then
          call fail("remote velocity-residual receive extent mismatch")
       end if
    end do

    do local_index = 1,n_local
       b = local_block_catalog(local_index)
       n_patch = local_block_patch_count(b)
       if (block_velocity_remainder(local_index)%catalog_index /= b .or. &
            block_velocity_remainder(local_index)%installed_patch_count /= &
            n_patch) then
          call fail("velocity-residual installation coverage differs")
       end if
       block_velocity_remainder(local_index)%ready = .true.
    end do

    allocation_after = block_velocity_remainder_allocations
    if (allocation_after < allocation_before) then
       call fail("velocity-residual allocation counter regressed")
    end if
    call prepare_velocity_remainder_storage(n_local)
    if (block_velocity_remainder_allocations /= allocation_after) then
       call fail("velocity-residual storage was not reusable")
    end if

  contains

    subroutine prepare_velocity_remainder_storage (n_block)

      implicit none

      integer, intent(in) :: n_block

      integer :: catalog_index
      integer :: count
      integer :: index
      integer :: patch_count

      if (allocated(block_velocity_remainder)) then
         if (size(block_velocity_remainder) /= n_block) then
            deallocate(block_velocity_remainder)
         end if
      end if
      if (.not. allocated(block_velocity_remainder)) then
         allocate(block_velocity_remainder(n_block))
         block_velocity_remainder_allocations = &
              block_velocity_remainder_allocations + 1_int64
      end if

      do index = 1,n_block
         catalog_index = local_block_catalog(index)
         patch_count = local_block_patch_count(catalog_index)
         count = patch_count*block_writeback_plan%vector_patch_nvalue
         if (allocated(block_velocity_remainder(index)%patch)) then
            if (block_velocity_remainder(index)%catalog_index /= &
                 catalog_index .or. &
                 size(block_velocity_remainder(index)%patch) /= count) then
               deallocate(block_velocity_remainder(index)%patch)
            end if
         end if
         if (.not. allocated(block_velocity_remainder(index)%patch)) then
            allocate(block_velocity_remainder(index)%patch(count))
            block_velocity_remainder_allocations = &
                 block_velocity_remainder_allocations + 1_int64
         end if
         block_velocity_remainder(index)%catalog_index = catalog_index
      end do

    end subroutine prepare_velocity_remainder_storage


    subroutine install_remainder_patch (catalog_index,patch_index,value)

      implicit none

      integer, intent(in) :: catalog_index
      integer, intent(in) :: patch_index
      real(dp), intent(in) :: value(:)

      integer :: first
      integer :: index
      integer :: patch_count

      index = catalog_local_block(catalog_index)
      if (index < 1 .or. index > size(block_velocity_remainder)) then
         call fail("velocity-residual local block is invalid")
      end if
      patch_count = local_block_patch_count(catalog_index)
      if (patch_index < 0 .or. patch_index >= patch_count) then
         call fail("velocity-residual local patch is invalid")
      end if
      if (size(value) /= block_writeback_plan%vector_patch_nvalue) then
         call fail("velocity-residual patch extent is invalid")
      end if
      first = patch_index*block_writeback_plan%vector_patch_nvalue + 1
      if (first < 1 .or. first+size(value)-1 > &
           size(block_velocity_remainder(index)%patch)) then
         call fail("velocity-residual storage extent is invalid")
      end if
      block_velocity_remainder(index)%patch( &
           first:first+size(value)-1) = value
      block_velocity_remainder(index)%installed_patch_count = &
           block_velocity_remainder(index)%installed_patch_count + 1

    end subroutine install_remainder_patch


    recursive subroutine install_retained_subtree ( &
         d,p,catalog_index,patch_index)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(in) :: catalog_index
      integer, intent(inout) :: patch_index

      integer :: c
      integer :: child
      integer :: scalar_pos
      integer :: vector_pos

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("retained velocity-residual patch is invalid")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return

      scalar_pos = 1
      vector_pos = 1
      call pack_domain_patch_prognostic( &
           d,p,BLOCK_PAYLOAD_PHYSICAL_COMPONENTS, &
           ghost_exchange_plan%scalar_patch_buffer,scalar_pos, &
           ghost_exchange_plan%vector_patch_buffer,vector_pos,domain_sol)
      if (scalar_pos /= &
           size(ghost_exchange_plan%scalar_patch_buffer)+1 .or. &
           vector_pos /= &
           size(ghost_exchange_plan%vector_patch_buffer)+1) then
         call fail("retained velocity-residual payload extent differs")
      end if
      call install_remainder_patch( &
           catalog_index,patch_index, &
           ghost_exchange_plan%vector_patch_buffer)
      patch_index = patch_index + 1

      do c = 1,N_CHDRN
         child = grid(d)%patch%elts(p+1)%children(c)
         if (child <= 0) cycle
         call install_retained_subtree( &
              d,child,catalog_index,patch_index)
      end do

    end subroutine install_retained_subtree

  end subroutine refresh_candidate_block_velocity_remainder


  subroutine begin_block_scalar_divergence_capture
    ! Prepare one persistent Domain-owner to block-owner transport for the
    ! validation flux stencil, immutable metric inputs, and non-advective
    ! physics residual required by block-native scalar-flux production.

    implicit none

    integer :: b
    integer :: boundary_index
    integer :: boundary_sample_count
    integer :: count
    integer :: ghost_sample_count
    integer :: index
    integer :: n_local
    integer :: patch_count

    integer(int64) :: allocation_after
    integer(int64) :: restriction_allocation_after

    logical :: state_ready

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail("scalar-divergence capture before block state is ready")
    end if
    if (block_scalar_divergence_plan%active) then
       call fail("scalar-divergence capture is already active")
    end if

    call prepare_scalar_divergence_plan
    call prepare_block_scalar_restriction_exchange
    allocation_after = block_scalar_divergence_plan%allocations
    restriction_allocation_after = &
         block_scalar_restriction_exchange%allocations
    call prepare_scalar_divergence_plan
    call prepare_block_scalar_restriction_exchange
    if (block_scalar_divergence_plan%allocations /= allocation_after) then
       call fail("scalar-divergence transport was not reusable")
    end if
    if (block_scalar_restriction_exchange%allocations /= &
         restriction_allocation_after) then
       call fail("scalar-restriction transport was not reusable")
    end if

    n_local = n_local_blocks()
    if (allocated(block_scalar_tendency)) then
       if (size(block_scalar_tendency) /= n_local) then
          deallocate(block_scalar_tendency)
       end if
    end if
    if (.not. allocated(block_scalar_tendency)) then
       allocate(block_scalar_tendency(n_local))
       block_scalar_tendency_allocations = &
            block_scalar_tendency_allocations + 1_int64
    end if
    do index = 1,n_local
       b = local_block_catalog(index)
       patch_count = local_block_patch_count(b)
       count = patch_count*block_writeback_plan%scalar_patch_nvalue
       boundary_sample_count = 0
       do boundary_index = 1,local_block_boundary_count(b)
          boundary_sample_count = boundary_sample_count + &
               local_block_scalar_family_boundary_nvalue( &
               b,boundary_index)
       end do
       ghost_sample_count = local_block_ghost_count(b)* &
            block_writeback_plan%scalar_patch_nvalue
       if (allocated(block_scalar_tendency(index)%patch)) then
          if (block_scalar_tendency(index)%catalog_index /= b .or. &
               size(block_scalar_tendency(index)%patch) /= &
               BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*count) then
             deallocate(block_scalar_tendency(index)%patch)
          end if
       end if
       if (allocated(block_scalar_tendency(index)%covered)) then
          if (block_scalar_tendency(index)%catalog_index /= b .or. &
               size(block_scalar_tendency(index)%covered) /= count) then
             deallocate(block_scalar_tendency(index)%covered)
          end if
       end if
       if (allocated(block_scalar_tendency(index)%bdry)) then
          if (block_scalar_tendency(index)%catalog_index /= b .or. &
               size(block_scalar_tendency(index)%bdry) /= &
               BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
               boundary_sample_count) then
             deallocate(block_scalar_tendency(index)%bdry)
          end if
       end if
       if (allocated(block_scalar_tendency(index)%ghost)) then
          if (block_scalar_tendency(index)%catalog_index /= b .or. &
               size(block_scalar_tendency(index)%ghost) /= &
               BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
               ghost_sample_count) then
             deallocate(block_scalar_tendency(index)%ghost)
          end if
       end if
       if (.not. allocated(block_scalar_tendency(index)%patch)) then
          allocate(block_scalar_tendency(index)%patch( &
               BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*count))
          block_scalar_tendency_allocations = &
               block_scalar_tendency_allocations + 1_int64
       end if
       if (.not. allocated(block_scalar_tendency(index)%covered)) then
          allocate(block_scalar_tendency(index)%covered(count))
          block_scalar_tendency_allocations = &
               block_scalar_tendency_allocations + 1_int64
       end if
       if (.not. allocated(block_scalar_tendency(index)%bdry)) then
          allocate(block_scalar_tendency(index)%bdry( &
               BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
               boundary_sample_count))
          block_scalar_tendency_allocations = &
               block_scalar_tendency_allocations + 1_int64
       end if
       if (.not. allocated(block_scalar_tendency(index)%ghost)) then
          allocate(block_scalar_tendency(index)%ghost( &
               BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*ghost_sample_count))
          block_scalar_tendency_allocations = &
               block_scalar_tendency_allocations + 1_int64
       end if
       block_scalar_tendency(index)%catalog_index = b
       block_scalar_tendency(index)%installed_patch_count = 0
       block_scalar_tendency(index)%ready = .false.
       block_scalar_tendency(index)%patch = BLOCK_PATCH_POISON
       block_scalar_tendency(index)%bdry = BLOCK_BOUNDARY_POISON
       block_scalar_tendency(index)%ghost = BLOCK_GHOST_POISON
       block_scalar_tendency(index)%covered = .false.
    end do

    block_scalar_divergence_plan%recv_buffer = BLOCK_PATCH_POISON
    block_scalar_divergence_plan%send_buffer = 0.0_dp
    block_scalar_divergence_plan%recv_covered = .false.
    block_scalar_restriction_exchange%boundary_send_buffer = &
         BLOCK_BOUNDARY_POISON
    block_scalar_restriction_exchange%boundary_recv_buffer = &
         BLOCK_BOUNDARY_POISON
    block_scalar_restriction_exchange%ghost_send_buffer = &
         BLOCK_GHOST_POISON
    block_scalar_restriction_exchange%ghost_recv_buffer = &
         BLOCK_GHOST_POISON
    block_scalar_divergence_plan%ready = .false.
    block_scalar_divergence_plan%active = .true.

  contains

    subroutine prepare_scalar_divergence_plan

      implicit none

      integer :: n_recv
      integer :: n_send

      if (block_scalar_divergence_plan%generation == &
           block_writeback_plan_generation) return

      if (allocated(block_scalar_divergence_plan%send_count)) &
           deallocate(block_scalar_divergence_plan%send_count)
      if (allocated(block_scalar_divergence_plan%recv_count)) &
           deallocate(block_scalar_divergence_plan%recv_count)
      if (allocated(block_scalar_divergence_plan%send_displ)) &
           deallocate(block_scalar_divergence_plan%send_displ)
      if (allocated(block_scalar_divergence_plan%recv_displ)) &
           deallocate(block_scalar_divergence_plan%recv_displ)
      if (allocated(block_scalar_divergence_plan%send_buffer)) &
           deallocate(block_scalar_divergence_plan%send_buffer)
      if (allocated(block_scalar_divergence_plan%recv_buffer)) &
           deallocate(block_scalar_divergence_plan%recv_buffer)
      if (allocated(block_scalar_divergence_plan%recv_covered)) &
           deallocate(block_scalar_divergence_plan%recv_covered)

      allocate(block_scalar_divergence_plan%send_count(n_process))
      allocate(block_scalar_divergence_plan%recv_count(n_process))
      allocate(block_scalar_divergence_plan%send_displ(n_process))
      allocate(block_scalar_divergence_plan%recv_displ(n_process))
      block_scalar_divergence_plan%send_count = &
           BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
           block_writeback_plan%scalar_send_count
      block_scalar_divergence_plan%recv_count = &
           BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
           block_writeback_plan%scalar_recv_count
      block_scalar_divergence_plan%send_displ = &
           BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
           block_writeback_plan%scalar_send_displ
      block_scalar_divergence_plan%recv_displ = &
           BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
           block_writeback_plan%scalar_recv_displ
      n_send = sum(block_scalar_divergence_plan%send_count)
      n_recv = sum(block_scalar_divergence_plan%recv_count)
      allocate(block_scalar_divergence_plan%send_buffer(n_send))
      allocate(block_scalar_divergence_plan%recv_buffer(n_recv))
      allocate(block_scalar_divergence_plan%recv_covered( &
           sum(block_writeback_plan%scalar_recv_count)))
      block_scalar_divergence_plan%allocations = &
           block_scalar_divergence_plan%allocations + 7_int64
      block_scalar_divergence_plan%generation = &
           block_writeback_plan_generation

    end subroutine prepare_scalar_divergence_plan

  end subroutine begin_block_scalar_divergence_capture


  subroutine prepare_block_scalar_restriction_exchange
    ! Allocate persistent compact-boundary and inter-block-ghost routes for
    ! the scalar restriction record. Routing is inherited from the validated
    ! prognostic boundary and ghost plans; only the payload width differs.

    implicit none

    integer :: n_boundary_recv
    integer :: n_boundary_send
    integer :: n_ghost_recv
    integer :: n_ghost_send

    if (block_scalar_restriction_exchange%generation == &
         block_writeback_plan_generation) return

    if (allocated(block_scalar_restriction_exchange% &
         boundary_send_count)) deallocate( &
         block_scalar_restriction_exchange%boundary_send_count)
    if (allocated(block_scalar_restriction_exchange% &
         boundary_recv_count)) deallocate( &
         block_scalar_restriction_exchange%boundary_recv_count)
    if (allocated(block_scalar_restriction_exchange% &
         boundary_send_displ)) deallocate( &
         block_scalar_restriction_exchange%boundary_send_displ)
    if (allocated(block_scalar_restriction_exchange% &
         boundary_recv_displ)) deallocate( &
         block_scalar_restriction_exchange%boundary_recv_displ)
    if (allocated(block_scalar_restriction_exchange% &
         boundary_send_buffer)) deallocate( &
         block_scalar_restriction_exchange%boundary_send_buffer)
    if (allocated(block_scalar_restriction_exchange% &
         boundary_recv_buffer)) deallocate( &
         block_scalar_restriction_exchange%boundary_recv_buffer)
    if (allocated(block_scalar_restriction_exchange%ghost_send_count)) &
         deallocate(block_scalar_restriction_exchange%ghost_send_count)
    if (allocated(block_scalar_restriction_exchange%ghost_recv_count)) &
         deallocate(block_scalar_restriction_exchange%ghost_recv_count)
    if (allocated(block_scalar_restriction_exchange%ghost_send_displ)) &
         deallocate(block_scalar_restriction_exchange%ghost_send_displ)
    if (allocated(block_scalar_restriction_exchange%ghost_recv_displ)) &
         deallocate(block_scalar_restriction_exchange%ghost_recv_displ)
    if (allocated(block_scalar_restriction_exchange%ghost_send_buffer)) &
         deallocate(block_scalar_restriction_exchange%ghost_send_buffer)
    if (allocated(block_scalar_restriction_exchange%ghost_recv_buffer)) &
         deallocate(block_scalar_restriction_exchange%ghost_recv_buffer)
    if (allocated(block_scalar_restriction_exchange%ghost_patch_buffer)) &
         deallocate(block_scalar_restriction_exchange%ghost_patch_buffer)

    allocate(block_scalar_restriction_exchange% &
         boundary_send_count(n_process))
    allocate(block_scalar_restriction_exchange% &
         boundary_recv_count(n_process))
    allocate(block_scalar_restriction_exchange% &
         boundary_send_displ(n_process))
    allocate(block_scalar_restriction_exchange% &
         boundary_recv_displ(n_process))
    block_scalar_restriction_exchange%boundary_send_count = &
         BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
         block_writeback_plan%boundary_scalar_domain_send_count
    block_scalar_restriction_exchange%boundary_recv_count = &
         BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
         block_writeback_plan%boundary_scalar_block_recv_count
    block_scalar_restriction_exchange%boundary_send_displ = &
         BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
         block_writeback_plan%boundary_scalar_domain_send_displ
    block_scalar_restriction_exchange%boundary_recv_displ = &
         BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
         block_writeback_plan%boundary_scalar_block_recv_displ
    n_boundary_send = sum( &
         block_scalar_restriction_exchange%boundary_send_count)
    n_boundary_recv = sum( &
         block_scalar_restriction_exchange%boundary_recv_count)
    allocate(block_scalar_restriction_exchange% &
         boundary_send_buffer(max(1,n_boundary_send)))
    allocate(block_scalar_restriction_exchange% &
         boundary_recv_buffer(max(1,n_boundary_recv)))

    allocate(block_scalar_restriction_exchange% &
         ghost_send_count(n_process))
    allocate(block_scalar_restriction_exchange% &
         ghost_recv_count(n_process))
    allocate(block_scalar_restriction_exchange% &
         ghost_send_displ(n_process))
    allocate(block_scalar_restriction_exchange% &
         ghost_recv_displ(n_process))
    block_scalar_restriction_exchange%ghost_send_count = &
         BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
         ghost_exchange_plan%scalar_n_value* &
         ghost_exchange_plan%recv_record_count
    block_scalar_restriction_exchange%ghost_recv_count = &
         BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
         ghost_exchange_plan%scalar_n_value* &
         ghost_exchange_plan%send_record_count
    block_scalar_restriction_exchange%ghost_send_displ(1) = 0
    block_scalar_restriction_exchange%ghost_recv_displ(1) = 0
    block_scalar_restriction_exchange%ghost_send_displ(2:n_process) = &
         BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
         ghost_exchange_plan%scalar_n_value* &
         ghost_exchange_plan%recv_record_displ(2:n_process)
    block_scalar_restriction_exchange%ghost_recv_displ(2:n_process) = &
         BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
         ghost_exchange_plan%scalar_n_value* &
         ghost_exchange_plan%send_record_displ(2:n_process)
    n_ghost_send = sum( &
         block_scalar_restriction_exchange%ghost_send_count)
    n_ghost_recv = sum( &
         block_scalar_restriction_exchange%ghost_recv_count)
    allocate(block_scalar_restriction_exchange% &
         ghost_send_buffer(max(1,n_ghost_send)))
    allocate(block_scalar_restriction_exchange% &
         ghost_recv_buffer(max(1,n_ghost_recv)))
    allocate(block_scalar_restriction_exchange%ghost_patch_buffer( &
         BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
         ghost_exchange_plan%scalar_n_value))

    block_scalar_restriction_exchange%boundary_send_buffer = &
         BLOCK_BOUNDARY_POISON
    block_scalar_restriction_exchange%boundary_recv_buffer = &
         BLOCK_BOUNDARY_POISON
    block_scalar_restriction_exchange%ghost_send_buffer = &
         BLOCK_GHOST_POISON
    block_scalar_restriction_exchange%ghost_recv_buffer = &
         BLOCK_GHOST_POISON
    block_scalar_restriction_exchange%ghost_patch_buffer = &
         BLOCK_GHOST_POISON
    block_scalar_restriction_exchange%allocations = &
         block_scalar_restriction_exchange%allocations + 13_int64
    block_scalar_restriction_exchange%generation = &
         block_writeback_plan_generation
    block_scalar_restriction_exchange%ready = .true.

  end subroutine prepare_block_scalar_restriction_exchange


  subroutine capture_block_scalar_divergence_level ( &
       domain_sol,physics_flux,scalar_id,field_level,grid_level, &
       direct_flux,domain_tendency,dscalar_only)
    ! Before hierarchy restriction, capture the three directly evaluated
    ! positive-edge fluxes and their immutable production inputs. After
    ! restriction and boundary refresh, capture the authoritative six-edge
    ! stencil used by scalar divergence.

    implicit none

    type(Float_Field), intent(inout) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    procedure(Block_Scalar_Physics_Flux) :: physics_flux
    integer, intent(in) :: scalar_id
    integer, intent(in) :: field_level
    integer, intent(in) :: grid_level
    logical, optional, intent(in) :: direct_flux
    type(Float_Field), optional, intent(in) :: &
         domain_tendency(1:N_VARIABLE,1:zlevels)
    logical, optional, intent(in) :: dscalar_only

    integer :: b
    integer :: d
    integer :: first_field_level
    integer :: level_slot
    integer :: local_index
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_variable
    integer :: patch_index
    integer :: r
    integer :: sample_start
    integer :: scalar_slot
    integer :: slot
    integer :: v_scalar
    integer :: v_vector

    logical :: capture_direct
    logical :: capture_dscalar

    if (.not. block_scalar_divergence_plan%active) return
    capture_direct = .false.
    if (present(direct_flux)) capture_direct = direct_flux
    capture_dscalar = .false.
    if (present(dscalar_only)) capture_dscalar = dscalar_only
    if (capture_direct .and. capture_dscalar) then
       call fail("scalar-divergence capture mode is invalid")
    end if
    if (capture_dscalar .and. .not. present(domain_tendency)) then
       call fail("scalar-divergence tendency input is absent")
    end if

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    scalar_slot = scalar_id-v_scalar+1
    level_slot = field_level-first_field_level+1
    if (scalar_slot < 1 .or. scalar_slot > n_scalar_variable .or. &
         level_slot < 1 .or. level_slot > n_field_level .or. &
         mult_scalar /= 1 .or. mult_vector /= EDGE) then
       call fail("scalar-divergence capture field layout is invalid")
    end if

    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       if (source_rank(b) /= rank) cycle
       d = loc_id(block_catalog(b)%root_domain+1) + 1
       if (d < 1 .or. d > size(grid)) then
          call fail("retained scalar-divergence Domain is invalid")
       end if
       patch_index = 0
       call capture_subtree( &
            d,block_catalog(b)%root_patch,b,patch_index,1,local_index)
       if (patch_index /= local_block_patch_count(b)) then
          call fail("retained scalar-divergence traversal is incomplete")
       end if
    end do

    do r = 1,n_process
       sample_start = block_writeback_plan%scalar_recv_displ(r) + 1
       do slot = block_writeback_plan%recv_displ(r)+1, &
            block_writeback_plan%recv_displ(r) + &
            block_writeback_plan%recv_count(r)
          b = block_writeback_plan%recv_block(slot)
          if (source_rank(b) /= rank) then
             call fail("remote scalar-divergence source is invalid")
          end if
          d = loc_id(block_catalog(b)%root_domain+1) + 1
          if (d < 1 .or. d > size(grid)) then
             call fail("remote scalar-divergence Domain is invalid")
          end if
          patch_index = 0
          call capture_subtree( &
               d,block_catalog(b)%root_patch,b,patch_index, &
               sample_start,0)
          if (patch_index /= &
               block_writeback_plan%recv_patch_count(slot)) then
             call fail("remote scalar-divergence traversal is incomplete")
          end if
          sample_start = sample_start + &
               block_writeback_plan%recv_scalar_nvalue(slot)
       end do
       if (sample_start /= &
            block_writeback_plan%scalar_recv_displ(r) + &
            block_writeback_plan%scalar_recv_count(r) + 1) then
          call fail("scalar-divergence capture extent mismatch")
       end if
    end do

    call capture_block_scalar_restriction_boundaries( &
         scalar_id,field_level,grid_level,capture_direct, &
         domain_tendency,capture_dscalar)

  contains

    recursive subroutine capture_subtree ( &
         d,p,b,patch_index,block_sample_start,storage_index)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(in) :: b
      integer, intent(inout) :: patch_index
      integer, intent(in) :: block_sample_start
      integer, intent(in) :: storage_index

      integer :: c
      integer :: child

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("scalar-divergence capture patch is invalid")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return

      if (grid(d)%patch%elts(p+1)%level == grid_level) then
         call capture_patch( &
              d,p,b,patch_index,block_sample_start,storage_index)
      end if
      patch_index = patch_index + 1

      do c = 1,N_CHDRN
         child = grid(d)%patch%elts(p+1)%children(c)
         if (child <= 0) cycle
         call capture_subtree( &
              d,child,b,patch_index,block_sample_start,storage_index)
      end do

    end subroutine capture_subtree


    subroutine capture_patch ( &
         d,p,b,patch_index,block_sample_start,storage_index)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(in) :: b
      integer, intent(in) :: patch_index
      integer, intent(in) :: block_sample_start
      integer, intent(in) :: storage_index

      integer :: data_start
      integer :: dims(2,N_BDRY+1)
      integer :: i
      integer :: id
      integer :: id_e
      integer :: id_n
      integer :: id_ne
      integer :: id_s
      integer :: id_sw
      integer :: id_w
      integer :: j
      integer :: offs(N_BDRY+1)
      integer :: q
      integer :: sample
      integer :: source_start

      real(dp) :: physics_positive(EDGE)
      real(dp) :: value(BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT)

      call get_offs_Domain(grid(d),p,offs,dims)
      source_start = grid(d)%patch%elts(p+1)%elts_start
      do q = 0,PATCH_SIZE**2-1
         i = mod(q,PATCH_SIZE)
         j = q/PATCH_SIZE
         id = idx(i,j,offs,dims)
         if (id /= source_start+q) then
            call fail("scalar-divergence centre index differs")
         end if
         value = 0.0_dp
         if (capture_dscalar) then
            value(BLOCK_SCALAR_REFERENCE_DSCALAR_INDEX) = &
                 domain_tendency(scalar_id,field_level)%data(d)%elts(id+1)
         else if (capture_direct) then
            id_e = idx(i+1,j,offs,dims)
            id_ne = idx(i+1,j+1,offs,dims)
            id_n = idx(i,j+1,offs,dims)
            physics_positive = physics_flux( &
                 domain_sol,grid(d),id,id_e,id_ne,id_n, &
                 scalar_id,field_level)
            value(BLOCK_SCALAR_DIRECT_FLUX_START: &
                 BLOCK_SCALAR_DIRECT_FLUX_START+EDGE-1) = &
                 horiz_flux(scalar_id)%data(d)%elts( &
                 EDGE*id+RT+1:EDGE*id+UP+1)
            value(BLOCK_SCALAR_PEDLEN_START: &
                 BLOCK_SCALAR_PEDLEN_START+EDGE-1) = &
                 grid(d)%pedlen%elts(EDGE*id+RT+1:EDGE*id+UP+1)
            value(BLOCK_SCALAR_PHYSICS_START: &
                 BLOCK_SCALAR_PHYSICS_START+EDGE-1) = physics_positive
         else
            id_w = idx(i-1,j,offs,dims)
            id_sw = idx(i-1,j-1,offs,dims)
            id_s = idx(i,j-1,offs,dims)
            value(1:BLOCK_SCALAR_FLUX_COUNT) = [ &
                 horiz_flux(scalar_id)%data(d)%elts(EDGE*id+RT+1), &
                 horiz_flux(scalar_id)%data(d)%elts(EDGE*id_w+RT+1), &
                 horiz_flux(scalar_id)%data(d)%elts(EDGE*id_sw+DG+1), &
                 horiz_flux(scalar_id)%data(d)%elts(EDGE*id+DG+1), &
                 horiz_flux(scalar_id)%data(d)%elts(EDGE*id+UP+1), &
                 horiz_flux(scalar_id)%data(d)%elts(EDGE*id_s+UP+1)]
            value(BLOCK_SCALAR_AREA_INDEX) = &
                 grid(d)%areas%elts(id+1)%hex_inv
            value(BLOCK_SCALAR_ACTIVE_INDEX) = merge( &
                 1.0_dp,0.0_dp,grid(d)%mask_n%elts(id+1) >= TRSK)
            value(BLOCK_SCALAR_WAVELET_MASK_INDEX) = &
                 real(grid(d)%mask_n%elts(id+1),dp)
            value(BLOCK_VECTOR_WAVELET_WEIGHT_START: &
                 BLOCK_VECTOR_WAVELET_WEIGHT_START+8) = &
                 real(grid(d)%I_u_wgt%elts(id+1)%enc,dp)
            value(BLOCK_SCALAR_RESTRICTED_FLUX_START: &
                 BLOCK_SCALAR_RESTRICTED_FLUX_START+EDGE-1) = &
                 horiz_flux(scalar_id)%data(d)%elts( &
                 EDGE*id+RT+1:EDGE*id+UP+1)
            value(BLOCK_SCALAR_EDGE_MASK_START: &
                 BLOCK_SCALAR_EDGE_MASK_START+EDGE-1) = real( &
                 grid(d)%mask_e%elts(EDGE*id+RT+1:EDGE*id+UP+1),dp)
            value(BLOCK_SCALAR_RESTRICTION_WEIGHT_START: &
                 BLOCK_SCALAR_RESTRICTION_WEIGHT_START+EDGE-1) = &
                 grid(d)%R_F_wgt%elts(id+1)%enc
            value(BLOCK_SCALAR_OVERLAP_START: &
                 BLOCK_SCALAR_OVERLAP_START+3) = &
                 grid(d)%overl_areas%elts(id+1)%a
            value(BLOCK_SCALAR_OVERLAP_START+4: &
                 BLOCK_SCALAR_OVERLAP_START+5) = &
                 grid(d)%overl_areas%elts(id+1)%split
         end if
         value(BLOCK_SCALAR_SOURCE_INDEX) = real(id,dp)
         sample = block_sample_start + &
              patch_index*block_writeback_plan%scalar_patch_nvalue + &
              ((scalar_slot-1)*n_field_level + level_slot-1)* &
              PATCH_SIZE**2 + q
         if (storage_index > 0) then
            if (storage_index > size(block_scalar_tendency) .or. &
                 sample < 1 .or. sample > &
                 size(block_scalar_tendency(storage_index)%covered)) then
               call fail("retained scalar-divergence index is invalid")
            end if
            data_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                 (sample-1) + 1
            if (capture_dscalar) then
               block_scalar_tendency(storage_index)%patch( &
                    data_start+BLOCK_SCALAR_REFERENCE_DSCALAR_INDEX-1) = &
                    value(BLOCK_SCALAR_REFERENCE_DSCALAR_INDEX)
            else if (capture_direct) then
               block_scalar_tendency(storage_index)%patch( &
                    data_start+BLOCK_SCALAR_DIRECT_FLUX_START-1: &
                    data_start+BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1) = &
                    value(BLOCK_SCALAR_DIRECT_FLUX_START: &
                    BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT)
            else
               block_scalar_tendency(storage_index)%patch( &
                    data_start:data_start+BLOCK_SCALAR_ACTIVE_INDEX-1) = &
                    value(1:BLOCK_SCALAR_ACTIVE_INDEX)
               block_scalar_tendency(storage_index)%patch( &
                    data_start+BLOCK_SCALAR_RESTRICTED_FLUX_START-1: &
                    data_start+BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1) = &
                    value(BLOCK_SCALAR_RESTRICTED_FLUX_START: &
                    BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT)
               block_scalar_tendency(storage_index)%covered(sample) = .true.
            end if
         else
            if (sample < 1 .or. &
                 sample > size(block_scalar_divergence_plan%recv_covered)) &
                 then
               call fail("remote scalar-divergence index is invalid")
            end if
            data_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                 (sample-1) + 1
            if (capture_dscalar) then
               block_scalar_divergence_plan%recv_buffer( &
                    data_start+BLOCK_SCALAR_REFERENCE_DSCALAR_INDEX-1) = &
                    value(BLOCK_SCALAR_REFERENCE_DSCALAR_INDEX)
            else if (capture_direct) then
               block_scalar_divergence_plan%recv_buffer( &
                    data_start+BLOCK_SCALAR_DIRECT_FLUX_START-1: &
                    data_start+BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1) = &
                    value(BLOCK_SCALAR_DIRECT_FLUX_START: &
                    BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT)
            else
               block_scalar_divergence_plan%recv_buffer( &
                    data_start:data_start+BLOCK_SCALAR_ACTIVE_INDEX-1) = &
                    value(1:BLOCK_SCALAR_ACTIVE_INDEX)
               block_scalar_divergence_plan%recv_buffer( &
                    data_start+BLOCK_SCALAR_RESTRICTED_FLUX_START-1: &
                    data_start+BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1) = &
                    value(BLOCK_SCALAR_RESTRICTED_FLUX_START: &
                    BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT)
               block_scalar_divergence_plan%recv_covered(sample) = .true.
            end if
         end if

      end do

    end subroutine capture_patch

  end subroutine capture_block_scalar_divergence_level


  subroutine capture_block_scalar_restriction_boundaries ( &
       scalar_id,field_level,grid_level,capture_direct, &
       domain_tendency,capture_dscalar)
    ! Capture positive scalar flux and immutable restriction geometry for
    ! compact Domain-boundary records. These records remain authoritative
    ! compatibility inputs; inter-block records are refreshed from native
    ! block interiors before every bottom-up restriction level.

    implicit none

    integer, intent(in) :: scalar_id
    integer, intent(in) :: field_level
    integer, intent(in) :: grid_level
    logical, intent(in) :: capture_direct
    type(Float_Field), optional, intent(in) :: &
         domain_tendency(1:N_VARIABLE,1:zlevels)
    logical, intent(in) :: capture_dscalar

    integer :: b
    integer :: boundary_index
    integer :: d
    integer :: first_field_level
    integer :: level_slot
    integer :: local_index
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_boundary_node
    integer :: n_field_level
    integer :: n_node
    integer :: n_scalar
    integer :: n_scalar_variable
    integer :: node_start
    integer :: pos_sample
    integer :: r
    integer :: scalar_slot
    integer :: slot
    integer :: source_bdry
    integer :: source_level
    integer :: v_scalar
    integer :: v_vector

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    scalar_slot = scalar_id-v_scalar+1
    level_slot = field_level-first_field_level+1
    if (scalar_slot < 1 .or. scalar_slot > n_scalar_variable .or. &
         level_slot < 1 .or. level_slot > n_field_level .or. &
         mult_scalar /= 1 .or. mult_vector /= EDGE) then
       call fail("scalar-restriction boundary layout is invalid")
    end if

    do r = 1,n_process
       pos_sample = block_writeback_plan% &
            boundary_scalar_domain_send_displ(r) + 1
       do slot = block_writeback_plan%recv_displ(r)+1, &
            block_writeback_plan%recv_displ(r) + &
            block_writeback_plan%recv_count(r)
          b = block_writeback_plan%recv_block(slot)
          d = loc_id(block_catalog(b)%root_domain+1) + 1
          if (source_rank(b) /= rank .or. d < 1 .or. &
               d > size(grid)) then
             call fail("scalar-restriction boundary route is invalid")
          end if
          do boundary_index = 1, &
               block_writeback_plan%recv_boundary_count(slot)
             source_bdry = block_writeback_plan%recv_boundary_source( &
                  block_writeback_plan%recv_boundary_displ(slot) + &
                  boundary_index)
             source_level = block_writeback_plan%recv_boundary_level( &
                  block_writeback_plan%recv_boundary_displ(slot) + &
                  boundary_index)
             n_node = block_writeback_plan%recv_boundary_nnode( &
                  block_writeback_plan%recv_boundary_displ(slot) + &
                  boundary_index)
             n_scalar = n_node*n_scalar_variable*n_field_level
             call fill_domain_boundary_record( &
                  d,source_bdry,source_level,n_node,scalar_slot,level_slot, &
                  grid_level,capture_direct, &
                  block_scalar_restriction_exchange% &
                  boundary_send_buffer, &
                  BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                  (pos_sample-1)+1)
             pos_sample = pos_sample + n_scalar
          end do
       end do
       if (pos_sample /= block_writeback_plan% &
            boundary_scalar_domain_send_displ(r) + &
            block_writeback_plan% &
            boundary_scalar_domain_send_count(r) + 1) then
          call fail("scalar-restriction boundary packed extent differs")
       end if
    end do

    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       if (source_rank(b) /= rank) cycle
       d = loc_id(block_catalog(b)%root_domain+1) + 1
       if (d < 1 .or. d > size(grid)) then
          call fail("retained scalar-restriction Domain is invalid")
       end if
       n_boundary_node = size( &
            block_scalar_tendency(local_index)%bdry)/ &
            (BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
            n_scalar_variable*n_field_level)
       node_start = 0
       do boundary_index = 1,local_block_boundary_count(b)
          call get_local_block_boundary_source( &
               b,boundary_index,source_bdry,slot,n_node,source_level)
          call fill_retained_boundary_record( &
               d,source_bdry,source_level,n_node,scalar_slot,level_slot, &
               grid_level,capture_direct,local_index, &
               n_boundary_node,node_start)
          node_start = node_start + n_node
       end do
       if (node_start /= n_boundary_node) then
          call fail("retained scalar-restriction boundary extent differs")
       end if
    end do

  contains

    subroutine fill_domain_boundary_record ( &
         d,source_bdry,boundary_level,n_node,scalar_slot,level_slot,grid_level, &
         capture_direct,buffer,data_start)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: source_bdry
      integer, intent(in) :: boundary_level
      integer, intent(in) :: n_node
      integer, intent(in) :: scalar_slot
      integer, intent(in) :: level_slot
      integer, intent(in) :: grid_level
      logical, intent(in) :: capture_direct
      real(dp), intent(inout) :: buffer(:)
      integer, intent(in) :: data_start

      integer :: id
      integer :: node
      integer :: record_start
      integer :: sample

      if (boundary_level /= grid_level) return
      id = grid(d)%bdry_patch%elts(source_bdry+1)%elts_start
      do node = 0,n_node-1
         sample = ((scalar_slot-1)*n_field_level + level_slot-1)* &
              n_node + node
         record_start = data_start + &
              BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample
         call fill_boundary_node( &
              d,id+node,capture_direct,buffer(record_start: &
              record_start+BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1))
      end do

    end subroutine fill_domain_boundary_record


    subroutine fill_retained_boundary_record ( &
         d,source_bdry,boundary_level,n_node,scalar_slot,level_slot,grid_level, &
         capture_direct,local_index,n_boundary_node,node_start)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: source_bdry
      integer, intent(in) :: boundary_level
      integer, intent(in) :: n_node
      integer, intent(in) :: scalar_slot
      integer, intent(in) :: level_slot
      integer, intent(in) :: grid_level
      logical, intent(in) :: capture_direct
      integer, intent(in) :: local_index
      integer, intent(in) :: n_boundary_node
      integer, intent(in) :: node_start

      integer :: data_start
      integer :: id
      integer :: node
      integer :: sample

      if (boundary_level /= grid_level) return
      id = grid(d)%bdry_patch%elts(source_bdry+1)%elts_start
      do node = 0,n_node-1
         sample = ((scalar_slot-1)*n_field_level + level_slot-1)* &
              n_boundary_node + node_start + node
         data_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + 1
         call fill_boundary_node( &
              d,id+node,capture_direct, &
              block_scalar_tendency(local_index)%bdry(data_start: &
              data_start+BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1))
      end do

    end subroutine fill_retained_boundary_record


    subroutine fill_boundary_node (d,id,capture_direct,value)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: id
      logical, intent(in) :: capture_direct
      real(dp), intent(inout) :: &
           value(BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT)

      if (capture_dscalar) then
         value(BLOCK_SCALAR_REFERENCE_DSCALAR_INDEX) = &
              domain_tendency(scalar_id,field_level)%data(d)%elts(id+1)
      else if (capture_direct) then
         value(BLOCK_SCALAR_DIRECT_FLUX_START: &
              BLOCK_SCALAR_DIRECT_FLUX_START+EDGE-1) = &
              horiz_flux(scalar_id)%data(d)%elts( &
              EDGE*id+RT+1:EDGE*id+UP+1)
      else
         value(BLOCK_SCALAR_AREA_INDEX) = &
              grid(d)%areas%elts(id+1)%hex_inv
         value(BLOCK_SCALAR_ACTIVE_INDEX) = merge( &
              1.0_dp,0.0_dp,grid(d)%mask_n%elts(id+1) >= TRSK)
         value(BLOCK_SCALAR_WAVELET_MASK_INDEX) = &
              real(grid(d)%mask_n%elts(id+1),dp)
         value(BLOCK_VECTOR_WAVELET_WEIGHT_START: &
              BLOCK_VECTOR_WAVELET_WEIGHT_START+8) = &
              real(grid(d)%I_u_wgt%elts(id+1)%enc,dp)
         value(BLOCK_SCALAR_RESTRICTED_FLUX_START: &
              BLOCK_SCALAR_RESTRICTED_FLUX_START+EDGE-1) = &
              horiz_flux(scalar_id)%data(d)%elts( &
              EDGE*id+RT+1:EDGE*id+UP+1)
         value(BLOCK_SCALAR_EDGE_MASK_START: &
              BLOCK_SCALAR_EDGE_MASK_START+EDGE-1) = real( &
              grid(d)%mask_e%elts(EDGE*id+RT+1:EDGE*id+UP+1),dp)
         value(BLOCK_SCALAR_RESTRICTION_WEIGHT_START: &
              BLOCK_SCALAR_RESTRICTION_WEIGHT_START+EDGE-1) = &
              grid(d)%R_F_wgt%elts(id+1)%enc
         value(BLOCK_SCALAR_OVERLAP_START: &
              BLOCK_SCALAR_OVERLAP_START+3) = &
              grid(d)%overl_areas%elts(id+1)%a
         value(BLOCK_SCALAR_OVERLAP_START+4: &
              BLOCK_SCALAR_OVERLAP_START+5) = &
              grid(d)%overl_areas%elts(id+1)%split
      end if
      value(BLOCK_SCALAR_SOURCE_INDEX) = real(id,dp)

    end subroutine fill_boundary_node


  end subroutine capture_block_scalar_restriction_boundaries


  subroutine finalize_block_scalar_divergence_capture
    ! Transfer the pre-restriction native-flux shadow and the authoritative
    ! restricted divergence stencil once, then make every final-owner input
    ! ready for the rejected block-native kernel.

    implicit none

    integer :: b
    integer :: data_count
    integer :: data_start
    integer :: ierr
    integer :: local_index
    integer :: r
    integer :: slot

    integer(int64) :: allocation_before

    if (.not. block_scalar_divergence_plan%active) then
       call fail("scalar-divergence finalize without active capture")
    end if
    call complete_uncaptured_scalar_divergence_coverage
    if (.not. all(block_scalar_divergence_plan%recv_covered)) then
       call fail("scalar-divergence Domain capture is incomplete")
    end if

    allocation_before = block_scalar_divergence_plan%allocations
    call MPI_Alltoallv( &
         block_scalar_divergence_plan%recv_buffer, &
         block_scalar_divergence_plan%recv_count, &
         block_scalar_divergence_plan%recv_displ, &
         MPI_DOUBLE_PRECISION, &
         block_scalar_divergence_plan%send_buffer, &
         block_scalar_divergence_plan%send_count, &
         block_scalar_divergence_plan%send_displ, &
         MPI_DOUBLE_PRECISION,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv scalar-divergence input")

    do r = 1,n_process
       data_start = block_scalar_divergence_plan%send_displ(r) + 1
       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)
          b = block_writeback_plan%send_block(slot)
          local_index = catalog_local_block(b)
          if (local_index < 1 .or. &
               local_index > size(block_scalar_tendency)) then
             call fail("scalar-divergence received block is invalid")
          end if
          data_count = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
               block_writeback_plan%send_scalar_nvalue(slot)
          if (data_start < 1 .or. data_start+data_count-1 > &
               size(block_scalar_divergence_plan%send_buffer) .or. &
               data_count /= &
               size(block_scalar_tendency(local_index)%patch)) then
             call fail("scalar-divergence received extent is invalid")
          end if
          block_scalar_tendency(local_index)%patch = &
               block_scalar_divergence_plan%send_buffer( &
               data_start:data_start+data_count-1)
          block_scalar_tendency(local_index)%covered = .true.
          data_start = data_start + data_count
       end do
       if (data_start /= block_scalar_divergence_plan%send_displ(r) + &
            block_scalar_divergence_plan%send_count(r) + 1) then
          call fail("scalar-divergence receive extent mismatch")
       end if
    end do

    call finalize_block_scalar_restriction_boundaries

    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       if (.not. all(block_scalar_tendency(local_index)%covered)) then
          call fail("scalar-divergence block coverage is incomplete")
       end if
       block_scalar_tendency(local_index)%installed_patch_count = &
            local_block_patch_count(b)
       block_scalar_tendency(local_index)%ready = .true.
    end do
    if (block_scalar_divergence_plan%allocations /= allocation_before) then
       call fail("scalar-divergence finalize reallocated transport")
    end if
    block_scalar_divergence_plan%active = .false.
    block_scalar_divergence_plan%ready = .true.

  end subroutine finalize_block_scalar_divergence_capture


  subroutine finalize_block_scalar_restriction_boundaries
    ! Complete the one-shot Domain-owner to final-block transfer of compact
    ! boundary restriction records. Retained records were installed directly
    ! during level capture and are left untouched.

    implicit none

    integer :: b
    integer :: boundary_index
    integer :: buffer_start
    integer :: data_start
    integer :: ierr
    integer :: level_slot
    integer :: local_index
    integer :: n_boundary_node
    integer :: n_field_level
    integer :: n_node
    integer :: n_scalar_variable
    integer :: node
    integer :: node_start
    integer :: pos_sample
    integer :: r
    integer :: sample
    integer :: scalar_slot
    integer :: slot

    call MPI_Alltoallv( &
         block_scalar_restriction_exchange%boundary_send_buffer, &
         block_scalar_restriction_exchange%boundary_send_count, &
         block_scalar_restriction_exchange%boundary_send_displ, &
         MPI_DOUBLE_PRECISION, &
         block_scalar_restriction_exchange%boundary_recv_buffer, &
         block_scalar_restriction_exchange%boundary_recv_count, &
         block_scalar_restriction_exchange%boundary_recv_displ, &
         MPI_DOUBLE_PRECISION,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv scalar-restriction boundaries")

    call get_block_field_layout_counts( &
         n_scalar_variable,n_field_level)
    do r = 1,n_process
       pos_sample = block_writeback_plan% &
            boundary_scalar_block_recv_displ(r) + 1
       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)
          b = block_writeback_plan%send_block(slot)
          local_index = catalog_local_block(b)
          if (local_index < 1 .or. &
               local_index > size(block_scalar_tendency)) then
             call fail("scalar-restriction boundary block is invalid")
          end if
          n_boundary_node = size( &
               block_scalar_tendency(local_index)%bdry)/ &
               (BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
               n_scalar_variable*n_field_level)
          node_start = 0
          do boundary_index = 1,local_block_boundary_count(b)
             n_node = local_block_scalar_family_boundary_nvalue( &
                  b,boundary_index)/(n_scalar_variable*n_field_level)
             do scalar_slot = 1,n_scalar_variable
                do level_slot = 1,n_field_level
                   do node = 0,n_node-1
                      sample = ((scalar_slot-1)*n_field_level + &
                           level_slot-1)*n_boundary_node + &
                           node_start + node
                      data_start = &
                           BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + 1
                      buffer_start = &
                           BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                           (pos_sample-1 + &
                           ((scalar_slot-1)*n_field_level + &
                           level_slot-1)*n_node + node) + 1
                      block_scalar_tendency(local_index)%bdry( &
                           data_start:data_start+ &
                           BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1) = &
                           block_scalar_restriction_exchange% &
                           boundary_recv_buffer(buffer_start: &
                           buffer_start+ &
                           BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1)
                   end do
                end do
             end do
             pos_sample = pos_sample + &
                  n_node*n_scalar_variable*n_field_level
             node_start = node_start + n_node
          end do
          if (node_start /= n_boundary_node) then
             call fail("scalar-restriction boundary install differs")
          end if
       end do
       if (pos_sample /= block_writeback_plan% &
            boundary_scalar_block_recv_displ(r) + &
            block_writeback_plan% &
            boundary_scalar_block_recv_count(r) + 1) then
          call fail("scalar-restriction boundary receive differs")
       end if
    end do

  contains

    subroutine get_block_field_layout_counts ( &
         n_scalar_variable,n_field_level)

      implicit none

      integer, intent(out) :: n_scalar_variable
      integer, intent(out) :: n_field_level

      integer :: first_field_level
      integer :: mult_scalar
      integer :: mult_vector
      integer :: v_scalar
      integer :: v_vector

      call get_block_field_layout( &
           v_scalar,n_scalar_variable,v_vector,first_field_level, &
           n_field_level,mult_scalar,mult_vector)
      if (v_scalar < 1 .or. v_vector < 1 .or. &
           first_field_level > zlevels .or. mult_scalar /= 1 .or. &
           mult_vector /= EDGE .or. n_scalar_variable < 1 .or. &
           n_field_level < 1) then
         call fail("scalar-restriction boundary field layout is invalid")
      end if

    end subroutine get_block_field_layout_counts

  end subroutine finalize_block_scalar_restriction_boundaries


  subroutine exchange_block_scalar_restriction_ghosts
    ! Refresh every inter-block restriction ghost from the current native
    ! hierarchy flux and its immutable geometry. One persistent all-to-all is
    ! issued per bottom-up horizontal level; no per-cell communication occurs.

    implicit none

    integer, parameter :: REQUEST_SIZE = 4

    integer :: destination
    integer :: destination_ghost
    integer :: i
    integer :: ierr
    integer :: local_index
    integer :: pos
    integer :: r
    integer :: request
    integer :: source
    integer :: source_patch

    if (.not. block_scalar_restriction_exchange%ready) then
       call fail("scalar-restriction ghost exchange is not ready")
    end if
    block_scalar_restriction_exchange%ghost_send_buffer = &
         BLOCK_GHOST_POISON
    block_scalar_restriction_exchange%ghost_recv_buffer = &
         BLOCK_GHOST_POISON

    do request = 1,ghost_exchange_plan%n_request
       if (ghost_exchange_plan%source_owner(request) /= rank) cycle
       source = ghost_exchange_plan%source_block(request)
       source_patch = &
            ghost_exchange_plan%source_local_patch(request)
       destination = ghost_exchange_plan%destination_block(request)
       destination_ghost = &
            ghost_exchange_plan%destination_ghost(request)
       call install_local_source( &
            source,source_patch,destination,destination_ghost)
    end do

    do r = 1,n_process
       do i = 0,ghost_exchange_plan%recv_record_count(r)-1
          pos = REQUEST_SIZE*( &
               ghost_exchange_plan%recv_record_displ(r)+i)
          source = ghost_exchange_plan%recv_data(pos+1)
          source_patch = ghost_exchange_plan%recv_data(pos+2)
          local_index = catalog_local_block(source)
          if (local_index < 1 .or. &
               local_index > size(block_scalar_tendency)) then
             call fail("scalar-restriction ghost source is invalid")
          end if
          call pack_patch_record( &
               local_index,source_patch, &
               block_scalar_restriction_exchange%ghost_send_buffer, &
               BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
               ghost_exchange_plan%scalar_n_value* &
               (ghost_exchange_plan%recv_record_displ(r)+i)+1)
       end do
    end do

    call MPI_Alltoallv( &
         block_scalar_restriction_exchange%ghost_send_buffer, &
         block_scalar_restriction_exchange%ghost_send_count, &
         block_scalar_restriction_exchange%ghost_send_displ, &
         MPI_DOUBLE_PRECISION, &
         block_scalar_restriction_exchange%ghost_recv_buffer, &
         block_scalar_restriction_exchange%ghost_recv_count, &
         block_scalar_restriction_exchange%ghost_recv_displ, &
         MPI_DOUBLE_PRECISION,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv scalar-restriction ghosts")

    do r = 1,n_process
       do i = 0,ghost_exchange_plan%send_record_count(r)-1
          request = ghost_exchange_plan%request_index( &
               ghost_exchange_plan%send_record_displ(r)+i+1)
          destination = &
               ghost_exchange_plan%destination_block(request)
          destination_ghost = &
               ghost_exchange_plan%destination_ghost(request)
          call install_buffer_ghost( &
               destination,destination_ghost, &
               block_scalar_restriction_exchange%ghost_recv_buffer, &
               BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
               ghost_exchange_plan%scalar_n_value* &
               (ghost_exchange_plan%send_record_displ(r)+i)+1)
       end do
    end do
    block_scalar_restriction_exchange%exchanges = &
         block_scalar_restriction_exchange%exchanges + 1_int64

  contains

    subroutine install_local_source ( &
         source,source_patch,destination,destination_ghost)

      implicit none

      integer, intent(in) :: source
      integer, intent(in) :: source_patch
      integer, intent(in) :: destination
      integer, intent(in) :: destination_ghost

      integer :: source_index

      source_index = catalog_local_block(source)
      if (source_index < 1 .or. &
           source_index > size(block_scalar_tendency)) then
         call fail("local scalar-restriction source is invalid")
      end if
      call pack_patch_record( &
           source_index,source_patch, &
           block_scalar_restriction_exchange%ghost_patch_buffer,1)
      call install_buffer_ghost( &
           destination,destination_ghost, &
           block_scalar_restriction_exchange%ghost_patch_buffer,1)

    end subroutine install_local_source


    subroutine pack_patch_record ( &
         local_index,source_patch,buffer,data_start)

      implicit none

      integer, intent(in) :: local_index
      integer, intent(in) :: source_patch
      real(dp), intent(inout) :: buffer(:)
      integer, intent(in) :: data_start

      integer :: data_count
      integer :: source_start

      data_count = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
           ghost_exchange_plan%scalar_n_value
      source_start = source_patch*data_count + 1
      if (source_patch < 0 .or. source_start < 1 .or. &
           source_start+data_count-1 > &
           size(block_scalar_tendency(local_index)%patch) .or. &
           data_start < 1 .or. data_start+data_count-1 > &
           size(buffer)) then
         call fail("scalar-restriction ghost pack extent is invalid")
      end if
      buffer(data_start:data_start+data_count-1) = &
           block_scalar_tendency(local_index)%patch( &
           source_start:source_start+data_count-1)

    end subroutine pack_patch_record


    subroutine install_buffer_ghost ( &
         destination,destination_ghost,buffer,data_start)

      implicit none

      integer, intent(in) :: destination
      integer, intent(in) :: destination_ghost
      real(dp), intent(in) :: buffer(:)
      integer, intent(in) :: data_start

      integer :: destination_index
      integer :: destination_start
      integer :: field_sample
      integer :: n_ghost
      integer :: q
      integer :: sample

      destination_index = catalog_local_block(destination)
      if (destination_index < 1 .or. &
           destination_index > size(block_scalar_tendency)) then
         call fail("scalar-restriction ghost destination is invalid")
      end if
      n_ghost = local_block_ghost_count(destination)
      if (destination_ghost < 1 .or. destination_ghost > n_ghost) then
         call fail("scalar-restriction destination ghost is invalid")
      end if
      do field_sample = 0, &
           ghost_exchange_plan%scalar_n_value/PATCH_SIZE**2-1
         do q = 0,PATCH_SIZE**2-1
            sample = field_sample*n_ghost*PATCH_SIZE**2 + &
                 (destination_ghost-1)*PATCH_SIZE**2 + q
            destination_start = &
                 BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + 1
            block_scalar_tendency(destination_index)%ghost( &
                 destination_start:destination_start+ &
                 BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1) = &
                 buffer(data_start+ &
                 BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                 (field_sample*PATCH_SIZE**2+q): &
                 data_start+BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                 (field_sample*PATCH_SIZE**2+q+1)-1)
         end do
      end do

    end subroutine install_buffer_ghost

  end subroutine exchange_block_scalar_restriction_ghosts


  subroutine evaluate_candidate_block_scalar_restriction
    ! Replay cpt_or_restr_flux bottom-up in compact block storage. Boundary
    ! values are immutable compatibility inputs; patch interiors and every
    ! inter-block ghost refresh are native block products.

    implicit none

    type(Block_Scalar_Restriction_Context) :: statistics

    integer :: ierr
    integer :: l

    integer(int64) :: accumulator_allocation_before
    integer(int64) :: count_global(7)
    integer(int64) :: count_local(7)

    logical :: accumulator_ready

    if (.not. block_scalar_restriction_exchange%ready) then
       call fail("block-native scalar restriction exchange is not ready")
    end if
    call initialize_scalar_restriction_boundary_flux
    ! Establish a native finest-level divergence before it is consumed by the
    ! first coarse restriction. The exchange supplies neighboring edge flux.
    call exchange_block_scalar_restriction_ghosts
    statistics%target_level = level_end
    call apply_local_block_field_consumer( &
         recompute_block_scalar_divergence_level,statistics)
    do l = level_end-1,level_start,-1
       ! Propagate the newly recomputed finer dscalar before restricting l.
       call exchange_block_scalar_restriction_ghosts
       statistics%target_level = l
       call apply_local_block_field_consumer( &
            restrict_block_scalar_flux_level,statistics)
       ! Restriction changed the positive-edge flux at l. Refresh its ghost
       ! stencil and immediately form the dscalar required by level l-1.
       call exchange_block_scalar_restriction_ghosts
       call apply_local_block_field_consumer( &
            recompute_block_scalar_divergence_level,statistics)
    end do
    statistics%target_level = -1
    call apply_local_block_field_consumer( &
         compare_block_scalar_restricted_flux,statistics)
    call apply_local_block_field_consumer( &
         compare_block_scalar_restricted_divergence,statistics)
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (.not. accumulator_ready) then
       call fail("native scalar-divergence activation register is not ready")
    end if
    accumulator_allocation_before = &
         local_block_tendency_accumulator_allocation_count()
    call apply_local_block_field_consumer( &
         install_block_scalar_restricted_divergence,statistics)
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (.not. accumulator_ready .or. &
         local_block_tendency_accumulator_allocation_count() /= &
         accumulator_allocation_before) then
       call fail("native scalar-divergence activation changed register state")
    end if

    count_local = [statistics%parent_patch_count, &
         statistics%restricted_edge_count, &
         statistics%compared_edge_count, &
         statistics%divergence_replay_count, &
         statistics%divergence_sample_count, &
         statistics%divergence_compared_count, &
         statistics%divergence_activated_count]
    call MPI_Allreduce( &
         count_local,count_global,size(count_local),MPI_INTEGER8, &
         MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce block scalar restriction")
    if (count_global(1) < 1_int64 .or. &
         count_global(2) < 1_int64 .or. &
         count_global(3) < 1_int64 .or. &
         count_global(4) < 1_int64 .or. &
         count_global(5) < 1_int64 .or. &
         count_global(6) < 1_int64 .or. &
         count_global(7) < 1_int64) then
       call fail("block-native scalar restriction coverage is empty")
    end if
    if (count_global(4) /= count_global(5)) then
       call fail("block-native scalar divergence replay coverage differs")
    end if

  end subroutine evaluate_candidate_block_scalar_restriction


  subroutine initialize_scalar_restriction_boundary_flux
    ! Physical-boundary records are immutable compatibility inputs. Seed the
    ! native positive-edge flux and dscalar slots from their independently
    ! captured Domain references before the bottom-up restriction replay.

    implicit none

    integer :: b
    integer :: data_start
    integer :: sample

    do b = 1,size(block_scalar_tendency)
       if (.not. block_scalar_tendency(b)%ready) then
          call fail("scalar-restriction boundary source is stale")
       end if
       if (mod(size(block_scalar_tendency(b)%bdry), &
            BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT) /= 0) then
          call fail("scalar-restriction boundary extent is invalid")
       end if
       do sample = 0,size(block_scalar_tendency(b)%bdry)/ &
            BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1
          data_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + 1
          block_scalar_tendency(b)%bdry( &
               data_start+BLOCK_SCALAR_DIRECT_FLUX_START-1: &
               data_start+BLOCK_SCALAR_DIRECT_FLUX_START+EDGE-2) = &
               block_scalar_tendency(b)%bdry( &
               data_start+BLOCK_SCALAR_RESTRICTED_FLUX_START-1: &
               data_start+BLOCK_SCALAR_RESTRICTED_FLUX_START+EDGE-2)
          block_scalar_tendency(b)%bdry( &
               data_start+BLOCK_SCALAR_NATIVE_DSCALAR_INDEX-1) = &
               block_scalar_tendency(b)%bdry( &
               data_start+BLOCK_SCALAR_REFERENCE_DSCALAR_INDEX-1)
       end do
    end do

  end subroutine initialize_scalar_restriction_boundary_flux


  subroutine restrict_block_scalar_flux_level ( &
       catalog_index,block,context)

    implicit none

    integer, intent(in) :: catalog_index
    type(Block_Data), intent(in) :: block
    class(*), intent(inout) :: context

    integer :: c
    integer :: child
    integer :: e
    integer :: i
    integer :: i_chd
    integer :: i_par
    integer :: j
    integer :: j_chd
    integer :: j_par
    integer :: level_slot
    integer :: local_index
    integer :: p
    integer :: scalar_slot

    type(Block_Scalar_Restriction_Cursor) :: cursor

    real(dp) :: edge_mask
    real(dp) :: comparison_tolerance
    real(dp) :: operation_scale
    real(dp) :: reference_value
    real(dp) :: sm_flux(4)
    real(dp) :: value

    local_index = catalog_local_block(catalog_index)
    if (local_index < 1 .or. &
         local_index > size(block_scalar_tendency)) then
       call fail("scalar-restriction block index is invalid")
    end if
    select type (statistics => context)
    type is (Block_Scalar_Restriction_Context)
       do p = 1,size(block%patch)
          if (block%patch(p)%level /= statistics%target_level) cycle
          statistics%parent_patch_count = &
               statistics%parent_patch_count + 1_int64
          do c = 1,N_CHDRN
             child = block%patch(p)%children(c)
             if (child <= 0) cycle
             if (child >= size(block%patch)) then
                call fail("scalar-restriction child patch is invalid")
             end if
             cursor%target_level = statistics%target_level
             cursor%catalog_index = catalog_index
             cursor%block_id = block%id
             cursor%parent_patch = p
             cursor%child_index = c
             cursor%child_patch = child+1
             do scalar_slot = 0,block%n_scalar_variable-1
                cursor%scalar_slot = scalar_slot
                do level_slot = 1,block%n_field_level
                   if (block%field_level+level_slot-1 < 1 .or. &
                        block%field_level+level_slot-1 > zlevels) cycle
                   cursor%level_slot = level_slot
                   cursor%physical_level = &
                        block%field_level+level_slot-1
                   do j = 1,PATCH_SIZE/2
                      j_chd = 2*(j-1)
                      j_par = j-1+chd_offs(2,c)
                      do i = 1,PATCH_SIZE/2
                         i_chd = 2*(i-1)
                         i_par = i-1+chd_offs(1,c)
                         cursor%i_parent = i_par
                         cursor%j_parent = j_par
                         cursor%i_child = i_chd
                         cursor%j_child = j_chd
                         cursor%edge = -1
                         if (max_parent_edge_mask( &
                              block,local_index,p,scalar_slot,level_slot, &
                              i_par,j_par) >= real(RESTRCT,dp)) then
                            sm_flux = interpolate_block_scalar_flux( &
                                 block,local_index,child+1,scalar_slot, &
                                 level_slot,i_chd,j_chd, &
                                 BLOCK_SCALAR_DIRECT_FLUX_START)
                            call validate_scalar_restriction_vector( &
                                 "interpolate_block_scalar_flux", &
                                 sm_flux,cursor)
                         else
                            sm_flux = 0.0_dp
                         end if
                         do e = RT,UP
                            edge_mask = block_scalar_record_value( &
                                 block,local_index,p,scalar_slot, &
                                 level_slot,i_par,j_par, &
                                 BLOCK_SCALAR_EDGE_MASK_START+e)
                            if (edge_mask < real(RESTRCT,dp)) cycle
                            cursor%edge = e
                            value = complete_block_coarse_flux( &
                                 sm_flux,block,local_index,child+1, &
                                 scalar_slot,level_slot,i_par,j_par, &
                                 i_chd,j_chd,e,cursor,operation_scale)
                            call validate_scalar_restriction_value( &
                                 "complete_block_coarse_flux", &
                                 value,cursor)
                            reference_value = block_scalar_record_value( &
                                 block,local_index,p,scalar_slot, &
                                 level_slot,i_par,j_par, &
                                 BLOCK_SCALAR_RESTRICTED_FLUX_START+e)
                            comparison_tolerance = &
                                 scalar_restriction_roundoff_tolerance( &
                                 value,reference_value, &
                                 level_end-cursor%target_level, &
                                 operation_scale)
                            if (abs(value-reference_value) > &
                                 comparison_tolerance) then
                               call report_scalar_restriction_cursor( &
                                    "restricted scalar-flux comparison "// &
                                    "exceeded roundoff bound",cursor)
                               write(error_unit, &
                                    '(a,4(es24.16,1x))') &
                                    "  native, reference, difference, "// &
                                    "allowed = ",value,reference_value, &
                                    abs(value-reference_value), &
                                    comparison_tolerance
                               flush(error_unit)
                               call report_scalar_restriction_components( &
                                    block,local_index,child+1,sm_flux, &
                                    value,reference_value,cursor)
                               call fail( &
                                    "scalar-restriction component mismatch")
                            end if
                            call set_block_patch_scalar_record_value( &
                                 local_index,p,block%n_field_level, &
                                 scalar_slot,level_slot, &
                                 i_par,j_par, &
                                 BLOCK_SCALAR_DIRECT_FLUX_START+e,value)
                            statistics%restricted_edge_count = &
                                 statistics%restricted_edge_count + 1_int64
                         end do
                      end do
                   end do
                end do
             end do
          end do
       end do
    class default
       call fail("scalar-restriction context is invalid")
    end select

  end subroutine restrict_block_scalar_flux_level


  subroutine compare_block_scalar_restricted_flux ( &
       catalog_index,block,context)

    implicit none

    integer, intent(in) :: catalog_index
    type(Block_Data), intent(in) :: block
    class(*), intent(inout) :: context

    integer :: e
    integer :: i
    integer :: j
    integer :: level_slot
    integer :: local_index
    integer :: p
    integer :: scalar_slot

    real(dp) :: native_value
    real(dp) :: reference_value
    real(dp) :: comparison_tolerance
    real(dp) :: edge_mask
    real(dp) :: operation_scale

    local_index = catalog_local_block(catalog_index)
    select type (statistics => context)
    type is (Block_Scalar_Restriction_Context)
       do p = 1,size(block%patch)
          do scalar_slot = 0,block%n_scalar_variable-1
             do level_slot = 1,block%n_field_level
                if (block%field_level+level_slot-1 < 1 .or. &
                     block%field_level+level_slot-1 > zlevels) cycle
                do j = 0,PATCH_SIZE-1
                   do i = 0,PATCH_SIZE-1
                      do e = RT,UP
                         native_value = block_scalar_record_value( &
                              block,local_index,p,scalar_slot,level_slot, &
                              i,j,BLOCK_SCALAR_DIRECT_FLUX_START+e)
                         reference_value = block_scalar_record_value( &
                              block,local_index,p,scalar_slot,level_slot, &
                              i,j,BLOCK_SCALAR_RESTRICTED_FLUX_START+e)
                         comparison_tolerance = &
                              scalar_restriction_roundoff_tolerance( &
                              native_value,reference_value, &
                              level_end-level_start)
                         if (abs(native_value-reference_value) > &
                              comparison_tolerance) then
                            edge_mask = block_scalar_record_value( &
                                 block,local_index,p,scalar_slot, &
                                 level_slot,i,j, &
                                 BLOCK_SCALAR_EDGE_MASK_START+e)
                            if (edge_mask >= real(RESTRCT,dp)) then
                               operation_scale = &
                                    scalar_restriction_operation_scale( &
                                    catalog_index,block,local_index,p, &
                                    scalar_slot,level_slot,i,j,e)
                               comparison_tolerance = &
                                    scalar_restriction_roundoff_tolerance( &
                                    native_value,reference_value, &
                                    level_end-level_start,operation_scale)
                            end if
                         end if
                         if (abs(native_value-reference_value) > &
                              comparison_tolerance) then
                            write(6, &
                                 '(a,i0,a,i0,a,i0,a,i0,a,i0)') &
                                 "Rank ",rank, &
                                 ": restricted scalar flux mismatch: block = ", &
                                 catalog_index,", patch = ",p, &
                                 ", i = ",i,", j = ",j
                            write(6,'(a,i0,a,i0,a,i0)') &
                                 "  scalar slot = ",scalar_slot, &
                                 ", level slot = ",level_slot, &
                                 ", edge = ",e
                            write(6, &
                                 '(a,es24.16,a,es24.16,a,es24.16)') &
                                 "  cpt_or_restr_flux value = ", &
                                 reference_value,", block value = ", &
                                 native_value,", absolute difference = ", &
                                 abs(native_value-reference_value)
                            write(6,'(a,es24.16)') &
                                 "  allowed roundoff difference = ", &
                                 comparison_tolerance
                            flush(6)
                            call fail( &
                                 "block-native restricted scalar flux differs")
                         end if
                         statistics%compared_edge_count = &
                              statistics%compared_edge_count + 1_int64
                      end do
                   end do
                end do
             end do
          end do
       end do
    class default
       call fail("scalar-restriction comparison context is invalid")
    end select
  end subroutine compare_block_scalar_restricted_flux


  subroutine recompute_block_scalar_divergence_level ( &
       catalog_index,block,context)
    ! Recompute native dscalar immediately after the native flux at one level
    ! becomes final, so the next coarser restriction consumes that result.

    implicit none

    integer, intent(in) :: catalog_index
    type(Block_Data), intent(in) :: block
    class(*), intent(inout) :: context

    integer :: i
    integer :: j
    integer :: level_slot
    integer :: local_index
    integer :: p
    integer :: scalar_slot

    real(dp) :: native_value

    local_index = catalog_local_block(catalog_index)
    if (local_index < 1 .or. &
         local_index > size(block_scalar_tendency)) then
       call fail("scalar-divergence replay block is invalid")
    end if
    select type (statistics => context)
    type is (Block_Scalar_Restriction_Context)
       do p = 1,size(block%patch)
          if (block%patch(p)%level /= statistics%target_level) cycle
          do scalar_slot = 0,block%n_scalar_variable-1
             do level_slot = 1,block%n_field_level
                if (block%field_level+level_slot-1 < 1 .or. &
                     block%field_level+level_slot-1 > zlevels) cycle
                do j = 0,PATCH_SIZE-1
                   do i = 0,PATCH_SIZE-1
                      native_value = block_scalar_flux_divergence( &
                           block,local_index,p,scalar_slot,level_slot, &
                           i,j,BLOCK_SCALAR_DIRECT_FLUX_START)
                      call set_block_patch_scalar_record_value( &
                           local_index,p,block%n_field_level, &
                           scalar_slot,level_slot,i,j, &
                           BLOCK_SCALAR_NATIVE_DSCALAR_INDEX,native_value)
                      statistics%divergence_replay_count = &
                           statistics%divergence_replay_count + 1_int64
                   end do
                end do
             end do
          end do
       end do
    class default
       call fail("scalar-divergence replay context is invalid")
    end select

  end subroutine recompute_block_scalar_divergence_level


  real(dp) function block_scalar_flux_divergence ( &
       block,local_index,p,scalar_slot,level_slot,i,j,flux_start, &
       edge_flux,inverse_area,operation_scale) result(value)
    ! Apply the ops_mod::scalar_trend six-edge orientation and node mask to
    ! either the native or independently captured positive-edge flux.

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: flux_start
    real(dp), optional, intent(out) :: &
         edge_flux(BLOCK_SCALAR_FLUX_COUNT)
    real(dp), optional, intent(out) :: inverse_area
    real(dp), optional, intent(out) :: operation_scale

    real(dp) :: active
    real(dp) :: area
    real(dp) :: flux(BLOCK_SCALAR_FLUX_COUNT)

    if (flux_start /= BLOCK_SCALAR_DIRECT_FLUX_START .and. &
         flux_start /= BLOCK_SCALAR_RESTRICTED_FLUX_START) then
       call fail("scalar-divergence flux mode is invalid")
    end if
    flux(1) = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot, &
         i,j,flux_start+RT)
    flux(2) = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot, &
         i-1,j,flux_start+RT)
    flux(3) = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot, &
         i-1,j-1,flux_start+DG)
    flux(4) = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot, &
         i,j,flux_start+DG)
    flux(5) = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot, &
         i,j,flux_start+UP)
    flux(6) = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot, &
         i,j-1,flux_start+UP)
    area = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot, &
         i,j,BLOCK_SCALAR_AREA_INDEX)
    active = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot, &
         i,j,BLOCK_SCALAR_ACTIVE_INDEX)

    value = 0.0_dp
    if (active > 0.5_dp) then
       value = -(flux(1)-flux(2)+flux(3)-flux(4) + &
            flux(5)-flux(6))*area
    end if
    if (present(edge_flux)) edge_flux = flux
    if (present(inverse_area)) inverse_area = area
    if (present(operation_scale)) then
       operation_scale = abs(area)*sum(abs(flux))
    end if

  end function block_scalar_flux_divergence


  subroutine compare_block_scalar_restricted_divergence ( &
       catalog_index,block,context)
    ! Evaluate scalar_trend from the retained native restricted positive-edge
    ! flux. The independently captured Domain dq remains authoritative; the
    ! native result is retained only after the comparison succeeds.

    implicit none

    integer, intent(in) :: catalog_index
    type(Block_Data), intent(in) :: block
    class(*), intent(inout) :: context

    integer :: i
    integer :: j
    integer :: level_slot
    integer :: local_index
    integer :: n_restriction_level
    integer :: p
    integer :: scalar_slot

    real(dp) :: area
    real(dp) :: comparison_tolerance
    real(dp) :: flux(BLOCK_SCALAR_FLUX_COUNT)
    real(dp) :: native_operation_scale
    real(dp) :: native_value
    real(dp) :: operation_scale
    real(dp) :: reference_flux(BLOCK_SCALAR_FLUX_COUNT)
    real(dp) :: reference_operation_scale
    real(dp) :: reference_recomputed
    real(dp) :: reference_tolerance
    real(dp) :: reference_value
    real(dp) :: stored_native_value
    real(dp) :: transported_difference_bound

    local_index = catalog_local_block(catalog_index)
    if (local_index < 1 .or. &
         local_index > size(block_scalar_tendency)) then
       call fail("scalar-divergence comparison block is invalid")
    end if
    select type (statistics => context)
    type is (Block_Scalar_Restriction_Context)
       do p = 1,size(block%patch)
          if (block%patch(p)%level < level_start .or. &
               block%patch(p)%level > level_end) cycle
          n_restriction_level = max( &
               1,level_end-block%patch(p)%level+1)
          do scalar_slot = 0,block%n_scalar_variable-1
             do level_slot = 1,block%n_field_level
                if (block%field_level+level_slot-1 < 1 .or. &
                     block%field_level+level_slot-1 > zlevels) cycle
                do j = 0,PATCH_SIZE-1
                   do i = 0,PATCH_SIZE-1
                      native_value = block_scalar_flux_divergence( &
                           block,local_index,p,scalar_slot,level_slot, &
                           i,j,BLOCK_SCALAR_DIRECT_FLUX_START, &
                           flux,area,native_operation_scale)
                      reference_recomputed = &
                           block_scalar_flux_divergence( &
                           block,local_index,p,scalar_slot,level_slot, &
                           i,j,BLOCK_SCALAR_RESTRICTED_FLUX_START, &
                           edge_flux=reference_flux, &
                           operation_scale=reference_operation_scale)
                      stored_native_value = block_scalar_record_value( &
                           block,local_index,p,scalar_slot,level_slot, &
                           i,j,BLOCK_SCALAR_NATIVE_DSCALAR_INDEX)
                      if (abs(stored_native_value-native_value) > 0.0_dp) then
                         write(error_unit,'(/,a,i0,a)') &
                              "Rank ",rank, &
                              ": replayed scalar divergence changed"
                         write(error_unit,'(a,i0,a,i0,a,i0)') &
                              "  catalog block = ",catalog_index, &
                              ", block id = ",block%id,", patch = ",p
                         write(error_unit,'(a,i0,a,i0,a,i0)') &
                              "  patch level = ",block%patch(p)%level, &
                              ", i = ",i,", j = ",j
                         write(error_unit,'(a,i0,a,i0)') &
                              "  scalar slot = ",scalar_slot, &
                              ", field-level slot = ",level_slot
                         write(error_unit,'(a,3(es24.16,1x))') &
                              "  stored, recomputed, difference = ", &
                              stored_native_value,native_value, &
                              abs(stored_native_value-native_value)
                         flush(error_unit)
                         call fail( &
                              "native scalar-divergence replay is not stable")
                      end if
                      reference_value = block_scalar_record_value( &
                           block,local_index,p,scalar_slot,level_slot, &
                           i,j,BLOCK_SCALAR_REFERENCE_DSCALAR_INDEX)
                      operation_scale = max( &
                           native_operation_scale, &
                           reference_operation_scale)
                      reference_tolerance = &
                           scalar_restriction_roundoff_tolerance( &
                           reference_recomputed,reference_value, &
                           1,operation_scale)
                      if (abs(reference_recomputed-reference_value) > &
                           reference_tolerance) then
                         write(error_unit,'(/,a,i0,a)') &
                              "Rank ",rank, &
                              ": reference scalar divergence mismatch"
                         write(error_unit,'(a,i0,a,i0,a,i0)') &
                              "  catalog block = ",catalog_index, &
                              ", block id = ",block%id,", patch = ",p
                         write(error_unit,'(a,i0,a,i0,a,i0)') &
                              "  patch level = ",block%patch(p)%level, &
                              ", i = ",i,", j = ",j
                         write(error_unit,'(a,i0,a,i0)') &
                              "  scalar slot = ",scalar_slot, &
                              ", field-level slot = ",level_slot
                         write(error_unit,'(a,6(es24.16,1x))') &
                              "  reference edge flux = ",reference_flux
                         write(error_unit,'(a,4(es24.16,1x))') &
                              "  recomputed, Domain, difference, allowed = ", &
                              reference_recomputed,reference_value, &
                              abs(reference_recomputed-reference_value), &
                              reference_tolerance
                         flush(error_unit)
                         call fail( &
                              "captured Domain scalar divergence differs")
                      end if
                      transported_difference_bound = &
                           abs(area)*sum(abs(flux-reference_flux))
                      comparison_tolerance = &
                           transported_difference_bound + &
                           scalar_restriction_roundoff_tolerance( &
                           native_value,reference_value, &
                           n_restriction_level,operation_scale)
                      if (abs(native_value-reference_value) > &
                           comparison_tolerance) then
                         write(error_unit,'(/,a,i0,a)') &
                              "Rank ",rank, &
                              ": restricted scalar divergence mismatch"
                         write(error_unit,'(a,i0,a,i0,a,i0)') &
                              "  catalog block = ",catalog_index, &
                              ", block id = ",block%id,", patch = ",p
                         write(error_unit,'(a,i0,a,i0,a,i0)') &
                              "  patch level = ",block%patch(p)%level, &
                              ", i = ",i,", j = ",j
                         write(error_unit,'(a,i0,a,i0)') &
                              "  scalar slot = ",scalar_slot, &
                              ", field-level slot = ",level_slot
                         write(error_unit,'(a,6(es24.16,1x))') &
                              "  native edge flux = ",flux
                         write(error_unit,'(a,6(es24.16,1x))') &
                              "  reference edge flux = ",reference_flux
                         write(error_unit,'(a,3(es24.16,1x))') &
                              "  inverse area, operation scale, transported bound = ", &
                              area,operation_scale, &
                              transported_difference_bound
                         write(error_unit,'(a,4(es24.16,1x))') &
                              "  native, Domain, difference, allowed = ", &
                              native_value,reference_value, &
                              abs(native_value-reference_value), &
                              comparison_tolerance
                         flush(error_unit)
                         call fail( &
                              "block-native restricted scalar divergence differs")
                      end if
                      statistics%divergence_sample_count = &
                           statistics%divergence_sample_count + 1_int64
                      statistics%divergence_compared_count = &
                           statistics%divergence_compared_count + 1_int64
                   end do
                end do
             end do
          end do
       end do
    class default
       call fail("scalar-divergence comparison context is invalid")
    end select

  end subroutine compare_block_scalar_restricted_divergence


  subroutine install_block_scalar_restricted_divergence ( &
       catalog_index,block,context)
    ! Replace only the scalar component of the retained RK tendency with the
    ! validated native restricted-flux divergence. The vector component and
    ! all transaction state remain unchanged.

    implicit none

    integer, intent(in) :: catalog_index
    type(Block_Data), intent(in) :: block
    class(*), intent(inout) :: context

    integer :: i
    integer :: j
    integer :: level_slot
    integer :: local_index
    integer :: p
    integer :: pos
    integer :: scalar_slot

    local_index = catalog_local_block(catalog_index)
    if (local_index < 1 .or. &
         local_index > size(block_scalar_tendency)) then
       call fail("scalar-divergence activation block is invalid")
    end if
    if (block%scalar_mult /= 1 .or. &
         size(ghost_exchange_plan%scalar_patch_buffer) /= &
         block%n_scalar_variable*block%n_field_level*PATCH_SIZE**2) then
       call fail("scalar-divergence activation layout is invalid")
    end if

    select type (statistics => context)
    type is (Block_Scalar_Restriction_Context)
       do p = 1,size(block%patch)
          pos = 1
          do scalar_slot = 0,block%n_scalar_variable-1
             do level_slot = 1,block%n_field_level
                do j = 0,PATCH_SIZE-1
                   do i = 0,PATCH_SIZE-1
                      ghost_exchange_plan%scalar_patch_buffer(pos) = &
                           block_scalar_record_value( &
                           block,local_index,p,scalar_slot,level_slot, &
                           i,j,BLOCK_SCALAR_NATIVE_DSCALAR_INDEX)
                      pos = pos + 1
                   end do
                end do
             end do
          end do
          if (pos /= &
               size(ghost_exchange_plan%scalar_patch_buffer)+1) then
             call fail("scalar-divergence activation extent differs")
          end if
          call set_local_block_tendency_accumulator_scalar_patch_values( &
               catalog_index,p-1, &
               ghost_exchange_plan%scalar_patch_buffer)
          statistics%divergence_activated_count = &
               statistics%divergence_activated_count + &
               int(pos-1,int64)
       end do
    class default
       call fail("scalar-divergence activation context is invalid")
    end select

  end subroutine install_block_scalar_restricted_divergence


  pure real(dp) function scalar_restriction_roundoff_tolerance ( &
       first_value,second_value,n_restriction_level,operation_scale) &
       result(tolerance)
    ! Independently evaluated but algebraically identical restriction
    ! expressions may differ by a few rounding units after optimization.
    ! Roundoff from every completed fine-to-coarse level is propagated into
    ! the next coarser result.

    implicit none

    real(dp), intent(in) :: first_value
    real(dp), intent(in) :: second_value
    integer, intent(in) :: n_restriction_level
    real(dp), optional, intent(in) :: operation_scale

    real(dp) :: comparison_scale

    comparison_scale = max( &
         1.0_dp,abs(first_value),abs(second_value))
    if (present(operation_scale)) then
       comparison_scale = max(comparison_scale,abs(operation_scale))
    end if
    tolerance = 32.0_dp*real(max(1,n_restriction_level),dp)* &
         epsilon(1.0_dp)*comparison_scale

  end function scalar_restriction_roundoff_tolerance


  real(dp) function max_parent_edge_mask ( &
       block,local_index,p,scalar_slot,level_slot,i,j) result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j

    integer :: e

    value = -huge(0.0_dp)
    do e = RT,UP
       value = max(value,block_scalar_record_value( &
            block,local_index,p,scalar_slot,level_slot,i,j, &
            BLOCK_SCALAR_EDGE_MASK_START+e))
    end do

  end function max_parent_edge_mask


  real(dp) function block_scalar_record_value ( &
       block,local_index,p,scalar_slot,level_slot,i,j,record_slot) &
       result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: record_slot

    integer :: data_start
    integer :: node
    integer :: record
    integer :: sample
    integer :: storage_class

    value = 0.0_dp
    data_start = 0
    node = -1
    record = -1
    sample = -1
    storage_class = 0
    call locate_block_scalar_record( &
         block,local_index,p,i,j,storage_class,record,node)
    if (scalar_slot < 0 .or. scalar_slot >= block%n_scalar_variable .or. &
         level_slot < 1 .or. level_slot > block%n_field_level .or. &
         record_slot < 1 .or. &
         record_slot > BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT) then
       call fail("scalar-restriction record field is invalid")
    end if
    select case (storage_class)
    case (STORE_PATCH)
       sample = record*block_writeback_plan%scalar_patch_nvalue + &
            (scalar_slot*block%n_field_level+level_slot-1)* &
            PATCH_SIZE**2 + node
       data_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + 1
       if (data_start+record_slot-1 > &
            size(block_scalar_tendency(local_index)%patch)) then
          call fail("scalar-restriction patch record is invalid")
       end if
       value = block_scalar_tendency(local_index)%patch( &
            data_start+record_slot-1)
    case (STORE_BDRY)
       sample = (scalar_slot*block%n_field_level+level_slot-1)* &
            size(block%bdry_node) + node
       data_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + 1
       if (data_start+record_slot-1 > &
            size(block_scalar_tendency(local_index)%bdry)) then
          call fail("scalar-restriction boundary record is invalid")
       end if
       value = block_scalar_tendency(local_index)%bdry( &
            data_start+record_slot-1)
    case (STORE_GHOST)
       sample = (scalar_slot*block%n_field_level+level_slot-1)* &
            size(block%ghost_node) + node
       data_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + 1
       if (data_start+record_slot-1 > &
            size(block_scalar_tendency(local_index)%ghost)) then
          call fail("scalar-restriction ghost record is invalid")
       end if
       value = block_scalar_tendency(local_index)%ghost( &
            data_start+record_slot-1)
    case default
       call fail("scalar-restriction record storage is invalid")
    end select
    if (.not. ieee_is_finite(value)) then
       call report_record_value("non-finite")
       call fail("scalar-restriction record value is non-finite")
    end if
    if (.not. (abs(value) < BLOCK_RESTRICTION_VALUE_LIMIT)) then
       call report_record_value("poisoned or uninitialized")
       call fail("scalar-restriction record value is poisoned")
    end if

  contains

    subroutine report_record_value (description)

      implicit none

      character(*), intent(in) :: description

      write(error_unit,'(/,a,i0,3a)') &
           "Rank ",rank,": scalar-restriction record is ", &
           trim(description),":"
      write(error_unit,'(a,i0,a,i0,a,i0)') &
           "  block id = ",block%id,", local index = ",local_index, &
           ", patch = ",p
      write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
           "  coordinates = ",i,", ",j,", scalar slot = ", &
           scalar_slot,", level slot = ",level_slot
      write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
           "  storage = ",storage_class,", record = ",record, &
           ", node = ",node,", record slot = ",record_slot
      write(error_unit,'(a,i0,a,es24.16)') &
           "  data index = ",data_start+record_slot-1, &
           ", value = ",value
      flush(error_unit)

    end subroutine report_record_value

  end function block_scalar_record_value


  subroutine set_block_patch_scalar_record_value ( &
       local_index,p,n_field_level,scalar_slot,level_slot,i,j, &
       record_slot,value)

    implicit none

    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: n_field_level
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: record_slot
    real(dp), intent(in) :: value

    integer :: data_start
    integer :: sample

    if (p < 1 .or. &
         p > block_scalar_tendency(local_index)%installed_patch_count .or. &
         n_field_level < 1 .or. scalar_slot < 0 .or. &
         level_slot < 1 .or. level_slot > n_field_level .or. &
         i < 0 .or. i >= PATCH_SIZE .or. &
         j < 0 .or. j >= PATCH_SIZE) then
       call fail("scalar-restriction patch write coordinate is invalid")
    end if
    sample = (p-1)*block_writeback_plan%scalar_patch_nvalue + &
         (scalar_slot*n_field_level+level_slot-1)* &
         PATCH_SIZE**2 + PATCH_SIZE*j+i
    data_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + 1
    if (record_slot < 1 .or. &
         data_start+record_slot-1 > &
         size(block_scalar_tendency(local_index)%patch)) then
       call fail("scalar-restriction patch write record is invalid")
    end if
    block_scalar_tendency(local_index)%patch( &
         data_start+record_slot-1) = value

  end subroutine set_block_patch_scalar_record_value


  subroutine locate_block_scalar_record ( &
       block,local_index,p,i,j,storage_class,record,node)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(out) :: storage_class
    integer, intent(out) :: record
    integer, intent(out) :: node

    integer :: address
    integer :: base_adjustment
    integer :: candidate_start
    integer :: dims(2)
    integer :: local_address
    integer :: r
    integer :: side
    integer :: target_domain
    integer :: target_index
    integer :: target_start

    address = 0
    base_adjustment = 0
    candidate_start = -1
    dims = 0
    local_address = 0
    r = 0
    side = 0
    target_domain = -1
    target_index = -1
    target_start = -1
    storage_class = 0
    record = -1
    node = -1
    if (p < 1 .or. p > size(block%patch)) then
       call fail("scalar-restriction stencil patch is invalid")
    end if
    if (i >= 0 .and. i < PATCH_SIZE .and. &
         j >= 0 .and. j < PATCH_SIZE) then
       storage_class = STORE_PATCH
       record = p-1
       node = PATCH_SIZE*j+i
       return
    end if
    if (i < 0) then
       if (j < 0) then
          side = SOUTHWEST
       else if (j >= PATCH_SIZE) then
          side = NORTHWEST
       else
          side = WEST
       end if
    else if (i >= PATCH_SIZE) then
       if (j >= PATCH_SIZE) then
          side = NORTHEAST
       else if (j < 0) then
          side = SOUTHEAST
       else
          side = EAST
       end if
    else if (j < 0) then
       side = SOUTH
    else
       side = NORTH
    end if

    storage_class = block%stencil(side,p)%storage
    record = block%stencil(side,p)%id
    dims = block%stencil(side,p)%dims
    address = block%stencil(side,p)%offset
    if (any(dims < 1)) then
       call fail("scalar-restriction stencil dimensions are invalid")
    end if
    select case (side)
    case (SOUTHWEST)
       base_adjustment = dims(1)*dims(2)-1
       local_address = (j+dims(2))*dims(1)+i+dims(1)
    case (NORTHWEST)
       base_adjustment = dims(1)-1-PATCH_SIZE*(PATCH_SIZE-1)
       local_address = (j-PATCH_SIZE)*dims(1)+i+dims(1)
    case (WEST)
       base_adjustment = dims(1)-1
       local_address = j*dims(1)+i+dims(1)
    case (NORTHEAST)
       base_adjustment = -(PATCH_SIZE*PATCH_SIZE-1)
       local_address = (j-PATCH_SIZE)*dims(1)+i-PATCH_SIZE
    case (SOUTHEAST)
       base_adjustment = dims(1)*( &
            block%stencil(SOUTH,p)%dims(2)-1)-(PATCH_SIZE-1)
       local_address = (j+dims(2))*dims(1)+i-PATCH_SIZE
    case (EAST)
       base_adjustment = -(PATCH_SIZE-1)
       local_address = j*dims(1)+i-PATCH_SIZE
    case (SOUTH)
       base_adjustment = dims(1)*(dims(2)-1)
       local_address = (j+dims(2))*dims(1)+i
    case (NORTH)
       base_adjustment = -PATCH_SIZE*(PATCH_SIZE-1)
       local_address = (j-PATCH_SIZE)*dims(1)+i
    case default
       call fail("scalar-restriction stencil side is invalid")
    end select
    address = address-base_adjustment+local_address

    select case (storage_class)
    case (STORE_PATCH)
       if (record < 0 .or. record >= size(block%patch)) then
          call fail("scalar-restriction stencil patch record is invalid")
       end if
       target_start = block_patch_source_start( &
            block,local_index,record+1)
       target_domain = block%root_domain
    case (STORE_BDRY)
       if (record < 1 .or. record > size(block%bdry_storage)) then
          call fail("scalar-restriction stencil boundary record is invalid")
       end if
       if (block%bdry_storage(record)%n_node < 1) then
          call fail("scalar-restriction boundary extent is invalid")
       end if
       target_start = block%bdry_storage(record)%elts_start
       target_domain = block%root_domain
    case (STORE_GHOST)
       if (record < 1 .or. record > size(block%ghost_storage)) then
          call fail("scalar-restriction stencil ghost record is invalid")
       end if
       if (block%ghost_storage(record)%n_node /= PATCH_SIZE**2) then
          call fail("scalar-restriction ghost patch extent is invalid")
       end if
       target_start = block%ghost_storage(record)%elts_start
       target_domain = block%ghost_storage(record)%source_domain
    case default
       call fail("scalar-restriction stencil storage is invalid")
    end select
    target_index = target_start+address

    if (target_domain == block%root_domain) then
       do r = 1,size(block%patch)
          candidate_start = block_patch_source_start( &
               block,local_index,r)
          if (target_index < candidate_start .or. &
               target_index >= candidate_start+PATCH_SIZE**2) cycle
          storage_class = STORE_PATCH
          record = r-1
          node = target_index-candidate_start
          return
       end do
       do r = 1,size(block%bdry_storage)
          candidate_start = block%bdry_storage(r)%elts_start
          if (target_index < candidate_start .or. &
               target_index >= candidate_start+ &
               block%bdry_storage(r)%n_node) cycle
          storage_class = STORE_BDRY
          record = r
          node = block%bdry_storage(r)%local_start + &
               target_index-candidate_start
          return
       end do
    end if
    do r = 1,size(block%ghost_storage)
       if (block%ghost_storage(r)%source_domain /= target_domain) cycle
       candidate_start = block%ghost_storage(r)%elts_start
       if (target_index < candidate_start .or. &
            target_index >= candidate_start+ &
            block%ghost_storage(r)%n_node) cycle
       storage_class = STORE_GHOST
       record = r
       node = block%ghost_storage(r)%local_start + &
            target_index-candidate_start
       return
    end do

    write(error_unit,'(a,i0,a,i0,a,i0,a,i0,a,i0)') &
         "Rank ",rank, &
         ": unresolved scalar-restriction source: block = ",block%id, &
         ", patch = ",p,", i = ",i,", j = ",j
    write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
         "  side = ",side,", initial storage = ",storage_class, &
         ", initial record = ",record,", offset = ", &
         block%stencil(side,p)%offset
    write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
         "  base adjustment = ",base_adjustment, &
         ", local address = ",local_address, &
         ", target domain = ",target_domain, &
         ", target index = ",target_index
    flush(error_unit)
    call fail("scalar-restriction source index is unresolved")

  end subroutine locate_block_scalar_record


  integer function block_patch_source_start ( &
       block,local_index,p) result(source_start)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p

    integer :: data_index
    integer :: level_slot
    integer :: sample

    real(dp) :: source_value

    source_start = -1
    if (p < 1 .or. p > size(block%patch)) then
       call fail("scalar-restriction source patch is invalid")
    end if
    level_slot = 1-block%field_level+1
    if (level_slot < 1 .or. level_slot > block%n_field_level) then
       call fail("scalar-restriction source level is invalid")
    end if
    sample = (p-1)*block_writeback_plan%scalar_patch_nvalue + &
         (level_slot-1)*PATCH_SIZE**2
    data_index = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + &
         BLOCK_SCALAR_SOURCE_INDEX
    if (data_index < 1 .or. data_index > &
         size(block_scalar_tendency(local_index)%patch)) then
       call fail("scalar-restriction source index is invalid")
    end if
    source_value = &
         block_scalar_tendency(local_index)%patch(data_index)
    if (.not. ieee_is_finite(source_value) .or. &
         source_value < 0.0_dp .or. &
         source_value > real(huge(source_start),dp)) then
       write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
            "Rank ",rank, &
            ": invalid patch source value: block = ",block%id, &
            ", patch = ",p,", data index = ",data_index
       write(error_unit,'(a,es24.16,a,i0)') &
            "  source value = ",source_value, &
            ", physical level slot = ",level_slot
       flush(error_unit)
       call fail("scalar-restriction patch source value is invalid")
    end if
    source_start = nint(source_value)
    if (source_start < 0 .or. &
         abs(source_value-real(source_start,dp)) > 0.0_dp) then
       call fail("scalar-restriction patch source is invalid")
    end if

  end function block_patch_source_start


  function interpolate_block_scalar_flux ( &
       block,local_index,p,scalar_slot,level_slot,i,j,flux_start) &
       result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: flux_start
    real(dp) :: value(4)

    integer :: edge_component(0:19)
    integer :: edge_i(0:19)
    integer :: edge_j(0:19)
    integer :: scalar_i(0:19)
    integer :: scalar_j(0:19)

    call get_block_restriction_indices( &
         i+1,j,RT,edge_i,edge_j,edge_component,scalar_i,scalar_j)
    value(1) = -sum_edge_weight_product( &
         [WPM,UZM,VMM],i+1,j-2) - &
         sum_edge_difference_weight_product( &
         [VPM,WMMM,UMZ],[UPZ,VPMM,WMM],i+1,j-1)
    value(2) = sum_edge_weight_product( &
         [WMP,UZP,VPP],i,j) + &
         sum_edge_difference_weight_product( &
         [VMP,WPPP,UPZ],[UMZ,VMPP,WPP],i,j+1)

    call get_block_restriction_indices( &
         i,j+1,UP,edge_i,edge_j,edge_component,scalar_i,scalar_j)
    value(3) = -sum_edge_weight_product( &
         [UZM,VMM,WPM],i+1,j) - &
         sum_edge_difference_weight_product( &
         [WMMM,UMZ,VPM],[VPMM,WMM,UPZ],i+1,j+1)
    value(4) = sum_edge_weight_product( &
         [UZP,VPP,WMP],i-2,j) + &
         sum_edge_difference_weight_product( &
         [WPPP,UPZ,VMP],[VMPP,WPP,UMZ],i-2,j+1)

  contains

    real(dp) function sum_edge_weight_product (aliases,wi,wj) &
         result(total)

      implicit none

      integer, intent(in) :: aliases(3)
      integer, intent(in) :: wi
      integer, intent(in) :: wj

      integer :: k

      total = 0.0_dp
      do k = 1,EDGE
         total = total + block_restriction_edge_flux( &
              block,local_index,p,scalar_slot,level_slot, &
              edge_i(aliases(k)),edge_j(aliases(k)), &
              edge_component(aliases(k)),flux_start)* &
              block_scalar_record_value( &
              block,local_index,p,scalar_slot,level_slot,wi,wj, &
              BLOCK_SCALAR_RESTRICTION_WEIGHT_START+k-1)
      end do

    end function sum_edge_weight_product


    real(dp) function sum_edge_difference_weight_product ( &
         positive_aliases,negative_aliases,wi,wj) result(total)

      implicit none

      integer, intent(in) :: positive_aliases(3)
      integer, intent(in) :: negative_aliases(3)
      integer, intent(in) :: wi
      integer, intent(in) :: wj

      integer :: k

      total = 0.0_dp
      do k = 1,EDGE
         total = total + (block_restriction_edge_flux( &
              block,local_index,p,scalar_slot,level_slot, &
              edge_i(positive_aliases(k)), &
              edge_j(positive_aliases(k)), &
              edge_component(positive_aliases(k)),flux_start)- &
              block_restriction_edge_flux( &
              block,local_index,p,scalar_slot,level_slot, &
              edge_i(negative_aliases(k)), &
              edge_j(negative_aliases(k)), &
              edge_component(negative_aliases(k)),flux_start))* &
              block_scalar_record_value( &
              block,local_index,p,scalar_slot,level_slot,wi,wj, &
              BLOCK_SCALAR_RESTRICTION_WEIGHT_START+k-1)
      end do

    end function sum_edge_difference_weight_product

  end function interpolate_block_scalar_flux


  real(dp) function complete_block_coarse_flux ( &
       sm_flux,block,local_index,p,scalar_slot,level_slot, &
       i_par,j_par,i_chd,j_chd,e,cursor,roundoff_scale) result(value)

    implicit none

    real(dp), intent(in) :: sm_flux(4)
    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i_par
    integer, intent(in) :: j_par
    integer, intent(in) :: i_chd
    integer, intent(in) :: j_chd
    integer, intent(in) :: e
    type(Block_Scalar_Restriction_Cursor), intent(in) :: cursor
    real(dp), optional, intent(out) :: roundoff_scale

    integer :: i_edge
    integer :: j_edge
    real(dp) :: coarse_value
    real(dp) :: partial_value

    value = 0.0_dp
    if (present(roundoff_scale)) roundoff_scale = 0.0_dp
    i_edge = 0
    j_edge = 0
    select case (e)
    case (RT)
       i_edge = i_chd+1
       j_edge = j_chd
    case (DG)
       i_edge = i_chd+1
       j_edge = j_chd+1
    case (UP)
       i_edge = i_chd
       j_edge = j_chd+1
    case default
       call fail("scalar-restriction coarse edge is invalid")
    end select
    partial_value = partial_block_coarse_flux( &
         block,local_index,p,scalar_slot,level_slot,i_edge,j_edge,e, &
         cursor,BLOCK_SCALAR_DIRECT_FLUX_START)
    call validate_scalar_restriction_value( &
         "partial_block_coarse_flux",partial_value,cursor)
    coarse_value = block_coarse_flux( &
         block,local_index,p,scalar_slot,level_slot, &
         i_par,j_par,i_edge,j_edge,e, &
         BLOCK_SCALAR_DIRECT_FLUX_START)
    call validate_scalar_restriction_value( &
         "block_coarse_flux",coarse_value,cursor)
    select case (e)
    case (RT)
       value = partial_value+coarse_value+sm_flux(1)+sm_flux(2)
       if (present(roundoff_scale)) then
          roundoff_scale = abs(partial_value)+abs(coarse_value)+ &
               abs(sm_flux(1))+abs(sm_flux(2))
       end if
    case (DG)
       value = partial_value+coarse_value+sm_flux(2)+sm_flux(3)
       if (present(roundoff_scale)) then
          roundoff_scale = abs(partial_value)+abs(coarse_value)+ &
               abs(sm_flux(2))+abs(sm_flux(3))
       end if
    case (UP)
       value = partial_value+coarse_value+sm_flux(3)+sm_flux(4)
       if (present(roundoff_scale)) then
          roundoff_scale = abs(partial_value)+abs(coarse_value)+ &
               abs(sm_flux(3))+abs(sm_flux(4))
       end if
    case default
       call fail("scalar-restriction coarse edge is invalid")
    end select

  end function complete_block_coarse_flux


  real(dp) function scalar_restriction_operation_scale ( &
       catalog_index,block,local_index,p,scalar_slot,level_slot, &
       i_par,j_par,e) result(operation_scale)
    ! Reconstruct the absolute term scale for a restricted edge whose
    ! independently evaluated final values differ. This is invoked only on
    ! the exceptional comparison path.

    implicit none

    integer, intent(in) :: catalog_index
    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i_par
    integer, intent(in) :: j_par
    integer, intent(in) :: e

    integer :: c
    integer :: child
    integer :: i_chd
    integer :: j_chd
    integer :: n_match

    real(dp) :: ignored_value
    real(dp) :: sm_flux(4)

    type(Block_Scalar_Restriction_Cursor) :: cursor

    child = -1
    i_chd = -1
    j_chd = -1
    n_match = 0
    do c = 1,N_CHDRN
       if (i_par < chd_offs(1,c) .or. &
            i_par >= chd_offs(1,c)+PATCH_SIZE/2 .or. &
            j_par < chd_offs(2,c) .or. &
            j_par >= chd_offs(2,c)+PATCH_SIZE/2) cycle
       child = block%patch(p)%children(c)
       i_chd = 2*(i_par-chd_offs(1,c))
       j_chd = 2*(j_par-chd_offs(2,c))
       n_match = n_match + 1
       cursor%child_index = c
    end do
    if (n_match /= 1 .or. child <= 0 .or. &
         child >= size(block%patch)) then
       call fail("scalar-restriction scale child is invalid")
    end if

    cursor%target_level = block%patch(p)%level
    cursor%catalog_index = catalog_index
    cursor%block_id = block%id
    cursor%parent_patch = p
    cursor%child_patch = child+1
    cursor%scalar_slot = scalar_slot
    cursor%level_slot = level_slot
    cursor%physical_level = block%field_level+level_slot-1
    cursor%i_parent = i_par
    cursor%j_parent = j_par
    cursor%i_child = i_chd
    cursor%j_child = j_chd
    cursor%edge = e

    if (max_parent_edge_mask( &
         block,local_index,p,scalar_slot,level_slot,i_par,j_par) >= &
         real(RESTRCT,dp)) then
       sm_flux = interpolate_block_scalar_flux( &
            block,local_index,child+1,scalar_slot,level_slot, &
            i_chd,j_chd,BLOCK_SCALAR_DIRECT_FLUX_START)
    else
       sm_flux = 0.0_dp
    end if
    ignored_value = complete_block_coarse_flux( &
         sm_flux,block,local_index,child+1,scalar_slot,level_slot, &
         i_par,j_par,i_chd,j_chd,e,cursor,operation_scale)
    call validate_scalar_restriction_value( &
         "scalar_restriction_operation_scale",ignored_value,cursor)

  end function scalar_restriction_operation_scale


  subroutine report_scalar_restriction_components ( &
       block,local_index,p,sm_flux,native_value,reference_value,cursor)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    real(dp), intent(in) :: sm_flux(4)
    real(dp), intent(in) :: native_value
    real(dp), intent(in) :: reference_value
    type(Block_Scalar_Restriction_Cursor), intent(in) :: cursor

    integer :: i_edge
    integer :: j_edge

    real(dp) :: native_coarse
    real(dp) :: native_partial
    real(dp) :: native_sm_pair
    real(dp) :: native_total
    real(dp) :: reference_coarse
    real(dp) :: reference_partial
    real(dp) :: reference_sm(4)
    real(dp) :: reference_sm_pair
    real(dp) :: reference_total

    i_edge = 0
    j_edge = 0
    native_sm_pair = 0.0_dp
    reference_sm_pair = 0.0_dp
    select case (cursor%edge)
    case (RT)
       i_edge = cursor%i_child+1
       j_edge = cursor%j_child
    case (DG)
       i_edge = cursor%i_child+1
       j_edge = cursor%j_child+1
    case (UP)
       i_edge = cursor%i_child
       j_edge = cursor%j_child+1
    case default
       call fail("scalar-restriction diagnostic edge is invalid")
    end select

    reference_sm = interpolate_block_scalar_flux( &
         block,local_index,p,cursor%scalar_slot,cursor%level_slot, &
         cursor%i_child,cursor%j_child, &
         BLOCK_SCALAR_RESTRICTED_FLUX_START)
    native_partial = partial_block_coarse_flux( &
         block,local_index,p,cursor%scalar_slot,cursor%level_slot, &
         i_edge,j_edge,cursor%edge,cursor, &
         BLOCK_SCALAR_DIRECT_FLUX_START)
    reference_partial = partial_block_coarse_flux( &
         block,local_index,p,cursor%scalar_slot,cursor%level_slot, &
         i_edge,j_edge,cursor%edge,cursor, &
         BLOCK_SCALAR_RESTRICTED_FLUX_START)
    native_coarse = block_coarse_flux( &
         block,local_index,p,cursor%scalar_slot,cursor%level_slot, &
         cursor%i_parent,cursor%j_parent,i_edge,j_edge,cursor%edge, &
         BLOCK_SCALAR_DIRECT_FLUX_START)
    reference_coarse = block_coarse_flux( &
         block,local_index,p,cursor%scalar_slot,cursor%level_slot, &
         cursor%i_parent,cursor%j_parent,i_edge,j_edge,cursor%edge, &
         BLOCK_SCALAR_RESTRICTED_FLUX_START)

    select case (cursor%edge)
    case (RT)
       native_sm_pair = sm_flux(1)+sm_flux(2)
       reference_sm_pair = reference_sm(1)+reference_sm(2)
    case (DG)
       native_sm_pair = sm_flux(2)+sm_flux(3)
       reference_sm_pair = reference_sm(2)+reference_sm(3)
    case (UP)
       native_sm_pair = sm_flux(3)+sm_flux(4)
       reference_sm_pair = reference_sm(3)+reference_sm(4)
    case default
       call fail("scalar-restriction diagnostic edge is invalid")
    end select
    native_total = native_partial+native_coarse+native_sm_pair
    reference_total = &
         reference_partial+reference_coarse+reference_sm_pair

    call report_scalar_restriction_cursor( &
         "restricted scalar-flux component mismatch",cursor)
    write(error_unit,'(a,4(es24.16,1x))') &
         "  native sm_flux = ",sm_flux
    write(error_unit,'(a,4(es24.16,1x))') &
         "  reference sm_flux = ",reference_sm
    write(error_unit,'(a,3(es24.16,1x))') &
         "  native partial, coarse, sm pair = ", &
         native_partial,native_coarse,native_sm_pair
    write(error_unit,'(a,3(es24.16,1x))') &
         "  reference partial, coarse, sm pair = ", &
         reference_partial,reference_coarse,reference_sm_pair
    write(error_unit,'(a,3(es24.16,1x))') &
         "  component differences = ", &
         native_partial-reference_partial, &
         native_coarse-reference_coarse, &
         native_sm_pair-reference_sm_pair
    write(error_unit,'(a,2(es24.16,1x))') &
         "  recomputed native, reference totals = ", &
         native_total,reference_total
    write(error_unit,'(a,3(es24.16,1x))') &
         "  stored native, reference, difference = ", &
         native_value,reference_value,native_value-reference_value
    write(error_unit,'(a,es24.16)') &
         "  reference reconstruction difference = ", &
         reference_total-reference_value
    flush(error_unit)

  end subroutine report_scalar_restriction_components


  real(dp) function partial_block_coarse_flux ( &
       block,local_index,p,scalar_slot,level_slot,i,j,e,cursor, &
       flux_start) result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: e
    type(Block_Scalar_Restriction_Cursor), intent(in) :: cursor
    integer, intent(in) :: flux_start

    integer :: edge_component(0:19)
    integer :: edge_i(0:19)
    integer :: edge_j(0:19)
    integer :: scalar_i(0:19)
    integer :: scalar_j(0:19)

    real(dp) :: area(2)
    real(dp) :: area_input(2)
    real(dp) :: area_sum
    real(dp) :: ol_area(4)
    real(dp) :: ol_area_input(4)
    real(dp) :: ol_area_terms(6)

    call get_block_restriction_indices( &
         i,j,e,edge_i,edge_j,edge_component,scalar_i,scalar_j)
    area = [block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i,j,1), &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i,j,2)]
    ol_area(1:2) = [block_overlap_split( &
         block,local_index,p,scalar_slot,level_slot,i,j,1), &
         block_overlap_split( &
         block,local_index,p,scalar_slot,level_slot,i,j,2)]
    ol_area(3:4) = [block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i,j,3), &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i,j,4)]
    area_input = area
    ol_area_input = ol_area
    if (.not. all(ieee_is_finite(area_input)) .or. &
         .not. all(ieee_is_finite(ol_area_input))) then
       call report_scalar_restriction_cursor( &
            "non-finite partial coarse-flux input",cursor)
       write(error_unit,'(a,2(es24.16,1x))') &
            "  area input = ",area_input
       write(error_unit,'(a,4(es24.16,1x))') &
            "  overlap-area input = ",ol_area_input
       flush(error_unit)
       call fail("partial coarse-flux input is non-finite")
    end if
    ol_area(3:4) = ol_area(3:4)-ol_area(1:2)
    area(1) = area(1)+ol_area(1)+ol_area(4)
    area(2) = area(2)+ol_area(2)+ol_area(3)
    area_sum = sum(area)
    if (.not. all(ieee_is_finite(area)) .or. &
         .not. all(ieee_is_finite(ol_area)) .or. &
         .not. ieee_is_finite(area_sum) .or. &
         .not. (abs(area_sum) > 0.0_dp)) then
       call report_scalar_restriction_cursor( &
            "invalid partial coarse-flux normalization",cursor)
       write(error_unit,'(a,2(es24.16,1x))') &
            "  area = ",area
       write(error_unit,'(a,4(es24.16,1x))') &
            "  overlap area = ",ol_area
       write(error_unit,'(a,es24.16)') &
            "  area sum = ",area_sum
       flush(error_unit)
       call fail("partial coarse-flux normalization is invalid")
    end if
    area = area/area_sum

    ol_area_terms(1) = block_overlap_split( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(PP),scalar_j(PP),1)
    ol_area_terms(2) = block_overlap_split( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(MM),scalar_j(MM),2)
    ol_area_terms(3) = block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(MP),scalar_j(MP),3)
    ol_area_terms(4) = block_overlap_split( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(MP),scalar_j(MP),1)
    ol_area_terms(5) = block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(PM),scalar_j(PM),4)
    ol_area_terms(6) = block_overlap_split( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(PM),scalar_j(PM),2)
    if (.not. all(ieee_is_finite(ol_area_terms))) then
       call report_scalar_restriction_cursor( &
            "non-finite partial coarse-flux overlap input",cursor)
       write(error_unit,'(a,6(es24.16,1x))') &
            "  overlap-area terms = ",ol_area_terms
       flush(error_unit)
       call fail("partial coarse-flux overlap input is non-finite")
    end if
    ol_area = [ol_area_terms(1),ol_area_terms(2), &
         ol_area_terms(3)-ol_area_terms(4), &
         ol_area_terms(5)-ol_area_terms(6)]
    if (.not. all(ieee_is_finite(ol_area))) then
       call report_scalar_restriction_cursor( &
            "non-finite partial coarse-flux overlap result",cursor)
       write(error_unit,'(a,4(es24.16,1x))') &
            "  overlap area = ",ol_area
       flush(error_unit)
       call fail("partial coarse-flux overlap result is non-finite")
    end if

    value = (block_restriction_edge_flux( &
         block,local_index,p,scalar_slot,level_slot, &
         edge_i(UPZ),edge_j(UPZ),edge_component(UPZ), &
         flux_start)*area(1) + &
         block_restriction_edge_flux( &
         block,local_index,p,scalar_slot,level_slot, &
         edge_i(UMZ),edge_j(UMZ),edge_component(UMZ), &
         flux_start)*area(2)) - &
         (block_restriction_edge_flux( &
         block,local_index,p,scalar_slot,level_slot, &
         edge_i(VMM),edge_j(VMM),edge_component(VMM),flux_start) + &
         block_restriction_edge_flux( &
         block,local_index,p,scalar_slot,level_slot, &
         edge_i(WMP),edge_j(WMP),edge_component(WMP), &
         flux_start))*area(2) - &
         (block_restriction_edge_flux( &
         block,local_index,p,scalar_slot,level_slot, &
         edge_i(WPM),edge_j(WPM),edge_component(WPM),flux_start) + &
         block_restriction_edge_flux( &
         block,local_index,p,scalar_slot,level_slot, &
         edge_i(VPP),edge_j(VPP),edge_component(VPP), &
         flux_start))*area(1) + &
         ol_area(3)*block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(MP),scalar_j(MP),flux_start) - &
         ol_area(4)*block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(PM),scalar_j(PM),flux_start) - &
         ol_area(1)*block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(PP),scalar_j(PP),flux_start) + &
         ol_area(2)*block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(MM),scalar_j(MM),flux_start)

  end function partial_block_coarse_flux


  real(dp) function block_coarse_flux ( &
       block,local_index,p,scalar_slot,level_slot, &
       i_par,j_par,i,j,e,flux_start) result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i_par
    integer, intent(in) :: j_par
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: e
    integer, intent(in) :: flux_start

    integer :: i_mm
    integer :: i_mm2
    integer :: i_mp
    integer :: i_mp2
    integer :: i_mz
    integer :: i_pm
    integer :: i_pm2
    integer :: i_pp
    integer :: i_pp2
    integer :: i_pz
    integer :: j_mm
    integer :: j_mm2
    integer :: j_mp
    integer :: j_mp2
    integer :: j_mz
    integer :: j_pm
    integer :: j_pm2
    integer :: j_pp
    integer :: j_pp2
    integer :: j_pz

    real(dp) :: coefficient

    if (i_par < 0 .or. j_par < 0) then
       call fail("scalar-restriction parent coordinate is invalid")
    end if
    i_mz = i+nghb_pt(1,hex_s_offs(e+1)+2)
    j_mz = j+nghb_pt(2,hex_s_offs(e+1)+2)
    i_pz = i+nghb_pt(1,hex_s_offs(e+1)+5)
    j_pz = j+nghb_pt(2,hex_s_offs(e+1)+5)
    i_mp = i+nghb_pt(1,hex_s_offs(e+1)+1)
    j_mp = j+nghb_pt(2,hex_s_offs(e+1)+1)
    i_pp = i+nghb_pt(1,hex_s_offs(e+1)+6)
    j_pp = j+nghb_pt(2,hex_s_offs(e+1)+6)
    i_pm = i+nghb_pt(1,hex_s_offs(e+1)+4)
    j_pm = j+nghb_pt(2,hex_s_offs(e+1)+4)
    i_mm = i+nghb_pt(1,hex_s_offs(e+1)+3)
    j_mm = j+nghb_pt(2,hex_s_offs(e+1)+3)
    i_mm2 = i+bfly_no2(1,1,e+1)
    j_mm2 = j+bfly_no2(2,1,e+1)
    i_pm2 = i+bfly_no2(1,2,e+1)
    j_pm2 = j+bfly_no2(2,2,e+1)
    i_pp2 = i+bfly_no2(1,3,e+1)
    j_pp2 = j+bfly_no2(2,3,e+1)
    i_mp2 = i+bfly_no2(1,4,e+1)
    j_mp2 = j+bfly_no2(2,4,e+1)

    coefficient = block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i,j,1)* &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i,j,2)* &
         block_area_value( &
         block,local_index,p,scalar_slot,level_slot,i,j) + &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i_mp,j_mp,2)* &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i_mp,j_mp,3)* &
         block_area_value( &
         block,local_index,p,scalar_slot,level_slot,i_mp,j_mp) + &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i_pp,j_pp,1)* &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i_pp,j_pp,3)* &
         block_area_value( &
         block,local_index,p,scalar_slot,level_slot,i_pp,j_pp) + &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i_pm,j_pm,1)* &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i_pm,j_pm,4)* &
         block_area_value( &
         block,local_index,p,scalar_slot,level_slot,i_pm,j_pm) + &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i_mm,j_mm,2)* &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i_mm,j_mm,4)* &
         block_area_value( &
         block,local_index,p,scalar_slot,level_slot,i_mm,j_mm)
    value = coefficient*(block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_pz,j_pz, &
         flux_start)- &
         block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_mz,j_mz, &
         flux_start))
    value = value + 0.5_dp*overlap_area_product( &
         i_pp,j_pp,3,4)*(block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_pp2,j_pp2, &
         flux_start)- &
         block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_mz,j_mz, &
         flux_start))
    value = value + 0.5_dp*overlap_area_product( &
         i_pm,j_pm,3,4)*(block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_pm2,j_pm2, &
         flux_start)- &
         block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_mz,j_mz, &
         flux_start))
    value = value + 0.5_dp*overlap_area_product( &
         i_mp,j_mp,3,4)*(block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_pz,j_pz, &
         flux_start)- &
         block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_mp2,j_mp2, &
         flux_start))
    value = value + 0.5_dp*overlap_area_product( &
         i_mm,j_mm,3,4)*(block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_pz,j_pz, &
         flux_start)- &
         block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_mm2,j_mm2, &
         flux_start))

  contains

    real(dp) function overlap_area_product ( &
         oi,oj,first_component,second_component) result(product)

      implicit none

      integer, intent(in) :: oi
      integer, intent(in) :: oj
      integer, intent(in) :: first_component
      integer, intent(in) :: second_component

      product = block_overlap_value( &
           block,local_index,p,scalar_slot,level_slot,oi,oj, &
           first_component)*block_overlap_value( &
           block,local_index,p,scalar_slot,level_slot,oi,oj, &
           second_component)*block_area_value( &
           block,local_index,p,scalar_slot,level_slot,oi,oj)

    end function overlap_area_product

  end function block_coarse_flux


  subroutine validate_scalar_restriction_vector (name,value,cursor)

    implicit none

    character(*), intent(in) :: name
    real(dp), intent(in) :: value(:)
    type(Block_Scalar_Restriction_Cursor), intent(in) :: cursor

    if (all(ieee_is_finite(value))) return
    call report_scalar_restriction_cursor( &
         "non-finite "//trim(name)//" result",cursor)
    write(error_unit,'(a,*(es24.16,1x))') "  result = ",value
    flush(error_unit)
    call fail(trim(name)//" returned a non-finite value")

  end subroutine validate_scalar_restriction_vector


  subroutine validate_scalar_restriction_value (name,value,cursor)

    implicit none

    character(*), intent(in) :: name
    real(dp), intent(in) :: value
    type(Block_Scalar_Restriction_Cursor), intent(in) :: cursor

    if (ieee_is_finite(value)) return
    call report_scalar_restriction_cursor( &
         "non-finite "//trim(name)//" result",cursor)
    write(error_unit,'(a,es24.16)') "  result = ",value
    flush(error_unit)
    call fail(trim(name)//" returned a non-finite value")

  end subroutine validate_scalar_restriction_value


  subroutine report_scalar_restriction_cursor (message,cursor)

    implicit none

    character(*), intent(in) :: message
    type(Block_Scalar_Restriction_Cursor), intent(in) :: cursor

    write(error_unit,'(/,a,i0,2a)') &
         "Rank ",rank,": ",trim(message)
    write(error_unit,'(a,i0,a,i0,a,i0)') &
         "  target level = ",cursor%target_level, &
         ", catalog block = ",cursor%catalog_index, &
         ", block id = ",cursor%block_id
    write(error_unit,'(a,i0,a,i0,a,i0)') &
         "  parent patch = ",cursor%parent_patch, &
         ", child = ",cursor%child_index, &
         ", child patch = ",cursor%child_patch
    write(error_unit,'(a,i0,a,i0,a,i0)') &
         "  scalar slot = ",cursor%scalar_slot, &
         ", field-level slot = ",cursor%level_slot, &
         ", physical level = ",cursor%physical_level
    write(error_unit,'(a,i0,a,i0,a,i0,a,i0,a,i0)') &
         "  parent coordinates = ",cursor%i_parent,", ",cursor%j_parent, &
         "; child coordinates = ",cursor%i_child,", ",cursor%j_child, &
         "; edge = ",cursor%edge
    flush(error_unit)

  end subroutine report_scalar_restriction_cursor


  real(dp) function block_restriction_dscalar ( &
       block,local_index,p,scalar_slot,level_slot,i,j,flux_start) &
       result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: flux_start

    if (flux_start /= BLOCK_SCALAR_DIRECT_FLUX_START .and. &
         flux_start /= BLOCK_SCALAR_RESTRICTED_FLUX_START) then
       call fail("scalar-restriction dscalar mode is invalid")
    end if
    value = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot,i,j, &
         BLOCK_SCALAR_NATIVE_DSCALAR_INDEX)

  end function block_restriction_dscalar


  real(dp) function block_restriction_edge_flux ( &
       block,local_index,p,scalar_slot,level_slot,i,j,e,flux_start) &
       result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: e
    integer, intent(in) :: flux_start

    if (e < RT .or. e > UP) then
       call fail("scalar-restriction edge component is invalid")
    end if
    value = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot,i,j, &
         flux_start+e)

  end function block_restriction_edge_flux


  real(dp) function block_area_value ( &
       block,local_index,p,scalar_slot,level_slot,i,j) result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j

    value = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot,i,j, &
         BLOCK_SCALAR_AREA_INDEX)

  end function block_area_value


  real(dp) function block_overlap_value ( &
       block,local_index,p,scalar_slot,level_slot,i,j,component) &
       result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: component

    if (component < 1 .or. component > 4) then
       call fail("scalar-restriction overlap component is invalid")
    end if
    value = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot,i,j, &
         BLOCK_SCALAR_OVERLAP_START+component-1)

  end function block_overlap_value


  real(dp) function block_overlap_split ( &
       block,local_index,p,scalar_slot,level_slot,i,j,component) &
       result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: component

    if (component < 1 .or. component > 2) then
       call fail("scalar-restriction split component is invalid")
    end if
    value = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot,i,j, &
         BLOCK_SCALAR_OVERLAP_START+3+component)

  end function block_overlap_split


  subroutine get_block_restriction_indices ( &
       i,j,e,edge_i,edge_j,edge_component,scalar_i,scalar_j)

    implicit none

    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: e
    integer, intent(out) :: edge_i(0:19)
    integer, intent(out) :: edge_j(0:19)
    integer, intent(out) :: edge_component(0:19)
    integer, intent(out) :: scalar_i(0:19)
    integer, intent(out) :: scalar_j(0:19)

    integer :: i_mm
    integer :: i_mp
    integer :: i_pm
    integer :: i_pp
    integer :: j_mm
    integer :: j_mp
    integer :: j_pm
    integer :: j_pp

    edge_i = 0
    edge_j = 0
    edge_component = 0
    scalar_i = 0
    scalar_j = 0
    call set_edge(UMZ,i,j,hex_s_offs(e+1)+2)
    call set_edge(UPZ,i,j,hex_s_offs(e+1)+5)
    call set_edge(WMP,i,j,hex_s_offs(e+1)+1)
    call set_edge(VPP,i,j,hex_s_offs(e+1)+6)
    call set_edge(WPM,i,j,hex_s_offs(e+1)+4)
    call set_edge(VMM,i,j,hex_s_offs(e+1)+3)

    i_mp = i+nghb_pt(1,hex_s_offs(e+1)+1)
    j_mp = j+nghb_pt(2,hex_s_offs(e+1)+1)
    i_pp = i+nghb_pt(1,hex_s_offs(e+1)+6)
    j_pp = j+nghb_pt(2,hex_s_offs(e+1)+6)
    i_pm = i+nghb_pt(1,hex_s_offs(e+1)+4)
    j_pm = j+nghb_pt(2,hex_s_offs(e+1)+4)
    i_mm = i+nghb_pt(1,hex_s_offs(e+1)+3)
    j_mm = j+nghb_pt(2,hex_s_offs(e+1)+3)
    scalar_i(MP) = i_mp
    scalar_j(MP) = j_mp
    scalar_i(PP) = i_pp
    scalar_j(PP) = j_pp
    scalar_i(PM) = i_pm
    scalar_j(PM) = j_pm
    scalar_i(MM) = i_mm
    scalar_j(MM) = j_mm

    call set_edge(VMP,i_mp,j_mp,hex_s_offs(e+1)+3)
    call set_edge(VMPP,i_mp,j_mp,hex_s_offs(e+1)+6)
    call set_edge(UZP,i_mp,j_mp,hex_s_offs(e+1)+5)
    call set_edge(WPPP,i_pp,j_pp,hex_s_offs(e+1)+1)
    call set_edge(WPP,i_pp,j_pp,hex_s_offs(e+1)+4)
    call set_edge(VPM,i_pm,j_pm,hex_s_offs(e+1)+6)
    call set_edge(VPMM,i_pm,j_pm,hex_s_offs(e+1)+3)
    call set_edge(UZM,i_pm,j_pm,hex_s_offs(e+1)+2)
    call set_edge(WMMM,i_mm,j_mm,hex_s_offs(e+1)+4)
    call set_edge(WMM,i_mm,j_mm,hex_s_offs(e+1)+1)

  contains

    subroutine set_edge (alias,base_i,base_j,side_index)

      implicit none

      integer, intent(in) :: alias
      integer, intent(in) :: base_i
      integer, intent(in) :: base_j
      integer, intent(in) :: side_index

      if (alias < 0 .or. alias > 19 .or. &
           side_index < 1 .or. side_index > size(hex_sides,2)) then
         call fail("scalar-restriction edge alias is invalid")
      end if
      edge_i(alias) = base_i+hex_sides(1,side_index)
      edge_j(alias) = base_j+hex_sides(2,side_index)
      edge_component(alias) = hex_sides(3,side_index)

    end subroutine set_edge

  end subroutine get_block_restriction_indices


  subroutine complete_uncaptured_scalar_divergence_coverage
      ! Complete only records outside the horizontal/vertical levels visited
      ! by trend_ml. Where an authoritative Domain tendency exists, it must
      ! remain exactly zero. Missing production coverage is still an error.

      implicit none

      integer :: b
      integer :: d
      integer :: first_field_level
      integer :: local_index
      integer :: mult_scalar
      integer :: mult_vector
      integer :: n_field_level
      integer :: n_scalar_variable
      integer :: patch_index
      integer :: r
      integer :: sample_start
      integer :: slot
      integer :: v_scalar
      integer :: v_vector

      call get_block_field_layout( &
           v_scalar,n_scalar_variable,v_vector,first_field_level, &
           n_field_level,mult_scalar,mult_vector)
      if (mult_scalar /= 1 .or. mult_vector /= EDGE .or. &
           n_scalar_variable < 1 .or. n_field_level < 1 .or. &
           v_scalar < 1 .or. v_vector < 1) then
         call fail("uncaptured scalar-divergence layout is invalid")
      end if

      do local_index = 1,n_local_blocks()
         b = local_block_catalog(local_index)
         if (source_rank(b) /= rank) cycle
         d = loc_id(block_catalog(b)%root_domain+1) + 1
         if (d < 1 .or. d > size(grid)) then
            call fail("uncaptured scalar-divergence Domain is invalid")
         end if
         patch_index = 0
         call complete_subtree( &
              d,block_catalog(b)%root_patch,patch_index,1,local_index)
         if (patch_index /= local_block_patch_count(b)) then
            call fail( &
                 "uncaptured scalar-divergence traversal is incomplete")
         end if
      end do

      do r = 1,n_process
         sample_start = block_writeback_plan%scalar_recv_displ(r) + 1
         do slot = block_writeback_plan%recv_displ(r)+1, &
              block_writeback_plan%recv_displ(r) + &
              block_writeback_plan%recv_count(r)
            b = block_writeback_plan%recv_block(slot)
            if (source_rank(b) /= rank) then
               call fail( &
                    "uncaptured scalar-divergence source is invalid")
            end if
            d = loc_id(block_catalog(b)%root_domain+1) + 1
            if (d < 1 .or. d > size(grid)) then
               call fail( &
                    "remote uncaptured scalar-divergence Domain is invalid")
            end if
            patch_index = 0
            call complete_subtree( &
                 d,block_catalog(b)%root_patch,patch_index, &
                 sample_start,0)
            if (patch_index /= &
                 block_writeback_plan%recv_patch_count(slot)) then
               call fail( &
                    "remote uncaptured scalar-divergence traversal is incomplete")
            end if
            sample_start = sample_start + &
                 block_writeback_plan%recv_scalar_nvalue(slot)
         end do
      end do

    contains

      recursive subroutine complete_subtree ( &
           d,p,patch_index,block_sample_start,storage_index)

        implicit none

        integer, intent(in) :: d
        integer, intent(in) :: p
        integer, intent(inout) :: patch_index
        integer, intent(in) :: block_sample_start
        integer, intent(in) :: storage_index

        integer :: c
        integer :: child

        if (p < 0 .or. p >= grid(d)%patch%length) then
           call fail("uncaptured scalar-divergence patch is invalid")
        end if
        if (grid(d)%patch%elts(p+1)%deleted) return

        call complete_patch( &
             d,p,patch_index,block_sample_start,storage_index)
        patch_index = patch_index + 1

        do c = 1,N_CHDRN
           child = grid(d)%patch%elts(p+1)%children(c)
           if (child <= 0) cycle
           call complete_subtree( &
                d,child,patch_index,block_sample_start,storage_index)
        end do

      end subroutine complete_subtree


      subroutine complete_patch ( &
           d,p,patch_index,block_sample_start,storage_index)

        implicit none

        integer, intent(in) :: d
        integer, intent(in) :: p
        integer, intent(in) :: patch_index
        integer, intent(in) :: block_sample_start
        integer, intent(in) :: storage_index

        integer :: data_start
        integer :: field_level
        integer :: level_slot
        integer :: node
        integer :: q
        integer :: sample
        integer :: scalar_id
        integer :: scalar_slot

        logical :: horizontal_integrated
        logical :: physical_level

        horizontal_integrated = &
             grid(d)%patch%elts(p+1)%level >= level_start .and. &
             grid(d)%patch%elts(p+1)%level <= level_end

        do scalar_slot = 1,n_scalar_variable
           scalar_id = v_scalar + scalar_slot - 1
           do level_slot = 1,n_field_level
              field_level = first_field_level + level_slot - 1
              physical_level = &
                   field_level >= 1 .and. field_level <= zlevels
              if (horizontal_integrated .and. physical_level) cycle
              do q = 0,PATCH_SIZE**2-1
                 node = grid(d)%patch%elts(p+1)%elts_start + q
                 if (physical_level) then
                    if (node < 0 .or. node >= &
                         size(trend(scalar_id,field_level)%data(d)%elts)) &
                         then
                       call fail( &
                            "nonintegrated scalar tendency extent is invalid")
                    end if
                    if (abs(trend(scalar_id,field_level)% &
                         data(d)%elts(node+1)) > 0.0_dp) then
                       call fail( &
                            "nonintegrated scalar tendency is not zero")
                    end if
                 end if
                 sample = block_sample_start + &
                      patch_index* &
                      block_writeback_plan%scalar_patch_nvalue + &
                      ((scalar_slot-1)*n_field_level + level_slot-1)* &
                      PATCH_SIZE**2 + q
                 data_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                      (sample-1) + 1
                 if (storage_index > 0) then
                    if (sample < 1 .or. sample > &
                         size(block_scalar_tendency(storage_index)% &
                         covered)) then
                       call fail( &
                            "retained nonintegrated scalar index is invalid")
                    end if
                    block_scalar_tendency(storage_index)%patch( &
                         data_start:data_start+ &
                         BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1) = 0.0_dp
                    block_scalar_tendency(storage_index)% &
                         covered(sample) = .true.
                 else
                    if (sample < 1 .or. sample > &
                         size(block_scalar_divergence_plan%recv_covered)) &
                         then
                       call fail( &
                            "remote nonintegrated scalar index is invalid")
                    end if
                    block_scalar_divergence_plan%recv_buffer( &
                         data_start:data_start+ &
                         BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1) = 0.0_dp
                    block_scalar_divergence_plan% &
                         recv_covered(sample) = .true.
                 end if
              end do
           end do
        end do

      end subroutine complete_patch

  end subroutine complete_uncaptured_scalar_divergence_coverage




  subroutine evaluate_candidate_block_exner_shadow ( &
       domain_sol,payload_family,thermodynamic_product,metric_division, &
       velocity_recomposition,checkpoint_required, &
       complete_physical_recomposition,retain_stage_tendency)
    ! Reconstruct an Exner-gradient numerator from complete provisional
    ! block columns and compare every patch independently. Diagnostic products
    ! are discarded; a complete physical tendency may be retained explicitly.

    implicit none

    type(Float_Field), intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    integer, intent(in) :: payload_family
    logical, intent(in) :: thermodynamic_product
    logical, intent(in) :: metric_division
    logical, optional, intent(in) :: velocity_recomposition
    logical, optional, intent(in) :: checkpoint_required
    logical, optional, intent(in) :: complete_physical_recomposition
    logical, optional, intent(in) :: retain_stage_tendency

    integer :: b
    integer :: first_field_level
    integer :: ierr
    integer :: local_index
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_physical_level
    integer :: n_scalar_variable
    integer :: physical_first
    integer :: physical_last
    integer :: v_scalar
    integer :: v_vector

    integer(int64) :: allocation_before
    integer(int64) :: count_global(3)
    integer(int64) :: count_local(3)
    integer(int64) :: execution_before
    integer(int64) :: expected_patch_count
    integer(int64) :: expected_sample_count
    integer(int64) :: field_count(2)
    integer(int64) :: field_count_after(2)
    integer(int64) :: hydrostatic_refresh_before
    integer(int64) :: production_writeback_before
    integer(int64) :: validated_patch_count
    integer(int64) :: writeback_allocation_before

    real(dp) :: field_moment(3,2)
    real(dp) :: field_moment_after(3,2)

    logical :: accumulator_ready
    logical :: checkpoint_ready
    logical :: tendency_ready
    logical :: trial_active
    logical :: recompose_velocity
    logical :: recompose_physical
    logical :: require_checkpoint
    logical :: retain_tendency

    type(Block_Exner_Difference_Kernel_Context) :: kernel

    recompose_velocity = .false.
    if (present(velocity_recomposition)) then
       recompose_velocity = velocity_recomposition
    end if
    require_checkpoint = .true.
    if (present(checkpoint_required)) then
       require_checkpoint = checkpoint_required
    end if
    recompose_physical = .false.
    if (present(complete_physical_recomposition)) then
       recompose_physical = complete_physical_recomposition
    end if
    retain_tendency = .false.
    if (present(retain_stage_tendency)) then
       retain_tendency = retain_stage_tendency
    end if
    if (retain_tendency .and. &
         payload_family /= &
         BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY) then
       call fail("retained stage tendency payload is invalid")
    end if

    if (payload_family /= BLOCK_PAYLOAD_EXNER_DIFFERENCE .and. &
         payload_family /= BLOCK_PAYLOAD_THERMODYNAMIC_GRADIENT .and. &
         payload_family /= BLOCK_PAYLOAD_COMPLETE_EXNER_GRADIENT .and. &
         payload_family /= BLOCK_PAYLOAD_COMPLETE_VELOCITY .and. &
         payload_family /= &
         BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY) then
       call fail("Exner-gradient shadow payload is invalid")
    end if
    if (thermodynamic_product .neqv. &
         (payload_family == BLOCK_PAYLOAD_THERMODYNAMIC_GRADIENT .or. &
         payload_family == BLOCK_PAYLOAD_COMPLETE_EXNER_GRADIENT .or. &
         payload_family == BLOCK_PAYLOAD_COMPLETE_VELOCITY .or. &
         payload_family == &
         BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY)) then
       call fail("Exner-gradient shadow mode is invalid")
    end if
    if (metric_division .neqv. &
         (payload_family == BLOCK_PAYLOAD_COMPLETE_EXNER_GRADIENT .or. &
         payload_family == BLOCK_PAYLOAD_COMPLETE_VELOCITY .or. &
         payload_family == &
         BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY)) then
       call fail("Exner-gradient shadow metric mode is invalid")
    end if
    if (recompose_velocity .neqv. &
         (payload_family == BLOCK_PAYLOAD_COMPLETE_VELOCITY .or. &
         payload_family == &
         BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY)) then
       call fail("Exner-gradient velocity recomposition mode is invalid")
    end if
    if (recompose_physical .neqv. &
         (payload_family == &
         BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY)) then
       call fail("complete physical recomposition mode is invalid")
    end if

    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (trial_active .or. tendency_ready .or. &
         accumulator_ready) then
       call fail("Exner-difference shadow transaction is invalid")
    end if
    if (checkpoint_ready .neqv. require_checkpoint) then
       call fail("Exner-difference shadow checkpoint state is invalid")
    end if
    if (.not. local_block_hydrostatic_state_ready()) then
       call fail("Exner-difference shadow hydrostatic state is stale")
    end if

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    if (mult_scalar /= 1 .or. mult_vector /= EDGE .or. &
         S_MASS < v_scalar .or. &
         S_MASS >= v_scalar+n_scalar_variable .or. &
         (thermodynamic_product .and. &
         (S_TEMP < v_scalar .or. &
         S_TEMP >= v_scalar+n_scalar_variable)) .or. &
         v_vector < 1) then
       call fail("Exner-gradient shadow field layout is invalid")
    end if
    physical_first = max(1,first_field_level)
    physical_last = min( &
         zlevels,first_field_level+n_field_level-1)
    n_physical_level = max(0,physical_last-physical_first+1)
    if (n_physical_level /= zlevels) then
       call fail("Exner-difference physical-level coverage is invalid")
    end if

    call local_block_field_statistics( &
         field_count(1),field_count(2), &
         field_moment(:,1),field_moment(:,2))
    allocation_before = local_block_tendency_allocation_count()
    execution_before = local_block_tendency_execution_count()
    hydrostatic_refresh_before = local_block_hydrostatic_refresh_count()
    writeback_allocation_before = &
         block_writeback_plan_allocation_count()
    production_writeback_before = &
         block_domain_production_writeback_count()

    if (metric_division) call refresh_candidate_block_edge_metrics
    call exchange_domain_to_block_payloads( &
         payload_family,domain_sol=domain_sol)
    kernel = Block_Exner_Difference_Kernel_Context()
    kernel%thermodynamic_product = thermodynamic_product
    kernel%metric_division = metric_division
    kernel%velocity_recomposition = recompose_velocity
    kernel%complete_physical_recomposition = recompose_physical
    call apply_local_block_tendency_kernel( &
         compute_block_exner_difference_kernel,kernel)

    tendency_ready = local_block_tendency_state_ready()
    if (.not. tendency_ready) then
       call fail("Exner-difference shadow output is not ready")
    end if
    if (local_block_tendency_execution_count() /= &
         execution_before+1_int64) then
       call fail("Exner-difference execution count is invalid")
    end if
    if (local_block_tendency_allocation_count() /= allocation_before) then
       call fail("Exner-difference reallocated tendency workspace")
    end if

    expected_patch_count = 0_int64
    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       expected_patch_count = expected_patch_count + &
            int(local_block_patch_count(b),int64)
    end do
    expected_sample_count = expected_patch_count* &
         int(n_physical_level*EDGE*PATCH_SIZE**2,int64)
    if (kernel%block_count /= int(n_local_blocks(),int64) .or. &
         kernel%patch_count /= expected_patch_count .or. &
         kernel%sample_count /= expected_sample_count) then
       call fail("Exner-difference shadow traversal is incomplete")
    end if
    if (recompose_physical) then
       if (kernel%scalar_sample_count /= expected_patch_count* &
            int(n_scalar_variable*n_field_level*PATCH_SIZE**2, &
            int64)) then
          call fail("complete physical scalar traversal is incomplete")
       end if
    else if (kernel%scalar_sample_count /= 0_int64) then
       call fail("Exner-difference shadow changed scalar tendency")
    end if

    call assert_candidate_block_tendency_payload_match( &
         payload_family,domain_sol,validated_patch_count)
    if (validated_patch_count /= expected_patch_count) then
       call fail("Exner-difference validation coverage differs")
    end if

    call local_block_field_statistics( &
         field_count_after(1),field_count_after(2), &
         field_moment_after(:,1),field_moment_after(:,2))
    if (any(field_count_after /= field_count)) then
       call fail("Exner-difference shadow changed field coverage")
    end if
    if (.not. field_moments_match( &
         field_moment_after(:,1),field_moment(:,1),field_count(1)) .or. &
         .not. field_moments_match( &
         field_moment_after(:,2),field_moment(:,2),field_count(2))) then
       call fail("Exner-difference shadow changed block fields")
    end if
    if (local_block_hydrostatic_refresh_count() /= &
         hydrostatic_refresh_before) then
       call fail("Exner-difference refreshed hydrostatic cache")
    end if
    if (block_writeback_plan_allocation_count() /= &
         writeback_allocation_before) then
       call fail("Exner-difference shadow reallocated transport")
    end if
    if (block_domain_production_writeback_count() /= &
         production_writeback_before) then
       call fail("Exner-difference shadow modified Domain fields")
    end if

    count_local = [kernel%block_count,kernel%patch_count, &
         kernel%sample_count]
    call MPI_Allreduce(count_local,count_global,3, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce Exner-difference coverage")
    if (any(count_global <= 0_int64)) then
       call fail("Exner-difference global coverage is empty")
    end if

    if (retain_tendency) then
       call retain_local_block_tendency_in_accumulator
    else
       call discard_local_block_tendency_output
    end if
    tendency_ready = local_block_tendency_state_ready()
    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (tendency_ready .or. trial_active .or. &
         (accumulator_ready .neqv. retain_tendency)) then
       call fail("Exner-difference shadow completion state is invalid")
    end if
    if (checkpoint_ready .neqv. require_checkpoint) then
       call fail("Exner-difference shadow discard lost checkpoint state")
    end if

  end subroutine evaluate_candidate_block_exner_shadow


  subroutine assert_candidate_block_tendency_payload_match ( &
       payload_family,domain_sol,validated_patch_count)
    ! Compare a ready block-native tendency-shaped payload with an
    ! independently packed Domain payload on retained and remote blocks.

    implicit none

    integer, intent(in) :: payload_family
    type(Float_Field), intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    integer(int64), intent(out) :: validated_patch_count

    integer :: b
    integer :: d
    integer :: local_index
    integer :: local_patch
    integer :: n_patch
    integer :: pos_scalar
    integer :: pos_vector
    integer :: r
    integer :: slot

    if (payload_family /= BLOCK_PAYLOAD_EXNER_DIFFERENCE .and. &
         payload_family /= BLOCK_PAYLOAD_THERMODYNAMIC_GRADIENT .and. &
         payload_family /= BLOCK_PAYLOAD_COMPLETE_EXNER_GRADIENT .and. &
         payload_family /= BLOCK_PAYLOAD_COMPLETE_VELOCITY .and. &
         payload_family /= &
         BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY) then
       call fail("candidate tendency payload family is invalid")
    end if
    if (.not. local_block_tendency_state_ready()) then
       call fail("candidate tendency payload is not ready")
    end if
    if (.not. allocated(ghost_exchange_plan%scalar_patch_buffer)) then
       call fail("candidate scalar patch buffer is not allocated")
    end if
    if (.not. allocated(ghost_exchange_plan%vector_patch_buffer)) then
       call fail("candidate vector patch buffer is not allocated")
    end if
    if (size(ghost_exchange_plan%scalar_patch_buffer) /= &
         block_writeback_plan%scalar_patch_nvalue .or. &
         size(ghost_exchange_plan%vector_patch_buffer) /= &
         block_writeback_plan%vector_patch_nvalue) then
       call fail("candidate tendency validation layout differs")
    end if

    validated_patch_count = 0_int64
    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       r = source_rank(b)
       if (r /= rank) cycle
       d = loc_id(block_catalog(b)%root_domain+1) + 1
       if (d < 1 .or. d > size(grid)) then
          call fail("candidate tendency retained Domain is invalid")
       end if
       local_patch = 0
       call assert_retained_subtree( &
            d,block_catalog(b)%root_patch,b,local_patch)
       if (local_patch /= local_block_patch_count(b)) then
          call fail("candidate tendency retained validation incomplete")
       end if
    end do

    do r = 1,n_process
       pos_scalar = block_writeback_plan%scalar_send_displ(r) + 1
       pos_vector = block_writeback_plan%vector_send_displ(r) + 1
       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)
          b = block_writeback_plan%send_block(slot)
          n_patch = local_block_patch_count(b)
          do local_patch = 0,n_patch-1
             if (pos_scalar < 1 .or. pos_scalar + &
                  block_writeback_plan%scalar_patch_nvalue - 1 > &
                  size(block_writeback_plan%scalar_send_buffer) .or. &
                  pos_vector < 1 .or. pos_vector + &
                  block_writeback_plan%vector_patch_nvalue - 1 > &
                  size(block_writeback_plan%vector_send_buffer)) then
                call fail("candidate tendency remote payload truncated")
             end if
             call assert_local_block_tendency_patch_values( &
                  b,local_patch, &
                  block_writeback_plan%scalar_send_buffer( &
                  pos_scalar:pos_scalar+ &
                  block_writeback_plan%scalar_patch_nvalue-1), &
                  block_writeback_plan%vector_send_buffer( &
                  pos_vector:pos_vector+ &
                  block_writeback_plan%vector_patch_nvalue-1))
             pos_scalar = pos_scalar + &
                  block_writeback_plan%scalar_patch_nvalue
             pos_vector = pos_vector + &
                  block_writeback_plan%vector_patch_nvalue
             validated_patch_count = validated_patch_count + 1_int64
          end do
       end do
       if (pos_scalar /= block_writeback_plan%scalar_send_displ(r) + &
            block_writeback_plan%scalar_send_count(r) + 1 .or. &
            pos_vector /= block_writeback_plan%vector_send_displ(r) + &
            block_writeback_plan%vector_send_count(r) + 1) then
          call fail("candidate tendency remote validation extent mismatch")
       end if
    end do

  contains

    recursive subroutine assert_retained_subtree ( &
         d,p,b,local_patch_index)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(in) :: b
      integer, intent(inout) :: local_patch_index

      integer :: c
      integer :: p_child
      integer :: scalar_pos
      integer :: vector_pos

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("candidate tendency retained patch is invalid")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return

      scalar_pos = 1
      vector_pos = 1
      call pack_domain_patch_prognostic( &
           d,p,payload_family, &
           ghost_exchange_plan%scalar_patch_buffer,scalar_pos, &
           ghost_exchange_plan%vector_patch_buffer,vector_pos,domain_sol)
      if (scalar_pos /= &
           size(ghost_exchange_plan%scalar_patch_buffer)+1 .or. &
           vector_pos /= &
           size(ghost_exchange_plan%vector_patch_buffer)+1) then
         call fail("candidate tendency retained payload extent mismatch")
      end if
      call assert_local_block_tendency_patch_values( &
           b,local_patch_index, &
           ghost_exchange_plan%scalar_patch_buffer, &
           ghost_exchange_plan%vector_patch_buffer)
      local_patch_index = local_patch_index + 1
      validated_patch_count = validated_patch_count + 1_int64

      do c = 1,N_CHDRN
         p_child = grid(d)%patch%elts(p+1)%children(c)
         if (p_child <= 0) cycle
         call assert_retained_subtree( &
              d,p_child,b,local_patch_index)
      end do

    end subroutine assert_retained_subtree

  end subroutine assert_candidate_block_tendency_payload_match


  subroutine refresh_parallel_block_domain_prognostic_state
    ! Refresh complete sol and wav_coeff interiors, compact boundaries,
    ! and inter-block ghosts from the authoritative Domain representation
    ! after its wavelet transform. Persistent allocations are retained.

    implicit none

    integer :: b
    integer :: boundary_index
    integer :: ierr
    integer :: local_index
    integer :: n_boundary
    integer :: n_patch
    integer :: scalar_ghost_recv_size_before
    integer :: scalar_ghost_send_size_before
    integer :: vector_ghost_recv_size_before
    integer :: vector_ghost_send_size_before

    integer(int64) :: global_boundary_count
    integer(int64) :: global_boundary_scalar_count
    integer(int64) :: global_boundary_vector_count
    integer(int64) :: global_ghost_count
    integer(int64) :: global_patch_count
    integer(int64) :: local_boundary_count
    integer(int64) :: local_boundary_scalar_count
    integer(int64) :: local_boundary_vector_count
    integer(int64) :: local_ghost_count
    integer(int64) :: local_patch_count
    integer(int64) :: production_writeback_before
    integer(int64) :: stage_allocation_before
    integer(int64) :: writeback_allocation_before

    logical :: accumulator_ready
    logical :: hydrostatic_ready
    logical :: state_ready
    logical :: tendency_ready

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail("Domain prognostic refresh before block state is ready")
    end if

    writeback_allocation_before = &
         block_writeback_plan_allocation_count()
    stage_allocation_before = block_writeback_plan%stage_allocations
    production_writeback_before = &
         block_domain_production_writeback_count()
    scalar_ghost_send_size_before = &
         size(ghost_exchange_plan%scalar_send_buffer)
    scalar_ghost_recv_size_before = &
         size(ghost_exchange_plan%scalar_recv_buffer)
    vector_ghost_send_size_before = &
         size(ghost_exchange_plan%vector_send_buffer)
    vector_ghost_recv_size_before = &
         size(ghost_exchange_plan%vector_recv_buffer)

    call import_domain_field_family_to_blocks(BLOCK_PAYLOAD_SOL)
    call import_domain_field_family_to_blocks(BLOCK_PAYLOAD_WAV_COEFF)
    call assert_block_domain_field_family_match(BLOCK_PAYLOAD_SOL)
    call assert_block_domain_field_family_match( &
         BLOCK_PAYLOAD_WAV_COEFF)

    call import_domain_boundary_field_family_to_blocks( &
         BLOCK_PAYLOAD_SOL,.false.)
    call import_domain_boundary_field_family_to_blocks( &
         BLOCK_PAYLOAD_WAV_COEFF,.false.)
    call import_domain_boundary_field_family_to_blocks( &
         BLOCK_PAYLOAD_SOL,.true.)
    call import_domain_boundary_field_family_to_blocks( &
         BLOCK_PAYLOAD_WAV_COEFF,.true.)

    call refresh_block_sol_wav_coeff_ghosts
    call exchange_block_scalar_ghost_payloads( &
         BLOCK_PAYLOAD_SOL,.false.,.true.)
    call exchange_block_vector_ghost_payloads( &
         BLOCK_PAYLOAD_SOL,.false.,.true.)
    call exchange_block_scalar_ghost_payloads( &
         BLOCK_PAYLOAD_WAV_COEFF,.false.,.true.)
    call exchange_block_vector_ghost_payloads( &
         BLOCK_PAYLOAD_WAV_COEFF,.false.,.true.)

    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (tendency_ready .or. accumulator_ready) then
       call fail("Domain prognostic refresh retained stale tendencies")
    end if

    if (compressible) then
       call ensure_local_block_hydrostatic_state
       hydrostatic_ready = local_block_hydrostatic_state_ready()
       if (.not. hydrostatic_ready) then
          call fail("Domain prognostic refresh hydrostatic state failed")
       end if
    end if

    if (block_writeback_plan_allocation_count() /= &
         writeback_allocation_before) then
       call fail("Domain prognostic refresh reallocated transport buffers")
    end if
    if (block_writeback_plan%stage_allocations /= &
         stage_allocation_before) then
       call fail("Domain prognostic refresh reallocated Domain staging")
    end if
    if (block_domain_production_writeback_count() /= &
         production_writeback_before) then
       call fail("Domain prognostic refresh modified Domain fields")
    end if
    if (size(ghost_exchange_plan%scalar_send_buffer) /= &
         scalar_ghost_send_size_before .or. &
         size(ghost_exchange_plan%scalar_recv_buffer) /= &
         scalar_ghost_recv_size_before .or. &
         size(ghost_exchange_plan%vector_send_buffer) /= &
         vector_ghost_send_size_before .or. &
         size(ghost_exchange_plan%vector_recv_buffer) /= &
         vector_ghost_recv_size_before) then
       call fail("Domain prognostic refresh resized ghost buffers")
    end if

    local_patch_count = 0_int64
    local_boundary_count = 0_int64
    local_boundary_scalar_count = 0_int64
    local_boundary_vector_count = 0_int64
    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       n_patch = local_block_patch_count(b)
       local_patch_count = local_patch_count + int(n_patch,int64)
       n_boundary = local_block_boundary_count(b)
       local_boundary_count = local_boundary_count + &
            int(n_boundary,int64)
       do boundary_index = 1,n_boundary
          local_boundary_scalar_count = &
               local_boundary_scalar_count + int( &
               local_block_scalar_family_boundary_nvalue( &
               b,boundary_index),int64)
          local_boundary_vector_count = &
               local_boundary_vector_count + int( &
               local_block_vector_family_boundary_nvalue( &
               b,boundary_index),int64)
       end do
    end do
    call MPI_Allreduce(local_patch_count,global_patch_count,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce production Domain refresh patches")
    call MPI_Allreduce(local_boundary_count,global_boundary_count,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce production boundary records")
    call MPI_Allreduce( &
         local_boundary_scalar_count,global_boundary_scalar_count,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce production scalar boundaries")
    call MPI_Allreduce( &
         local_boundary_vector_count,global_boundary_vector_count,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce production vector boundaries")
    local_ghost_count = int(ghost_exchange_plan%n_request,int64)
    call MPI_Allreduce(local_ghost_count,global_ghost_count,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce production ghost refresh patches")

    block_writeback_plan%production_domain_refresh_count = &
         block_writeback_plan%production_domain_refresh_count + 1_int64

    if (rank == 0) then
       write(6,'(/,a,i0)') &
            "Production post-wavelet Domain refresh number = ", &
            block_writeback_plan%production_domain_refresh_count
       write(6,'(a,i0)') &
            "Global post-wavelet Domain refresh patches = ", &
            global_patch_count
       write(6,'(a,i0)') &
            "Global post-wavelet Domain boundary records = ", &
            global_boundary_count
       write(6,'(a,i0)') &
            "Global post-wavelet scalar boundary values = ", &
            global_boundary_scalar_count
       write(6,'(a,i0)') &
            "Global post-wavelet vector boundary values = ", &
            global_boundary_vector_count
       write(6,'(a,i0)') &
            "Global post-wavelet block ghost patches = ", &
            global_ghost_count
       write(6,'(a)') &
            "  exact sol patch-interior refresh passed"
       write(6,'(a)') &
            "  exact wav_coeff patch-interior refresh passed"
       write(6,'(a)') &
            "  exact scalar/vector sol boundary refresh passed"
       write(6,'(a)') &
            "  exact scalar/vector wav_coeff boundary refresh passed"
       write(6,'(a)') &
            "  repeated persistent boundary-buffer reuse passed"
       write(6,'(a)') &
            "  exact scalar/vector sol ghost refresh passed"
       write(6,'(a)') &
            "  exact scalar/vector wav_coeff ghost refresh passed"
       write(6,'(a)') &
            "  repeated persistent ghost-buffer reuse passed"
       if (compressible) then
          write(6,'(a)') &
               "  hydrostatic state current after refresh"
       end if
       write(6,'(a)') &
            "Post-wavelet block prognostic ghost refresh passed"
       write(6,'(a)') &
            "Post-wavelet block prognostic boundary refresh passed"
       write(6,'(a,/)') &
            "Post-wavelet Domain-to-block prognostic refresh passed"
    end if

  end subroutine refresh_parallel_block_domain_prognostic_state


  subroutine check_domain_trend_roundtrip (verbose)
    ! Exercise the production trend field layout over the reverse route and
    ! echo it to the Domain owner for an exact comparison. Deterministic tags
    ! make the validation nontrivial even before trend_ml has initialized dq.

    implicit none

    logical, optional, intent(in) :: verbose

    integer :: ierr

    integer(int64) :: allocation_after
    integer(int64) :: allocation_before
    integer(int64) :: global_scalar
    integer(int64) :: global_vector
    integer(int64) :: local_scalar
    integer(int64) :: local_vector
    integer(int64) :: stage_allocation_after
    integer(int64) :: stage_allocation_before

    logical :: plan_ready
    logical :: print_summary

    real(dp), allocatable :: scalar_reference(:)
    real(dp), allocatable :: vector_reference(:)

    print_summary = .true.
    if (present(verbose)) print_summary = verbose

    plan_ready = block_writeback_plan_is_ready()
    if (.not. plan_ready) then
       call fail("Domain trend roundtrip before plan is ready")
    end if

    allocate(scalar_reference(size( &
         block_writeback_plan%scalar_recv_buffer)))
    allocate(vector_reference(size( &
         block_writeback_plan%vector_recv_buffer)))

    allocation_before = block_writeback_plan_allocation_count()
    stage_allocation_before = block_writeback_plan%stage_allocations

    call check_roundtrip
    call check_roundtrip

    allocation_after = block_writeback_plan_allocation_count()
    stage_allocation_after = block_writeback_plan%stage_allocations
    if (allocation_after /= allocation_before) then
       call fail("Domain trend roundtrip reallocated payload buffers")
    end if
    if (stage_allocation_after /= stage_allocation_before) then
       call fail("Domain trend roundtrip reallocated Domain staging")
    end if

    local_scalar = sum(int( &
         block_writeback_plan%scalar_recv_count,int64))
    local_vector = sum(int( &
         block_writeback_plan%vector_recv_count,int64))
    call MPI_Allreduce(local_scalar,global_scalar,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce trend roundtrip scalar values")
    call MPI_Allreduce(local_vector,global_vector,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce trend roundtrip vector values")

    if (print_summary) then
       write(6,'(/,a,i0,a)') &
            "Domain trend reverse roundtrip for rank ",rank,":"
       write(6,'(a,i0)') "  scalar values returned = ",local_scalar
       write(6,'(a,i0)') "  vector values returned = ",local_vector
       write(6,'(a)') "  exact tagged scalar trend roundtrip passed"
       write(6,'(a)') "  exact tagged vector trend roundtrip passed"
       write(6,'(a,/)') "  repeated trend roundtrip buffer reuse passed"
    end if

    if (print_summary .and. rank == 0) then
       write(6,'(/,a,i0)') &
            "Global Domain trend scalar values = ",global_scalar
       write(6,'(a,i0)') &
            "Global Domain trend vector values = ",global_vector
       write(6,'(a,/)') &
            "Exact Domain trend reverse-route roundtrip passed"
    end if

    deallocate(vector_reference)
    deallocate(scalar_reference)

  contains

    subroutine check_roundtrip

      implicit none

      call exchange_domain_to_block_payloads( &
           BLOCK_PAYLOAD_TREND,.true.)
      scalar_reference = block_writeback_plan%scalar_recv_buffer
      vector_reference = block_writeback_plan%vector_recv_buffer

      call MPI_Alltoallv( &
           block_writeback_plan%scalar_send_buffer, &
           block_writeback_plan%scalar_send_count, &
           block_writeback_plan%scalar_send_displ, &
           MPI_DOUBLE_PRECISION, &
           block_writeback_plan%scalar_recv_buffer, &
           block_writeback_plan%scalar_recv_count, &
           block_writeback_plan%scalar_recv_displ, &
           MPI_DOUBLE_PRECISION,comm,ierr)
      call check_mpi(ierr,"MPI_Alltoallv scalar trend echo")

      call MPI_Alltoallv( &
           block_writeback_plan%vector_send_buffer, &
           block_writeback_plan%vector_send_count, &
           block_writeback_plan%vector_send_displ, &
           MPI_DOUBLE_PRECISION, &
           block_writeback_plan%vector_recv_buffer, &
           block_writeback_plan%vector_recv_count, &
           block_writeback_plan%vector_recv_displ, &
           MPI_DOUBLE_PRECISION,comm,ierr)
      call check_mpi(ierr,"MPI_Alltoallv vector trend echo")

      if (any(abs(block_writeback_plan%scalar_recv_buffer - &
           scalar_reference) > 0.0_dp)) then
         call fail("scalar Domain trend roundtrip mismatch")
      end if
      if (any(abs(block_writeback_plan%vector_recv_buffer - &
           vector_reference) > 0.0_dp)) then
         call fail("vector Domain trend roundtrip mismatch")
      end if

    end subroutine check_roundtrip

  end subroutine check_domain_trend_roundtrip


  subroutine import_domain_trend_to_block_tendency ( &
       validate_exact,imported_patch_count)
    ! Import the complete Domain trend layout into persistent final-owner
    ! tendency storage. Soil-level slots are the explicit zeros packed by
    ! the Stage 78 field-layout transport. Production callers can request
    ! direct exact patch validation without allocating diagnostic copies.

    implicit none

    logical, optional, intent(in) :: validate_exact
    integer(int64), optional, intent(out) :: imported_patch_count

    integer :: b
    integer :: d
    integer :: local_index
    integer :: local_patch
    integer :: n_patch
    integer :: pos_scalar
    integer :: pos_vector
    integer :: r
    integer :: slot

    logical :: exact_validation
    logical :: plan_ready

    integer(int64) :: patch_count

    exact_validation = .false.
    if (present(validate_exact)) exact_validation = validate_exact
    patch_count = 0_int64

    plan_ready = block_writeback_plan_is_ready()
    if (.not. plan_ready) then
       call fail("trend tendency import before plan is ready")
    end if
    if (.not. allocated(ghost_exchange_plan%scalar_patch_buffer)) then
       call fail("retained scalar trend import buffer is not allocated")
    end if
    if (.not. allocated(ghost_exchange_plan%vector_patch_buffer)) then
       call fail("retained vector trend import buffer is not allocated")
    end if
    if (size(ghost_exchange_plan%scalar_patch_buffer) /= &
         block_writeback_plan%scalar_patch_nvalue .or. &
         size(ghost_exchange_plan%vector_patch_buffer) /= &
         block_writeback_plan%vector_patch_nvalue) then
       call fail("retained trend import patch layout mismatch")
    end if

    call exchange_domain_to_block_payloads(BLOCK_PAYLOAD_TREND)
    call begin_local_block_tendency_import

    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       r = source_rank(b)
       if (r /= rank) cycle

       d = loc_id(block_catalog(b)%root_domain+1) + 1
       if (d < 1 .or. d > size(grid)) then
          call fail("retained trend import Domain is invalid")
       end if
       local_patch = 0
       call import_retained_subtree( &
            d,block_catalog(b)%root_patch,b,local_patch)
       n_patch = local_block_patch_count(b)
       if (local_patch /= n_patch) then
          call fail("retained trend import patch coverage mismatch")
       end if
    end do

    do r = 1,n_process
       pos_scalar = block_writeback_plan%scalar_send_displ(r) + 1
       pos_vector = block_writeback_plan%vector_send_displ(r) + 1

       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)
          b = block_writeback_plan%send_block(slot)
          n_patch = local_block_patch_count(b)

          do local_patch = 0,n_patch-1
             if (pos_scalar < 1 .or. pos_scalar + &
                  block_writeback_plan%scalar_patch_nvalue - 1 > &
                  size(block_writeback_plan%scalar_send_buffer) .or. &
                  pos_vector < 1 .or. pos_vector + &
                  block_writeback_plan%vector_patch_nvalue - 1 > &
                  size(block_writeback_plan%vector_send_buffer)) then
                call fail("remote trend import payload is truncated")
             end if

             call set_local_block_tendency_patch_values( &
                  b,local_patch, &
                  block_writeback_plan%scalar_send_buffer( &
                  pos_scalar:pos_scalar+ &
                  block_writeback_plan%scalar_patch_nvalue-1), &
                  block_writeback_plan%vector_send_buffer( &
                  pos_vector:pos_vector+ &
                  block_writeback_plan%vector_patch_nvalue-1))
             pos_scalar = pos_scalar + &
                  block_writeback_plan%scalar_patch_nvalue
             pos_vector = pos_vector + &
                  block_writeback_plan%vector_patch_nvalue
          end do
       end do

       if (pos_scalar /= block_writeback_plan%scalar_send_displ(r) + &
            block_writeback_plan%scalar_send_count(r) + 1 .or. &
            pos_vector /= block_writeback_plan%vector_send_displ(r) + &
            block_writeback_plan%vector_send_count(r) + 1) then
          call fail("remote trend import receive extent mismatch")
       end if
    end do

    call finish_local_block_tendency_import
    if (local_block_tendency_import_is_active()) then
       call fail("trend tendency import remained active")
    end if
    if (exact_validation) call validate_imported_patches
    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       patch_count = patch_count + &
            int(local_block_patch_count(b),int64)
    end do
    if (present(imported_patch_count)) then
       imported_patch_count = patch_count
    end if

  contains

    subroutine validate_imported_patches

      implicit none

      integer :: local_patch_index

      do local_index = 1,n_local_blocks()
         b = local_block_catalog(local_index)
         r = source_rank(b)
         if (r /= rank) cycle
         d = loc_id(block_catalog(b)%root_domain+1) + 1
         local_patch_index = 0
         call assert_retained_subtree( &
              d,block_catalog(b)%root_patch,b,local_patch_index)
         if (local_patch_index /= local_block_patch_count(b)) then
            call fail("retained trend validation coverage mismatch")
         end if
      end do

      do r = 1,n_process
         pos_scalar = block_writeback_plan%scalar_send_displ(r) + 1
         pos_vector = block_writeback_plan%vector_send_displ(r) + 1
         do slot = block_writeback_plan%send_displ(r)+1, &
              block_writeback_plan%send_displ(r) + &
              block_writeback_plan%send_count(r)
            b = block_writeback_plan%send_block(slot)
            n_patch = local_block_patch_count(b)
            do local_patch_index = 0,n_patch-1
               call assert_local_block_tendency_patch_values( &
                    b,local_patch_index, &
                    block_writeback_plan%scalar_send_buffer( &
                    pos_scalar:pos_scalar+ &
                    block_writeback_plan%scalar_patch_nvalue-1), &
                    block_writeback_plan%vector_send_buffer( &
                    pos_vector:pos_vector+ &
                    block_writeback_plan%vector_patch_nvalue-1))
               pos_scalar = pos_scalar + &
                    block_writeback_plan%scalar_patch_nvalue
               pos_vector = pos_vector + &
                    block_writeback_plan%vector_patch_nvalue
            end do
         end do
         if (pos_scalar /= block_writeback_plan%scalar_send_displ(r) + &
              block_writeback_plan%scalar_send_count(r) + 1 .or. &
              pos_vector /= block_writeback_plan%vector_send_displ(r) + &
              block_writeback_plan%vector_send_count(r) + 1) then
            call fail("remote trend validation extent mismatch")
         end if
      end do

    end subroutine validate_imported_patches


    recursive subroutine assert_retained_subtree ( &
         d,p,b,local_patch_index)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(in) :: b
      integer, intent(inout) :: local_patch_index

      integer :: c
      integer :: p_child
      integer :: scalar_pos
      integer :: vector_pos

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("retained trend validation patch is invalid")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return

      scalar_pos = 1
      vector_pos = 1
      call pack_domain_patch_prognostic( &
           d,p,BLOCK_PAYLOAD_TREND, &
           ghost_exchange_plan%scalar_patch_buffer,scalar_pos, &
           ghost_exchange_plan%vector_patch_buffer,vector_pos)
      if (scalar_pos /= &
           size(ghost_exchange_plan%scalar_patch_buffer)+1 .or. &
           vector_pos /= &
           size(ghost_exchange_plan%vector_patch_buffer)+1) then
         call fail("retained trend validation extent mismatch")
      end if
      call assert_local_block_tendency_patch_values( &
           b,local_patch_index, &
           ghost_exchange_plan%scalar_patch_buffer, &
           ghost_exchange_plan%vector_patch_buffer)
      local_patch_index = local_patch_index + 1

      do c = 1,N_CHDRN
         p_child = grid(d)%patch%elts(p+1)%children(c)
         if (p_child <= 0) cycle
         call assert_retained_subtree( &
              d,p_child,b,local_patch_index)
      end do

    end subroutine assert_retained_subtree

    recursive subroutine import_retained_subtree ( &
         d,p,b,local_patch)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(in) :: b
      integer, intent(inout) :: local_patch

      integer :: c
      integer :: p_child
      integer :: scalar_pos
      integer :: vector_pos

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("retained trend import patch is invalid")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return

      scalar_pos = 1
      vector_pos = 1
      call pack_domain_patch_prognostic( &
           d,p,BLOCK_PAYLOAD_TREND, &
           ghost_exchange_plan%scalar_patch_buffer,scalar_pos, &
           ghost_exchange_plan%vector_patch_buffer,vector_pos)
      if (scalar_pos /= &
           size(ghost_exchange_plan%scalar_patch_buffer)+1 .or. &
           vector_pos /= &
           size(ghost_exchange_plan%vector_patch_buffer)+1) then
         call fail("retained trend import patch extent mismatch")
      end if
      call set_local_block_tendency_patch_values( &
           b,local_patch,ghost_exchange_plan%scalar_patch_buffer, &
           ghost_exchange_plan%vector_patch_buffer)
      local_patch = local_patch + 1

      do c = 1,N_CHDRN
         p_child = grid(d)%patch%elts(p+1)%children(c)
         if (p_child <= 0) cycle
         call import_retained_subtree(d,p_child,b,local_patch)
      end do

    end subroutine import_retained_subtree

  end subroutine import_domain_trend_to_block_tendency


  subroutine check_domain_trend_tendency_import (verbose)
    ! Validate exact imported patch values and repeated persistent reuse.

    implicit none

    logical, optional, intent(in) :: verbose

    integer :: ierr

    integer(int64) :: global_patch
    integer(int64) :: import_allocation_after_first
    integer(int64) :: import_allocation_before
    integer(int64) :: local_patch
    integer(int64) :: tendency_allocation_after_first
    integer(int64) :: tendency_allocation_before
    integer(int64) :: writeback_allocation_before

    logical :: print_summary

    real(dp), allocatable :: actual_scalar(:)
    real(dp), allocatable :: actual_vector(:)
    real(dp), allocatable :: expected_scalar(:)
    real(dp), allocatable :: expected_vector(:)

    print_summary = .true.
    if (present(verbose)) print_summary = verbose

    allocate(actual_scalar(block_writeback_plan%scalar_patch_nvalue))
    allocate(actual_vector(block_writeback_plan%vector_patch_nvalue))
    allocate(expected_scalar(block_writeback_plan%scalar_patch_nvalue))
    allocate(expected_vector(block_writeback_plan%vector_patch_nvalue))

    tendency_allocation_before = &
         local_block_tendency_allocation_count()
    import_allocation_before = &
         local_block_tendency_import_allocation_count()
    writeback_allocation_before = &
         block_writeback_plan_allocation_count()

    call import_domain_trend_to_block_tendency
    call validate_imported_tendency(local_patch)
    tendency_allocation_after_first = &
         local_block_tendency_allocation_count()
    import_allocation_after_first = &
         local_block_tendency_import_allocation_count()

    call import_domain_trend_to_block_tendency
    call validate_imported_tendency(local_patch)

    if (local_block_tendency_allocation_count() /= &
         tendency_allocation_after_first) then
       call fail("repeated trend import reallocated tendency arrays")
    end if
    if (local_block_tendency_import_allocation_count() /= &
         import_allocation_after_first) then
       call fail("repeated trend import reallocated coverage storage")
    end if
    if (tendency_allocation_after_first < &
         tendency_allocation_before .or. &
         import_allocation_after_first < import_allocation_before) then
       call fail("trend import allocation count regressed")
    end if
    if (block_writeback_plan_allocation_count() /= &
         writeback_allocation_before) then
       call fail("trend import reallocated transport buffers")
    end if

    call MPI_Allreduce(local_patch,global_patch,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce imported trend patches")

    if (print_summary) then
       write(6,'(/,a,i0,a)') &
            "Domain trend tendency import for rank ",rank,":"
       write(6,'(a,i0)') "  imported patches = ",local_patch
       write(6,'(a)') "  exact scalar tendency patch comparison passed"
       write(6,'(a)') "  exact vector tendency patch comparison passed"
       write(6,'(a)') "  complete import transaction passed"
       write(6,'(a,/)') "  repeated tendency import reuse passed"
    end if

    if (print_summary .and. rank == 0) then
       write(6,'(/,a,i0)') &
            "Global imported Domain trend patches = ",global_patch
       write(6,'(a,/)') &
            "Exact Domain trend-to-block tendency import passed"
    end if

    deallocate(expected_vector)
    deallocate(expected_scalar)
    deallocate(actual_vector)
    deallocate(actual_scalar)

  contains

    subroutine validate_imported_tendency (patch_count)

      implicit none

      integer(int64), intent(out) :: patch_count

      integer :: b
      integer :: d
      integer :: local_index
      integer :: local_patch_index
      integer :: n_patch
      integer :: pos_scalar
      integer :: pos_vector
      integer :: r
      integer :: slot

      patch_count = 0_int64

      do local_index = 1,n_local_blocks()
         b = local_block_catalog(local_index)
         r = source_rank(b)
         if (r /= rank) cycle
         d = loc_id(block_catalog(b)%root_domain+1) + 1
         local_patch_index = 0
         call compare_retained_subtree( &
              d,block_catalog(b)%root_patch,b,local_patch_index)
         n_patch = local_block_patch_count(b)
         if (local_patch_index /= n_patch) then
            call fail("retained imported trend coverage mismatch")
         end if
         patch_count = patch_count + int(n_patch,int64)
      end do

      do r = 1,n_process
         pos_scalar = block_writeback_plan%scalar_send_displ(r) + 1
         pos_vector = block_writeback_plan%vector_send_displ(r) + 1
         do slot = block_writeback_plan%send_displ(r)+1, &
              block_writeback_plan%send_displ(r) + &
              block_writeback_plan%send_count(r)
            b = block_writeback_plan%send_block(slot)
            n_patch = local_block_patch_count(b)
            do local_patch_index = 0,n_patch-1
               if (pos_scalar < 1 .or. &
                    pos_scalar+size(actual_scalar)-1 > &
                    size(block_writeback_plan%scalar_send_buffer) .or. &
                    pos_vector < 1 .or. &
                    pos_vector+size(actual_vector)-1 > &
                    size(block_writeback_plan%vector_send_buffer)) then
                  call fail("remote imported trend payload is truncated")
               end if
               call get_local_block_tendency_patch_values( &
                    b,local_patch_index,actual_scalar,actual_vector)
               if (any(abs(actual_scalar - &
                    block_writeback_plan%scalar_send_buffer( &
                    pos_scalar:pos_scalar+size(actual_scalar)-1)) > &
                    0.0_dp)) then
                  call fail("remote imported scalar trend mismatch")
               end if
               if (any(abs(actual_vector - &
                    block_writeback_plan%vector_send_buffer( &
                    pos_vector:pos_vector+size(actual_vector)-1)) > &
                    0.0_dp)) then
                  call fail("remote imported vector trend mismatch")
               end if
               pos_scalar = pos_scalar + size(actual_scalar)
               pos_vector = pos_vector + size(actual_vector)
            end do
            patch_count = patch_count + int(n_patch,int64)
         end do
         if (pos_scalar /= &
              block_writeback_plan%scalar_send_displ(r) + &
              block_writeback_plan%scalar_send_count(r) + 1 .or. &
              pos_vector /= &
              block_writeback_plan%vector_send_displ(r) + &
              block_writeback_plan%vector_send_count(r) + 1) then
            call fail("remote imported trend validation extent mismatch")
         end if
      end do

    end subroutine validate_imported_tendency


    recursive subroutine compare_retained_subtree ( &
         d,p,b,local_patch_index)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(in) :: b
      integer, intent(inout) :: local_patch_index

      integer :: c
      integer :: p_child
      integer :: scalar_pos
      integer :: vector_pos

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("retained imported trend patch is invalid")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return

      scalar_pos = 1
      vector_pos = 1
      call pack_domain_patch_prognostic( &
           d,p,BLOCK_PAYLOAD_TREND,expected_scalar,scalar_pos, &
           expected_vector,vector_pos)
      if (scalar_pos /= size(expected_scalar)+1 .or. &
           vector_pos /= size(expected_vector)+1) then
         call fail("retained imported trend validation extent mismatch")
      end if
      call get_local_block_tendency_patch_values( &
           b,local_patch_index,actual_scalar,actual_vector)
      if (any(abs(actual_scalar-expected_scalar) > 0.0_dp)) then
         call fail("retained imported scalar trend mismatch")
      end if
      if (any(abs(actual_vector-expected_vector) > 0.0_dp)) then
         call fail("retained imported vector trend mismatch")
      end if
      local_patch_index = local_patch_index + 1

      do c = 1,N_CHDRN
         p_child = grid(d)%patch%elts(p+1)%children(c)
         if (p_child <= 0) cycle
         call compare_retained_subtree( &
              d,p_child,b,local_patch_index)
      end do

    end subroutine compare_retained_subtree

  end subroutine check_domain_trend_tendency_import


  subroutine begin_block_domain_trend_step (scale)
    ! Form one reversible Euler candidate from the current Domain trend.

    implicit none

    real(dp), intent(in) :: scale

    logical :: checkpoint_ready
    logical :: plan_ready
    logical :: store_ready
    logical :: tendency_ready
    logical :: trial_active

    store_ready = local_block_store_ready()
    plan_ready = block_writeback_plan_is_ready()
    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    if (.not. store_ready .or. .not. plan_ready) then
       call fail("Domain-trend block step before persistent state is ready")
    end if
    if (trial_active .or. checkpoint_ready) then
       call fail("Domain-trend block step found a pending transaction")
    end if

    call import_domain_trend_to_block_tendency
    call begin_local_block_tendency_trial(scale)
    call commit_local_block_tendency_trial

    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    tendency_ready = local_block_tendency_state_ready()
    if (trial_active .or. .not. checkpoint_ready) then
       call fail("Domain-trend block step did not retain its checkpoint")
    end if
    if (tendency_ready) then
       call fail("Domain-trend block step retained stale tendencies")
    end if

  end subroutine begin_block_domain_trend_step


  subroutine complete_block_domain_trend_step (accept)
    ! Resolve the checkpoint produced by begin_block_domain_trend_step.

    implicit none

    logical, intent(in) :: accept

    ! The existing two-stage resolver is deliberately state-generic: it
    ! commits or restores any pending block-sol checkpoint transaction.
    call complete_block_two_stage_tendency_step(accept)

  end subroutine complete_block_domain_trend_step


  subroutine advance_block_domain_trend_euler (scale)
    ! Accept one actual Domain-trend block Euler update and synchronize the
    ! resulting sol image transactionally to authoritative Domain owners.

    implicit none

    real(dp), intent(in) :: scale

    integer :: ierr

    integer(int64) :: global_changed_block_count(2)
    integer(int64) :: import_allocation_before
    integer(int64) :: local_changed_block_count(2)
    integer(int64) :: production_writeback_before
    integer(int64) :: tendency_allocation_before
    integer(int64) :: writeback_allocation_before

    logical :: checkpoint_ready
    logical :: state_ready
    logical :: trial_active

    real(dp) :: global_max_update(2)
    real(dp) :: local_max_update(2)

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail("production block Euler step before state is ready")
    end if

    tendency_allocation_before = &
         local_block_tendency_allocation_count()
    import_allocation_before = &
         local_block_tendency_import_allocation_count()
    writeback_allocation_before = &
         block_writeback_plan_allocation_count()
    production_writeback_before = &
         block_domain_production_writeback_count()

    call begin_block_domain_trend_step(scale)
    call local_block_tendency_commit_checkpoint_statistics( &
         local_changed_block_count(1),local_changed_block_count(2), &
         local_max_update(1),local_max_update(2))
    call complete_block_domain_trend_step(.true.)

    call assert_block_domain_field_family_match(BLOCK_PAYLOAD_SOL)
    call assert_block_domain_field_family_match(BLOCK_PAYLOAD_WAV_COEFF)

    if (local_block_tendency_allocation_count() /= &
         tendency_allocation_before) then
       call fail("production block Euler step reallocated tendency arrays")
    end if
    if (local_block_tendency_import_allocation_count() /= &
         import_allocation_before) then
       call fail("production block Euler step reallocated import coverage")
    end if
    if (block_writeback_plan_allocation_count() /= &
         writeback_allocation_before) then
       call fail("production block Euler step reallocated transport storage")
    end if
    if (block_domain_production_writeback_count() /= &
         production_writeback_before + 1_int64) then
       call fail("production block Euler writeback count is invalid")
    end if

    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    if (trial_active .or. checkpoint_ready) then
       call fail("production block Euler step left a pending transaction")
    end if

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail("production block Euler step invalidated persistent state")
    end if

    call MPI_Allreduce( &
         local_changed_block_count,global_changed_block_count,2, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce accepted block Euler coverage")
    call MPI_Allreduce(local_max_update,global_max_update,2, &
         MPI_DOUBLE_PRECISION,MPI_MAX,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce accepted block Euler update")

    block_writeback_plan%production_euler_step_count = &
         block_writeback_plan%production_euler_step_count + 1_int64

    if (rank == 0) then
       write(6,'(/,a,i0)') &
            "Accepted production block Euler timestep number = ", &
            block_writeback_plan%production_euler_step_count
       write(6,'(a,es14.6)') "  timestep scale = ",scale
       write(6,'(a,i0)') "  scalar changed blocks = ", &
            global_changed_block_count(1)
       write(6,'(a,i0)') "  vector changed blocks = ", &
            global_changed_block_count(2)
       write(6,'(a,es14.6)') "  scalar maximum update = ", &
            global_max_update(1)
       write(6,'(a,es14.6)') "  vector maximum update = ", &
            global_max_update(2)
       write(6,'(a)') &
            "  accepted sol synchronized exactly to Domain owners"
       write(6,'(a)') &
            "  wav_coeff remained exact before wavelet transform"
       write(6,'(a,/)') &
            "Production block Euler timestep accepted"
    end if

  end subroutine advance_block_domain_trend_euler


  subroutine capture_block_domain_multistage_candidate_tendency ( &
       stage,stage_count,domain_sol)
    ! Compute one complete block-native RK tendency, compare every compact
    ! patch exactly with the authoritative Domain tendency, and retain the
    ! native result in the persistent stage register. For stages after the
    ! first, restore the timestep-start state after the native tendency has
    ! been secured independently of the pending field checkpoint.

    implicit none

    integer, intent(in) :: stage
    integer, intent(in) :: stage_count
    type(Float_Field), intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)

    logical :: accumulator_ready
    logical :: checkpoint_ready
    logical :: state_ready
    logical :: tendency_ready
    logical :: trial_active

    character(len=3) :: scheme_name

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail("multistage tendency capture before state is ready")
    end if
    if (stage_count /= 3 .and. stage_count /= 4) then
       call fail("multistage tendency capture stage count is invalid")
    end if
    if (stage < 1 .or. stage > stage_count) then
       call fail("multistage tendency capture stage is invalid")
    end if
    if (production_multistage_candidate_stage /= stage-1 .or. &
         production_multistage_captured_tendency_stage /= 0 .or. &
         production_multistage_native_candidate_stage /= 0) then
       call fail("multistage tendency capture sequence is invalid")
    end if
    if (block_writeback_plan%native_stage_ready) then
       call fail("multistage tendency capture found retained candidate")
    end if

    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (trial_active .or. tendency_ready .or. accumulator_ready) then
       call fail("multistage tendency capture found pending output")
    end if

    if (stage == 1) then
       if (checkpoint_ready) then
          call fail("multistage tendency capture found a checkpoint")
       end if
       if (block_writeback_plan% &
            production_multistage_boundary_refresh_count /= 0_int64) then
          call fail("multistage tendency boundary state was not finalized")
       end if
       production_multistage_candidate_stage_count = stage_count
       call assert_block_domain_field_family_match(BLOCK_PAYLOAD_SOL)
       call assert_block_domain_field_family_match( &
            BLOCK_PAYLOAD_WAV_COEFF)
       production_multistage_tendency_allocation_before = &
            local_block_tendency_allocation_count()
       production_multistage_accumulator_allocation_before = &
            local_block_tendency_accumulator_allocation_count()
       production_multistage_import_allocation_before = &
            local_block_tendency_import_allocation_count()
       production_multistage_writeback_allocation_before = &
            block_writeback_plan_allocation_count()
       production_multistage_stage_allocation_before = &
            block_writeback_plan%stage_allocations
       production_multistage_writeback_before = &
            block_domain_production_writeback_count()
       call evaluate_candidate_block_velocity_recomposition( &
            domain_sol,.false.)
    else
       if (production_multistage_candidate_stage_count /= stage_count) then
          call fail("multistage tendency capture method changed")
       end if
       if (block_writeback_plan% &
            production_multistage_boundary_refresh_count /= &
            int(stage-1,int64)) then
          call fail("multistage tendency boundary was not refreshed")
       end if
       if (.not. checkpoint_ready) then
          call fail("multistage tendency capture has no checkpoint")
       end if
       call evaluate_candidate_block_velocity_recomposition( &
            domain_sol,.true.)
       call complete_block_domain_trend_step(.false.)
    end if

    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    trial_active = local_block_tendency_trial_is_active()
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (checkpoint_ready .or. trial_active .or. tendency_ready .or. &
         .not. accumulator_ready) then
       call fail("multistage native tendency retention is invalid")
    end if
    if (local_block_tendency_allocation_count() /= &
         production_multistage_tendency_allocation_before .or. &
         local_block_tendency_accumulator_allocation_count() /= &
         production_multistage_accumulator_allocation_before) then
       call fail("multistage tendency capture reallocated workspace")
    end if
    if (block_writeback_plan_allocation_count() /= &
         production_multistage_writeback_allocation_before) then
       call fail("multistage tendency capture reallocated transport")
    end if
    if (block_domain_production_writeback_count() /= &
         production_multistage_writeback_before + &
         int(stage-1,int64)) then
       call fail("multistage tendency capture writeback sequence is invalid")
    end if

    production_multistage_captured_tendency_stage = stage
    if (stage_count == 3) then
       scheme_name = "RK3"
    else
       scheme_name = "RK4"
    end if
    if (rank == 0) then
       write(6,'(/,a,a,a,i0,a,i0)') &
            "Captured production block ",scheme_name, &
            " validated native tendency stage = ",stage," of ",stage_count
    end if

  end subroutine capture_block_domain_multistage_candidate_tendency


  subroutine begin_block_domain_multistage_candidate_stage ( &
       scale,stage,stage_count)
    ! Consume one roundoff-bounded validated block-native tendency from the
    ! persistent stage register and form a retained provisional low-storage
    ! RK3 or RK4 candidate. Every stage remains based on the retained
    ! timestep-start block state and remains reversible until the guard.

    implicit none

    real(dp), intent(in) :: scale
    integer, intent(in) :: stage
    integer, intent(in) :: stage_count

    logical :: accumulator_ready
    logical :: checkpoint_ready
    logical :: state_ready
    logical :: tendency_ready
    logical :: trial_active

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail( &
            "production multistage block candidate before state is ready")
    end if
    if (stage_count /= 3 .and. stage_count /= 4) then
       call fail("production block candidate stage count is invalid")
    end if
    if (stage < 1 .or. stage > stage_count) then
       call fail("production multistage block candidate stage is invalid")
    end if
    if (production_multistage_candidate_stage /= stage-1) then
       call fail( &
            "production multistage block candidate sequence is invalid")
    end if
    if (production_multistage_candidate_stage_count /= stage_count .or. &
         production_multistage_captured_tendency_stage /= stage .or. &
         production_multistage_native_candidate_stage /= 0) then
       call fail( &
            "production multistage native tendency was not retained")
    end if

    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (trial_active .or. checkpoint_ready .or. tendency_ready .or. &
         .not. accumulator_ready) then
       call fail( &
            "production multistage native tendency state is invalid")
    end if

    call begin_local_block_accumulated_tendency_trial(scale)
    call commit_local_block_tendency_trial
    call discard_local_block_tendency_accumulator
    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (trial_active .or. .not. checkpoint_ready .or. tendency_ready .or. &
         accumulator_ready) then
       call fail( &
            "production native block candidate state is invalid")
    end if

    production_multistage_captured_tendency_stage = 0
    production_multistage_native_candidate_stage = stage

  end subroutine begin_block_domain_multistage_candidate_stage


  subroutine retain_native_multistage_candidate_snapshot ( &
       stage,stage_count)
    ! Preserve the complete reconstructed native candidate so the following
    ! Domain wavelet transform cannot silently alter transaction-owned blocks.

    implicit none

    integer, intent(in) :: stage
    integer, intent(in) :: stage_count

    if (block_writeback_plan%native_stage_ready) then
       call fail("native multistage snapshot is already retained")
    end if
    if (stage_count /= 3 .and. stage_count /= 4) then
       call fail("native multistage snapshot stage count is invalid")
    end if
    if (stage < 1 .or. stage > stage_count) then
       call fail("native multistage snapshot stage is invalid")
    end if

    call reconstruct_block_writeback_domain_stage(BLOCK_PAYLOAD_SOL)
    block_writeback_plan%native_scalar_stage = &
         block_writeback_plan%scalar_domain_stage
    block_writeback_plan%native_vector_stage = &
         block_writeback_plan%vector_domain_stage
    block_writeback_plan%native_stage = stage
    block_writeback_plan%native_stage_count = stage_count
    block_writeback_plan%native_stage_ready = .true.

  end subroutine retain_native_multistage_candidate_snapshot


  subroutine consume_native_multistage_candidate_snapshot ( &
       stage,stage_count)
    ! Verify exact retention across the caller-controlled interval (including
    ! the Domain wavelet boundary for intermediate stages), then release the
    ! snapshot for reuse by the next RK stage.

    implicit none

    integer, intent(in) :: stage
    integer, intent(in) :: stage_count

    if (.not. block_writeback_plan%native_stage_ready .or. &
         block_writeback_plan%native_stage /= stage .or. &
         block_writeback_plan%native_stage_count /= stage_count) then
       call fail("native multistage snapshot sequence is invalid")
    end if

    call reconstruct_block_writeback_domain_stage(BLOCK_PAYLOAD_SOL)
    if (any(abs(block_writeback_plan%scalar_domain_stage - &
         block_writeback_plan%native_scalar_stage) > 0.0_dp)) then
       call fail("native scalar candidate changed across wavelet boundary")
    end if
    if (any(abs(block_writeback_plan%vector_domain_stage - &
         block_writeback_plan%native_vector_stage) > 0.0_dp)) then
       call fail("native vector candidate changed across wavelet boundary")
    end if

    block_writeback_plan%native_stage = 0
    block_writeback_plan%native_stage_count = 0
    block_writeback_plan%native_stage_ready = .false.

  end subroutine consume_native_multistage_candidate_snapshot


  subroutine retain_block_native_multistage_candidate ( &
       domain_sol,stage,stage_count)
    ! Validate one block-native pre-wavelet RK candidate against the
    ! independently evaluated authoritative Domain stage, then retain the
    ! complete native candidate and its reversible timestep-start checkpoint,
    ! then install the validated native stage as the following wavelet input.

    implicit none

    type(Float_Field), intent(inout) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    integer, intent(in) :: stage
    integer, intent(in) :: stage_count

    integer(int64) :: production_writeback_before
    integer(int64) :: writeback_allocation_before

    logical :: accumulator_ready
    logical :: checkpoint_ready
    logical :: state_ready
    logical :: tendency_ready
    logical :: trial_active

    character(len=3) :: scheme_name

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail("native multistage retention before state is ready")
    end if
    if (stage_count /= 3 .and. stage_count /= 4) then
       call fail("native multistage retention stage count is invalid")
    end if
    if (stage < 1 .or. stage > stage_count) then
       call fail("native multistage retention stage is invalid")
    end if
    if (production_multistage_candidate_stage_count /= stage_count .or. &
         production_multistage_candidate_stage /= stage-1 .or. &
         production_multistage_native_candidate_stage /= stage) then
       call fail("native multistage retention sequence is invalid")
    end if

    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (trial_active .or. .not. checkpoint_ready .or. tendency_ready .or. &
         accumulator_ready) then
       call fail("native multistage retention state is invalid")
    end if

    writeback_allocation_before = &
         block_writeback_plan_allocation_count()
    production_writeback_before = &
         block_domain_production_writeback_count()
    call assert_block_domain_field_family_match( &
         BLOCK_PAYLOAD_SOL,domain_sol, &
         integrated_only=.true., &
         comparison_name="native", &
         roundoff_tolerant=.true.)
    call retain_native_multistage_candidate_snapshot(stage,stage_count)
    call write_block_field_family_to_domains( &
         BLOCK_PAYLOAD_SOL,domain_sol)
    call assert_block_domain_field_family_match( &
         BLOCK_PAYLOAD_SOL,domain_sol)

    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (trial_active .or. .not. checkpoint_ready .or. tendency_ready .or. &
         accumulator_ready) then
       call fail("native multistage transaction was not retained")
    end if
    if (local_block_tendency_allocation_count() /= &
         production_multistage_tendency_allocation_before .or. &
         local_block_tendency_import_allocation_count() /= &
         production_multistage_import_allocation_before) then
       call fail("native multistage retention reallocated workspace")
    end if
    if (block_writeback_plan_allocation_count() /= &
         writeback_allocation_before) then
       call fail("native multistage retention reallocated transport")
    end if
    if (block_writeback_plan%stage_allocations /= &
         production_multistage_stage_allocation_before) then
       call fail("native multistage retention reallocated snapshot storage")
    end if
    if (block_domain_production_writeback_count() /= &
         production_writeback_before + 1_int64) then
       call fail("native multistage stage writeback count is invalid")
    end if

    production_multistage_native_candidate_stage = 0
    production_multistage_candidate_stage = stage
    if (stage_count == 3) then
       scheme_name = "RK3"
    else
       scheme_name = "RK4"
    end if
    if (rank == 0) then
       write(6,'(/,a,a,a,i0,a,i0)') &
            "Retained production block ",scheme_name, &
            " validated candidate for wavelet input: stage = ", &
            stage," of ",stage_count
    end if

  end subroutine retain_block_native_multistage_candidate


  subroutine prepare_block_native_multistage_wavelet_acceptance ( &
       stage_count)
    ! Consume the exact final pre-wavelet SOL snapshot before WT_after_step
    ! performs its legitimate level_start-1 velocity restriction. Keep the
    ! rollback checkpoint live so acceptance can remain conditional on the
    ! subsequent uncompressed scalar-wavelet comparison.

    implicit none

    integer, intent(in) :: stage_count

    logical :: checkpoint_ready
    logical :: state_ready
    logical :: trial_active

    if (stage_count /= 3 .and. stage_count /= 4) then
       call fail("wavelet acceptance stage count is invalid")
    end if
    if (production_multistage_candidate_stage_count /= stage_count .or. &
         production_multistage_candidate_stage /= stage_count .or. &
         production_multistage_captured_tendency_stage /= 0 .or. &
         production_multistage_native_candidate_stage /= 0) then
       call fail("wavelet acceptance candidate is incomplete")
    end if
    if (production_multistage_final_snapshot_consumed) then
       call fail("wavelet acceptance snapshot was already consumed")
    end if

    state_ready = parallel_block_state_is_ready()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    trial_active = local_block_tendency_trial_is_active()
    if (.not. state_ready .or. trial_active .or. .not. checkpoint_ready) then
       call fail("wavelet acceptance transaction is not ready")
    end if
    if (.not. block_writeback_plan%native_stage_ready .or. &
         block_writeback_plan%native_stage /= stage_count .or. &
         block_writeback_plan%native_stage_count /= stage_count) then
       call fail("wavelet acceptance native snapshot is not ready")
    end if

    call consume_native_multistage_candidate_snapshot( &
         stage_count,stage_count)
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    if (.not. checkpoint_ready .or. &
         block_writeback_plan%native_stage_ready) then
       call fail("wavelet acceptance snapshot boundary is invalid")
    end if
    production_multistage_final_snapshot_consumed = .true.

  end subroutine prepare_block_native_multistage_wavelet_acceptance


  subroutine accept_block_native_multistage_candidate (stage_count)
    ! Accept the retained final native candidate after its scalar-wavelet
    ! guard. The exact pre-restriction SOL snapshot has already been consumed;
    ! close the reversible timestep-start checkpoint only after the guarded
    ! uncompressed transform is complete.

    implicit none

    integer, intent(in) :: stage_count

    integer :: ierr

    integer(int64) :: global_changed_block_count(2)
    integer(int64) :: local_changed_block_count(2)

    logical :: checkpoint_ready
    logical :: state_ready
    logical :: trial_active

    real(dp) :: global_max_update(2)
    real(dp) :: local_max_update(2)

    character(len=3) :: scheme_name

    if (stage_count /= 3 .and. stage_count /= 4) then
       call fail("accepted production block candidate stage count is invalid")
    end if
    if (production_multistage_candidate_stage_count /= stage_count .or. &
         production_multistage_candidate_stage /= stage_count .or. &
         production_multistage_captured_tendency_stage /= 0 .or. &
         production_multistage_native_candidate_stage /= 0) then
       call fail("production multistage block candidate is incomplete")
    end if
    if (.not. production_multistage_final_snapshot_consumed .or. &
         block_writeback_plan%native_stage_ready) then
       call fail("production multistage snapshot boundary is incomplete")
    end if
    if (production_velocity_restriction_level /= level_start-1) then
       call fail("production velocity restriction is incomplete")
    end if
    if (.not. production_coarse_outer_wavelet_validated) then
       call fail("production coarse outer wavelet is incomplete")
    end if
    if (.not. production_complete_vector_wavelet_validated) then
       call fail("production complete vector wavelet is incomplete")
    end if
    if (production_pre_refinement_mask_pending) then
       call fail("previous pre-refinement mask validation is pending")
    end if
    if (block_writeback_plan% &
         production_multistage_boundary_refresh_count /= &
         int(stage_count-1,int64)) then
       call fail( &
            "production multistage boundary refresh is incomplete")
    end if
    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    if (trial_active .or. .not. checkpoint_ready) then
       call fail("production multistage final checkpoint is not ready")
    end if

    call local_block_tendency_commit_checkpoint_statistics( &
         local_changed_block_count(1),local_changed_block_count(2), &
         local_max_update(1),local_max_update(2))
    call finalize_local_block_tendency_commit
    call assert_block_domain_field_family_match(BLOCK_PAYLOAD_SOL)

    if (local_block_tendency_allocation_count() /= &
         production_multistage_tendency_allocation_before) then
       call fail( &
            "production multistage candidate reallocated tendency arrays")
    end if
    if (local_block_tendency_accumulator_allocation_count() /= &
         production_multistage_accumulator_allocation_before) then
       call fail( &
            "production multistage candidate reallocated stage register")
    end if
    if (local_block_tendency_import_allocation_count() /= &
         production_multistage_import_allocation_before) then
       call fail( &
            "production multistage candidate reallocated import coverage")
    end if
    if (block_writeback_plan_allocation_count() /= &
         production_multistage_writeback_allocation_before) then
       call fail( &
            "production multistage candidate reallocated transport storage")
    end if
    if (block_writeback_plan%stage_allocations /= &
         production_multistage_stage_allocation_before) then
       call fail( &
            "production multistage candidate reallocated snapshot storage")
    end if
    if (block_domain_production_writeback_count() /= &
         production_multistage_writeback_before + &
         int(stage_count,int64)) then
       call fail( &
            "accepted production multistage writeback count is invalid")
    end if
    if (local_block_tendency_trial_is_active() .or. &
         local_block_tendency_commit_checkpoint_is_ready()) then
       call fail( &
            "accepted production multistage transaction remained pending")
    end if
    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail( &
            "accepted production multistage invalidated persistent state")
    end if

    call MPI_Allreduce( &
         local_changed_block_count,global_changed_block_count,2, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce multistage candidate coverage")
    call MPI_Allreduce(local_max_update,global_max_update,2, &
         MPI_DOUBLE_PRECISION,MPI_MAX,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce multistage candidate update")

    if (stage_count == 3) then
       scheme_name = "RK3"
       block_writeback_plan%production_rk3_step_count = &
            block_writeback_plan%production_rk3_step_count + 1_int64
    else
       scheme_name = "RK4"
       block_writeback_plan%production_rk4_step_count = &
            block_writeback_plan%production_rk4_step_count + 1_int64
    end if
    production_pre_refinement_mask_pending = .true.
    production_multistage_candidate_stage = 0
    production_multistage_candidate_stage_count = 0
    production_multistage_captured_tendency_stage = 0
    production_multistage_native_candidate_stage = 0
    production_velocity_restriction_level = -1
    production_coarse_outer_wavelet_validated = .false.
    production_complete_vector_wavelet_validated = .false.
    production_multistage_final_snapshot_consumed = .false.
    production_multistage_stage_allocation_before = 0_int64
    block_writeback_plan%production_multistage_boundary_refresh_count = &
         0_int64

    if (rank == 0) then
       if (stage_count == 3) then
          write(6,'(/,a,a,a,i0)') &
               "Accepted production block ",scheme_name, &
               " timestep number = ", &
               block_writeback_plan%production_rk3_step_count
       else
          write(6,'(/,a,a,a,i0)') &
               "Accepted production block ",scheme_name, &
               " timestep number = ", &
               block_writeback_plan%production_rk4_step_count
       end if
       write(6,'(a,i0)') &
            "  completed candidate stages = ",stage_count
       write(6,'(a,i0)') &
            "  completed provisional boundary refreshes = ",stage_count-1
       write(6,'(a,i0)') "  scalar changed blocks = ", &
            global_changed_block_count(1)
       write(6,'(a,i0)') "  vector changed blocks = ", &
            global_changed_block_count(2)
       write(6,'(a,es14.6)') "  scalar maximum update = ", &
            global_max_update(1)
       write(6,'(a,es14.6)') "  vector maximum update = ", &
            global_max_update(2)
       write(6,'(a,a,a,/)') &
            "Production multistage block ",scheme_name, &
            " timestep accepted"
    end if

  end subroutine accept_block_native_multistage_candidate


  subroutine check_block_domain_trend_step (verbose)
    ! Validate a complete actual-trend Euler candidate, temporary Domain
    ! synchronization, exact rollback and repeated persistent reuse.

    implicit none

    logical, optional, intent(in) :: verbose

    integer :: ierr

    integer(int64) :: global_patch_count
    integer(int64) :: import_allocation_after_first
    integer(int64) :: local_patch_count
    integer(int64) :: production_writeback_before
    integer(int64) :: tendency_allocation_after_first
    integer(int64) :: writeback_allocation_after_first
    integer(int64) :: writeback_allocation_before

    logical :: checkpoint_ready
    logical :: print_summary
    logical :: trial_active

    real(dp), parameter :: validation_scale = 1.0_dp

    logical, allocatable :: candidate_patch(:)
    real(dp), allocatable :: baseline_scalar(:)
    real(dp), allocatable :: baseline_vector(:)
    real(dp), allocatable :: trend_scalar(:)
    real(dp), allocatable :: trend_vector(:)

    print_summary = .true.
    if (present(verbose)) print_summary = verbose

    if (.not. block_writeback_plan_is_ready()) then
       call fail("Domain-trend block-step check before plan is ready")
    end if

    allocate(baseline_scalar( &
         size(block_writeback_plan%scalar_domain_stage)))
    allocate(baseline_vector( &
         size(block_writeback_plan%vector_domain_stage)))
    allocate(trend_scalar(block_writeback_plan%scalar_patch_nvalue))
    allocate(trend_vector(block_writeback_plan%vector_patch_nvalue))
    allocate(candidate_patch( &
         size(block_writeback_plan%domain_patch_covered)))

    call assert_block_domain_field_family_match(BLOCK_PAYLOAD_SOL)
    call reconstruct_block_writeback_domain_stage(BLOCK_PAYLOAD_SOL)
    baseline_scalar = block_writeback_plan%scalar_domain_stage
    baseline_vector = block_writeback_plan%vector_domain_stage

    writeback_allocation_before = &
         block_writeback_plan_allocation_count()
    production_writeback_before = &
         block_domain_production_writeback_count()

    call begin_block_domain_trend_step(validation_scale)
    call complete_block_domain_trend_step(.false.)
    call assert_restored_state
    if (block_domain_production_writeback_count() /= &
         production_writeback_before) then
       call fail("rejected Domain-trend block step wrote Domain sol")
    end if

    call exercise_candidate(local_patch_count)
    tendency_allocation_after_first = &
         local_block_tendency_allocation_count()
    import_allocation_after_first = &
         local_block_tendency_import_allocation_count()
    writeback_allocation_after_first = &
         block_writeback_plan_allocation_count()

    call exercise_candidate(local_patch_count)

    if (local_block_tendency_allocation_count() /= &
         tendency_allocation_after_first) then
       call fail("repeated Euler bridge reallocated tendency arrays")
    end if
    if (local_block_tendency_import_allocation_count() /= &
         import_allocation_after_first) then
       call fail("repeated Euler bridge reallocated import coverage")
    end if
    if (block_writeback_plan_allocation_count() /= &
         writeback_allocation_after_first .or. &
         writeback_allocation_after_first /= &
         writeback_allocation_before) then
       call fail("Euler bridge reallocated persistent transport storage")
    end if
    if (block_domain_production_writeback_count() /= &
         production_writeback_before + 4_int64) then
       call fail("Euler bridge writeback count is invalid")
    end if

    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    if (trial_active .or. checkpoint_ready) then
       call fail("Euler bridge left a pending block transaction")
    end if

    call MPI_Allreduce(local_patch_count,global_patch_count,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce Euler bridge patches")

    if (print_summary) then
       write(6,'(/,a,i0,a)') &
            "Domain-trend block Euler bridge for rank ",rank,":"
       write(6,'(a,i0)') &
            "  candidate block-owned patches = ",local_patch_count
       write(6,'(a)') &
            "  rejected actual-trend step preserved Domain sol"
       write(6,'(a)') &
            "  exact scalar Euler candidate comparison passed"
       write(6,'(a)') &
            "  exact vector Euler candidate comparison passed"
       write(6,'(a)') &
            "  candidate sol synchronized to Domain owners"
       write(6,'(a)') "  exact block/Domain rollback passed"
       write(6,'(a,/)') &
            "  repeated actual-trend transaction reuse passed"
    end if

    if (print_summary .and. rank == 0) then
       write(6,'(/,a,i0)') &
            "Global Domain-trend Euler candidate patches = ", &
            global_patch_count
       write(6,'(a,/)') &
            "Production Domain-trend block Euler bridge passed"
    end if

    deallocate(candidate_patch)
    deallocate(trend_vector)
    deallocate(trend_scalar)
    deallocate(baseline_vector)
    deallocate(baseline_scalar)

  contains

    subroutine exercise_candidate (patch_count)

      implicit none

      integer(int64), intent(out) :: patch_count

      call begin_block_domain_trend_step(validation_scale)
      call reconstruct_block_writeback_domain_stage(BLOCK_PAYLOAD_SOL)
      call validate_candidate_stage(patch_count)

      call write_block_field_family_to_domains(BLOCK_PAYLOAD_SOL)
      call assert_block_domain_field_family_match(BLOCK_PAYLOAD_SOL)

      call restore_local_block_tendency_commit
      call write_block_field_family_to_domains(BLOCK_PAYLOAD_SOL)
      call assert_restored_state
      call assert_block_domain_field_family_match( &
           BLOCK_PAYLOAD_WAV_COEFF)

    end subroutine exercise_candidate


    subroutine assert_restored_state

      implicit none

      logical :: checkpoint_pending
      logical :: trial_pending

      call assert_block_domain_field_family_match(BLOCK_PAYLOAD_SOL)
      call reconstruct_block_writeback_domain_stage(BLOCK_PAYLOAD_SOL)
      if (any(abs(block_writeback_plan%scalar_domain_stage - &
           baseline_scalar) > 0.0_dp)) then
         call fail("Euler bridge scalar rollback mismatch")
      end if
      if (any(abs(block_writeback_plan%vector_domain_stage - &
           baseline_vector) > 0.0_dp)) then
         call fail("Euler bridge vector rollback mismatch")
      end if

      trial_pending = local_block_tendency_trial_is_active()
      checkpoint_pending = &
           local_block_tendency_commit_checkpoint_is_ready()
      if (trial_pending .or. checkpoint_pending) then
         call fail("Euler bridge rollback retained transaction state")
      end if

    end subroutine assert_restored_state


    subroutine validate_candidate_stage (patch_count)

      implicit none

      integer(int64), intent(out) :: patch_count

      integer :: b
      integer :: d
      integer :: local_index
      integer :: p
      integer :: patch_slot
      integer :: r
      integer :: slot

      candidate_patch = .false.

      do local_index = 1,n_local_blocks()
         b = local_block_catalog(local_index)
         r = source_rank(b)
         if (r /= rank) cycle
         d = loc_id(block_catalog(b)%root_domain+1) + 1
         call validate_candidate_subtree( &
              d,block_catalog(b)%root_patch)
      end do

      do r = 1,n_process
         do slot = block_writeback_plan%recv_displ(r)+1, &
              block_writeback_plan%recv_displ(r) + &
              block_writeback_plan%recv_count(r)
            b = block_writeback_plan%recv_block(slot)
            d = loc_id(block_catalog(b)%root_domain+1) + 1
            call validate_candidate_subtree( &
                 d,block_catalog(b)%root_patch)
         end do
      end do

      if (count(candidate_patch) /= &
           block_writeback_plan%reconstructed_patch_count) then
         call fail("Euler candidate patch coverage mismatch")
      end if

      do d = 1,size(grid)
         do p = 0,grid(d)%patch%length-1
            patch_slot = &
                 block_writeback_plan%domain_patch_displ(d) + p + 1
            if (grid(d)%patch%elts(p+1)%deleted) then
               if (candidate_patch(patch_slot)) then
                  call fail("Euler candidate covered a deleted patch")
               end if
            else if (.not. candidate_patch(patch_slot)) then
               call compare_preserved_patch(patch_slot)
            end if
         end do
      end do

      patch_count = int(count(candidate_patch),int64)

    end subroutine validate_candidate_stage


    recursive subroutine validate_candidate_subtree (d,p)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p

      integer :: c
      integer :: p_child
      integer :: patch_slot
      integer :: scalar_pos
      integer :: vector_pos

      if (d < 1 .or. d > size(grid)) then
         call fail("Euler candidate Domain is invalid")
      end if
      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("Euler candidate patch is invalid")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return

      patch_slot = block_writeback_plan%domain_patch_displ(d) + p + 1
      if (candidate_patch(patch_slot)) then
         call fail("Euler candidate patch was covered more than once")
      end if
      candidate_patch(patch_slot) = .true.

      scalar_pos = 1
      vector_pos = 1
      call pack_domain_patch_prognostic( &
           d,p,BLOCK_PAYLOAD_TREND,trend_scalar,scalar_pos, &
           trend_vector,vector_pos)
      if (scalar_pos /= size(trend_scalar)+1 .or. &
           vector_pos /= size(trend_vector)+1) then
         call fail("Euler candidate trend patch extent mismatch")
      end if
      call compare_updated_patch(patch_slot)

      do c = 1,N_CHDRN
         p_child = grid(d)%patch%elts(p+1)%children(c)
         if (p_child <= 0) cycle
         call validate_candidate_subtree(d,p_child)
      end do

    end subroutine validate_candidate_subtree


    subroutine compare_updated_patch (patch_slot)

      implicit none

      integer, intent(in) :: patch_slot

      integer :: scalar_start
      integer :: vector_start

      scalar_start = (patch_slot-1)* &
           block_writeback_plan%scalar_patch_nvalue + 1
      vector_start = (patch_slot-1)* &
           block_writeback_plan%vector_patch_nvalue + 1

      if (any(abs(block_writeback_plan%scalar_domain_stage( &
           scalar_start:scalar_start+size(trend_scalar)-1) - &
           (baseline_scalar( &
           scalar_start:scalar_start+size(trend_scalar)-1) + &
           validation_scale*trend_scalar)) > 0.0_dp)) then
         call fail("scalar Domain-trend Euler candidate mismatch")
      end if
      if (any(abs(block_writeback_plan%vector_domain_stage( &
           vector_start:vector_start+size(trend_vector)-1) - &
           (baseline_vector( &
           vector_start:vector_start+size(trend_vector)-1) + &
           validation_scale*trend_vector)) > 0.0_dp)) then
         call fail("vector Domain-trend Euler candidate mismatch")
      end if

    end subroutine compare_updated_patch


    subroutine compare_preserved_patch (patch_slot)

      implicit none

      integer, intent(in) :: patch_slot

      integer :: scalar_start
      integer :: vector_start

      scalar_start = (patch_slot-1)* &
           block_writeback_plan%scalar_patch_nvalue + 1
      vector_start = (patch_slot-1)* &
           block_writeback_plan%vector_patch_nvalue + 1

      if (any(abs(block_writeback_plan%scalar_domain_stage( &
           scalar_start:scalar_start+ &
           block_writeback_plan%scalar_patch_nvalue-1) - &
           baseline_scalar(scalar_start:scalar_start+ &
           block_writeback_plan%scalar_patch_nvalue-1)) > 0.0_dp)) then
         call fail("preserved scalar Euler scaffold mismatch")
      end if
      if (any(abs(block_writeback_plan%vector_domain_stage( &
           vector_start:vector_start+ &
           block_writeback_plan%vector_patch_nvalue-1) - &
           baseline_vector(vector_start:vector_start+ &
           block_writeback_plan%vector_patch_nvalue-1)) > 0.0_dp)) then
         call fail("preserved vector Euler scaffold mismatch")
      end if

    end subroutine compare_preserved_patch

  end subroutine check_block_domain_trend_step


  recursive subroutine pack_domain_subtree_prognostic ( &
       d,p,payload_family,scalar_payload,scalar_pos, &
       vector_payload,vector_pos,n_patch,domain_sol)
    ! Pack one Domain field-family subtree in compact block preorder.

    implicit none

    integer, intent(in) :: d
    integer, intent(in) :: p
    integer, intent(in) :: payload_family
    real(dp), intent(inout) :: scalar_payload(:)
    integer, intent(inout) :: scalar_pos
    real(dp), intent(inout) :: vector_payload(:)
    integer, intent(inout) :: vector_pos
    integer, intent(inout) :: n_patch
    type(Float_Field), optional, intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)

    integer :: c
    integer :: p_child

    if (p < 0 .or. p >= grid(d)%patch%length) then
       call fail("invalid patch in writeback Domain payload")
    end if
    if (grid(d)%patch%elts(p+1)%deleted) return

    call pack_domain_patch_prognostic( &
         d,p,payload_family,scalar_payload,scalar_pos, &
         vector_payload,vector_pos,domain_sol)

    n_patch = n_patch + 1

    do c = 1,N_CHDRN
       p_child = grid(d)%patch%elts(p+1)%children(c)
       if (p_child <= 0) cycle
       call pack_domain_subtree_prognostic( &
            d,p_child,payload_family,scalar_payload,scalar_pos, &
            vector_payload,vector_pos,n_patch,domain_sol)
    end do

  end subroutine pack_domain_subtree_prognostic


  subroutine pack_domain_patch_prognostic ( &
       d,p,payload_family,scalar_payload,scalar_pos, &
       vector_payload,vector_pos,domain_sol)
    ! Pack one active Domain patch in compact field-family order.

    implicit none

    integer, intent(in) :: d
    integer, intent(in) :: p
    integer, intent(in) :: payload_family
    real(dp), intent(inout) :: scalar_payload(:)
    integer, intent(inout) :: scalar_pos
    real(dp), intent(inout) :: vector_payload(:)
    integer, intent(inout) :: vector_pos
    type(Float_Field), optional, intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)

    integer :: field_level
    integer :: first_field_level
    integer :: level_slot
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_patch
    integer :: n_scalar_variable
    integer :: n_value
    integer :: n_vector_patch
    integer :: scalar_id
    integer :: scalar_slot
    integer :: start
    integer :: v_scalar
    integer :: v_vector

    if (d < 1 .or. d > size(grid)) then
       call fail("invalid Domain in writeback record")
    end if
    if (p < 0 .or. p >= grid(d)%patch%length) then
       call fail("invalid patch in Domain writeback record")
    end if
    if (grid(d)%patch%elts(p+1)%deleted) then
       call fail("deleted patch in Domain writeback record")
    end if
    if (payload_family /= BLOCK_PAYLOAD_SOL .and. &
         payload_family /= BLOCK_PAYLOAD_WAV_COEFF .and. &
         payload_family /= BLOCK_PAYLOAD_TREND .and. &
         payload_family /= BLOCK_PAYLOAD_THETA_EDGE .and. &
         payload_family /= BLOCK_PAYLOAD_EXNER_DIFFERENCE .and. &
         payload_family /= BLOCK_PAYLOAD_THERMODYNAMIC_GRADIENT .and. &
         payload_family /= BLOCK_PAYLOAD_COMPLETE_EXNER_GRADIENT .and. &
         payload_family /= BLOCK_PAYLOAD_EDGE_LENGTH .and. &
         payload_family /= BLOCK_PAYLOAD_VELOCITY_REMAINDER .and. &
         payload_family /= BLOCK_PAYLOAD_COMPLETE_VELOCITY .and. &
         payload_family /= BLOCK_PAYLOAD_PHYSICAL_COMPONENTS .and. &
         payload_family /= &
         BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY) then
       call fail("invalid Domain writeback payload family")
    end if

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)

    n_scalar_patch = &
         n_scalar_variable*n_field_level*mult_scalar*PATCH_SIZE**2
    n_vector_patch = n_field_level*mult_vector*PATCH_SIZE**2
    if (scalar_pos < 1 .or. &
         scalar_pos+n_scalar_patch-1 > size(scalar_payload) .or. &
         vector_pos < 1 .or. &
         vector_pos+n_vector_patch-1 > size(vector_payload)) then
       call fail("Domain writeback record buffer extent is invalid")
    end if

    if (payload_family == BLOCK_PAYLOAD_PHYSICAL_COMPONENTS .or. &
         payload_family == &
         BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY) then
       start = mult_scalar*grid(d)%patch%elts(p+1)%elts_start
       n_value = mult_scalar*PATCH_SIZE**2
       do scalar_slot = 1,n_scalar_variable
          scalar_id = v_scalar + scalar_slot - 1
          do level_slot = 1,n_field_level
             field_level = first_field_level + level_slot - 1
             if (field_level < 1) then
                scalar_payload( &
                     scalar_pos:scalar_pos+n_value-1) = 0.0_dp
             else
                if (field_level > zlevels) then
                   call fail( &
                        "physical scalar tendency level is invalid")
                end if
                if (start < 0 .or. start+n_value > &
                     size(trend(scalar_id,field_level)%data(d)%elts)) then
                   call fail( &
                        "physical scalar tendency extent is invalid")
                end if
                scalar_payload(scalar_pos:scalar_pos+n_value-1) = &
                     trend(scalar_id,field_level)%data(d)%elts( &
                     start+1:start+n_value)
             end if
             scalar_pos = scalar_pos + n_value
          end do
       end do
       if (.not. present(domain_sol)) then
          call fail("physical tendency payload requires stage sol")
       end if
       call pack_domain_patch_velocity_recomposition( &
            d,p,vector_payload( &
            vector_pos:vector_pos+n_vector_patch-1),domain_sol, &
            payload_family == &
            BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY)
       vector_pos = vector_pos + n_vector_patch
       return
    end if

    if (payload_family == BLOCK_PAYLOAD_THETA_EDGE) then
       scalar_payload(scalar_pos:scalar_pos+n_scalar_patch-1) = 0.0_dp
       if (present(domain_sol)) then
          call pack_domain_patch_theta_edge( &
               d,p,vector_payload( &
               vector_pos:vector_pos+n_vector_patch-1),domain_sol)
       else
          call pack_domain_patch_theta_edge( &
               d,p,vector_payload( &
               vector_pos:vector_pos+n_vector_patch-1))
       end if
       scalar_pos = scalar_pos + n_scalar_patch
       vector_pos = vector_pos + n_vector_patch
       return
    end if

    if (payload_family == BLOCK_PAYLOAD_EXNER_DIFFERENCE) then
       scalar_payload(scalar_pos:scalar_pos+n_scalar_patch-1) = 0.0_dp
       if (present(domain_sol)) then
          call pack_domain_patch_exner_difference( &
               d,p,vector_payload( &
               vector_pos:vector_pos+n_vector_patch-1),domain_sol)
       else
          call pack_domain_patch_exner_difference( &
               d,p,vector_payload( &
               vector_pos:vector_pos+n_vector_patch-1))
       end if
       scalar_pos = scalar_pos + n_scalar_patch
       vector_pos = vector_pos + n_vector_patch
       return
    end if

    if (payload_family == BLOCK_PAYLOAD_THERMODYNAMIC_GRADIENT) then
       scalar_payload(scalar_pos:scalar_pos+n_scalar_patch-1) = 0.0_dp
       if (present(domain_sol)) then
          call pack_domain_patch_exner_difference( &
               d,p,vector_payload( &
               vector_pos:vector_pos+n_vector_patch-1),domain_sol,.true.)
       else
          call pack_domain_patch_exner_difference( &
               d,p,vector_payload( &
               vector_pos:vector_pos+n_vector_patch-1), &
               thermodynamic_product=.true.)
       end if
       scalar_pos = scalar_pos + n_scalar_patch
       vector_pos = vector_pos + n_vector_patch
       return
    end if

    if (payload_family == BLOCK_PAYLOAD_COMPLETE_EXNER_GRADIENT) then
       scalar_payload(scalar_pos:scalar_pos+n_scalar_patch-1) = 0.0_dp
       if (present(domain_sol)) then
          call pack_domain_patch_exner_difference( &
               d,p,vector_payload( &
               vector_pos:vector_pos+n_vector_patch-1),domain_sol, &
               .true.,.true.)
       else
          call pack_domain_patch_exner_difference( &
               d,p,vector_payload( &
               vector_pos:vector_pos+n_vector_patch-1), &
               thermodynamic_product=.true.,metric_division=.true.)
       end if
       scalar_pos = scalar_pos + n_scalar_patch
       vector_pos = vector_pos + n_vector_patch
       return
    end if

    if (payload_family == BLOCK_PAYLOAD_EDGE_LENGTH) then
       scalar_payload(scalar_pos:scalar_pos+n_scalar_patch-1) = 0.0_dp
       call pack_domain_patch_edge_length( &
            d,p,vector_payload( &
            vector_pos:vector_pos+n_vector_patch-1))
       scalar_pos = scalar_pos + n_scalar_patch
       vector_pos = vector_pos + n_vector_patch
       return
    end if

    if (payload_family == BLOCK_PAYLOAD_VELOCITY_REMAINDER .or. &
         payload_family == BLOCK_PAYLOAD_COMPLETE_VELOCITY) then
       if (.not. present(domain_sol)) then
          call fail("Domain velocity recomposition requires stage sol")
       end if
       scalar_payload(scalar_pos:scalar_pos+n_scalar_patch-1) = 0.0_dp
       call pack_domain_patch_velocity_recomposition( &
            d,p,vector_payload( &
            vector_pos:vector_pos+n_vector_patch-1),domain_sol, &
            payload_family == BLOCK_PAYLOAD_COMPLETE_VELOCITY)
       scalar_pos = scalar_pos + n_scalar_patch
       vector_pos = vector_pos + n_vector_patch
       return
    end if

    start = mult_scalar*grid(d)%patch%elts(p+1)%elts_start
    n_value = mult_scalar*PATCH_SIZE**2

    do scalar_slot = 1,n_scalar_variable
       scalar_id = v_scalar + scalar_slot - 1
       do level_slot = 1,n_field_level
          field_level = first_field_level + level_slot - 1
          select case (payload_family)
          case (BLOCK_PAYLOAD_SOL)
             if (present(domain_sol) .and. field_level >= 1 .and. &
                  field_level <= zlevels) then
                if (start < 0 .or. start+n_value > size( &
                     domain_sol(scalar_id,field_level)%data(d)%elts)) then
                   call fail("stage scalar sol payload extent is invalid")
                end if
                scalar_payload(scalar_pos:scalar_pos+n_value-1) = &
                     domain_sol(scalar_id,field_level)%data(d)%elts( &
                     start+1:start+n_value)
             else
                if (start < 0 .or. start+n_value > &
                     size(sol(scalar_id,field_level)%data(d)%elts)) then
                   call fail( &
                        "legacy scalar sol writeback extent is invalid")
                end if
                scalar_payload(scalar_pos:scalar_pos+n_value-1) = &
                     sol(scalar_id,field_level)%data(d)%elts( &
                     start+1:start+n_value)
             end if
          case (BLOCK_PAYLOAD_WAV_COEFF)
             if (start < 0 .or. start+n_value > &
                  size(wav_coeff(scalar_id,field_level)%data(d)%elts)) then
                call fail( &
                     "legacy scalar wav_coeff writeback extent is invalid")
             end if
             scalar_payload(scalar_pos:scalar_pos+n_value-1) = &
                  wav_coeff(scalar_id,field_level)%data(d)%elts( &
                  start+1:start+n_value)
          case (BLOCK_PAYLOAD_TREND)
             if (field_level < 1) then
                scalar_payload( &
                     scalar_pos:scalar_pos+n_value-1) = 0.0_dp
             else
                if (start < 0 .or. start+n_value > &
                     size(trend(scalar_id,field_level)%data(d)%elts)) then
                   call fail( &
                        "legacy scalar trend payload extent is invalid")
                end if
                scalar_payload(scalar_pos:scalar_pos+n_value-1) = &
                     trend(scalar_id,field_level)%data(d)%elts( &
                     start+1:start+n_value)
             end if
          end select
          scalar_pos = scalar_pos + n_value
       end do
    end do

    start = mult_vector*grid(d)%patch%elts(p+1)%elts_start
    n_value = mult_vector*PATCH_SIZE**2

    do level_slot = 1,n_field_level
       field_level = first_field_level + level_slot - 1
       select case (payload_family)
       case (BLOCK_PAYLOAD_SOL)
          if (present(domain_sol) .and. field_level >= 1 .and. &
               field_level <= zlevels) then
             if (start < 0 .or. start+n_value > &
                  size(domain_sol(v_vector,field_level)%data(d)%elts)) then
                call fail("stage vector sol payload extent is invalid")
             end if
             vector_payload(vector_pos:vector_pos+n_value-1) = &
                  domain_sol(v_vector,field_level)%data(d)%elts( &
                  start+1:start+n_value)
          else
             if (start < 0 .or. start+n_value > &
                  size(sol(v_vector,field_level)%data(d)%elts)) then
                call fail("legacy vector sol writeback extent is invalid")
             end if
             vector_payload(vector_pos:vector_pos+n_value-1) = &
                  sol(v_vector,field_level)%data(d)%elts( &
                  start+1:start+n_value)
          end if
       case (BLOCK_PAYLOAD_WAV_COEFF)
          if (start < 0 .or. start+n_value > &
               size(wav_coeff(v_vector,field_level)%data(d)%elts)) then
             call fail( &
                  "legacy vector wav_coeff writeback extent is invalid")
          end if
          vector_payload(vector_pos:vector_pos+n_value-1) = &
               wav_coeff(v_vector,field_level)%data(d)%elts( &
               start+1:start+n_value)
       case (BLOCK_PAYLOAD_TREND)
          if (field_level < 1) then
             vector_payload( &
                  vector_pos:vector_pos+n_value-1) = 0.0_dp
          else
             if (start < 0 .or. start+n_value > &
                  size(trend(v_vector,field_level)%data(d)%elts)) then
                call fail("legacy vector trend payload extent is invalid")
             end if
             vector_payload(vector_pos:vector_pos+n_value-1) = &
                  trend(v_vector,field_level)%data(d)%elts( &
                  start+1:start+n_value)
          end if
       end select
       vector_pos = vector_pos + n_value
    end do

  end subroutine pack_domain_patch_prognostic


  subroutine pack_domain_patch_edge_length (d,p,edge_length)
    ! Repeat the authoritative, initialized production primal-edge metric
    ! in the block vector layout for every physical model level.

    implicit none

    integer, intent(in) :: d
    integer, intent(in) :: p
    real(dp), intent(out) :: edge_length(:)

    integer :: field_level
    integer :: first_field_level
    integer :: level_slot
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_variable
    integer :: n_value
    integer :: output_base
    integer :: start
    integer :: v_scalar
    integer :: v_vector

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    if (mult_scalar /= 1 .or. mult_vector /= EDGE .or. &
         n_scalar_variable < 1 .or. v_scalar < 1 .or. v_vector < 1) then
       call fail("Domain edge-metric field layout is invalid")
    end if
    n_value = EDGE*PATCH_SIZE**2
    if (size(edge_length) /= n_field_level*n_value) then
       call fail("Domain edge-metric payload extent is invalid")
    end if
    start = EDGE*grid(d)%patch%elts(p+1)%elts_start
    if (start < 0 .or. start+n_value > size(grid(d)%len%elts)) then
       call fail("Domain edge-metric source extent is invalid")
    end if

    edge_length = 0.0_dp
    do level_slot = 1,n_field_level
       field_level = first_field_level + level_slot - 1
       if (field_level < 1) cycle
       if (field_level > zlevels) then
          call fail("Domain edge-metric field level is invalid")
       end if
       output_base = (level_slot-1)*n_value
       edge_length(output_base+1:output_base+n_value) = &
            grid(d)%len%elts(start+1:start+n_value)
    end do

  end subroutine pack_domain_patch_edge_length


  subroutine pack_domain_patch_velocity_recomposition ( &
       d,p,velocity_value,domain_sol,recompose)
    ! Form the authoritative non-Exner residual as trend plus the complete
    ! Exner term. Optionally apply the matching subtraction to provide an
    ! independent Domain reference for the rejected block recomposition.

    implicit none

    integer, intent(in) :: d
    integer, intent(in) :: p
    real(dp), intent(out) :: velocity_value(:)
    type(Float_Field), intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    logical, intent(in) :: recompose

    integer :: field_level
    integer :: first_field_level
    integer :: level_slot
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_variable
    integer :: n_value
    integer :: output_base
    integer :: source_base
    integer :: value_index
    integer :: v_scalar
    integer :: v_vector

    real(dp) :: exner_term
    real(dp) :: trend_value

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    if (mult_scalar /= 1 .or. mult_vector /= EDGE .or. &
         n_scalar_variable < 1 .or. v_scalar < 1 .or. v_vector < 1) then
       call fail("Domain velocity recomposition layout is invalid")
    end if
    n_value = EDGE*PATCH_SIZE**2
    if (size(velocity_value) /= n_field_level*n_value) then
       call fail("Domain velocity recomposition extent is invalid")
    end if

    call pack_domain_patch_exner_difference( &
         d,p,velocity_value,domain_sol,.true.,.true.)
    source_base = EDGE*grid(d)%patch%elts(p+1)%elts_start
    do level_slot = 1,n_field_level
       field_level = first_field_level + level_slot - 1
       if (field_level < 1) cycle
       if (field_level > zlevels) then
          call fail("Domain velocity recomposition level is invalid")
       end if
       if (source_base < 0 .or. source_base+n_value > &
            size(trend(v_vector,field_level)%data(d)%elts)) then
          call fail("Domain velocity trend source extent is invalid")
       end if
       output_base = (level_slot-1)*n_value
       do value_index = 1,n_value
          exner_term = velocity_value(output_base+value_index)
          trend_value = trend(v_vector,field_level)%data(d)%elts( &
               source_base+value_index)
          velocity_value(output_base+value_index) = &
               trend_value + exner_term
          if (recompose) then
             velocity_value(output_base+value_index) = &
                  velocity_value(output_base+value_index) - exner_term
          end if
       end do
    end do

  end subroutine pack_domain_patch_velocity_recomposition


  subroutine pack_domain_patch_theta_edge (d,p,theta_edge,domain_sol)
    ! Independently reconstruct the potential-temperature edge averages
    ! used by the compressible velocity-gradient tendency from Domain data.

    implicit none

    integer, intent(in) :: d
    integer, intent(in) :: p
    real(dp), intent(out) :: theta_edge(:)
    type(Float_Field), optional, intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)

    integer :: dims(2,N_BDRY+1)
    integer :: field_level
    integer :: first_field_level
    integer :: i
    integer :: id_center
    integer :: id_east
    integer :: id_north
    integer :: id_northeast
    integer :: j
    integer :: level_slot
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_variable
    integer :: offs(N_BDRY+1)
    integer :: output_base
    integer :: q
    integer :: v_scalar
    integer :: v_vector

    real(dp) :: mass_center
    real(dp) :: mass_east
    real(dp) :: mass_north
    real(dp) :: mass_northeast
    real(dp) :: temp_center
    real(dp) :: temp_east
    real(dp) :: temp_north
    real(dp) :: temp_northeast
    real(dp) :: theta_center
    real(dp) :: theta_east
    real(dp) :: theta_north
    real(dp) :: theta_northeast

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    if (mult_scalar /= 1 .or. mult_vector /= EDGE .or. &
         S_MASS < v_scalar .or. &
         S_MASS >= v_scalar+n_scalar_variable .or. &
         S_TEMP < v_scalar .or. &
         S_TEMP >= v_scalar+n_scalar_variable) then
       call fail("Domain theta-edge field layout is invalid")
    end if
    if (size(theta_edge) /= &
         n_field_level*EDGE*PATCH_SIZE**2) then
       call fail("Domain theta-edge payload extent is invalid")
    end if

    call get_offs_Domain(grid(d),p,offs,dims)
    theta_edge = 0.0_dp
    do level_slot = 1,n_field_level
       field_level = first_field_level + level_slot - 1
       if (field_level < 1) cycle
       if (field_level > zlevels) then
          call fail("Domain theta-edge field level is invalid")
       end if
       output_base = (level_slot-1)*EDGE*PATCH_SIZE**2

       do j = 0,PATCH_SIZE-1
          do i = 0,PATCH_SIZE-1
             q = i + PATCH_SIZE*j
             id_center = idx(i,j,offs,dims)
             id_east = idx(i+1,j,offs,dims)
             id_northeast = idx(i+1,j+1,offs,dims)
             id_north = idx(i,j+1,offs,dims)

             if (present(domain_sol)) then
                mass_center = domain_sol(S_MASS,field_level)% &
                     data(d)%elts(id_center+1)
                mass_east = domain_sol(S_MASS,field_level)% &
                     data(d)%elts(id_east+1)
                mass_northeast = domain_sol(S_MASS,field_level)% &
                     data(d)%elts(id_northeast+1)
                mass_north = domain_sol(S_MASS,field_level)% &
                     data(d)%elts(id_north+1)
                temp_center = domain_sol(S_TEMP,field_level)% &
                     data(d)%elts(id_center+1)
                temp_east = domain_sol(S_TEMP,field_level)% &
                     data(d)%elts(id_east+1)
                temp_northeast = domain_sol(S_TEMP,field_level)% &
                     data(d)%elts(id_northeast+1)
                temp_north = domain_sol(S_TEMP,field_level)% &
                     data(d)%elts(id_north+1)
             else
                mass_center = sol(S_MASS,field_level)% &
                     data(d)%elts(id_center+1)
                mass_east = sol(S_MASS,field_level)% &
                     data(d)%elts(id_east+1)
                mass_northeast = sol(S_MASS,field_level)% &
                     data(d)%elts(id_northeast+1)
                mass_north = sol(S_MASS,field_level)% &
                     data(d)%elts(id_north+1)
                temp_center = sol(S_TEMP,field_level)% &
                     data(d)%elts(id_center+1)
                temp_east = sol(S_TEMP,field_level)% &
                     data(d)%elts(id_east+1)
                temp_northeast = sol(S_TEMP,field_level)% &
                     data(d)%elts(id_northeast+1)
                temp_north = sol(S_TEMP,field_level)% &
                     data(d)%elts(id_north+1)
             end if

             mass_center = mass_center + sol_mean(S_MASS,field_level)% &
                  data(d)%elts(id_center+1)
             mass_east = mass_east + sol_mean(S_MASS,field_level)% &
                  data(d)%elts(id_east+1)
             mass_northeast = mass_northeast + &
                  sol_mean(S_MASS,field_level)%data(d)%elts( &
                  id_northeast+1)
             mass_north = mass_north + sol_mean(S_MASS,field_level)% &
                  data(d)%elts(id_north+1)
             temp_center = temp_center + sol_mean(S_TEMP,field_level)% &
                  data(d)%elts(id_center+1)
             temp_east = temp_east + sol_mean(S_TEMP,field_level)% &
                  data(d)%elts(id_east+1)
             temp_northeast = temp_northeast + &
                  sol_mean(S_TEMP,field_level)%data(d)%elts( &
                  id_northeast+1)
             temp_north = temp_north + sol_mean(S_TEMP,field_level)% &
                  data(d)%elts(id_north+1)

             if (min(mass_center,mass_east,mass_northeast,mass_north) &
                  <= 0.0_dp) then
                call fail("Domain theta-edge reconstruction has bad mass")
             end if
             theta_center = temp_center/mass_center
             theta_east = temp_east/mass_east
             theta_northeast = temp_northeast/mass_northeast
             theta_north = temp_north/mass_north

             theta_edge(output_base+EDGE*q+RT+1) = &
                  0.5_dp*(theta_center+theta_east)
             theta_edge(output_base+EDGE*q+DG+1) = &
                  0.5_dp*(theta_center+theta_northeast)
             theta_edge(output_base+EDGE*q+UP+1) = &
                  0.5_dp*(theta_center+theta_north)
          end do
       end do
    end do

  end subroutine pack_domain_patch_theta_edge


  subroutine pack_domain_patch_exner_difference ( &
       d,p,exner_difference,domain_sol,thermodynamic_product, &
       metric_division)
    ! Independently reconstruct the signed dynamic-Exner differences that
    ! form the numerator of gradi_e(exner) on each physical edge.

    implicit none

    integer, intent(in) :: d
    integer, intent(in) :: p
    real(dp), intent(out) :: exner_difference(:)
    type(Float_Field), optional, intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    logical, optional, intent(in) :: thermodynamic_product
    logical, optional, intent(in) :: metric_division

    integer :: component_slot
    integer :: dims(2,N_BDRY+1)
    integer :: field_level
    integer :: first_field_level
    integer :: i
    integer :: id_center
    integer :: id_east
    integer :: id_north
    integer :: id_northeast
    integer :: j
    integer :: level_slot
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_variable
    integer :: offs(N_BDRY+1)
    integer :: output_base
    integer :: q
    integer :: v_scalar
    integer :: v_vector

    real(dp) :: exner_center
    real(dp) :: exner_east
    real(dp) :: exner_north
    real(dp) :: exner_northeast
    real(dp) :: theta_center
    real(dp) :: theta_east
    real(dp) :: theta_north
    real(dp) :: theta_northeast

    logical :: apply_theta
    logical :: apply_metric

    apply_theta = .false.
    if (present(thermodynamic_product)) then
       apply_theta = thermodynamic_product
    end if
    apply_metric = .false.
    if (present(metric_division)) then
       apply_metric = metric_division
    end if
    if (apply_metric .and. .not. apply_theta) then
       call fail("Domain complete Exner-gradient mode is invalid")
    end if

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    if (mult_scalar /= 1 .or. mult_vector /= EDGE .or. &
         S_MASS < v_scalar .or. &
         S_MASS >= v_scalar+n_scalar_variable .or. &
         (apply_theta .and. &
         (S_TEMP < v_scalar .or. &
         S_TEMP >= v_scalar+n_scalar_variable)) .or. &
         v_vector < 1) then
       call fail("Domain Exner-difference field layout is invalid")
    end if
    if (size(exner_difference) /= &
         n_field_level*EDGE*PATCH_SIZE**2) then
       call fail("Domain Exner-difference payload extent is invalid")
    end if

    call get_offs_Domain(grid(d),p,offs,dims)
    exner_difference = 0.0_dp
    do level_slot = 1,n_field_level
       field_level = first_field_level + level_slot - 1
       if (field_level < 1) cycle
       if (field_level > zlevels) then
          call fail("Domain Exner-difference field level is invalid")
       end if
       output_base = (level_slot-1)*EDGE*PATCH_SIZE**2

       do j = 0,PATCH_SIZE-1
          do i = 0,PATCH_SIZE-1
             q = i + PATCH_SIZE*j
             id_center = idx(i,j,offs,dims)
             id_east = idx(i+1,j,offs,dims)
             id_northeast = idx(i+1,j+1,offs,dims)
             id_north = idx(i,j+1,offs,dims)

             exner_center = domain_dynamic_exner( &
                  id_center,field_level)
             exner_east = domain_dynamic_exner(id_east,field_level)
             exner_northeast = domain_dynamic_exner( &
                  id_northeast,field_level)
             exner_north = domain_dynamic_exner(id_north,field_level)

             exner_difference(output_base+EDGE*q+RT+1) = &
                  exner_east-exner_center
             exner_difference(output_base+EDGE*q+DG+1) = &
                  exner_center-exner_northeast
             exner_difference(output_base+EDGE*q+UP+1) = &
                  exner_north-exner_center
             if (apply_theta) then
                theta_center = domain_potential_temperature( &
                     id_center,field_level)
                theta_east = domain_potential_temperature( &
                     id_east,field_level)
                theta_northeast = domain_potential_temperature( &
                     id_northeast,field_level)
                theta_north = domain_potential_temperature( &
                     id_north,field_level)
                exner_difference(output_base+EDGE*q+RT+1) = &
                     exner_difference(output_base+EDGE*q+RT+1)* &
                     (0.5_dp*(theta_center+theta_east))
                exner_difference(output_base+EDGE*q+DG+1) = &
                     exner_difference(output_base+EDGE*q+DG+1)* &
                     (0.5_dp*(theta_center+theta_northeast))
                exner_difference(output_base+EDGE*q+UP+1) = &
                     exner_difference(output_base+EDGE*q+UP+1)* &
                     (0.5_dp*(theta_center+theta_north))
             end if
             if (apply_metric) then
                if (any(grid(d)%len%elts( &
                     EDGE*id_center+RT+1:EDGE*id_center+UP+1) <= &
                     0.0_dp)) then
                   call fail("Domain Exner-gradient edge length is invalid")
                end if
                do component_slot = 1,EDGE
                   exner_difference( &
                        output_base+EDGE*q+component_slot) = &
                        exner_difference( &
                        output_base+EDGE*q+component_slot)/ &
                        grid(d)%len%elts( &
                        EDGE*id_center+component_slot)
                end do
             end if
          end do
       end do
    end do

  contains

    real(dp) function domain_dynamic_exner (node,field_level) &
         result(exner_value)

      implicit none

      integer, intent(in) :: node
      integer, intent(in) :: field_level

      integer :: k

      real(dp) :: layer_pressure
      real(dp) :: pressure_lower
      real(dp) :: rho_dz

      pressure_lower = p_top
      do k = 1,zlevels
         rho_dz = domain_scalar_total(S_MASS,node,k)
         if (rho_dz <= 0.0_dp) then
            call fail("Domain Exner-difference diagnosed bad mass")
         end if
         pressure_lower = pressure_lower + grav_accel*rho_dz
      end do
      do k = 1,field_level-1
         pressure_lower = pressure_lower - &
              grav_accel*domain_scalar_total(S_MASS,node,k)
      end do
      rho_dz = domain_scalar_total(S_MASS,node,field_level)
      layer_pressure = pressure_lower - 0.5_dp*grav_accel*rho_dz
      if (layer_pressure <= 0.0_dp) then
         call fail("Domain Exner-difference pressure is nonpositive")
      end if
      exner_value = c_p*(layer_pressure/p_0)**kappa

    end function domain_dynamic_exner


    real(dp) function domain_potential_temperature ( &
         node,field_level) result(value)

      implicit none

      integer, intent(in) :: node
      integer, intent(in) :: field_level

      real(dp) :: rho_dz

      rho_dz = domain_scalar_total(S_MASS,node,field_level)
      if (rho_dz <= 0.0_dp) then
         call fail("Domain thermodynamic gradient has bad mass")
      end if
      value = domain_scalar_total(S_TEMP,node,field_level)/rho_dz

    end function domain_potential_temperature


    real(dp) function domain_scalar_total ( &
         scalar_id,node,field_level) result(value)

      implicit none

      integer, intent(in) :: scalar_id
      integer, intent(in) :: node
      integer, intent(in) :: field_level

      if (node < 0 .or. node >= &
           size(sol_mean(scalar_id,field_level)%data(d)%elts)) then
         call fail("Domain Exner-difference node is invalid")
      end if
      if (present(domain_sol)) then
         if (node >= &
              size(domain_sol(scalar_id,field_level)%data(d)%elts)) then
            call fail("Domain Exner-difference stage extent is invalid")
         end if
         value = domain_sol(scalar_id,field_level)%data(d)%elts(node+1)
      else
         if (node >= size(sol(scalar_id,field_level)%data(d)%elts)) then
            call fail("Domain Exner-difference sol extent is invalid")
         end if
         value = sol(scalar_id,field_level)%data(d)%elts(node+1)
      end if
      value = value + &
           sol_mean(scalar_id,field_level)%data(d)%elts(node+1)

    end function domain_scalar_total

  end subroutine pack_domain_patch_exner_difference


  subroutine reconstruct_block_writeback_domain_stage (payload_family)
    ! Reconstruct every active patch of each locally owned legacy Domain in
    ! persistent non-authoritative staging arrays. Retained blocks are read
    ! directly, remote blocks are consumed from the writeback buffers and
    ! fixed coarse-scaffold patches outside the catalogue are preserved.

    implicit none

    integer, intent(in) :: payload_family

    integer :: active_patch_count
    integer :: b
    integer :: d
    integer :: destination
    integer :: expected_patch_count
    integer :: local_index
    integer :: local_patch
    integer :: n_patch
    integer :: p
    integer :: patch_slot
    integer :: pos_scalar
    integer :: pos_vector
    integer :: preserved_patch_count
    integer :: r
    integer :: reconstructed_patch_count
    integer :: scalar_limit
    integer :: scalar_start
    integer :: slot
    integer :: vector_limit
    integer :: vector_stage_start
    integer :: vector_start
    integer :: scalar_stage_start

    if (.not. block_writeback_plan_is_ready()) then
       call fail("Domain reconstruction before writeback plan is ready")
    end if
    if (payload_family /= BLOCK_PAYLOAD_SOL .and. &
         payload_family /= BLOCK_PAYLOAD_WAV_COEFF) then
       call fail("invalid Domain reconstruction payload family")
    end if
    if (.not. allocated( &
         block_writeback_plan%domain_patch_reconstructed)) then
       call fail("Domain reconstruction patch origin is not allocated")
    end if
    if (size(block_writeback_plan%domain_patch_reconstructed) /= &
         size(block_writeback_plan%domain_patch_covered)) then
       call fail("Domain reconstruction patch origin extent mismatch")
    end if

    call exchange_block_writeback_payloads(payload_family)

    block_writeback_plan%scalar_domain_stage = 0.0_dp
    block_writeback_plan%vector_domain_stage = 0.0_dp
    block_writeback_plan%domain_patch_covered = .false.
    block_writeback_plan%domain_patch_reconstructed = .false.
    reconstructed_patch_count = 0
    preserved_patch_count = 0

    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       destination = source_rank(b)
       if (destination /= rank) cycle
       d = loc_id(block_catalog(b)%root_domain+1) + 1
       if (d < 1 .or. d > size(grid)) then
          call fail("retained writeback block has invalid local Domain")
       end if

       local_patch = 0
       n_patch = 0
       call stage_local_subtree( &
            d,block_catalog(b)%root_patch,b,payload_family, &
            local_patch,n_patch)
       expected_patch_count = local_block_patch_count(b)
       if (local_patch /= expected_patch_count .or. &
            n_patch /= expected_patch_count) then
          call fail("retained writeback block reconstruction is incomplete")
       end if
       reconstructed_patch_count = reconstructed_patch_count + n_patch
    end do

    do r = 1,n_process
       pos_scalar = block_writeback_plan%scalar_recv_displ(r) + 1
       pos_vector = block_writeback_plan%vector_recv_displ(r) + 1

       do slot = block_writeback_plan%recv_displ(r)+1, &
            block_writeback_plan%recv_displ(r) + &
            block_writeback_plan%recv_count(r)
          b = block_writeback_plan%recv_block(slot)
          destination = source_rank(b)
          if (destination /= rank) then
             call fail("received reconstruction block has wrong Domain owner")
          end if
          if (block_catalog(b)%owner /= r-1) then
             call fail("received reconstruction block has wrong source owner")
          end if

          d = loc_id(block_catalog(b)%root_domain+1) + 1
          if (d < 1 .or. d > size(grid)) then
             call fail("received writeback block has invalid local Domain")
          end if

          scalar_start = pos_scalar
          vector_start = pos_vector
          scalar_limit = scalar_start + &
               block_writeback_plan%recv_scalar_nvalue(slot) - 1
          vector_limit = vector_start + &
               block_writeback_plan%recv_vector_nvalue(slot) - 1
          n_patch = 0
          call stage_buffer_subtree( &
               d,block_catalog(b)%root_patch, &
               block_writeback_plan%scalar_recv_buffer,pos_scalar, &
               scalar_limit,block_writeback_plan%vector_recv_buffer, &
               pos_vector,vector_limit,n_patch)

          if (n_patch /= &
               block_writeback_plan%recv_patch_count(slot) .or. &
               pos_scalar-scalar_start /= &
               block_writeback_plan%recv_scalar_nvalue(slot) .or. &
               pos_vector-vector_start /= &
               block_writeback_plan%recv_vector_nvalue(slot)) then
             call fail("received Domain reconstruction extent mismatch")
          end if
          reconstructed_patch_count = reconstructed_patch_count + n_patch
       end do

       if (pos_scalar /= block_writeback_plan%scalar_recv_displ(r) + &
            block_writeback_plan%scalar_recv_count(r) + 1 .or. &
            pos_vector /= block_writeback_plan%vector_recv_displ(r) + &
            block_writeback_plan%vector_recv_count(r) + 1) then
          call fail("Domain reconstruction receive extent mismatch")
       end if
    end do

    if (count(block_writeback_plan%domain_patch_covered) /= &
         reconstructed_patch_count) then
       call fail("block-derived Domain patch coverage is inconsistent")
    end if
    if (count(block_writeback_plan%domain_patch_reconstructed) /= &
         reconstructed_patch_count) then
       call fail("block-derived Domain patch origin is inconsistent")
    end if

    active_patch_count = 0
    do d = 1,size(grid)
       do p = 0,grid(d)%patch%length-1
          patch_slot = block_writeback_plan%domain_patch_displ(d) + p + 1
          if (grid(d)%patch%elts(p+1)%deleted) then
             if (block_writeback_plan%domain_patch_covered(patch_slot)) then
                call fail("deleted Domain patch was reconstructed")
             end if
          else
             active_patch_count = active_patch_count + 1
             if (.not. &
                  block_writeback_plan%domain_patch_covered(patch_slot)) then
                scalar_stage_start = (patch_slot-1)* &
                     block_writeback_plan%scalar_patch_nvalue + 1
                vector_stage_start = (patch_slot-1)* &
                     block_writeback_plan%vector_patch_nvalue + 1
                call pack_domain_patch_prognostic( &
                     d,p,payload_family, &
                     block_writeback_plan%scalar_domain_stage, &
                     scalar_stage_start, &
                     block_writeback_plan%vector_domain_stage, &
                     vector_stage_start)
                block_writeback_plan%domain_patch_covered(patch_slot) = &
                     .true.
                preserved_patch_count = preserved_patch_count + 1
             end if
          end if
       end do
    end do

    if (count(block_writeback_plan%domain_patch_covered) /= &
         active_patch_count) then
       call fail("Domain reconstruction patch coverage is not exact")
    end if
    if (active_patch_count /= reconstructed_patch_count + &
         preserved_patch_count) then
       call fail("complete Domain reconstruction count is inconsistent")
    end if

    block_writeback_plan%reconstructed_patch_count = &
         reconstructed_patch_count
    block_writeback_plan%preserved_patch_count = preserved_patch_count

  contains

    subroutine claim_domain_patch ( &
         d,p,scalar_stage_start,vector_stage_start)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(out) :: scalar_stage_start
      integer, intent(out) :: vector_stage_start

      integer :: claimed_slot

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("invalid patch in Domain reconstruction")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) then
         call fail("deleted patch in Domain reconstruction")
      end if

      claimed_slot = &
           block_writeback_plan%domain_patch_displ(d) + p + 1
      if (block_writeback_plan%domain_patch_covered(claimed_slot)) then
         call fail("Domain patch was reconstructed more than once")
      end if
      block_writeback_plan%domain_patch_covered(claimed_slot) = .true.
      block_writeback_plan%domain_patch_reconstructed(claimed_slot) = &
           .true.

      scalar_stage_start = (claimed_slot-1)* &
           block_writeback_plan%scalar_patch_nvalue + 1
      vector_stage_start = (claimed_slot-1)* &
           block_writeback_plan%vector_patch_nvalue + 1

    end subroutine claim_domain_patch


    recursive subroutine stage_local_subtree ( &
         d,p,b,payload_family,local_patch,n_patch)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(in) :: b
      integer, intent(in) :: payload_family
      integer, intent(inout) :: local_patch
      integer, intent(inout) :: n_patch

      integer :: c
      integer :: p_child
      integer :: scalar_stage_start
      integer :: vector_stage_start

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("invalid retained patch in Domain reconstruction")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return
      if (local_patch >= local_block_patch_count(b)) then
         call fail("retained block patch traversal exceeded extent")
      end if

      call claim_domain_patch( &
           d,p,scalar_stage_start,vector_stage_start)
      call get_local_block_scalar_patch_family_values( &
           b,local_patch,payload_family, &
           block_writeback_plan%scalar_domain_stage( &
           scalar_stage_start:scalar_stage_start+ &
           block_writeback_plan%scalar_patch_nvalue-1))
      call get_local_block_vector_patch_family_values( &
           b,local_patch,payload_family, &
           block_writeback_plan%vector_domain_stage( &
           vector_stage_start:vector_stage_start+ &
           block_writeback_plan%vector_patch_nvalue-1))
      local_patch = local_patch + 1
      n_patch = n_patch + 1

      do c = 1,N_CHDRN
         p_child = grid(d)%patch%elts(p+1)%children(c)
         if (p_child <= 0) cycle
         call stage_local_subtree( &
              d,p_child,b,payload_family,local_patch,n_patch)
      end do

    end subroutine stage_local_subtree


    recursive subroutine stage_buffer_subtree ( &
         d,p,scalar_payload,scalar_pos,scalar_limit, &
         vector_payload,vector_pos,vector_limit,n_patch)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      real(dp), intent(in) :: scalar_payload(:)
      integer, intent(inout) :: scalar_pos
      integer, intent(in) :: scalar_limit
      real(dp), intent(in) :: vector_payload(:)
      integer, intent(inout) :: vector_pos
      integer, intent(in) :: vector_limit
      integer, intent(inout) :: n_patch

      integer :: c
      integer :: p_child
      integer :: scalar_stage_start
      integer :: vector_stage_start

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("invalid received patch in Domain reconstruction")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return
      if (scalar_pos+block_writeback_plan%scalar_patch_nvalue-1 > &
           scalar_limit .or. &
           vector_pos+block_writeback_plan%vector_patch_nvalue-1 > &
           vector_limit) then
         call fail("received block payload ended during reconstruction")
      end if

      call claim_domain_patch( &
           d,p,scalar_stage_start,vector_stage_start)
      block_writeback_plan%scalar_domain_stage( &
           scalar_stage_start:scalar_stage_start+ &
           block_writeback_plan%scalar_patch_nvalue-1) = &
           scalar_payload(scalar_pos:scalar_pos+ &
           block_writeback_plan%scalar_patch_nvalue-1)
      block_writeback_plan%vector_domain_stage( &
           vector_stage_start:vector_stage_start+ &
           block_writeback_plan%vector_patch_nvalue-1) = &
           vector_payload(vector_pos:vector_pos+ &
           block_writeback_plan%vector_patch_nvalue-1)
      scalar_pos = scalar_pos + &
           block_writeback_plan%scalar_patch_nvalue
      vector_pos = vector_pos + &
           block_writeback_plan%vector_patch_nvalue
      n_patch = n_patch + 1

      do c = 1,N_CHDRN
         p_child = grid(d)%patch%elts(p+1)%children(c)
         if (p_child <= 0) cycle
         call stage_buffer_subtree( &
              d,p_child,scalar_payload,scalar_pos,scalar_limit, &
              vector_payload,vector_pos,vector_limit,n_patch)
      end do

    end subroutine stage_buffer_subtree

  end subroutine reconstruct_block_writeback_domain_stage


  logical function domain_patch_prognostic_extent_is_valid ( &
       d,p,payload_family) result(valid)
    ! Preflight every authoritative array section touched by one patch.

    implicit none

    integer, intent(in) :: d
    integer, intent(in) :: p
    integer, intent(in) :: payload_family

    integer :: field_level
    integer :: first_field_level
    integer :: level_slot
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_variable
    integer :: n_value
    integer :: scalar_id
    integer :: scalar_slot
    integer :: start
    integer :: v_scalar
    integer :: v_vector

    valid = .false.
    if (d < 1 .or. d > size(grid)) return
    if (p < 0 .or. p >= grid(d)%patch%length) return
    if (grid(d)%patch%elts(p+1)%deleted) return
    if (payload_family /= BLOCK_PAYLOAD_SOL .and. &
         payload_family /= BLOCK_PAYLOAD_WAV_COEFF) return

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    if (v_scalar < 1 .or. v_vector < 1 .or. &
         n_scalar_variable < 1 .or. n_field_level < 1 .or. &
         mult_scalar < 1 .or. mult_vector < 1) return

    start = mult_scalar*grid(d)%patch%elts(p+1)%elts_start
    n_value = mult_scalar*PATCH_SIZE**2
    if (start < 0) return
    do scalar_slot = 1,n_scalar_variable
       scalar_id = v_scalar + scalar_slot - 1
       do level_slot = 1,n_field_level
          field_level = first_field_level + level_slot - 1
          select case (payload_family)
          case (BLOCK_PAYLOAD_SOL)
             if (start+n_value > &
                  size(sol(scalar_id,field_level)%data(d)%elts)) return
          case (BLOCK_PAYLOAD_WAV_COEFF)
             if (start+n_value > &
                  size(wav_coeff(scalar_id,field_level)%data(d)%elts)) &
                  return
          end select
       end do
    end do

    start = mult_vector*grid(d)%patch%elts(p+1)%elts_start
    n_value = mult_vector*PATCH_SIZE**2
    if (start < 0) return
    do level_slot = 1,n_field_level
       field_level = first_field_level + level_slot - 1
       select case (payload_family)
       case (BLOCK_PAYLOAD_SOL)
          if (start+n_value > &
               size(sol(v_vector,field_level)%data(d)%elts)) return
       case (BLOCK_PAYLOAD_WAV_COEFF)
          if (start+n_value > &
               size(wav_coeff(v_vector,field_level)%data(d)%elts)) return
       end select
    end do

    valid = .true.

  end function domain_patch_prognostic_extent_is_valid


  logical function block_writeback_domain_stage_is_valid ( &
       payload_family) result(valid)
    ! Validate complete coverage and every destination extent before the
    ! first authoritative value is changed.

    implicit none

    integer, intent(in) :: payload_family

    integer :: active_patch_count
    integer :: d
    integer :: p
    integer :: patch_slot
    integer :: scalar_start
    integer :: vector_start

    logical :: plan_ready
    logical :: patch_extent_valid

    valid = .false.
    plan_ready = block_writeback_plan_is_ready()
    if (.not. plan_ready) return
    if (payload_family /= BLOCK_PAYLOAD_SOL .and. &
         payload_family /= BLOCK_PAYLOAD_WAV_COEFF) return
    if (.not. allocated(block_writeback_plan%domain_patch_displ)) return
    if (.not. allocated(block_writeback_plan%domain_patch_covered)) return
    if (.not. allocated( &
         block_writeback_plan%domain_patch_reconstructed)) return
    if (size(block_writeback_plan%domain_patch_reconstructed) /= &
         size(block_writeback_plan%domain_patch_covered)) return
    if (.not. allocated(block_writeback_plan%scalar_domain_stage)) return
    if (.not. allocated(block_writeback_plan%vector_domain_stage)) return
    if (block_writeback_plan%scalar_patch_nvalue <= 0 .or. &
         block_writeback_plan%vector_patch_nvalue <= 0) return

    active_patch_count = 0
    do d = 1,size(grid)
       do p = 0,grid(d)%patch%length-1
          patch_slot = &
               block_writeback_plan%domain_patch_displ(d) + p + 1
          if (patch_slot < 1 .or. patch_slot > &
               size(block_writeback_plan%domain_patch_covered)) return
          if (grid(d)%patch%elts(p+1)%deleted) then
             if (block_writeback_plan%domain_patch_covered(patch_slot)) &
                  return
             if (block_writeback_plan% &
                  domain_patch_reconstructed(patch_slot)) return
             cycle
          end if

          active_patch_count = active_patch_count + 1
          if (.not. &
               block_writeback_plan%domain_patch_covered(patch_slot)) return

          scalar_start = (patch_slot-1)* &
               block_writeback_plan%scalar_patch_nvalue + 1
          vector_start = (patch_slot-1)* &
               block_writeback_plan%vector_patch_nvalue + 1
          if (scalar_start < 1 .or. scalar_start + &
               block_writeback_plan%scalar_patch_nvalue - 1 > &
               size(block_writeback_plan%scalar_domain_stage)) return
          if (vector_start < 1 .or. vector_start + &
               block_writeback_plan%vector_patch_nvalue - 1 > &
               size(block_writeback_plan%vector_domain_stage)) return

          patch_extent_valid = &
               domain_patch_prognostic_extent_is_valid( &
               d,p,payload_family)
          if (.not. patch_extent_valid) return
       end do
    end do

    if (active_patch_count /= &
         block_writeback_plan%reconstructed_patch_count + &
         block_writeback_plan%preserved_patch_count) return
    if (count(block_writeback_plan%domain_patch_covered) /= &
         active_patch_count) return
    if (count(block_writeback_plan%domain_patch_reconstructed) /= &
         block_writeback_plan%reconstructed_patch_count) return

    valid = .true.

  end function block_writeback_domain_stage_is_valid


  subroutine write_domain_patch_prognostic ( &
       d,p,payload_family,scalar_payload,scalar_pos, &
       vector_payload,vector_pos,domain_sol)
    ! Copy one already validated staged patch into authoritative fields.

    implicit none

    integer, intent(in) :: d
    integer, intent(in) :: p
    integer, intent(in) :: payload_family
    real(dp), intent(in) :: scalar_payload(:)
    integer, intent(inout) :: scalar_pos
    real(dp), intent(in) :: vector_payload(:)
    integer, intent(inout) :: vector_pos
    type(Float_Field), optional, intent(inout) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)

    integer :: field_level
    integer :: first_field_level
    integer :: level_slot
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_variable
    integer :: n_value
    integer :: scalar_id
    integer :: scalar_slot
    integer :: start
    integer :: v_scalar
    integer :: v_vector

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)

    start = mult_scalar*grid(d)%patch%elts(p+1)%elts_start
    n_value = mult_scalar*PATCH_SIZE**2
    do scalar_slot = 1,n_scalar_variable
       scalar_id = v_scalar + scalar_slot - 1
       do level_slot = 1,n_field_level
          field_level = first_field_level + level_slot - 1
          select case (payload_family)
          case (BLOCK_PAYLOAD_SOL)
             if (present(domain_sol) .and. field_level >= 1 .and. &
                  field_level <= zlevels) then
                domain_sol(scalar_id,field_level)%data(d)%elts( &
                     start+1:start+n_value) = &
                     scalar_payload(scalar_pos:scalar_pos+n_value-1)
             else
                sol(scalar_id,field_level)%data(d)%elts( &
                     start+1:start+n_value) = &
                     scalar_payload(scalar_pos:scalar_pos+n_value-1)
             end if
          case (BLOCK_PAYLOAD_WAV_COEFF)
             wav_coeff(scalar_id,field_level)%data(d)%elts( &
                  start+1:start+n_value) = &
                  scalar_payload(scalar_pos:scalar_pos+n_value-1)
          end select
          scalar_pos = scalar_pos + n_value
       end do
    end do

    start = mult_vector*grid(d)%patch%elts(p+1)%elts_start
    n_value = mult_vector*PATCH_SIZE**2
    do level_slot = 1,n_field_level
       field_level = first_field_level + level_slot - 1
       select case (payload_family)
       case (BLOCK_PAYLOAD_SOL)
          if (present(domain_sol) .and. field_level >= 1 .and. &
               field_level <= zlevels) then
             domain_sol(v_vector,field_level)%data(d)%elts( &
                  start+1:start+n_value) = &
                  vector_payload(vector_pos:vector_pos+n_value-1)
          else
             sol(v_vector,field_level)%data(d)%elts( &
                  start+1:start+n_value) = &
                  vector_payload(vector_pos:vector_pos+n_value-1)
          end if
       case (BLOCK_PAYLOAD_WAV_COEFF)
          wav_coeff(v_vector,field_level)%data(d)%elts( &
               start+1:start+n_value) = &
               vector_payload(vector_pos:vector_pos+n_value-1)
       end select
       vector_pos = vector_pos + n_value
    end do

  end subroutine write_domain_patch_prognostic


  logical function try_commit_block_writeback_domain_stage ( &
       payload_family,domain_sol) result(committed)
    ! Commit only after a complete preflight. A rejected transaction leaves
    ! every authoritative Domain value untouched.

    implicit none

    integer, intent(in) :: payload_family
    type(Float_Field), optional, intent(inout) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)

    integer :: d
    integer :: p
    integer :: patch_slot
    integer :: scalar_pos
    integer :: vector_pos

    logical :: stage_valid

    committed = .false.
    stage_valid = &
         block_writeback_domain_stage_is_valid(payload_family)
    if (.not. stage_valid) return

    do d = 1,size(grid)
       do p = 0,grid(d)%patch%length-1
          if (grid(d)%patch%elts(p+1)%deleted) cycle
          patch_slot = &
               block_writeback_plan%domain_patch_displ(d) + p + 1
          scalar_pos = (patch_slot-1)* &
               block_writeback_plan%scalar_patch_nvalue + 1
          vector_pos = (patch_slot-1)* &
               block_writeback_plan%vector_patch_nvalue + 1
          if (present(domain_sol)) then
             call write_domain_patch_prognostic( &
                  d,p,payload_family, &
                  block_writeback_plan%scalar_domain_stage,scalar_pos, &
                  block_writeback_plan%vector_domain_stage,vector_pos, &
                  domain_sol)
          else
             call write_domain_patch_prognostic( &
                  d,p,payload_family, &
                  block_writeback_plan%scalar_domain_stage,scalar_pos, &
                  block_writeback_plan%vector_domain_stage,vector_pos)
          end if
       end do
    end do

    committed = .true.

  end function try_commit_block_writeback_domain_stage


  subroutine write_block_field_family_to_domains ( &
       payload_family,domain_sol)
    ! Production-facing transaction for one prognostic field family.
    ! Reconstruction and complete validation precede authoritative mutation.

    implicit none

    integer, intent(in) :: payload_family
    type(Float_Field), optional, intent(inout) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)

    logical :: committed

    call reconstruct_block_writeback_domain_stage(payload_family)
    if (present(domain_sol)) then
       committed = try_commit_block_writeback_domain_stage( &
            payload_family,domain_sol)
    else
       committed = &
            try_commit_block_writeback_domain_stage(payload_family)
    end if
    if (.not. committed) then
       call fail("complete block-to-Domain transaction was rejected")
    end if
    block_writeback_plan%production_writeback_count = &
         block_writeback_plan%production_writeback_count + 1_int64

  end subroutine write_block_field_family_to_domains


  subroutine assert_block_domain_field_family_match ( &
       payload_family,domain_sol,integrated_only,compared_patch_count, &
       comparison_name,roundoff_tolerant)
    ! Reconstruct one family from final-owner blocks and compare every
    ! active authoritative Domain value. Copies and writebacks must match
    ! exactly. Independently evaluated pre-wavelet RK candidates allow only
    ! a small pointwise roundoff tolerance and may restrict comparison to
    ! patches initialized by RK_sub_step.

    implicit none

    integer, intent(in) :: payload_family
    type(Float_Field), optional, intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    logical, optional, intent(in) :: integrated_only
    integer(int64), optional, intent(out) :: compared_patch_count
    character(len=*), optional, intent(in) :: comparison_name
    logical, optional, intent(in) :: roundoff_tolerant

    integer :: d
    integer :: p
    integer :: patch_slot
    integer :: production_node_start
    integer :: scalar_pos
    integer :: scalar_start
    integer :: value_index
    integer :: vector_pos
    integer :: vector_start

    integer(int64) :: patch_count

    logical :: compare_integrated_only
    logical :: allow_roundoff

    real(dp) :: current_scalar( &
         block_writeback_plan%scalar_patch_nvalue)
    real(dp) :: current_vector( &
         block_writeback_plan%vector_patch_nvalue)
    real(dp) :: scalar_difference( &
         block_writeback_plan%scalar_patch_nvalue)
    real(dp) :: scalar_tolerance( &
         block_writeback_plan%scalar_patch_nvalue)
    real(dp) :: vector_difference( &
         block_writeback_plan%vector_patch_nvalue)
    real(dp) :: vector_tolerance( &
         block_writeback_plan%vector_patch_nvalue)
    real(dp) :: allowed_difference
    real(dp) :: block_value
    real(dp) :: current_value
    real(dp) :: difference

    compare_integrated_only = .false.
    if (present(integrated_only)) then
       compare_integrated_only = integrated_only
    end if
    if (compare_integrated_only .and. .not. present(domain_sol)) then
       call fail("integrated block/Domain comparison requires stage sol")
    end if
    allow_roundoff = .false.
    if (present(roundoff_tolerant)) then
       allow_roundoff = roundoff_tolerant
    end if
    if (allow_roundoff .and. .not. compare_integrated_only) then
       call fail("roundoff-tolerant comparison requires integrated RK state")
    end if

    patch_count = 0_int64
    call reconstruct_block_writeback_domain_stage(payload_family)

    do d = 1,size(grid)
       do p = 0,grid(d)%patch%length-1
          if (grid(d)%patch%elts(p+1)%deleted) cycle
          if (compare_integrated_only) then
             if (grid(d)%patch%length < 3) then
                call fail("integrated RK Domain patch inventory is invalid")
             end if
             production_node_start = &
                  grid(d)%patch%elts(3)%elts_start
             if (grid(d)%patch%elts(p+1)%elts_start < &
                  production_node_start) cycle
          end if
          patch_slot = &
               block_writeback_plan%domain_patch_displ(d) + p + 1
          if (compare_integrated_only .and. .not. &
               block_writeback_plan% &
               domain_patch_reconstructed(patch_slot)) then
             call fail("integrated RK patch was not reconstructed")
          end if
          scalar_start = (patch_slot-1)* &
               block_writeback_plan%scalar_patch_nvalue + 1
          vector_start = (patch_slot-1)* &
               block_writeback_plan%vector_patch_nvalue + 1
          scalar_pos = 1
          vector_pos = 1
          if (present(domain_sol) .and. block_writeback_plan% &
               domain_patch_reconstructed(patch_slot)) then
             call pack_domain_patch_prognostic( &
                  d,p,payload_family,current_scalar,scalar_pos, &
                  current_vector,vector_pos,domain_sol)
          else
             call pack_domain_patch_prognostic( &
                  d,p,payload_family,current_scalar,scalar_pos, &
                  current_vector,vector_pos)
          end if
          scalar_difference = abs(current_scalar- &
               block_writeback_plan%scalar_domain_stage( &
               scalar_start:scalar_start+ &
               block_writeback_plan%scalar_patch_nvalue-1))
          scalar_tolerance = 0.0_dp
          if (allow_roundoff) then
             scalar_tolerance = 32.0_dp*epsilon(1.0_dp)*max( &
                  1.0_dp,abs(current_scalar),abs( &
                  block_writeback_plan%scalar_domain_stage( &
                  scalar_start:scalar_start+ &
                  block_writeback_plan%scalar_patch_nvalue-1)))
          end if
          if (any(scalar_difference > scalar_tolerance)) then
             value_index = maxloc( &
                  scalar_difference-scalar_tolerance,dim=1)
             current_value = current_scalar(value_index)
             block_value = block_writeback_plan%scalar_domain_stage( &
                  scalar_start+value_index-1)
             difference = scalar_difference(value_index)
             allowed_difference = scalar_tolerance(value_index)
             call report_candidate_mismatch( &
                  "scalar",d,p,value_index,current_value, &
                  block_value,difference,allowed_difference)
             if (present(comparison_name)) then
                call fail(trim(comparison_name)// &
                     " integrated scalar block/Domain mismatch")
             else
                call fail("production scalar block/Domain mismatch")
             end if
          end if
          vector_difference = abs(current_vector- &
               block_writeback_plan%vector_domain_stage( &
               vector_start:vector_start+ &
               block_writeback_plan%vector_patch_nvalue-1))
          vector_tolerance = 0.0_dp
          if (allow_roundoff) then
             vector_tolerance = 32.0_dp*epsilon(1.0_dp)*max( &
                  1.0_dp,abs(current_vector),abs( &
                  block_writeback_plan%vector_domain_stage( &
                  vector_start:vector_start+ &
                  block_writeback_plan%vector_patch_nvalue-1)))
          end if
          if (any(vector_difference > vector_tolerance)) then
             value_index = maxloc( &
                  vector_difference-vector_tolerance,dim=1)
             current_value = current_vector(value_index)
             block_value = block_writeback_plan%vector_domain_stage( &
                  vector_start+value_index-1)
             difference = vector_difference(value_index)
             allowed_difference = vector_tolerance(value_index)
             call report_candidate_mismatch( &
                  "vector",d,p,value_index,current_value, &
                  block_value,difference,allowed_difference)
             if (present(comparison_name)) then
                call fail(trim(comparison_name)// &
                     " integrated vector block/Domain mismatch")
             else
                call fail("production vector block/Domain mismatch")
             end if
          end if
          patch_count = patch_count + 1_int64
       end do
    end do

    if (present(compared_patch_count)) then
       compared_patch_count = patch_count
    end if

  contains

    subroutine report_candidate_mismatch ( &
         family,d,p,index,current,block,difference,tolerance)

      implicit none

      character(len=*), intent(in) :: family
      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(in) :: index
      real(dp), intent(in) :: current
      real(dp), intent(in) :: block
      real(dp), intent(in) :: difference
      real(dp), intent(in) :: tolerance

      character(len=16) :: name

      name = "production"
      if (present(comparison_name)) name = comparison_name
      write(error_unit,'(a,i0,5a,i0,a,i0,a,i0)') &
           "Rank ",rank,": ",trim(name)," ",trim(family), &
           " mismatch: Domain index = ",d,", patch = ",p, &
           ", patch value index = ",index
      write(error_unit,'(4(a,es24.16))') &
           "  Domain value = ",current, &
           ", block value = ",block, &
           ", absolute difference = ",difference, &
           ", allowed difference = ",tolerance

    end subroutine report_candidate_mismatch

  end subroutine assert_block_domain_field_family_match


  subroutine check_block_writeback_domain_reconstruction (verbose)
    ! Validate complete sol and wav_coeff Domain staging and transactional
    ! writeback. Rejected commits must not mutate authoritative fields;
    ! accepted commits are verified exactly and restored to their references.

    implicit none

    logical, optional, intent(in) :: verbose

    integer :: active_patch_count
    integer :: d
    integer :: ierr
    integer :: p
    integer :: patch_slot
    integer :: scalar_start
    integer :: sol_preserved_patch_count
    integer :: sol_reconstructed_patch_count
    integer :: vector_start

    integer(int64) :: allocation_before
    integer(int64) :: global_patch_count
    integer(int64) :: global_preserved_patch_count
    integer(int64) :: global_reconstructed_patch_count
    integer(int64) :: global_scalar_count
    integer(int64) :: global_vector_count
    integer(int64) :: local_patch_count
    integer(int64) :: local_preserved_patch_count
    integer(int64) :: local_reconstructed_patch_count
    integer(int64) :: local_scalar_count
    integer(int64) :: local_vector_count

    logical :: print_summary

    real(dp), allocatable :: current_scalar(:)
    real(dp), allocatable :: current_vector(:)
    real(dp), allocatable :: reference_scalar(:)
    real(dp), allocatable :: reference_vector(:)

    print_summary = .true.
    if (present(verbose)) print_summary = verbose

    if (.not. block_writeback_plan_is_ready()) then
       call fail("Domain reconstruction check before plan is ready")
    end if

    allocate(reference_scalar( &
         size(block_writeback_plan%scalar_domain_stage)))
    allocate(reference_vector( &
         size(block_writeback_plan%vector_domain_stage)))
    allocate(current_scalar( &
         block_writeback_plan%scalar_patch_nvalue))
    allocate(current_vector( &
         block_writeback_plan%vector_patch_nvalue))

    allocation_before = block_writeback_plan%stage_allocations

    call check_family(BLOCK_PAYLOAD_SOL)
    sol_reconstructed_patch_count = &
         block_writeback_plan%reconstructed_patch_count
    sol_preserved_patch_count = &
         block_writeback_plan%preserved_patch_count
    call check_family(BLOCK_PAYLOAD_WAV_COEFF)
    if (block_writeback_plan%reconstructed_patch_count /= &
         sol_reconstructed_patch_count .or. &
         block_writeback_plan%preserved_patch_count /= &
         sol_preserved_patch_count) then
       call fail("sol and wav_coeff Domain patch coverage differs")
    end if

    if (block_writeback_plan%stage_allocations /= allocation_before) then
       call fail("Domain reconstruction reallocated persistent staging")
    end if

    active_patch_count = 0
    do d = 1,size(grid)
       do p = 0,grid(d)%patch%length-1
          if (.not. grid(d)%patch%elts(p+1)%deleted) then
             active_patch_count = active_patch_count + 1
          end if
       end do
    end do
    local_patch_count = int(active_patch_count,int64)
    local_reconstructed_patch_count = int( &
         block_writeback_plan%reconstructed_patch_count,int64)
    local_preserved_patch_count = int( &
         block_writeback_plan%preserved_patch_count,int64)
    local_scalar_count = local_patch_count*int( &
         block_writeback_plan%scalar_patch_nvalue,int64)
    local_vector_count = local_patch_count*int( &
         block_writeback_plan%vector_patch_nvalue,int64)

    call MPI_Allreduce(local_patch_count,global_patch_count,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce reconstructed Domain patches")
    call MPI_Allreduce( &
         local_reconstructed_patch_count,global_reconstructed_patch_count, &
         1,MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce block-derived Domain patches")
    call MPI_Allreduce( &
         local_preserved_patch_count,global_preserved_patch_count, &
         1,MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce preserved Domain patches")
    call MPI_Allreduce(local_scalar_count,global_scalar_count,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce reconstructed scalar values")
    call MPI_Allreduce(local_vector_count,global_vector_count,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce reconstructed vector values")

    if (print_summary) then
       write(6,'(/,a,i0,a)') &
            "Complete Domain reconstruction for rank ",rank,":"
       write(6,'(a,i0)') "  active Domain patches = ",local_patch_count
       write(6,'(a,i0)') "  block-derived patches = ", &
            local_reconstructed_patch_count
       write(6,'(a,i0)') "  preserved coarse patches = ", &
            local_preserved_patch_count
       write(6,'(a,i0)') "  scalar values staged = ",local_scalar_count
       write(6,'(a,i0)') "  vector values staged = ",local_vector_count
       write(6,'(a)') "  exact complete sol reconstruction passed"
       write(6,'(a)') "  exact complete wav_coeff reconstruction passed"
       write(6,'(a)') "  repeated persistent Domain staging passed"
       write(6,'(a)') "  incomplete transaction rejected without mutation"
       write(6,'(a)') "  exact transactional sol writeback passed"
       write(6,'(a)') "  exact transactional wav_coeff writeback passed"
       write(6,'(a)') "  repeated transactional Domain writeback passed"
       write(6,'(a,/)') "  authoritative Domain fields restored exactly"
    end if

    if (print_summary .and. rank == 0) then
       write(6,'(/,a,i0)') &
            "Global reconstructed Domain patches = ",global_patch_count
       write(6,'(a,i0)') &
            "Global block-derived Domain patches = ", &
            global_reconstructed_patch_count
       write(6,'(a,i0)') &
            "Global preserved coarse Domain patches = ", &
            global_preserved_patch_count
       write(6,'(a,i0)') &
            "Global reconstructed scalar values = ",global_scalar_count
       write(6,'(a,i0)') &
            "Global reconstructed vector values = ",global_vector_count
       write(6,'(a,/)') &
            "Transactional block-to-Domain writeback passed"
    end if

    deallocate(reference_vector)
    deallocate(reference_scalar)
    deallocate(current_vector)
    deallocate(current_scalar)

  contains

    subroutine build_reference (payload_family)

      implicit none

      integer, intent(in) :: payload_family

      reference_scalar = 0.0_dp
      reference_vector = 0.0_dp
      do d = 1,size(grid)
         do p = 0,grid(d)%patch%length-1
            if (grid(d)%patch%elts(p+1)%deleted) cycle
            patch_slot = &
                 block_writeback_plan%domain_patch_displ(d) + p + 1
            scalar_start = (patch_slot-1)* &
                 block_writeback_plan%scalar_patch_nvalue + 1
            vector_start = (patch_slot-1)* &
                 block_writeback_plan%vector_patch_nvalue + 1
            call pack_domain_patch_prognostic( &
                 d,p,payload_family,reference_scalar,scalar_start, &
                 reference_vector,vector_start)
         end do
      end do

    end subroutine build_reference


    subroutine compare_stage_and_authority (payload_family)

      implicit none

      integer, intent(in) :: payload_family

      integer :: current_scalar_pos
      integer :: current_vector_pos

      if (any(abs(block_writeback_plan%scalar_domain_stage- &
           reference_scalar) > 0.0_dp)) then
         if (payload_family == BLOCK_PAYLOAD_SOL) then
            call fail("complete scalar sol reconstruction mismatch")
         else
            call fail("complete scalar wav_coeff reconstruction mismatch")
         end if
      end if
      if (any(abs(block_writeback_plan%vector_domain_stage- &
           reference_vector) > 0.0_dp)) then
         if (payload_family == BLOCK_PAYLOAD_SOL) then
            call fail("complete vector sol reconstruction mismatch")
         else
            call fail("complete vector wav_coeff reconstruction mismatch")
         end if
      end if

      do d = 1,size(grid)
         do p = 0,grid(d)%patch%length-1
            if (grid(d)%patch%elts(p+1)%deleted) cycle
            patch_slot = &
                 block_writeback_plan%domain_patch_displ(d) + p + 1
            scalar_start = (patch_slot-1)* &
                 block_writeback_plan%scalar_patch_nvalue + 1
            vector_start = (patch_slot-1)* &
                 block_writeback_plan%vector_patch_nvalue + 1
            current_scalar_pos = 1
            current_vector_pos = 1
            call pack_domain_patch_prognostic( &
                 d,p,payload_family,current_scalar,current_scalar_pos, &
                 current_vector,current_vector_pos)
            if (any(abs(current_scalar-reference_scalar( &
                 scalar_start:scalar_start+ &
                 block_writeback_plan%scalar_patch_nvalue-1)) > &
                 0.0_dp)) then
               call fail("authoritative scalar Domain field changed")
            end if
            if (any(abs(current_vector-reference_vector( &
                 vector_start:vector_start+ &
                 block_writeback_plan%vector_patch_nvalue-1)) > &
                 0.0_dp)) then
               call fail("authoritative vector Domain field changed")
            end if
         end do
      end do

    end subroutine compare_stage_and_authority


    subroutine compare_authority_to_stage (payload_family)

      implicit none

      integer, intent(in) :: payload_family

      integer :: current_scalar_pos
      integer :: current_vector_pos

      do d = 1,size(grid)
         do p = 0,grid(d)%patch%length-1
            if (grid(d)%patch%elts(p+1)%deleted) cycle
            patch_slot = &
                 block_writeback_plan%domain_patch_displ(d) + p + 1
            scalar_start = (patch_slot-1)* &
                 block_writeback_plan%scalar_patch_nvalue + 1
            vector_start = (patch_slot-1)* &
                 block_writeback_plan%vector_patch_nvalue + 1
            current_scalar_pos = 1
            current_vector_pos = 1
            call pack_domain_patch_prognostic( &
                 d,p,payload_family,current_scalar,current_scalar_pos, &
                 current_vector,current_vector_pos)
            if (any(abs(current_scalar- &
                 block_writeback_plan%scalar_domain_stage( &
                 scalar_start:scalar_start+ &
                 block_writeback_plan%scalar_patch_nvalue-1)) > &
                 0.0_dp)) then
               call fail("transactional scalar Domain writeback mismatch")
            end if
            if (any(abs(current_vector- &
                 block_writeback_plan%vector_domain_stage( &
                 vector_start:vector_start+ &
                 block_writeback_plan%vector_patch_nvalue-1)) > &
                 0.0_dp)) then
               call fail("transactional vector Domain writeback mismatch")
            end if
         end do
      end do

    end subroutine compare_authority_to_stage


    subroutine check_transaction (payload_family)

      implicit none

      integer, intent(in) :: payload_family

      integer :: first_active_slot

      logical :: committed

      first_active_slot = 0
      do d = 1,size(grid)
         do p = 0,grid(d)%patch%length-1
            if (grid(d)%patch%elts(p+1)%deleted) cycle
            first_active_slot = &
                 block_writeback_plan%domain_patch_displ(d) + p + 1
            exit
         end do
         if (first_active_slot > 0) exit
      end do
      if (first_active_slot <= 0) then
         call fail("transactional writeback has no active Domain patch")
      end if

      block_writeback_plan%domain_patch_covered(first_active_slot) = &
           .false.
      committed = &
           try_commit_block_writeback_domain_stage(payload_family)
      block_writeback_plan%domain_patch_covered(first_active_slot) = &
           .true.
      if (committed) then
         call fail("incomplete Domain writeback transaction was accepted")
      end if
      call compare_stage_and_authority(payload_family)

      block_writeback_plan%scalar_domain_stage = 0.125_dp
      block_writeback_plan%vector_domain_stage = -0.125_dp
      committed = &
           try_commit_block_writeback_domain_stage(payload_family)
      if (.not. committed) then
         call fail("complete Domain writeback transaction was rejected")
      end if
      call compare_authority_to_stage(payload_family)

      block_writeback_plan%scalar_domain_stage = reference_scalar
      block_writeback_plan%vector_domain_stage = reference_vector
      committed = &
           try_commit_block_writeback_domain_stage(payload_family)
      if (.not. committed) then
         call fail("Domain writeback restoration was rejected")
      end if
      call compare_stage_and_authority(payload_family)

    end subroutine check_transaction


    subroutine check_family (payload_family)

      implicit none

      integer, intent(in) :: payload_family

      call build_reference(payload_family)
      call reconstruct_block_writeback_domain_stage(payload_family)
      call compare_stage_and_authority(payload_family)
      call reconstruct_block_writeback_domain_stage(payload_family)
      call compare_stage_and_authority(payload_family)
      call check_transaction(payload_family)

    end subroutine check_family

  end subroutine check_block_writeback_domain_reconstruction


  subroutine check_block_ghost_request_manifest (verbose)
    ! Exchange field-independent NGB_BLOCK ghost requests from each final
    ! owner to the current owner of the compact source block. This checks
    ! the routing layer only; Float_Field payload values are not moved yet.

    implicit none

    integer, parameter :: REQUEST_SIZE = 4

    logical, optional, intent(in) :: verbose

    integer :: b
    integer :: i
    integer :: ierr
    integer :: n_local_request
    integer :: n_remote_recv
    integer :: n_remote_send
    integer :: n_request
    integer :: pos
    integer :: r
    integer :: source

    integer(int64) :: count_local(3)
    integer(int64) :: count_global(3)
    integer(int64) :: recv_sum_local(REQUEST_SIZE)
    integer(int64) :: recv_sum_global(REQUEST_SIZE)
    integer(int64) :: send_sum_local(REQUEST_SIZE)
    integer(int64) :: send_sum_global(REQUEST_SIZE)

    integer, allocatable :: destination_block(:)
    integer, allocatable :: destination_ghost(:)
    integer, allocatable :: fill(:)
    integer, allocatable :: ghost_count_global(:)
    integer, allocatable :: ghost_count_local(:)
    integer, allocatable :: patch_count_global(:)
    integer, allocatable :: patch_count_local(:)
    integer, allocatable :: recv_count(:)
    integer, allocatable :: recv_data(:)
    integer, allocatable :: recv_displ(:)
    integer, allocatable :: recv_record_count(:)
    integer, allocatable :: send_count(:)
    integer, allocatable :: send_data(:)
    integer, allocatable :: send_displ(:)
    integer, allocatable :: send_record_count(:)
    integer, allocatable :: source_block(:)
    integer, allocatable :: source_local_patch(:)
    integer, allocatable :: source_owner(:)

    logical :: print_summary

    print_summary = .true.
    if (present(verbose)) print_summary = verbose

    allocate(ghost_count_global(size(block_catalog)))
    allocate(ghost_count_local(size(block_catalog)))
    allocate(patch_count_global(size(block_catalog)))
    allocate(patch_count_local(size(block_catalog)))

    ghost_count_local = 0
    patch_count_local = 0

    do b = 1, size(block_catalog)
       if (block_catalog(b)%owner /= rank) cycle
       if (catalog_local_block(b) < 1) then
          call fail("owned block missing from request manifest store")
       end if
       ghost_count_local(b) = local_block_ghost_count(b)
       patch_count_local(b) = local_block_patch_count(b)
    end do

    call MPI_Allreduce( &
         ghost_count_local,ghost_count_global,size(block_catalog), &
         MPI_INTEGER,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce block ghost counts")

    call MPI_Allreduce( &
         patch_count_local,patch_count_global,size(block_catalog), &
         MPI_INTEGER,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce local block patch counts")

    if (any(patch_count_global <= 0) .or. &
         any(ghost_count_global < 0)) then
       call fail("invalid global request-manifest block extents")
    end if

    call get_local_block_ghost_requests( &
         source_block,source_local_patch,source_owner, &
         destination_block,destination_ghost)

    n_request = size(source_block)

    if (size(source_local_patch) /= n_request .or. &
         size(source_owner) /= n_request .or. &
         size(destination_block) /= n_request .or. &
         size(destination_ghost) /= n_request) then
       call fail("inconsistent local ghost request arrays")
    end if

    allocate(send_record_count(n_process))
    allocate(recv_record_count(n_process))
    allocate(send_count(n_process))
    allocate(recv_count(n_process))
    allocate(send_displ(n_process))
    allocate(recv_displ(n_process))
    allocate(fill(n_process))

    send_record_count = 0
    n_local_request = 0

    do i = 1, n_request
       source = source_block(i)

       if (source < 1 .or. source > size(block_catalog)) then
          call fail("ghost request has invalid source block")
       end if
       if (source_owner(i) /= block_catalog(source)%owner) then
          call fail("ghost request has stale source owner")
       end if
       if (source_local_patch(i) < 0 .or. &
            source_local_patch(i) >= patch_count_global(source)) then
          call fail("ghost request has invalid compact source patch")
       end if
       if (destination_block(i) < 1 .or. &
            destination_block(i) > size(block_catalog)) then
          call fail("ghost request has invalid destination block")
       end if
       if (block_catalog(destination_block(i))%owner /= rank .or. &
            destination_ghost(i) < 1 .or. &
            destination_ghost(i) > &
            ghost_count_global(destination_block(i))) then
          call fail("ghost request has invalid destination record")
       end if

       if (source_owner(i) == rank) then
          if (catalog_local_block(source) < 1) then
             call fail("local ghost source block is unavailable")
          end if
          n_local_request = n_local_request + 1
       else
          send_record_count(source_owner(i)+1) = &
               send_record_count(source_owner(i)+1) + 1
       end if
    end do

    call MPI_Alltoall( &
         send_record_count,1,MPI_INTEGER, &
         recv_record_count,1,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoall ghost request counts")

    n_remote_send = sum(send_record_count)
    n_remote_recv = sum(recv_record_count)

    send_count = REQUEST_SIZE*send_record_count
    recv_count = REQUEST_SIZE*recv_record_count
    send_displ(1) = 0
    recv_displ(1) = 0

    do r = 2, n_process
       send_displ(r) = send_displ(r-1) + send_count(r-1)
       recv_displ(r) = recv_displ(r-1) + recv_count(r-1)
    end do

    allocate(send_data(REQUEST_SIZE*n_remote_send))
    allocate(recv_data(REQUEST_SIZE*n_remote_recv))

    fill = 0
    send_sum_local = 0_int64

    do i = 1, n_request
       if (source_owner(i) == rank) cycle
       r = source_owner(i) + 1
       pos = send_displ(r) + REQUEST_SIZE*fill(r)
       send_data(pos+1:pos+REQUEST_SIZE) = [ &
            source_block(i),source_local_patch(i), &
            destination_block(i),destination_ghost(i) ]
       send_sum_local = send_sum_local + &
            int(send_data(pos+1:pos+REQUEST_SIZE),int64)
       fill(r) = fill(r) + 1
    end do

    if (any(fill /= send_record_count)) then
       call fail("ghost request send packing count mismatch")
    end if

    call MPI_Alltoallv( &
         send_data,send_count,send_displ,MPI_INTEGER, &
         recv_data,recv_count,recv_displ,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv ghost requests")

    recv_sum_local = 0_int64

    do r = 1, n_process
       do i = 0, recv_record_count(r)-1
          pos = recv_displ(r) + REQUEST_SIZE*i
          source = recv_data(pos+1)

          if (source < 1 .or. source > size(block_catalog)) then
             call fail("received ghost request has invalid source block")
          end if
          if (block_catalog(source)%owner /= rank) then
             call fail("received ghost request source is not local")
          end if
          if (catalog_local_block(source) < 1) then
             call fail("received ghost request source block is absent")
          end if
          if (recv_data(pos+2) < 0 .or. &
               recv_data(pos+2) >= patch_count_global(source)) then
             call fail("received ghost request has invalid source patch")
          end if
          b = recv_data(pos+3)
          if (b < 1 .or. b > size(block_catalog)) then
             call fail("received ghost request has invalid destination")
          end if
          if (block_catalog(b)%owner /= r-1 .or. &
               recv_data(pos+4) < 1 .or. &
               recv_data(pos+4) > ghost_count_global(b)) then
             call fail("received ghost request has invalid ghost record")
          end if

          recv_sum_local = recv_sum_local + &
               int(recv_data(pos+1:pos+REQUEST_SIZE),int64)
       end do
    end do

    count_local = int([ &
         n_local_request,n_remote_send,n_remote_recv ],int64)

    call MPI_Allreduce( &
         count_local,count_global,3,MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce ghost request totals")

    call MPI_Allreduce( &
         send_sum_local,send_sum_global,REQUEST_SIZE, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce sent ghost request checksum")

    call MPI_Allreduce( &
         recv_sum_local,recv_sum_global,REQUEST_SIZE, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce received ghost request checksum")

    if (count_global(2) /= count_global(3) .or. &
         any(send_sum_global /= recv_sum_global)) then
       call fail("remote ghost request exchange mismatch")
    end if

    if (count_global(1)+count_global(2) /= &
         int(sum(ghost_count_global),int64)) then
       call fail("global ghost request inventory is incomplete")
    end if

    if (print_summary) then
       write(6,'(/,a,i0,a)') &
            "Float_Field ghost request manifest for rank ",rank,":"
       write(6,'(a,i0)') &
            "  local-source requests  = ",n_local_request
       write(6,'(a,i0)') &
            "  remote requests sent   = ",n_remote_send
       write(6,'(a,i0)') &
            "  remote requests received = ",n_remote_recv
       write(6,'(a,/)') &
            "  request source/destination checks passed"
    end if

    if (print_summary .and. rank == 0) then
       write(6,'(/,a,i0)') &
            "Global local-source ghost requests  = ",count_global(1)
       write(6,'(a,i0)') &
            "Global remote ghost requests        = ",count_global(2)
       write(6,'(a,i0)') &
            "Global Float_Field ghost requests   = ", &
            count_global(1)+count_global(2)
       write(6,'(a,/)') &
            "Float_Field ghost request manifest exchange passed"
    end if

    deallocate(destination_block)
    deallocate(destination_ghost)
    deallocate(fill)
    deallocate(ghost_count_global)
    deallocate(ghost_count_local)
    deallocate(patch_count_global)
    deallocate(patch_count_local)
    deallocate(recv_count)
    deallocate(recv_data)
    deallocate(recv_displ)
    deallocate(recv_record_count)
    deallocate(send_count)
    deallocate(send_data)
    deallocate(send_displ)
    deallocate(send_record_count)
    deallocate(source_block)
    deallocate(source_local_patch)
    deallocate(source_owner)

  end subroutine check_block_ghost_request_manifest


